INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88126, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "行政区划单位，比县小；规模比村大的居民点。", "primary_collocate": null, "pronunciation": "zhèn", "ipa": "ʈʂən˥˩", "syllable_count": 1, "sentences": [{"text": "这个县有十个镇。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镇比县小，比村大。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从镇里搬到了县城。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个镇有两万多人。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们镇今年修了一条新路。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "镇上要开一个大会。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新路连着两个镇。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是镇里小学的老师。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "每个镇都有自己的名字。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里的孩子去镇上读中学。", "target_word": "镇", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "鎮", "label": "繁体"}], "register": "中性", "sense_fingerprint": "镇：比县小的行政区划单位", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'cda74fbf-1808-476c-b0e7-6f1b5b85d218') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88126, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "镇", "is_correct": true, "explanation": "镇：比县小、规模比村大的行政区划单位。"}, {"text": "战", "is_correct": false, "explanation": "zhàn（第四声）与 zhèn 韵母不同（an/en），意思是战争。"}, {"text": "针", "is_correct": false, "explanation": "zhēn（第一声）与 zhèn 声调不同，意思是针。"}, {"text": "正", "is_correct": false, "explanation": "zhèng（第四声）与 zhèn 韵母不同（eng/en），意思是正确。"}], "explanations": {"镇": "镇：比县小、规模比村大的行政区划单位。", "战": "zhàn（第四声）与 zhèn 韵母不同（an/en），意思是战争。", "针": "zhēn（第一声）与 zhèn 声调不同，意思是针。", "正": "zhèng（第四声）与 zhèn 韵母不同（eng/en），意思是正确。"}, "sentence_index": null, "correct_answer": "镇"}, "level_3": {"options": [{"text": "镇", "is_correct": true, "explanation": "正确：“这个县有十个……”要接县的下属单位，“镇”符合。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是县的下属单位，与“这个县有十个”矛盾。"}, {"text": "手机", "is_correct": false, "explanation": "搭配：“这个县有十个……”后要接县的下属单位，“手机”不能这样搭配。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不是县的组成部分，与“这个县有十个”矛盾。"}], "explanations": {"镇": "正确：“这个县有十个……”要接县的下属单位，“镇”符合。", "书包": "语义：书包不是县的下属单位，与“这个县有十个”矛盾。", "手机": "搭配：“这个县有十个……”后要接县的下属单位，“手机”不能这样搭配。", "窗户": "语义：窗户不是县的组成部分，与“这个县有十个”矛盾。"}, "sentence_index": 0, "correct_answer": "镇"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这个镇的县长。", "explanation": "这里应该用〈县〉。镇比县小，镇的负责人是镇长；县长管理的是县，不能用“镇”。"}, {"text": "这个镇下面有三个县。", "explanation": "这里应该用〈市〉。镇是比县小的行政单位，下面不能有县。"}, {"text": "我们镇的省长今年换人了。", "explanation": "这里应该用〈省〉。省长负责省级行政区，镇比省小得多，不能用“镇”指这样的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88126, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "镇", "is_correct": true, "explanation": "镇：比县小、规模比村大的行政区划单位。"}, {"text": "站", "is_correct": false, "explanation": "zhàn（第四声）与 zhèn 韵母不同（an/en），意思是车站。"}, {"text": "真", "is_correct": false, "explanation": "zhēn（第一声）与 zhèn 声调不同，意思是真实。"}, {"text": "枕", "is_correct": false, "explanation": "zhěn（第三声）与 zhèn 声调不同，意思是枕头。"}], "explanations": {"镇": "镇：比县小、规模比村大的行政区划单位。", "站": "zhàn（第四声）与 zhèn 韵母不同（an/en），意思是车站。", "真": "zhēn（第一声）与 zhèn 声调不同，意思是真实。", "枕": "zhěn（第三声）与 zhèn 声调不同，意思是枕头。"}, "sentence_index": null, "correct_answer": "镇"}, "level_3": {"options": [{"text": "镇", "is_correct": true, "explanation": "正确：“连着”的对象是地方，“两个镇”符合语境。"}, {"text": "椅子", "is_correct": false, "explanation": "语义：椅子不是道路可以连接的地方，与“新路连着”矛盾。"}, {"text": "人", "is_correct": false, "explanation": "配价：“连着”要求地方作宾语，“人”不能作“连着”的对象。"}, {"text": "杯子", "is_correct": false, "explanation": "语义：杯子不能被道路连接，与语境矛盾。"}], "explanations": {"镇": "正确：“连着”的对象是地方，“两个镇”符合语境。", "椅子": "语义：椅子不是道路可以连接的地方，与“新路连着”矛盾。", "人": "配价：“连着”要求地方作宾语，“人”不能作“连着”的对象。", "杯子": "语义：杯子不能被道路连接，与语境矛盾。"}, "sentence_index": 6, "correct_answer": "镇"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个镇的市长很年轻。", "explanation": "这里应该用〈城市〉。镇的行政负责人是镇长，“市长”只用于城市。"}, {"text": "这个镇管着五个县。", "explanation": "这里应该用〈市〉。镇是比县小的行政单位，不能管辖县；管辖县的是“市”或“地区”，此处的“镇”与本词的意思不符。"}, {"text": "这个镇的大学有三十所。", "explanation": "这里应该用〈城市〉。三十所大学的规模属于城市，镇比城市小，不能用“镇”指这样的地方。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88126, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他在一条镇上开了一家店。", "corrected_sentence": "他在一个镇上开了一家店。", "error_description": "量词错误：「一条镇」应为「一个镇」。「条」用于长条形的事物，“镇”是地方单位，应用量词“个”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88126, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这条镇有两所小学。", "corrected_sentence": "这个镇有两所小学。", "error_description": "量词错误：「这条镇」应为「这个镇」。「条」用于长条形的东西，“镇”是地方，应用“个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '081d27b6-2776-49a0-9ed9-3975b461f9a5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
