INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88127, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "指做法或事物不弄脏周围的地方，能保护好空气、水和树。", "primary_collocate": null, "pronunciation": "huán bǎo", "ipa": "xu̯an˧˥ pau̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "用布袋买东西很环保。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "骑自行车上班既方便又环保。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种杯子可以用很多次，非常环保。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的做法很环保，从不乱扔垃圾。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种纸袋很环保，用完还能再用。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这样做一点也不环保。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家饭店不用一次性筷子，很环保。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐地铁比开车更环保。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "少用一次性餐具，这样很环保。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小朋友们用旧瓶子做花盆，又省钱又环保。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "环保袋", "label": "复合"}, {"form": "环保意识", "label": "复合"}], "register": "中性", "sense_fingerprint": "环保：日常生活中不弄脏环境、爱护空气水和树木的做法或特点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '314b788a-db43-4be2-9cd0-4c586b32fd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88127, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "漂亮", "is_correct": false, "explanation": "体貌：“漂亮”形容外表好看，不能用来评价“买东西”的做法"}, {"text": "环保", "is_correct": true, "explanation": "正确：“环保”评价做法对环境的影响，用在“用布袋买东西”上符合句意"}, {"text": "昂贵", "is_correct": false, "explanation": "语义：“昂贵”说价格高，这里评价的是“用布袋买东西”这种做法对环境的影响，不是价格"}, {"text": "严肃", "is_correct": false, "explanation": "语义：“严肃”形容态度，不能评价买东西的做法"}], "explanations": {"漂亮": "体貌：“漂亮”形容外表好看，不能用来评价“买东西”的做法", "环保": "正确：“环保”评价做法对环境的影响，用在“用布袋买东西”上符合句意", "昂贵": "语义：“昂贵”说价格高，这里评价的是“用布袋买东西”这种做法对环境的影响，不是价格", "严肃": "语义：“严肃”形容态度，不能评价买东西的做法"}, "sentence_index": 0, "correct_answer": "环保"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条围巾的颜色很环保。", "explanation": "搭配：“环保”评价做法或产品对环境的影响，不能评价颜色，颜色应说“漂亮”"}, {"text": "他听了这个消息很环保。", "explanation": "语义：“环保”用于评价做法或产品，不能形容人的情绪，应说“伤心”"}, {"text": "这个问题很环保，需要尽快解决。", "explanation": "语义：“环保”不能形容问题的程度，应说“严重”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88127, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "紧张", "is_correct": false, "explanation": "语义：“紧张”形容心理状态，不能用来评价饭店的做法"}, {"text": "环保", "is_correct": true, "explanation": "正确：“环保”评价饭店不用一次性筷子的做法，符合句意"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”形容味道，不能用来评价“不用筷子”的做法"}, {"text": "胖", "is_correct": false, "explanation": "体貌：“胖”形容人或动物的体形，不能用来形容饭店"}], "explanations": {"紧张": "语义：“紧张”形容心理状态，不能用来评价饭店的做法", "环保": "正确：“环保”评价饭店不用一次性筷子的做法，符合句意", "甜": "搭配：“甜”形容味道，不能用来评价“不用筷子”的做法", "胖": "体貌：“胖”形容人或动物的体形，不能用来形容饭店"}, "sentence_index": 6, "correct_answer": "环保"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌很环保，大家都喜欢听。", "explanation": "语义：“环保”不能形容歌曲的感染力，应说“动人”"}, {"text": "这场比赛很环保，大家都很紧张。", "explanation": "语义：“环保”不能形容比赛的激烈程度，应说“激烈”"}, {"text": "这件事很环保，我一想起来就害怕。", "explanation": "语义：“环保”不能形容事情令人害怕的程度，应说“可怕”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88127, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这种杯子可以用很多次，很的环保。", "corrected_sentence": "这种杯子可以用很多次，很环保。", "error_description": "错误：程度副词“很”与形容词之间不能加“的”，“很的环保”不成句。应去掉“的”，说“很环保”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88127, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家超市提供很环保布袋。", "corrected_sentence": "这家超市提供很环保的布袋。", "error_description": "错误：“很环保”修饰名词时漏掉了“的”。应说“很环保的布袋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
