INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88128, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "环境保护的简称，指保护自然环境、防止污染。", "primary_collocate": null, "pronunciation": "huán bǎo", "ipa": "xu̯an˧˥ pau̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "现在很多城市都重视环保。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家工厂因为环保问题停产了。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府每年在环保上花很多钱。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "环保是全世界共同的事情。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就关心环保。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校请专家给学生们讲了环保。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家对环保的要求越来越高。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了环保，这座城市不让烧煤。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的环保做得很好。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "政府把环保放在第一位。", "target_word": "环保", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "环保局", "label": "复合"}, {"form": "环保意识", "label": "复合"}], "register": "中性", "sense_fingerprint": "环保：环境保护的简称，指保护自然环境、防止污染的工作或事业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '314b788a-db43-4be2-9cd0-4c586b32fd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88128, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "螺丝", "is_correct": false, "explanation": "语义：“螺丝”是具体的小零件，不是“重视”的对象"}, {"text": "环保", "is_correct": true, "explanation": "正确：“环保”指环境保护这项事业，是“重视”的对象，符合句意"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：“冰箱”是具体的电器，不是“重视”的对象"}, {"text": "面条", "is_correct": false, "explanation": "搭配：“重视”一般搭配抽象事务，不搭配食物"}], "explanations": {"螺丝": "语义：“螺丝”是具体的小零件，不是“重视”的对象", "环保": "正确：“环保”指环境保护这项事业，是“重视”的对象，符合句意", "冰箱": "语义：“冰箱”是具体的电器，不是“重视”的对象", "面条": "搭配：“重视”一般搭配抽象事务，不搭配食物"}, "sentence_index": 0, "correct_answer": "环保"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座城市的环保污染很严重。", "explanation": "语义：这里应说“环境污染”。“环保”指保护环境的工作或事业，不指环境本身，所以不能说被污染的是“环保”。"}, {"text": "这家超市的环保很新鲜，每天都进货。", "explanation": "语义：“环保”指保护环境的事业，不指食品，不能用“新鲜”形容。"}, {"text": "这个小区的环保很干净，每个角落都没有垃圾。", "explanation": "语义：这里应说“环境很干净”。“环保”指保护环境的工作或事业，不指环境本身，不能说它干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88128, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是可以提出“要求”的对象"}, {"text": "环保", "is_correct": true, "explanation": "正确：“环保”是可以提出要求的事业，符合“国家对……的要求”的句意"}, {"text": "白天", "is_correct": false, "explanation": "搭配：“白天”是时间词，不能作“要求”的对象"}, {"text": "星星", "is_correct": false, "explanation": "语义：“星星”是天体，不能作“要求”的对象"}], "explanations": {"天气": "语义：“天气”不是可以提出“要求”的对象", "环保": "正确：“环保”是可以提出要求的事业，符合“国家对……的要求”的句意", "白天": "搭配：“白天”是时间词，不能作“要求”的对象", "星星": "语义：“星星”是天体，不能作“要求”的对象"}, "sentence_index": 6, "correct_answer": "环保"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家工厂的环保是一台机器，每天都在转动。", "explanation": "语义：“环保”指保护环境的事业，不指具体的机器；指设备应说“环保设备”"}, {"text": "下午我要去环保买点菜。", "explanation": "用法：“环保”不是场所名词，“去……买菜”要用市场、超市等场所"}, {"text": "这座城市的环保很大，走一天也走不完。", "explanation": "语义：误把“环保”当成“一片地方”来用。“环保”指保护环境的事业，不指一片地方或区域，所以不能用“走一天也走不完”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88128, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他环保很感兴趣。", "corrected_sentence": "他对环保很感兴趣。", "error_description": "错误：漏掉介词“对”。“感兴趣”的对象要用“对……”引出，应说“他对环保很感兴趣”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88128, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市民把环保放了在生活的第一位。", "corrected_sentence": "市民把环保放在了生活的第一位。", "error_description": "错误：“了”的位置不对。结果补语“在”后应接“了”，说“放在了”，不能说“放了在”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
