INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88129, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "扫描是用机器一点一点照着看，把图或字存进电脑。", "primary_collocate": null, "pronunciation": "sǎo miáo", "ipa": "sau˨˩ miau˧˥", "syllable_count": 2, "sentences": [{"text": "我想把旧照片扫描到电脑里。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈在家里扫描孩子的画。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个机器能扫描图片和文字。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他扫描了护照，发给了旅行社。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先扫描这几页，我等一下要用。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的打印机还能扫描，不用另买。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把信一封一封地扫描，很慢。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "扫描以后，这些旧书就不会丢了。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你有没有扫描过这张表？", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用新机器扫描了所有的文件。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扫描了", "label": "完成体"}, {"form": "扫描过", "label": "经历体"}, {"form": "扫描仪", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用机器把图或字存进电脑", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19caa3-16e4-4fcd-a031-4c3dbc5187f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88129, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扫描", "is_correct": true, "explanation": "扫描：用机器把旧照片读入电脑，与“电脑里”相衔接。"}, {"text": "印", "is_correct": false, "explanation": "语义：“印”指印到纸上，与“存进电脑”不符。"}, {"text": "删", "is_correct": false, "explanation": "语义：“删”是删除，与“存进电脑”的意思相反。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：照片可以“洗”，但不能说“洗到电脑里”。"}], "explanations": {"扫描": "扫描：用机器把旧照片读入电脑，与“电脑里”相衔接。", "印": "语义：“印”指印到纸上，与“存进电脑”不符。", "删": "语义：“删”是删除，与“存进电脑”的意思相反。", "洗": "搭配：照片可以“洗”，但不能说“洗到电脑里”。"}, "sentence_index": 0, "correct_answer": "扫描"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "妈妈每天扫描客厅，很辛苦。", "explanation": "这里应该用〈打扫〉。扫描是用仪器读取图像或文字，不指清扫房间。"}, {"text": "他把这首歌扫描到了电脑里。", "explanation": "这里应该用〈下载〉。扫描只用于图像或文字，不能用来把音乐存进电脑。"}, {"text": "他扫描了一杯果汁，一口气喝光了。", "explanation": "这里应该用〈喝〉…不，应改为“倒”：他倒了一杯果汁。扫描是用机器读取图像或文字，不能用于果汁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88129, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扫描", "is_correct": true, "explanation": "扫描：一封一封地用机器读入，与“很慢”的描述相符。"}, {"text": "踢", "is_correct": false, "explanation": "语义：“踢”以“信”为对象不合常理，句子不通。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不接“信”作宾语，“唱信”不成立。"}, {"text": "吃", "is_correct": false, "explanation": "搭配：“吃”不能与“信”搭配，“吃信”不成立。"}], "explanations": {"扫描": "扫描：一封一封地用机器读入，与“很慢”的描述相符。", "踢": "语义：“踢”以“信”为对象不合常理，句子不通。", "唱": "搭配：“唱”不接“信”作宾语，“唱信”不成立。", "吃": "搭配：“吃”不能与“信”搭配，“吃信”不成立。"}, "sentence_index": 6, "correct_answer": "扫描"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他用扫帚扫描了地板。", "explanation": "这里应该用〈清扫〉。扫描是读取图像或文字，不能用来指用扫帚清理地面。"}, {"text": "奶奶用毛巾扫描了灶台。", "explanation": "这里应该用〈擦〉。擦是用布抹去污渍，扫描不能用于清洁灶台。"}, {"text": "妈妈扫描了一碗汤，给我们喝。", "explanation": "这里应该用〈做〉（做汤）。扫描是用机器读取图像或文字，不能用于做汤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88129, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把那几本书扫描电脑里了。", "corrected_sentence": "我已经把那几本书扫描到电脑里了。", "error_description": "缺少补语“到”。正确说法是“扫描到电脑里”，用“到”引出动作的结果所在之处。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88129, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这张表我还没扫描了。", "corrected_sentence": "这张表我还没扫描。", "error_description": "错误：“还没扫描了”。正确：“还没扫描”。“还没”表示动作没有发生，后面不能再加表示完成的“了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
