INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88130, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用仪器逐点逐行地照射、读取，把图像或文字输入计算机。", "primary_collocate": null, "pronunciation": "sǎo miáo", "ipa": "sau˨˩ miau˧˥", "syllable_count": 2, "sentences": [{"text": "请把这张照片扫描一下，发给我。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用手机扫描了这份合同。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器扫描得很快，一分钟能扫十页。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他正在图书馆扫描旧报纸。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把身份证扫描以后，再上传到网站上。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这份文件太大，扫描了半个小时。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司要求大家先扫描文件，再把纸张扔掉。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她扫描完照片，就把它们存进电脑了。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书的每一页我都要扫描一遍。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你的作业可以扫描后发到我的邮箱。", "target_word": "扫描", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "扫描了", "label": "完成体"}, {"form": "扫描过", "label": "经历体"}, {"form": "扫描仪", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用仪器读取图像或文字并输入计算机", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1f19caa3-16e4-4fcd-a031-4c3dbc5187f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88130, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "扫描", "is_correct": true, "explanation": "扫描：用仪器把照片读入电脑，与后面的“发给我”衔接。"}, {"text": "撕", "is_correct": false, "explanation": "语义：撕掉照片之后就无法再发给我，与句意矛盾。"}, {"text": "扔", "is_correct": false, "explanation": "搭配：“扔”指丢掉，不能与“照片再发给我”这样的后续要求搭配。"}, {"text": "烧", "is_correct": false, "explanation": "语义：烧掉照片就没法发出去，句子读起来不通。"}], "explanations": {"扫描": "扫描：用仪器把照片读入电脑，与后面的“发给我”衔接。", "撕": "语义：撕掉照片之后就无法再发给我，与句意矛盾。", "扔": "搭配：“扔”指丢掉，不能与“照片再发给我”这样的后续要求搭配。", "烧": "语义：烧掉照片就没法发出去，句子读起来不通。"}, "sentence_index": 0, "correct_answer": "扫描"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "周末我们一起扫描了教室。", "explanation": "这里应该用〈打扫〉。扫描是用仪器读取图像或文字，不能用来清洁房间。"}, {"text": "我把这首歌扫描到了电脑里。", "explanation": "这里应该用〈下载〉。扫描只用于图像或文字，不能用来把音乐存进电脑。"}, {"text": "他在咖啡店扫描了一杯咖啡。", "explanation": "这里应该用〈买〉。扫描是用仪器读取图像或文字，不能用来指购买饮料。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88130, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "扫描", "is_correct": true, "explanation": "扫描：先把文件变成电子版，再丢掉纸张，前后意思衔接。"}, {"text": "打印", "is_correct": false, "explanation": "语义：打印会产生纸张，与“把纸张扔掉”的目的相矛盾。"}, {"text": "唱", "is_correct": false, "explanation": "搭配：“唱”不能用于文件，“唱文件”不成立。"}, {"text": "洗", "is_correct": false, "explanation": "搭配：“洗”不能用于文件，“洗文件”不成立。"}], "explanations": {"扫描": "扫描：先把文件变成电子版，再丢掉纸张，前后意思衔接。", "打印": "语义：打印会产生纸张，与“把纸张扔掉”的目的相矛盾。", "唱": "搭配：“唱”不能用于文件，“唱文件”不成立。", "洗": "搭配：“洗”不能用于文件，“洗文件”不成立。"}, "sentence_index": 6, "correct_answer": "扫描"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈用抹布扫描了桌子。", "explanation": "这里应该用〈擦〉。擦是用布抹去污渍，扫描是用仪器读取图像或文字，不能用来清洁桌面。"}, {"text": "天冷了，他扫描了一件厚毛衣穿上。", "explanation": "这里应该用〈拿〉。扫描是用仪器读取图像或文字，不能表示拿取衣物。"}, {"text": "老师用扫把扫描了讲台。", "explanation": "这里应该用〈清扫〉。扫描是读取图像或文字，不指用扫把清理地面。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88130, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我已经把这份合同扫描了完。", "corrected_sentence": "我已经把这份合同扫描完了。", "error_description": "错误：“扫描了完”。正确：“扫描完了”。结果补语“完”要紧接在动词之后，“了”放在补语之后，不能放在补语前面。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88130, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这份资料我已经扫描两遍过。", "corrected_sentence": "这份资料我已经扫描过两遍。", "error_description": "错误：“扫描两遍过”。正确：“扫描过两遍”。表示经历的“过”要紧跟在动词“扫描”后面，动量“两遍”放在“过”之后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '51a08e03-4a4a-4188-8898-bd0763341232') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88131, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "歇业", "is_correct": true, "explanation": "歇业：停止营业，与“开业”（开始营业）互为反义。"}, {"text": "出发", "is_correct": false, "explanation": "出发：指动身前往某地，与“开业”没有反义关系。"}, {"text": "散步", "is_correct": false, "explanation": "散步：指随意走走，与“开业”没有反义关系。"}, {"text": "写字", "is_correct": false, "explanation": "写字：指用笔书写文字，与“开业”没有反义关系。"}], "correct_answer": "歇业", "explanations": {"歇业": "歇业：停止营业，与“开业”（开始营业）互为反义。", "出发": "出发：指动身前往某地，与“开业”没有反义关系。", "散步": "散步：指随意走走，与“开业”没有反义关系。", "写字": "写字：指用笔书写文字，与“开业”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
