INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88131, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "开业是商店开门，开始做生意。", "primary_collocate": null, "pronunciation": "kāi yè", "ipa": "kʰaɪ˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "小店今天开业，门口摆满了花。", "target_word": "开业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老王的饭馆下个星期开业。", "target_word": "开业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想等新店开业再去买衣服。", "target_word": "开业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "开业第一天，来买东西的人很多。", "target_word": "开业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "书店开业了，我去买了两本书。", "target_word": "开业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家咖啡店刚开业，还没有名气。", "target_word": "开业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "因为下雨，蛋糕店推迟了开业时间。", "target_word": "开业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的新餐厅几点开业？", "target_word": "开业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开业前，工人们忙着打扫房间。", "target_word": "开业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "超市开业那天，所有东西都打折。", "target_word": "开业", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "开业了", "label": "体标（完成）"}, {"form": "开业典礼", "label": "复合"}, {"form": "開業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "商店开门，开始做生意", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968af400-236c-4070-b1b0-1aaf52250aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88131, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开业", "is_correct": true, "explanation": "开业：商店开门、开始做生意，与“小店今天”搭配。"}, {"text": "跑步", "is_correct": false, "explanation": "语义：小店不能跑步，与主语“小店”不相容。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：小店不会睡觉，这句读起来不通。"}, {"text": "举办", "is_correct": false, "explanation": "配价：“举办”是及物动词，需要带宾语（如“举办活动”），这里缺少宾语。"}], "explanations": {"开业": "开业：商店开门、开始做生意，与“小店今天”搭配。", "跑步": "语义：小店不能跑步，与主语“小店”不相容。", "睡觉": "语义：小店不会睡觉，这句读起来不通。", "举办": "配价：“举办”是及物动词，需要带宾语（如“举办活动”），这里缺少宾语。"}, "sentence_index": 0, "correct_answer": "开业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家便利店每天晚上十点开业，第二天早上关门。", "explanation": "这里应该用〈营业〉。开业只指开始营业的那一次，每天的营业时间要说〈营业〉。"}, {"text": "新学期开始，我们学校开业了。", "explanation": "这里应该用〈开学〉。学校开学要说〈开学〉，开业只用于商店、公司等。"}, {"text": "下周末的画展开业。", "explanation": "这里应该用〈开幕〉。画展等展览活动的开始要说〈开幕〉，不说〈开业〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88131, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开业", "is_correct": true, "explanation": "开业：店铺开始营业，与“蛋糕店推迟了……时间”搭配。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：蛋糕店不会游泳，“推迟了游泳时间”与句子语境不符。"}, {"text": "吵架", "is_correct": false, "explanation": "语义：蛋糕店推迟吵架时间没有意义，与语境不符。"}, {"text": "洗澡", "is_correct": false, "explanation": "语义：洗澡是人的动作，蛋糕店不能洗澡，“推迟了洗澡时间”与语境不符。"}], "explanations": {"开业": "开业：店铺开始营业，与“蛋糕店推迟了……时间”搭配。", "游泳": "语义：蛋糕店不会游泳，“推迟了游泳时间”与句子语境不符。", "吵架": "语义：蛋糕店推迟吵架时间没有意义，与语境不符。", "洗澡": "语义：洗澡是人的动作，蛋糕店不能洗澡，“推迟了洗澡时间”与语境不符。"}, "sentence_index": 6, "correct_answer": "开业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这档综艺节目下周一开业，大家都很期待。", "explanation": "这里应该用〈开播〉。开业用于店铺、企业，节目开始播出要说〈开播〉。"}, {"text": "这个工地下周一开业，工人们都很忙。", "explanation": "这里应该用〈开工〉。工地开始施工要说〈开工〉，不说〈开业〉。"}, {"text": "这门新课程下个月开业，报名的人很多。", "explanation": "这里应该用〈开课〉。课程开始上课要说〈开课〉，开业只用于店铺、企业等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88131, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "老王的饭馆下个月把开业。", "corrected_sentence": "老王的饭馆下个月开业。", "error_description": "“把”字句不能用于不及物动词“开业”：应去掉“把”，说“老王的饭馆下个月开业”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88131, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这家店还没开业了。", "corrected_sentence": "这家店还没开业。", "error_description": "“没”字句中不能带“了”：“还没开业”表示尚未开始营业，应去掉“了”，说“这家店还没开业”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
