INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88132, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "店铺或企业开始营业。", "primary_collocate": null, "pronunciation": "kāi yè", "ipa": "kʰaɪ˥ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "这家银行下个月开业。", "target_word": "开业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "新店今天上午十点开业。", "target_word": "开业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司开业那天，来了很多客人。", "target_word": "开业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我家附近的超市刚开业。", "target_word": "开业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "饭店开业三天了，生意很好。", "target_word": "开业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他们的花店明天开业，我要去看看。", "target_word": "开业", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "新诊所下周一开业。", "target_word": "开业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "公司准备在春天开业。", "target_word": "开业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "开业以后，老板每天都很忙。", "target_word": "开业", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "商场开业时有很多活动。", "target_word": "开业", "complexity_tier": "T1", "sentence_source": "generated"}], "morphological_forms": [{"form": "开业了", "label": "体标（完成）"}, {"form": "开业典礼", "label": "复合"}, {"form": "開業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "店铺或企业开始营业", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '968af400-236c-4070-b1b0-1aaf52250aaf') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXC