INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88132, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "开业", "is_correct": true, "explanation": "开业：店铺或企业开始营业，与“这家银行下个月”搭配。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：银行是机构，不会游泳，这句读起来不通。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：银行不能唱歌，与主语“这家银行”不相容。"}, {"text": "办理", "is_correct": false, "explanation": "配价：“办理”是及物动词，需要带宾语（如“办理业务”），这里缺少宾语。"}], "explanations": {"开业": "开业：店铺或企业开始营业，与“这家银行下个月”搭配。", "游泳": "语义：银行是机构，不会游泳，这句读起来不通。", "唱歌": "语义：银行不能唱歌，与主语“这家银行”不相容。", "办理": "配价：“办理”是及物动词，需要带宾语（如“办理业务”），这里缺少宾语。"}, "sentence_index": 0, "correct_answer": "开业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家超市每天晚上十点开业，十一点关门。", "explanation": "这里应该用〈营业〉。开业只指开始营业的那一次，每天的营业时间要说〈营业〉。"}, {"text": "下学期，我们学校开业了。", "explanation": "这里应该用〈开学〉。学校开学要说〈开学〉，开业只用于商店、公司等。"}, {"text": "下周一展览开业。", "explanation": "这里应该用〈开幕〉。展览、音乐会等活动的开始要说〈开幕〉，不说〈开业〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88132, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "开业", "is_correct": true, "explanation": "开业：店铺或企业开始营业，与“新诊所下周一”搭配。"}, {"text": "生病", "is_correct": false, "explanation": "语义：诊所是机构，不会生病，这句读起来不通。"}, {"text": "出院", "is_correct": false, "explanation": "搭配：“出院”指病人离开医院，诊所不能出院。"}, {"text": "退休", "is_correct": false, "explanation": "语义：“退休”指人停止工作，不能用于新建的诊所。"}], "explanations": {"开业": "开业：店铺或企业开始营业，与“新诊所下周一”搭配。", "生病": "语义：诊所是机构，不会生病，这句读起来不通。", "出院": "搭配：“出院”指病人离开医院，诊所不能出院。", "退休": "语义：“退休”指人停止工作，不能用于新建的诊所。"}, "sentence_index": 6, "correct_answer": "开业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个节目下周一开业，大家都很期待。", "explanation": "这里应该用〈开播〉。开业用于店铺、企业，节目开始播出要说〈开播〉。"}, {"text": "工地下周一开业，工人们都很忙。", "explanation": "这里应该用〈开工〉。工程、工地开始施工要说〈开工〉，不说〈开业〉。"}, {"text": "这门新课程下个月开业，报名的人很多。", "explanation": "这里应该用〈开课〉。课程开始上课要说〈开课〉，开业只用于店铺、企业等。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88132, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家商店下个月开业新店。", "corrected_sentence": "这家商店下个月开业。", "error_description": "错误：开业新店。正确：开业。“开业”是不及物动词，不能带宾语，多余的“新店”应去掉。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88132, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "新诊所被开业了。", "corrected_sentence": "新诊所开业了。", "error_description": "错误：被开业。正确：开业。“开业”不能用“被”字句，应说“新诊所开业了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd49623de-62a6-46c9-80de-54d676cd0681') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
