INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88133, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "铁路是火车走的路，用铁做成。", "primary_collocate": null, "pronunciation": "tiě lù", "ipa": "tʰiɛ˨˩˦ lu˥˩", "syllable_count": 2, "sentences": [{"text": "火车在铁路上跑得很快。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这段铁路是去年修好的。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路上有两条长长的铁轨。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路的旁边有一个小车站。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那条铁路通到北京。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路坏了，火车今天不开。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路上的雪太多了。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路修到了我们村。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们站在铁路边看火车。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路每天都有很多火车。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "铁路线", "label": "复合词"}, {"form": "铁路桥", "label": "复合词"}], "register": "中性", "sense_fingerprint": "火车行走的那条路，由铁轨做成", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a541dc3-3520-4439-b5c6-163a85c00558') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88133, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "铁路", "is_correct": true, "explanation": "正确：铁路（tiě lù），指火车行走的那条路。"}, {"text": "铁炉", "is_correct": false, "explanation": "铁炉（tiě lú）与铁路第二音节声调不同（lú 为第二声，lù 为第四声），意思是生铁做的炉子。"}, {"text": "铁锣", "is_correct": false, "explanation": "铁锣（tiě luó）第二音节韵母与声调都不同，意思是金属做的打击乐器。"}, {"text": "铁牢", "is_correct": false, "explanation": "铁牢（tiě láo）第二音节韵母与声调都不同，意思是坚固的牢狱。"}], "explanations": {"铁路": "正确：铁路（tiě lù），指火车行走的那条路。", "铁炉": "铁炉（tiě lú）与铁路第二音节声调不同（lú 为第二声，lù 为第四声），意思是生铁做的炉子。", "铁锣": "铁锣（tiě luó）第二音节韵母与声调都不同，意思是金属做的打击乐器。", "铁牢": "铁牢（tiě láo）第二音节韵母与声调都不同，意思是坚固的牢狱。"}, "sentence_index": null, "correct_answer": "铁路"}, "level_3": {"options": [{"text": "铁路", "is_correct": true, "explanation": "正确：火车在铁轨构成的铁路上行驶，符合语境。"}, {"text": "公路", "is_correct": false, "explanation": "语义：火车不在公路上行驶，公路是汽车走的路。"}, {"text": "跑道", "is_correct": false, "explanation": "搭配：跑道多用于飞机起降，不说火车在跑道上跑。"}, {"text": "河", "is_correct": false, "explanation": "语义：河上没有轨道，火车不能在河上跑。"}], "explanations": {"铁路": "正确：火车在铁轨构成的铁路上行驶，符合语境。", "公路": "语义：火车不在公路上行驶，公路是汽车走的路。", "跑道": "搭配：跑道多用于飞机起降，不说火车在跑道上跑。", "河": "语义：河上没有轨道，火车不能在河上跑。"}, "sentence_index": 0, "correct_answer": "铁路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们在一只铁路旁边等车。", "explanation": "这里量词应该用〈条〉，不能用〈只〉。「只」多用于动物等，铁路要用「条」来量。"}, {"text": "我们在铁路上开车去北京。", "explanation": "这里应该用〈公路〉。汽车在公路上行驶，铁路是火车走的轨道，不能开车。"}, {"text": "我们用铁路做了一把椅子。", "explanation": "这里应该用〈钢材〉。铁路是火车走的线路，不是金属材料，不能用来做椅子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88133, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "铁路", "is_correct": true, "explanation": "正确：铁路（tiě lù），指火车行走的那条路。"}, {"text": "铁律", "is_correct": false, "explanation": "铁律（tiě lǜ）第二音节韵母 ù 与 ǜ 不同（u 与 ü），意思是不可违背的规则。"}, {"text": "铁锣", "is_correct": false, "explanation": "铁锣（tiě luó）第二音节韵母与声调都不同，意思是金属做的打击乐器。"}, {"text": "铁轮", "is_correct": false, "explanation": "铁轮（tiě lún）第二音节韵尾由 u 变为 n，声调也不同，意思是铁制的轮子。"}], "explanations": {"铁路": "正确：铁路（tiě lù），指火车行走的那条路。", "铁律": "铁律（tiě lǜ）第二音节韵母 ù 与 ǜ 不同（u 与 ü），意思是不可违背的规则。", "铁锣": "铁锣（tiě luó）第二音节韵母与声调都不同，意思是金属做的打击乐器。", "铁轮": "铁轮（tiě lún）第二音节韵尾由 u 变为 n，声调也不同，意思是铁制的轮子。"}, "sentence_index": null, "correct_answer": "铁路"}, "level_3": {"options": [{"text": "铁路", "is_correct": true, "explanation": "正确：铁路上可以积雪，符合语境。"}, {"text": "书桌", "is_correct": false, "explanation": "语义：书桌一般在屋里，不会积雪。"}, {"text": "空中", "is_correct": false, "explanation": "搭配：「空中」是方位词，后面不接「上」，不说「空中上」。"}, {"text": "墨水", "is_correct": false, "explanation": "语义：墨水是液体，不会有积雪。"}], "explanations": {"铁路": "正确：铁路上可以积雪，符合语境。", "书桌": "语义：书桌一般在屋里，不会积雪。", "空中": "搭配：「空中」是方位词，后面不接「上」，不说「空中上」。", "墨水": "语义：墨水是液体，不会有积雪。"}, "sentence_index": 6, "correct_answer": "铁路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条铁路每天都停很多汽车。", "explanation": "这里应该用〈车库〉。汽车停放在车库里，铁路是火车走的轨道，不能停车。"}, {"text": "这条铁路里放着很多货。", "explanation": "这里应该用〈仓库〉。货物放在仓库里，「里」指室内空间，铁路是轨道，不能说「铁路里」。"}, {"text": "这条铁路每天都有很多飞机。", "explanation": "这里应该用〈机场〉。飞机在机场起降，铁路上行驶的是火车，没有飞机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88133, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台铁路通到了山下的小镇。", "corrected_sentence": "这条铁路通到了山下的小镇。", "error_description": "量词错误：「台」多用于机器、设备，铁路应该用量词「条」。应说「这条铁路通到了山下的小镇」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88133, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这本铁路上的积雪太多了，火车不能开。", "corrected_sentence": "这条铁路上的积雪太多了，火车不能开。", "error_description": "量词错误：「本」用于书册，铁路应该用量词「条」。应说「这条铁路上的积雪太多了，火车不能开」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
