INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88134, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "供火车行驶的轨道。", "primary_collocate": null, "pronunciation": "tiě lù", "ipa": "tʰiɛ˨˩˦ lu˥˩", "syllable_count": 2, "sentences": [{"text": "这条铁路很长。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路从山里穿过去。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路经过我家旁边。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在修新铁路。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "铁路两边有很多树。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家附近有一条铁路。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路已经用了五十年。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小孩不能在铁路上玩。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条铁路把两个城市连起来了。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们沿着铁路走了一个小时。", "target_word": "铁路", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "条", "label": "量词"}, {"form": "铁路线", "label": "复合词"}, {"form": "高速铁路", "label": "复合词"}], "register": "中性", "sense_fingerprint": "供火车行驶的轨道，可以修建、经过某地", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7a541dc3-3520-4439-b5c6-163a85c00558') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88134, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "铁路", "is_correct": true, "explanation": "正确：铁路（tiě lù），指供火车行驶的轨道。"}, {"text": "铁炉", "is_correct": false, "explanation": "铁炉（tiě lú）与铁路第二音节声调不同（lú 为第二声，lù 为第四声），意思是生铁做的炉子。"}, {"text": "铁锣", "is_correct": false, "explanation": "铁锣（tiě luó）第二音节韵母与声调都与铁路不同，意思是金属做的打击乐器。"}, {"text": "铁轮", "is_correct": false, "explanation": "铁轮（tiě lún）第二音节韵尾由 u 变为 n，声调也不同，意思是铁制的轮子。"}], "explanations": {"铁路": "正确：铁路（tiě lù），指供火车行驶的轨道。", "铁炉": "铁炉（tiě lú）与铁路第二音节声调不同（lú 为第二声，lù 为第四声），意思是生铁做的炉子。", "铁锣": "铁锣（tiě luó）第二音节韵母与声调都与铁路不同，意思是金属做的打击乐器。", "铁轮": "铁轮（tiě lún）第二音节韵尾由 u 变为 n，声调也不同，意思是铁制的轮子。"}, "sentence_index": null, "correct_answer": "铁路"}, "level_3": {"options": [{"text": "铁路", "is_correct": true, "explanation": "正确：铁路可以用量词「条」，也可以说「很长」，符合语境。"}, {"text": "杯子", "is_correct": false, "explanation": "体貌：杯子一般不是长条形的，「这条杯子很长」与它的形状不符。"}, {"text": "电话", "is_correct": false, "explanation": "搭配：电话通常用量词「通」，不说「这条电话」。"}, {"text": "硬币", "is_correct": false, "explanation": "语义：硬币不会「很长」；硬币的量词是「枚」，不说「这条硬币」。"}], "explanations": {"铁路": "正确：铁路可以用量词「条」，也可以说「很长」，符合语境。", "杯子": "体貌：杯子一般不是长条形的，「这条杯子很长」与它的形状不符。", "电话": "搭配：电话通常用量词「通」，不说「这条电话」。", "硬币": "语义：硬币不会「很长」；硬币的量词是「枚」，不说「这条硬币」。"}, "sentence_index": 0, "correct_answer": "铁路"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "工人们正在修一只新铁路。", "explanation": "这里量词应该用〈条〉，不能用〈只〉。「只」多用于动物等，铁路要用「条」来量。"}, {"text": "我每天在铁路买票。", "explanation": "这里应该用〈售票处〉。买票要去售票处，铁路是供火车行驶的轨道，不能在上面买票。"}, {"text": "我们在铁路等车。", "explanation": "这里应该用〈候车室〉。等车要在候车室或站台，铁路是轨道，人不能在上面等车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88134, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "铁路", "is_correct": true, "explanation": "正确：铁路（tiě lù），指供火车行驶的轨道。"}, {"text": "铁律", "is_correct": false, "explanation": "铁律（tiě lǜ）第二音节韵母 ù 与 ǜ 不同（u 与 ü），意思是不可违背的规则。"}, {"text": "铁锣", "is_correct": false, "explanation": "铁锣（tiě luó）第二音节韵母与声调都不同，意思是金属做的打击乐器。"}, {"text": "铁牢", "is_correct": false, "explanation": "铁牢（tiě láo）第二音节韵母与声调都不同，意思是坚固的牢狱。"}], "explanations": {"铁路": "正确：铁路（tiě lù），指供火车行驶的轨道。", "铁律": "铁律（tiě lǜ）第二音节韵母 ù 与 ǜ 不同（u 与 ü），意思是不可违背的规则。", "铁锣": "铁锣（tiě luó）第二音节韵母与声调都不同，意思是金属做的打击乐器。", "铁牢": "铁牢（tiě láo）第二音节韵母与声调都不同，意思是坚固的牢狱。"}, "sentence_index": null, "correct_answer": "铁路"}, "level_3": {"options": [{"text": "铁路", "is_correct": true, "explanation": "正确：铁路可以使用五十年，符合「已经用了」的语境。"}, {"text": "冰箱", "is_correct": false, "explanation": "搭配：冰箱的量词是「台」，不说「这条冰箱」。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：衣服的量词是「件」，不说「这条衣服」。"}, {"text": "花", "is_correct": false, "explanation": "语义：花不能「用」了五十年，「用了」多用于器物和设施。"}], "explanations": {"铁路": "正确：铁路可以使用五十年，符合「已经用了」的语境。", "冰箱": "搭配：冰箱的量词是「台」，不说「这条冰箱」。", "衣服": "搭配：衣服的量词是「件」，不说「这条衣服」。", "花": "语义：花不能「用」了五十年，「用了」多用于器物和设施。"}, "sentence_index": 6, "correct_answer": "铁路"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们在铁路里坐了一个小时。", "explanation": "这里应该用〈车厢〉。人是坐在车厢里，铁路是轨道，不是可以坐进去的空间，不能说「在铁路里」。"}, {"text": "我们沿着铁路游泳了一个小时。", "explanation": "这里应该用〈河〉。游泳要在河、湖、海里进行，铁路是火车走的轨道，不能沿着它游泳。"}, {"text": "我们开铁路去了北京。", "explanation": "这里应该用〈汽车〉。「开」接的是车辆，铁路是火车走的轨道，不能开。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88134, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张铁路通往南方。", "corrected_sentence": "这条铁路通往南方。", "error_description": "量词错误：「张」多用于平面的东西，铁路应该用量词「条」。应说「这条铁路通往南方」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88134, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台铁路穿过了那座城市。", "corrected_sentence": "这条铁路穿过了那座城市。", "error_description": "量词错误：「台」多用于机器、设备，铁路应该用量词「条」。应说「这条铁路穿过了那座城市」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '49b17db4-da70-4ffb-9036-e059ac3a09c4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88135, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "失控", "is_correct": true, "explanation": "正确：“失控”与“掌控”构成反义，指失去支配和管理的能力。"}, {"text": "散步", "is_correct": false, "explanation": "无关：“散步”指步行活动，与“掌控”没有反义关系。"}, {"text": "思考", "is_correct": false, "explanation": "无关：“思考”指用脑子进行推理，与“掌控”没有反义关系。"}, {"text": "欣赏", "is_correct": false, "explanation": "无关：“欣赏”指赞美和享受，与“掌控”没有反义关系。"}], "correct_answer": "失控", "explanations": {"失控": "正确：“失控”与“掌控”构成反义，指失去支配和管理的能力。", "散步": "无关：“散步”指步行活动，与“掌控”没有反义关系。", "思考": "无关：“思考”指用脑子进行推理，与“掌控”没有反义关系。", "欣赏": "无关：“欣赏”指赞美和享受，与“掌控”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
