INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88135, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "掌控是自己管着，能让事情照自己的想法走。", "primary_collocate": null, "pronunciation": "zhǎng kòng", "ipa": "ʈʂɑŋ˨˩ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他想掌控自己的生活。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事你要自己掌控。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她很会掌控时间。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没办法掌控明天会发生什么。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他不喜欢别人掌控他的选择。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板掌控着公司的一切。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到问题时，要学会掌控自己的心情。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比赛一开始，我们就掌控了节奏。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母不能掌控孩子的一切。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从来没有掌控过这个项目。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "掌控着", "label": "体标"}, {"form": "掌控了", "label": "体标"}, {"form": "掌控过", "label": "体标"}, {"form": "掌控力", "label": "复合"}], "register": "中性", "sense_fingerprint": "自己管着，让事情照自己的想法发展", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8a3557-0c41-45ec-8b3a-0a993a565589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_versi