INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88135, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掌控", "is_correct": true, "explanation": "正确：“掌控”表示支配和管理，与“他想……自己的生活”相合。"}, {"text": "烘烤", "is_correct": false, "explanation": "语义：“烘烤”指用火使食物变熟或变干，不能用于“自己的生活”。"}, {"text": "打听", "is_correct": false, "explanation": "搭配：“打听”的对象是消息或情况，不能说“打听自己的生活”。"}, {"text": "申请", "is_correct": false, "explanation": "搭配：“申请”的宾语是许可、名额等，不能说“申请自己的生活”。"}], "explanations": {"掌控": "正确：“掌控”表示支配和管理，与“他想……自己的生活”相合。", "烘烤": "语义：“烘烤”指用火使食物变熟或变干，不能用于“自己的生活”。", "打听": "搭配：“打听”的对象是消息或情况，不能说“打听自己的生活”。", "申请": "搭配：“申请”的宾语是许可、名额等，不能说“申请自己的生活”。"}, "sentence_index": 0, "correct_answer": "掌控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他很快掌控了游泳的技巧。", "explanation": "这里应该用〈掌握〉。“掌控”指支配或管理人和局面，学会技巧要用“掌握”。"}, {"text": "他紧紧掌控着那把伞。", "explanation": "这里应该用〈握〉。“掌控”指支配或管理，不指用手拿东西。"}, {"text": "这次考试，他掌控了所有的题目。", "explanation": "这里应该用〈做〉。“掌控”指支配或管理，答题要用“做”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88135, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掌控", "is_correct": true, "explanation": "正确：“掌控”与“自己的心情”搭配，表示情绪由自己管理。"}, {"text": "播放", "is_correct": false, "explanation": "语义：“播放”指放映或播送，不能用于“心情”。"}, {"text": "清点", "is_correct": false, "explanation": "搭配：“清点”用于数量较多的物品，不能说“清点心情”。"}, {"text": "收割", "is_correct": false, "explanation": "语义：“收割”指收取庄稼，与“心情”无关。"}], "explanations": {"掌控": "正确：“掌控”与“自己的心情”搭配，表示情绪由自己管理。", "播放": "语义：“播放”指放映或播送，不能用于“心情”。", "清点": "搭配：“清点”用于数量较多的物品，不能说“清点心情”。", "收割": "语义：“收割”指收取庄稼，与“心情”无关。"}, "sentence_index": 6, "correct_answer": "掌控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们认真掌控了这幅画的美。", "explanation": "这里应该用〈欣赏〉。“掌控”是支配和管理，不用于欣赏美感。"}, {"text": "他掌控了这杯咖啡的香味。", "explanation": "这里应该用〈闻〉。“掌控”指支配或管理，闻香气要用“闻”。"}, {"text": "他掌控了长时间的痛苦。", "explanation": "这里应该用〈忍受〉。“掌控”指支配或管理，不能用于承受痛苦。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88135, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她把时间掌控。", "corrected_sentence": "她把时间掌控好了。", "error_description": "把字句错误：“把”字句中的动词后要有补语或其他成分，应说“她把时间掌控好了”，不能只说“她把时间掌控”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
