INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88136, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "掌握并控制。", "primary_collocate": null, "pronunciation": "zhǎng kòng", "ipa": "ʈʂɑŋ˨˩ kʰʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "那家公司掌控着这个城市的水电。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察很快掌控了现场。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想掌控整个球队。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谁掌控了信息，谁就有力量。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大公司掌控着这个国家的经济。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个家族掌控着全村的土地。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生已经掌控了整个手术的进程。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他掌控不了这么大的场面。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "司机掌控着方向盘，一点也不紧张。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个游戏让玩家掌控整座城市。", "target_word": "掌控", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "掌控着", "label": "体标"}, {"form": "掌控了", "label": "体标"}, {"form": "掌控过", "label": "体标"}, {"form": "掌控力", "label": "复合"}], "register": "中性", "sense_fingerprint": "掌握住并加以控制", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8a3557-0c41-45ec-8b3a-0a993a565589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88136, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "掌控", "is_correct": true, "explanation": "正确：“掌控”表示掌握并控制，与“那家公司……水电”相合。"}, {"text": "欣赏", "is_correct": false, "explanation": "语义：“欣赏”指赞赏美好的事物，不能用于水电供应。"}, {"text": "装饰", "is_correct": false, "explanation": "搭配：“装饰”用于美化物品或房屋，不能说装饰城市的水电。"}, {"text": "聆听", "is_correct": false, "explanation": "语义：“聆听”指认真地听，水电不能被聆听。"}], "explanations": {"掌控": "正确：“掌控”表示掌握并控制，与“那家公司……水电”相合。", "欣赏": "语义：“欣赏”指赞赏美好的事物，不能用于水电供应。", "装饰": "搭配：“装饰”用于美化物品或房屋，不能说装饰城市的水电。", "聆听": "语义：“聆听”指认真地听，水电不能被聆听。"}, "sentence_index": 0, "correct_answer": "掌控"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她掌控了窗外的雨声。", "explanation": "这里应该用〈听〉。“掌控”指支配或管理，听声音要用“听”。"}, {"text": "他掌控了那只香蕉。", "explanation": "这里应该用〈剥〉。“掌控”指支配或管理，剥香蕉要用“剥”。"}, {"text": "她紧紧掌控着手里的杯子。", "explanation": "这里应该用〈握〉。“掌控”指支配或管理，不指用手拿东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88136, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "掌控", "is_correct": true, "explanation": "正确：“掌控”与“整个手术的进程”搭配，表示把握并控制。"}, {"text": "享受", "is_correct": false, "explanation": "搭配：“享受”的对象是生活或乐趣，不能说享受手术的进程。"}, {"text": "撕碎", "is_correct": false, "explanation": "语义：“撕碎”指把东西弄成碎片，与“进程”无关。"}, {"text": "烘干", "is_correct": false, "explanation": "语义：“烘干”指用热力使物体干燥，不能用于“进程”。"}], "explanations": {"掌控": "正确：“掌控”与“整个手术的进程”搭配，表示把握并控制。", "享受": "搭配：“享受”的对象是生活或乐趣，不能说享受手术的进程。", "撕碎": "语义：“撕碎”指把东西弄成碎片，与“进程”无关。", "烘干": "语义：“烘干”指用热力使物体干燥，不能用于“进程”。"}, "sentence_index": 6, "correct_answer": "掌控"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他掌控了这个春天的温暖。", "explanation": "这里应该用〈感受〉。“掌控”指支配或管理，不用于感受温暖。"}, {"text": "他掌控了这块木板。", "explanation": "这里应该用〈锯〉。“掌控”指支配或管理，锯木板要用“锯”。"}, {"text": "他掌控了这份甜点的美味。", "explanation": "这里应该用〈品尝〉。“掌控”不用于品尝滋味。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88136, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司掌控了着市场的价格。", "corrected_sentence": "这家公司掌控着市场的价格。", "error_description": "体标错误：“掌控着”表示持续状态，不能同时加“了”，应去掉“了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
