INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88137, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "陪伴是和你在一起，不让你一个人。", "primary_collocate": null, "pronunciation": "péi bàn", "ipa": "pʰei˧˥ pan˥˩", "syllable_count": 2, "sentences": [{"text": "你不开心的时候，我会陪伴你。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想陪伴你，不让你一个人难过。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷一个人住，我常去陪伴他。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她生病时，丈夫一直陪伴着她。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗陪伴我度过了孤单的日子。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别怕，今晚我陪伴你。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下班后，他总会陪伴在妈妈身边，听她讲讲一天的事。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孤独的时候，书也能陪伴我们。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们轮流陪伴着住院的老王。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我愿意陪伴你走完这一生。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "陪伴着", "label": "体标"}, {"form": "陪伴了", "label": "体标"}, {"form": "陪伴过", "label": "体标"}], "register": "通用", "sense_fingerprint": "和某人在一起，使其不孤单", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '707ca56f-bdbb-4406-b7c2-70c46bd994b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88137, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陪伴", "is_correct": true, "explanation": "「陪伴」表示和你在一起、不让你孤单，与「不开心的时候」的安慰语境相符。"}, {"text": "嘲笑", "is_correct": false, "explanation": "语义：「嘲笑」与「你不开心的时候」的安慰语境相反，句意不通。"}, {"text": "抛弃", "is_correct": false, "explanation": "语义：「抛弃」是丢下不管，与句中「我会……你」的承诺正相矛盾。"}, {"text": "惩戒", "is_correct": false, "explanation": "语域：「惩戒」语体庄重，多用于正式的赏罚场合，与这句口语化的安慰不合。"}], "explanations": {"陪伴": "「陪伴」表示和你在一起、不让你孤单，与「不开心的时候」的安慰语境相符。", "嘲笑": "语义：「嘲笑」与「你不开心的时候」的安慰语境相反，句意不通。", "抛弃": "语义：「抛弃」是丢下不管，与句中「我会……你」的承诺正相矛盾。", "惩戒": "语域：「惩戒」语体庄重，多用于正式的赏罚场合，与这句口语化的安慰不合。"}, "sentence_index": 0, "correct_answer": "陪伴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这朵白花陪伴红牡丹，把它衬得更加艳丽。", "explanation": "这里应该用〈陪衬〉。陪伴表示与人相伴，不表示用次要之物衬托主体；白花衬托红牡丹要用陪衬。"}, {"text": "士兵陪伴物资进入营地。", "explanation": "这里应该用〈护送〉。陪伴的对象是人或宠物，运送的物资要用护送。"}, {"text": "陪伴着欢呼声，比赛结束了。", "explanation": "这里应该用〈伴随〉。陪伴强调相伴的情感，欢呼声与比赛结束这样同时发生的情况要用伴随。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88137, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陪伴", "is_correct": true, "explanation": "「陪伴在」表示在妈妈身边相伴，与下班后陪妈妈聊天的温馨场景相符。"}, {"text": "工作", "is_correct": false, "explanation": "语义：句中「下班后」说明已经结束工作，再说「工作在妈妈身边」与时间矛盾。"}, {"text": "晕倒", "is_correct": false, "explanation": "语义：「晕倒」是突发的状况，与「听她讲讲一天的事」的平和场景不合。"}, {"text": "驻扎", "is_correct": false, "explanation": "语域：「驻扎」多用于军队等正式语境，与家庭中的温馨场景不合。"}], "explanations": {"陪伴": "「陪伴在」表示在妈妈身边相伴，与下班后陪妈妈聊天的温馨场景相符。", "工作": "语义：句中「下班后」说明已经结束工作，再说「工作在妈妈身边」与时间矛盾。", "晕倒": "语义：「晕倒」是突发的状况，与「听她讲讲一天的事」的平和场景不合。", "驻扎": "语域：「驻扎」多用于军队等正式语境，与家庭中的温馨场景不合。"}, "sentence_index": 6, "correct_answer": "陪伴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵陪伴边境线，日夜不离。", "explanation": "这里应该用〈守卫〉。陪伴的对象是人或宠物，防守边境线要用守卫。"}, {"text": "工人陪伴机器，检修了整整一天。", "explanation": "这里应该用〈维修〉。陪伴只表示相伴，修理、检修机器要用维修。"}, {"text": "老板陪伴工人的工作效率，时时检查有没有下降。", "explanation": "这里应该用〈关注〉。陪伴的对象是人或宠物，不能说陪伴效率；时时留意工作效率有没有下降要用关注。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88137, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "明天我会陪伴了你复查。", "corrected_sentence": "明天我会陪伴你复查。", "error_description": "错误形式：陪伴了你；正确形式：陪伴你。「会」表示将来，句中不能再加「了」表示动作已经完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88137, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我愿意陪伴过你一段时间。", "corrected_sentence": "我愿意陪伴你一段时间。", "error_description": "错误形式：陪伴过你；正确形式：陪伴你。「愿意」表示意愿或将来，「过」表示已经发生的经历，二者不能搭配，应直接用「陪伴你」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
