INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88138, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "陪同，伴随在身边。", "primary_collocate": null, "pronunciation": "péi bàn", "ipa": "pʰei˧˥ pan˥˩", "syllable_count": 2, "sentences": [{"text": "小狗一直陪伴着老人。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只猫陪伴了我十年。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爸爸陪伴孩子去医院看病。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "谢谢你一路陪伴我。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师陪伴同学们度过了毕业前的日子。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶的收音机陪伴她度过了很多夜晚。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旅途中，一首首老歌陪伴着我。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生整天陪伴在病人身边。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "父母应该多陪伴孩子成长。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "多年来，这位朋友一直陪伴在我身旁。", "target_word": "陪伴", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "陪伴着", "label": "体标"}, {"form": "陪伴了", "label": "体标"}, {"form": "陪伴过", "label": "体标"}], "register": "通用", "sense_fingerprint": "陪同并伴随在某人身边", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '707ca56f-bdbb-4406-b7c2-70c46bd994b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88138, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "陪伴", "is_correct": true, "explanation": "「陪伴」表示在身边相伴，不让老人孤单，与句意相符。"}, {"text": "抚养", "is_correct": false, "explanation": "语义：「抚养」指养育子女或需要扶养的人，老人不是被抚养的对象，句意不通。"}, {"text": "打扫", "is_correct": false, "explanation": "搭配：「打扫」的对象是房间、地面等场所或物品，不能说打扫老人。"}, {"text": "修理", "is_correct": false, "explanation": "搭配：「修理」用于机器、物品等，不能用于修理人，句子不通。"}], "explanations": {"陪伴": "「陪伴」表示在身边相伴，不让老人孤单，与句意相符。", "抚养": "语义：「抚养」指养育子女或需要扶养的人，老人不是被抚养的对象，句意不通。", "打扫": "搭配：「打扫」的对象是房间、地面等场所或物品，不能说打扫老人。", "修理": "搭配：「修理」用于机器、物品等，不能用于修理人，句子不通。"}, "sentence_index": 0, "correct_answer": "陪伴"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "三位市民陪伴法官审理这起案件。", "explanation": "这里应该用〈陪审〉。陪伴只表示与人相伴，不表示以陪审员身份参与审理；参与审理案件要用陪审。"}, {"text": "他陪伴那袋大米去了超市。", "explanation": "这里应该用〈拎〉。陪伴的对象是人或宠物，不能陪着一袋大米去超市；拿着大米去要用拎。"}, {"text": "陪伴着雷声，下起了大雨。", "explanation": "这里应该用〈伴随〉。陪伴强调相伴的情感，雷声与大雨同时出现、相随而来时应用伴随。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88138, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "陪伴", "is_correct": true, "explanation": "「陪伴着」表示老歌一路相伴、陪在我身边，与旅途中的句意相符。"}, {"text": "工作", "is_correct": false, "explanation": "语义：「工作」指做事或劳动，老歌不能工作，句意不通。"}, {"text": "晕倒", "is_correct": false, "explanation": "语义：「晕倒」是身体突然失去知觉，与老歌相伴的平和场景不合。"}, {"text": "驻扎", "is_correct": false, "explanation": "语域：「驻扎」多用于军队等正式语境，与旅途中轻松的语境不合。"}], "explanations": {"陪伴": "「陪伴着」表示老歌一路相伴、陪在我身边，与旅途中的句意相符。", "工作": "语义：「工作」指做事或劳动，老歌不能工作，句意不通。", "晕倒": "语义：「晕倒」是身体突然失去知觉，与老歌相伴的平和场景不合。", "驻扎": "语域：「驻扎」多用于军队等正式语境，与旅途中轻松的语境不合。"}, "sentence_index": 6, "correct_answer": "陪伴"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "士兵陪伴边境线，日夜不离。", "explanation": "这里应该用〈守卫〉。陪伴的对象是人或宠物，防守边境线要用守卫。"}, {"text": "工人陪伴机器，检修了整整一天。", "explanation": "这里应该用〈维修〉。陪伴只表示相伴，修理、检修机器要用维修。"}, {"text": "老板陪伴工人的工作效率，时时检查有没有下降。", "explanation": "这里应该用〈关注〉。陪伴的对象是人或宠物，不能说陪伴效率；时时留意工作效率有没有下降要用关注。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88138, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些年，她一直陪伴了在我身边。", "corrected_sentence": "这些年，她一直陪伴在我身边。", "error_description": "错误形式：陪伴了在我身边；正确形式：陪伴在我身边。「在我身边」是动词后表示处所的介词短语，「了」不能插在「陪伴」和「在」之间。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88138, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这几年，他没陪伴了我。", "corrected_sentence": "这几年，他没陪伴我。", "error_description": "错误形式：没陪伴了我；正确形式：没陪伴我。「没」表示否定，不能与表示完成的「了」同用，应去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
