INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88141, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "难道是用在问句里，表示你不应该这样想。", "primary_collocate": null, "pronunciation": "nán dào", "ipa": "nan˧˥ tɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "你难道不知道今天要考试吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难道你忘了我们的约定吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么简单的题，难道你不会做吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难道他一点儿也不担心吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难道你想一个人去吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气这么冷，难道你不穿外套吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难道这件事是我一个人的错吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天都学习，难道还不够努力吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难道你不想回家看看爸爸妈妈吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难道我说得不对吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "用在问句里，表示不应该这样想的反问副词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7334b5cb-6336-4b25-86db-f1f85bdb5c03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88141, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "难道", "is_correct": true, "explanation": "正确：难道 nán dào，用于反问，表示你不应该这样想。"}, {"text": "难倒", "is_correct": false, "explanation": "第二音节声调不同：dǎo（第三声）与 dào（第四声）不同，意思是使人无法应对。"}, {"text": "拿到", "is_correct": false, "explanation": "第一音节去掉了韵尾 n：ná 与 nán 不同，意思是取得、握住。"}, {"text": "难逃", "is_correct": false, "explanation": "第二音节不同：táo（声母 t，第二声）与 dào（声母 d，第四声）不同，意思是难以逃脱。"}], "explanations": {"难道": "正确：难道 nán dào，用于反问，表示你不应该这样想。", "难倒": "第二音节声调不同：dǎo（第三声）与 dào（第四声）不同，意思是使人无法应对。", "拿到": "第一音节去掉了韵尾 n：ná 与 nán 不同，意思是取得、握住。", "难逃": "第二音节不同：táo（声母 t，第二声）与 dào（声母 d，第四声）不同，意思是难以逃脱。"}, "sentence_index": null, "correct_answer": "难道"}, "level_3": {"options": [{"text": "难道", "is_correct": true, "explanation": "正确：难道用于反问，说你不知道今天要考试是不应该的。"}, {"text": "已经", "is_correct": false, "explanation": "语义：“已经”表示时间上已经发生，与“今天要考试”的反问语境不合。"}, {"text": "刚刚", "is_correct": false, "explanation": "语义：“刚刚”指不久前发生，不能表示反问的态度。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示进行中的动作，“不知道”是状态，不能用进行体。"}], "explanations": {"难道": "正确：难道用于反问，说你不知道今天要考试是不应该的。", "已经": "语义：“已经”表示时间上已经发生，与“今天要考试”的反问语境不合。", "刚刚": "语义：“刚刚”指不久前发生，不能表示反问的态度。", "正在": "体貌：“正在”表示进行中的动作，“不知道”是状态，不能用进行体。"}, "sentence_index": 0, "correct_answer": "难道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我明天难道去北京出差，行程已经定好了。", "explanation": "这里应该用〈将要〉。难道用于反问，不能陈述已经定好的将来行程；陈述将来要发生的事要用将要。"}, {"text": "我们下周难道搬到新家去住。", "explanation": "这里应该用〈打算〉。难道用于反问，不能陈述自己的计划；陈述计划要用打算。"}, {"text": "这份报告我难道今天交上去。", "explanation": "这里应该用〈应该〉。难道用于反问，不能陈述该做的事；陈述应当做的事要用应该。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88141, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "难道", "is_correct": true, "explanation": "正确：难道 nán dào，用于反问，表示你不应该这样想。"}, {"text": "南岛", "is_correct": false, "explanation": "第二音节声调不同：dǎo（第三声）与 dào（第四声）不同，意思是南方的岛屿。"}, {"text": "谈到", "is_correct": false, "explanation": "第一音节声母不同：tán 与 nán 的声母不同，意思是提到、谈论。"}, {"text": "难逃", "is_correct": false, "explanation": "第二音节不同：táo（声母 t，第二声）与 dào（声母 d，第四声）不同，意思是难以逃脱。"}], "explanations": {"难道": "正确：难道 nán dào，用于反问，表示你不应该这样想。", "南岛": "第二音节声调不同：dǎo（第三声）与 dào（第四声）不同，意思是南方的岛屿。", "谈到": "第一音节声母不同：tán 与 nán 的声母不同，意思是提到、谈论。", "难逃": "第二音节不同：táo（声母 t，第二声）与 dào（声母 d，第四声）不同，意思是难以逃脱。"}, "sentence_index": null, "correct_answer": "难道"}, "level_3": {"options": [{"text": "难道", "is_correct": true, "explanation": "正确：难道用于反问，认为这件事不应该只怪我一个人。"}, {"text": "果然", "is_correct": false, "explanation": "语义：“果然”表示与预期相符、事实被证实，与带质疑语气的反问不合。"}, {"text": "幸好", "is_correct": false, "explanation": "语义：“幸好”表示庆幸，与“是我一个人的错”的质疑语气不合，句意不通。"}, {"text": "诚然", "is_correct": false, "explanation": "语域：“诚然”是书面语，表示承认，与口语反问不合，句意不通。"}], "explanations": {"难道": "正确：难道用于反问，认为这件事不应该只怪我一个人。", "果然": "语义：“果然”表示与预期相符、事实被证实，与带质疑语气的反问不合。", "幸好": "语义：“幸好”表示庆幸，与“是我一个人的错”的质疑语气不合，句意不通。", "诚然": "语域：“诚然”是书面语，表示承认，与口语反问不合，句意不通。"}, "sentence_index": 6, "correct_answer": "难道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "周末的聚会，我难道请大家来我家吃饭。", "explanation": "这里应该用〈邀请〉。难道用于反问，不能陈述主动发出邀请的事实；发出邀请要用邀请。"}, {"text": "我每个周末难道都去跑步。", "explanation": "这里应该用〈经常〉。难道用于反问，不能陈述习惯性的重复；陈述经常发生的事要用经常。"}, {"text": "我这个学期难道去国外留学。", "explanation": "这里应该用〈准备〉。难道用于反问，不能陈述自己的计划；陈述即将做的事要用准备。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88141, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "难道你不想吃饭吧？", "corrected_sentence": "难道你不想吃饭吗？", "error_description": "“难道”引出的反问句末应用语气词“吗”，“吧”表示推测或商量，与反问语气不合；应为“难道你不想吃饭吗？”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88141, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "难道也你不想喝杯茶吗？", "corrected_sentence": "难道你不想喝杯茶吗？", "error_description": "“也”不能放在“难道”和主语“你”之间；正确说法是“难道你不想喝杯茶吗？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
