INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88142, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，加强反问语气。", "primary_collocate": null, "pronunciation": "nán dào", "ipa": "nan˧˥ tɑʊ̯˥˩", "syllable_count": 2, "sentences": [{"text": "难道这就是你的办法？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难道要我一个人做完所有的工作？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难道你要放弃了吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难道他不是你的朋友吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我都说了三次，难道你还没听懂？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这么晚了，难道你还不睡觉吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难道钱比健康还重要吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难道你没看见门口的牌子吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难道我们只能在这儿一直等吗？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "难道他真的不知道这件事？", "target_word": "难道", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "加强反问语气的副词，句末可不带吗", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7334b5cb-6336-4b25-86db-f1f85bdb5c03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88142, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "难道", "is_correct": true, "explanation": "正确：难道 nán dào，加强反问语气。"}, {"text": "难倒", "is_correct": false, "explanation": "第二音节声调不同：dǎo（第三声）与 dào（第四声）不同，意思是使人无法应对。"}, {"text": "拿到", "is_correct": false, "explanation": "第一音节去掉了韵尾 n：ná 与 nán 不同，意思是取得、握住。"}, {"text": "难逃", "is_correct": false, "explanation": "第二音节不同：táo（声母 t，第二声）与 dào（声母 d，第四声）不同，意思是难以逃脱。"}], "explanations": {"难道": "正确：难道 nán dào，加强反问语气。", "难倒": "第二音节声调不同：dǎo（第三声）与 dào（第四声）不同，意思是使人无法应对。", "拿到": "第一音节去掉了韵尾 n：ná 与 nán 不同，意思是取得、握住。", "难逃": "第二音节不同：táo（声母 t，第二声）与 dào（声母 d，第四声）不同，意思是难以逃脱。"}, "sentence_index": null, "correct_answer": "难道"}, "level_3": {"options": [{"text": "难道", "is_correct": true, "explanation": "正确：难道加强反问语气，语气中不认可“你的办法”。"}, {"text": "正在", "is_correct": false, "explanation": "体貌：“正在”表示动作进行，不能用于表示判断的“这就是”。"}, {"text": "正好", "is_correct": false, "explanation": "语义：“正好”表示恰巧，不能表示质疑“办法”的反问。"}, {"text": "偶尔", "is_correct": false, "explanation": "语义：“偶尔”表示不常发生，与“这就是你的办法”的判断语境不合。"}], "explanations": {"难道": "正确：难道加强反问语气，语气中不认可“你的办法”。", "正在": "体貌：“正在”表示动作进行，不能用于表示判断的“这就是”。", "正好": "语义：“正好”表示恰巧，不能表示质疑“办法”的反问。", "偶尔": "语义：“偶尔”表示不常发生，与“这就是你的办法”的判断语境不合。"}, "sentence_index": 0, "correct_answer": "难道"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们明天难道出发去机场。", "explanation": "这里应该用〈准备〉。难道用于反问，不能陈述即将进行的行动；陈述即将做的事要用准备。"}, {"text": "我每天难道都去健身房。", "explanation": "这里应该用〈经常〉。难道用于反问，不能陈述经常性的习惯；陈述经常发生的事要用经常。"}, {"text": "这次考试我难道考第一。", "explanation": "这里应该用〈希望〉。难道用于反问，不能陈述自己的愿望；表达愿望要用希望。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88142, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "难道", "is_correct": true, "explanation": "正确：难道 nán dào，加强反问语气。"}, {"text": "南岛", "is_correct": false, "explanation": "第二音节声调不同：dǎo（第三声）与 dào（第四声）不同，意思是南方的岛屿。"}, {"text": "谈到", "is_correct": false, "explanation": "第一音节声母不同：tán 与 nán 的声母不同，意思是提到、谈论。"}, {"text": "难逃", "is_correct": false, "explanation": "第二音节不同：táo（声母 t，第二声）与 dào（声母 d，第四声）不同，意思是难以逃脱。"}], "explanations": {"难道": "正确：难道 nán dào，加强反问语气。", "南岛": "第二音节声调不同：dǎo（第三声）与 dào（第四声）不同，意思是南方的岛屿。", "谈到": "第一音节声母不同：tán 与 nán 的声母不同，意思是提到、谈论。", "难逃": "第二音节不同：táo（声母 t，第二声）与 dào（声母 d，第四声）不同，意思是难以逃脱。"}, "sentence_index": null, "correct_answer": "难道"}, "level_3": {"options": [{"text": "难道", "is_correct": true, "explanation": "正确：难道加强反问语气，认为钱不应该比健康更重要。"}, {"text": "诚然", "is_correct": false, "explanation": "语域：“诚然”是书面语，表示承认，与口语反问不合。"}, {"text": "偏偏", "is_correct": false, "explanation": "语义：“偏偏”表示偏巧或故意，与此句反问的语境不合。"}, {"text": "忽然", "is_correct": false, "explanation": "语义：“忽然”表示突然发生，与比较钱和健康的反问不合。"}], "explanations": {"难道": "正确：难道加强反问语气，认为钱不应该比健康更重要。", "诚然": "语域：“诚然”是书面语，表示承认，与口语反问不合。", "偏偏": "语义：“偏偏”表示偏巧或故意，与此句反问的语境不合。", "忽然": "语义：“忽然”表示突然发生，与比较钱和健康的反问不合。"}, "sentence_index": 6, "correct_answer": "难道"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑我难道下个月买。", "explanation": "这里应该用〈打算〉。难道用于反问，不能陈述自己的计划；陈述计划要用打算。"}, {"text": "他难道每个月都去一次银行。", "explanation": "这里应该用〈经常〉。难道用于反问，不能陈述经常性的重复；陈述经常发生的事要用经常。"}, {"text": "他难道跑去车站接人。", "explanation": "这里应该用〈立即〉。难道用于反问，不能陈述即刻的行动；表示立即去做要用立即。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88142, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "难道你还要这样下去吧？", "corrected_sentence": "难道你还要这样下去吗？", "error_description": "“难道”引出的反问句末应用语气词“吗”，“吧”表示推测或商量，与反问语气不合；应为“难道你还要这样下去吗？”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88142, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "难道也你还不明白吗？", "corrected_sentence": "难道你还不明白吗？", "error_description": "“也”不能放在“难道”和主语“你”之间；正确说法是“难道你还不明白吗？”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
