INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88143, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雕像是用石头或木头刻出来的人或动物。", "primary_collocate": null, "pronunciation": "diāo xiàng", "ipa": "tiɑʊ˥ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "公园里有一座石头雕像。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上放着一个小小的木头雕像。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "广场中间的雕像是一位老人。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "门口的石头雕像像一只大狗。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个雕像用石头刻成，已经有五百年了。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "游客在雕像前面拍照。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送给我一个木头小鸟雕像。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座雕像刻的是一个正在读书的男孩。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨以后，雕像上全是水。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雕像的一只手断了，真可惜。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座雕像", "label": "量词"}, {"form": "一尊雕像", "label": "量词"}], "register": "中性", "sense_fingerprint": "用石头或木头刻成的人或动物的像", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d977b55-e838-4148-b0e4-160dae9a063e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88143, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雕像", "is_correct": true, "explanation": "正确：“石头雕像”指用石头刻成的人或动物的像，符合句意。"}, {"text": "面包", "is_correct": false, "explanation": "语义：面包是食物，不是石头做的雕塑，“石头面包”说不通。"}, {"text": "书包", "is_correct": false, "explanation": "搭配：书包是装书的袋子，不能用“座”计量，也不能说“一座石头书包”。"}, {"text": "雨伞", "is_correct": false, "explanation": "搭配：雨伞是遮雨的用具，不能说“一座石头雨伞”。"}], "explanations": {"雕像": "正确：“石头雕像”指用石头刻成的人或动物的像，符合句意。", "面包": "语义：面包是食物，不是石头做的雕塑，“石头面包”说不通。", "书包": "搭配：书包是装书的袋子，不能用“座”计量，也不能说“一座石头书包”。", "雨伞": "搭配：雨伞是遮雨的用具，不能说“一座石头雨伞”。"}, "sentence_index": 0, "correct_answer": "雕像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他把照片装进了雕像。", "explanation": "这里应该用〈相框〉。照片要装进相框；雕像是人或动物的立体造型，不能用来装照片。"}, {"text": "院子里种着很多雕像。", "explanation": "这里应该用〈花〉。“种”用于植物，雕像不能种；院子里种的是花草。"}, {"text": "天冷了，我把雕像穿在身上。", "explanation": "这里应该用〈大衣〉。雕像是石头或木头刻成的像，不能穿在身上；天冷穿的是大衣。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88143, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雕像", "is_correct": true, "explanation": "正确：“木头小鸟雕像”指用木头刻成的小鸟的像，符合句意。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕是食物，“木头小鸟蛋糕”不是送礼物时的说法。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：牛奶以杯或瓶计量，不能说“一个木头小鸟牛奶”。"}, {"text": "雨衣", "is_correct": false, "explanation": "语义：雨衣是穿在身上的衣服，不可能是用木头刻成的小鸟。"}], "explanations": {"雕像": "正确：“木头小鸟雕像”指用木头刻成的小鸟的像，符合句意。", "蛋糕": "语义：蛋糕是食物，“木头小鸟蛋糕”不是送礼物时的说法。", "牛奶": "搭配：牛奶以杯或瓶计量，不能说“一个木头小鸟牛奶”。", "雨衣": "语义：雨衣是穿在身上的衣服，不可能是用木头刻成的小鸟。"}, "sentence_index": 6, "correct_answer": "雕像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我昨天在书店买了一本雕像。", "explanation": "这里应该用〈尊〉。“本”用于书籍和册子，雕像不能用“本”计量。"}, {"text": "他家里放着一台雕像。", "explanation": "这里应该用〈尊〉。“台”用于机器和电器，雕像不能用“台”计量。"}, {"text": "我在河边捡了很多雕像。", "explanation": "这里应该用〈石头〉。雕像是人工雕刻的作品，不会在河边随便捡到；河边捡到的是石头。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88143, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在博物馆看到了三只雕像。", "corrected_sentence": "我在博物馆看到了三座雕像。", "error_description": "量词错误：雕像应用“座”或“尊”计量，“三只”应改为“三座”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88143, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座雕像刻很精致。", "corrected_sentence": "这座雕像刻得很精致。", "error_description": "补语标记“得”缺失。错误形式是“刻很精致”，正确形式是“刻得很精致”。“得”连接动词和补语，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
