INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88144, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用石、木、金属等材料雕刻而成的人或物的形象。", "primary_collocate": null, "pronunciation": "diāo xiàng", "ipa": "tiɑʊ˥ ɕiɑŋ˥˩", "syllable_count": 2, "sentences": [{"text": "广场上立着一座金属雕像。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座雕像是为了纪念一位老科学家。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校门口新立了一座雕像。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们正在给雕像擦灰。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位艺术家用木头做了一尊雕像。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "博物馆里有石头、木头和金属做的雕像。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这尊雕像高三米，站在山顶上。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把小雕像放在书架上。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了保护雕像，人们不让游客爬上去。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "城市中心的雕像是为纪念名人做的。", "target_word": "雕像", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一座雕像", "label": "量词"}, {"form": "一尊雕像", "label": "量词"}], "register": "中性", "sense_fingerprint": "用石、木、金属等雕刻成的人或物的形象", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d977b55-e838-4148-b0e4-160dae9a063e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88144, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "雕像", "is_correct": true, "explanation": "正确：“金属雕像”指用金属雕刻成的人或物的形象，符合句意。"}, {"text": "冰块", "is_correct": false, "explanation": "语义：冰块和金属是互相矛盾的材料，句子已经说明是金属。"}, {"text": "窗帘", "is_correct": false, "explanation": "搭配：窗帘挂在窗上，不能说“立着一座金属窗帘”。"}, {"text": "课本", "is_correct": false, "explanation": "搭配：课本是书，不能立在广场上，也不能用“座”计量。"}], "explanations": {"雕像": "正确：“金属雕像”指用金属雕刻成的人或物的形象，符合句意。", "冰块": "语义：冰块和金属是互相矛盾的材料，句子已经说明是金属。", "窗帘": "搭配：窗帘挂在窗上，不能说“立着一座金属窗帘”。", "课本": "搭配：课本是书，不能立在广场上，也不能用“座”计量。"}, "sentence_index": 0, "correct_answer": "雕像"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在商店买了一把雕像。", "explanation": "这里应该用〈尊〉或〈座〉。“把”用于有柄的器具或椅子，雕像不能用“把”计量。"}, {"text": "他在院子里种了一尊雕像。", "explanation": "这里应该用〈树〉。“种”用于树木和花草，雕像是人造的作品，不能种。"}, {"text": "他把照片装进了雕像。", "explanation": "这里应该用〈相框〉。照片要放进相框；雕像是立体造型，不能用来装照片。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88144, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "雕像", "is_correct": true, "explanation": "正确：“这尊雕像”指一个人或物的雕刻形象，可以高三米、站在山顶上。"}, {"text": "饭团", "is_correct": false, "explanation": "语义：饭团是食物，不会高三米，也不会站在山顶上。"}, {"text": "饼干", "is_correct": false, "explanation": "语义：饼干是食品，不能站在山顶上。"}, {"text": "牛奶", "is_correct": false, "explanation": "搭配：牛奶以杯或瓶计量，“尊”不能用于牛奶。"}], "explanations": {"雕像": "正确：“这尊雕像”指一个人或物的雕刻形象，可以高三米、站在山顶上。", "饭团": "语义：饭团是食物，不会高三米，也不会站在山顶上。", "饼干": "语义：饼干是食品，不能站在山顶上。", "牛奶": "搭配：牛奶以杯或瓶计量，“尊”不能用于牛奶。"}, "sentence_index": 6, "correct_answer": "雕像"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他家的电视机旁放着一台雕像。", "explanation": "这里应该用〈尊〉。“台”用于机器和电器，雕像不能用“台”计量。"}, {"text": "我在路边捡到了很多雕像。", "explanation": "这里应该用〈石头〉。雕像是人工雕刻的作品，不会在路边随便捡到；路边捡到的是石头。"}, {"text": "我昨天在书店买了一本雕像。", "explanation": "这里应该用〈尊〉。“本”用于书籍和册子，雕像不能用“本”计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88144, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这张雕像是用木头做的。", "corrected_sentence": "这尊雕像是用木头做的。", "error_description": "量词错误：雕像应用“尊”或“座”计量，“这张”应改为“这尊”；“张”用于平面的东西。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88144, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这座金属雕像刻很精细。", "corrected_sentence": "这座金属雕像刻得很精细。", "error_description": "补语标记“得”缺失。错误形式是“刻很精细”，正确形式是“刻得很精细”。“得”连接动词和补语，不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
