INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88145, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "紧急是事情很急，马上就要做，不能等。", "primary_collocate": null, "pronunciation": "jǐn jí", "ipa": "tɕin˨˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这件事很紧急，请马上处理。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我有紧急的事，要先走了。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "情况紧急，大家快点来。", "target_word": "紧急", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他接到一个紧急电话，马上出门了。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这份文件不紧急，明天再看也可以。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老板开了一个紧急会议。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "事情这么紧急，你怎么还不去？", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "紧急的时候，要先给家人打电话。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她有紧急的工作，今晚不能休息。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这封信很紧急，请你今天送到。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容事情很急，必须马上去做、不能拖延", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7334b5cb-6336-4b25-86db-f1f85bdb5c03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88145, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "紧急", "is_correct": true, "explanation": "正确：紧急 jǐnjí，事情很急，需要马上处理。"}, {"text": "紧记", "is_correct": false, "explanation": "第二音节声调不同：jì（第四声）与 jí（第二声）不同，意思是牢牢记住。"}, {"text": "锦鸡", "is_correct": false, "explanation": "第二音节声调不同：jī（第一声）与 jí（第二声）不同，意思是锦鸡，一种鸟。"}, {"text": "进击", "is_correct": false, "explanation": "两个音节的声调都不同：jìn（第四声）、jī（第一声），意思是向敌人发起攻击。"}, {"text": "金鸡", "is_correct": false, "explanation": "两个音节的声调都不同：jīn（第一声）、jī（第一声），意思是金色的公鸡。"}], "explanations": {"紧急": "正确：紧急 jǐnjí，事情很急，需要马上处理。", "紧记": "第二音节声调不同：jì（第四声）与 jí（第二声）不同，意思是牢牢记住。", "锦鸡": "第二音节声调不同：jī（第一声）与 jí（第二声）不同，意思是锦鸡，一种鸟。", "进击": "两个音节的声调都不同：jìn（第四声）、jī（第一声），意思是向敌人发起攻击。", "金鸡": "两个音节的声调都不同：jīn（第一声）、jī（第一声），意思是金色的公鸡。"}, "sentence_index": null, "correct_answer": "紧急"}, "level_3": {"options": [{"text": "紧急", "is_correct": true, "explanation": "正确：紧急说事情很急，需要马上处理，与“请马上处理”相符。"}, {"text": "缓慢", "is_correct": false, "explanation": "语义：缓慢说速度慢，与“请马上处理”的急迫要求相反。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”多用于人或环境，不说事情很安静。"}, {"text": "悠闲", "is_correct": false, "explanation": "搭配：“悠闲”形容人的状态，不能用来说事情很悠闲。"}], "explanations": {"紧急": "正确：紧急说事情很急，需要马上处理，与“请马上处理”相符。", "缓慢": "语义：缓慢说速度慢，与“请马上处理”的急迫要求相反。", "安静": "搭配：“安静”多用于人或环境，不说事情很安静。", "悠闲": "搭配：“悠闲”形容人的状态，不能用来说事情很悠闲。"}, "sentence_index": 0, "correct_answer": "紧急"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "听到消息后，他很紧急，马上给妈妈打电话。", "explanation": "这里应该用〈着急〉。紧急形容事情需要马上处理，人心里焦躁要用着急。"}, {"text": "昨天我看了一部很紧急的电影，心一直跳得很快。", "explanation": "这里应该用〈紧张〉。紧急形容事情需要马上处理，电影情节让人心里绷紧要用紧张。"}, {"text": "他紧急地等待医生的结果。", "explanation": "这里应该用〈急切〉。紧急指事情需要马上处理，迫切盼望的样子要用急切。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88145, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "紧急", "is_correct": true, "explanation": "正确：紧急 jǐnjí，事情很急，需要马上处理。"}, {"text": "禁忌", "is_correct": false, "explanation": "两个音节的声调都不同：jìn（第四声）、jì（第四声），意思是不能触犯的事物或言行。"}, {"text": "进级", "is_correct": false, "explanation": "第一音节声调不同：jìn（第四声）与 jǐn（第三声）不同，意思是升到更高的级别。"}, {"text": "晋级", "is_correct": false, "explanation": "第一音节声调不同：jìn（第四声）与 jǐn（第三声）不同，意思是升到更高的级别或进入下一轮比赛。"}], "explanations": {"紧急": "正确：紧急 jǐnjí，事情很急，需要马上处理。", "禁忌": "两个音节的声调都不同：jìn（第四声）、jì（第四声），意思是不能触犯的事物或言行。", "进级": "第一音节声调不同：jìn（第四声）与 jǐn（第三声）不同，意思是升到更高的级别。", "晋级": "第一音节声调不同：jìn（第四声）与 jǐn（第三声）不同，意思是升到更高的级别或进入下一轮比赛。"}, "sentence_index": null, "correct_answer": "紧急"}, "level_3": {"options": [{"text": "紧急", "is_correct": true, "explanation": "正确：紧急说事情急，与“你怎么还不去”的催促语气相合。"}, {"text": "清闲", "is_correct": false, "explanation": "搭配：“清闲”形容人或时间空闲，不能说事情很清闲。"}, {"text": "从容", "is_correct": false, "explanation": "搭配：“从容”形容人的态度，事情不能说从容。"}, {"text": "随意", "is_correct": false, "explanation": "语义：“随意”说态度随便，与“你怎么还不去”的催促不合。"}], "explanations": {"紧急": "正确：紧急说事情急，与“你怎么还不去”的催促语气相合。", "清闲": "搭配：“清闲”形容人或时间空闲，不能说事情很清闲。", "从容": "搭配：“从容”形容人的态度，事情不能说从容。", "随意": "语义：“随意”说态度随便，与“你怎么还不去”的催促不合。"}, "sentence_index": 6, "correct_answer": "紧急"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这次考试很紧急，你一定要认真准备。", "explanation": "这里应该用〈重要〉。紧急指事情需要马上处理，说事情的重要性要用重要。"}, {"text": "他的呼吸很紧急，好像跑了很远的路。", "explanation": "这里应该用〈急促〉。紧急形容事情的状况，呼吸快要用急促。"}, {"text": "他脾气很紧急，大家都不敢跟他说话。", "explanation": "这里应该用〈急躁〉。紧急形容事情，人的脾气要用急躁。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88145, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个问题是紧急，需要今天解决。", "corrected_sentence": "这个问题很紧急，需要今天解决。", "error_description": "形容词“紧急”作谓语前应加程度副词“很”，不能用“是”直接接形容词；应为“很紧急”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88145, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事情紧急下来了，我们得马上行动。", "corrected_sentence": "事情紧急起来了，我们得马上行动。", "error_description": "“紧急”后应接趋向补语“起来”，表示情况开始变得急迫；说“紧急下来”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
