INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88146, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "情况危急，需要立即处理。", "primary_collocate": null, "pronunciation": "jǐn jí", "ipa": "tɕin˨˩ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "医院收到紧急通知，医生马上赶来了。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "发生火灾时，要拨打紧急电话。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "河水太高，村里发出紧急警报。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "地震后，紧急救援队很快到了。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "病人情况紧急，必须马上做手术。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "情况紧急时，请从楼梯左边走。", "target_word": "紧急", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这是紧急情况，请不要慌。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他突然发病，情况非常紧急。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "桥坏了，情况很紧急，要马上修。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "紧急的时候，不要用电梯。", "target_word": "紧急", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容情况危急、需要立即采取措施应对", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7334b5cb-6336-4b25-86db-f1f85bdb5c03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88146, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "紧急", "is_correct": true, "explanation": "正确：紧急 jǐnjí，情况危急，需要立即处理。"}, {"text": "紧记", "is_correct": false, "explanation": "第二音节声调不同：jì（第四声）与 jí（第二声）不同，意思是牢牢记住。"}, {"text": "锦鸡", "is_correct": false, "explanation": "第二音节声调不同：jī（第一声）与 jí（第二声）不同，意思是锦鸡，一种鸟。"}, {"text": "进击", "is_correct": false, "explanation": "两个音节的声调都不同：jìn（第四声）、jī（第一声），意思是向敌人发起攻击。"}, {"text": "金鸡", "is_correct": false, "explanation": "两个音节的声调都不同：jīn（第一声）、jī（第一声），意思是金色的公鸡。"}], "explanations": {"紧急": "正确：紧急 jǐnjí，情况危急，需要立即处理。", "紧记": "第二音节声调不同：jì（第四声）与 jí（第二声）不同，意思是牢牢记住。", "锦鸡": "第二音节声调不同：jī（第一声）与 jí（第二声）不同，意思是锦鸡，一种鸟。", "进击": "两个音节的声调都不同：jìn（第四声）、jī（第一声），意思是向敌人发起攻击。", "金鸡": "两个音节的声调都不同：jīn（第一声）、jī（第一声），意思是金色的公鸡。"}, "sentence_index": null, "correct_answer": "紧急"}, "level_3": {"options": [{"text": "紧急", "is_correct": true, "explanation": "正确：紧急形容情况危急，需要立即处理，与“马上赶来”相合。"}, {"text": "缓慢", "is_correct": false, "explanation": "搭配：“缓慢”说速度慢，不能修饰“通知”，也与“马上赶来”不合。"}, {"text": "安静", "is_correct": false, "explanation": "搭配：“安静”不用来形容通知。"}, {"text": "空闲", "is_correct": false, "explanation": "搭配：“空闲”形容人或时间有空，不能修饰通知。"}], "explanations": {"紧急": "正确：紧急形容情况危急，需要立即处理，与“马上赶来”相合。", "缓慢": "搭配：“缓慢”说速度慢，不能修饰“通知”，也与“马上赶来”不合。", "安静": "搭配：“安静”不用来形容通知。", "空闲": "搭配：“空闲”形容人或时间有空，不能修饰通知。"}, "sentence_index": 0, "correct_answer": "紧急"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "面对评委的提问，他紧急得说不出话来。", "explanation": "这里应该用〈慌张〉。紧急形容事情需要马上处理，人在突发情况下惊慌失措的状态要用慌张。"}, {"text": "球赛的比分很紧急。", "explanation": "这里应该用〈紧张〉。紧急形容事情需要立即处理，比分胶着、气氛激烈要用紧张。"}, {"text": "他的呼吸很紧急。", "explanation": "这里应该用〈急促〉。紧急形容事情的状况，呼吸快要用急促。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88146, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "紧急", "is_correct": true, "explanation": "正确：紧急 jǐnjí，情况危急，需要立即处理。"}, {"text": "禁忌", "is_correct": false, "explanation": "两个音节的声调都不同：jìn（第四声）、jì（第四声），意思是不能触犯的事物或言行。"}, {"text": "进级", "is_correct": false, "explanation": "第一音节声调不同：jìn（第四声）与 jǐn（第三声）不同，意思是升到更高的级别。"}, {"text": "晋级", "is_correct": false, "explanation": "第一音节声调不同：jìn（第四声）与 jǐn（第三声）不同，意思是升到更高的级别或进入下一轮比赛。"}], "explanations": {"紧急": "正确：紧急 jǐnjí，情况危急，需要立即处理。", "禁忌": "两个音节的声调都不同：jìn（第四声）、jì（第四声），意思是不能触犯的事物或言行。", "进级": "第一音节声调不同：jìn（第四声）与 jǐn（第三声）不同，意思是升到更高的级别。", "晋级": "第一音节声调不同：jìn（第四声）与 jǐn（第三声）不同，意思是升到更高的级别或进入下一轮比赛。"}, "sentence_index": null, "correct_answer": "紧急"}, "level_3": {"options": [{"text": "紧急", "is_correct": true, "explanation": "正确：紧急情况指情况危急，需要冷静应对，与“请不要慌”相合。"}, {"text": "缓慢", "is_correct": false, "explanation": "语义：“缓慢”说速度慢，与“紧急情况”的危急语义不合。"}, {"text": "悠闲", "is_correct": false, "explanation": "搭配：“悠闲”形容人的状态，不能说“悠闲情况”。"}, {"text": "清闲", "is_correct": false, "explanation": "搭配：“清闲”形容人或时间空闲，不能修饰情况。"}], "explanations": {"紧急": "正确：紧急情况指情况危急，需要冷静应对，与“请不要慌”相合。", "缓慢": "语义：“缓慢”说速度慢，与“紧急情况”的危急语义不合。", "悠闲": "搭配：“悠闲”形容人的状态，不能说“悠闲情况”。", "清闲": "搭配：“清闲”形容人或时间空闲，不能修饰情况。"}, "sentence_index": 6, "correct_answer": "紧急"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他性格很紧急，说话总是很快。", "explanation": "这里应该用〈急躁〉。紧急形容事情，人的性格要用急躁。"}, {"text": "听到消息后，他心里很紧急。", "explanation": "这里应该用〈慌乱〉。紧急形容事情，人心里乱的状态要用慌乱。"}, {"text": "他每天都很紧急，几乎没有休息。", "explanation": "这里应该用〈忙碌〉。紧急形容事情，人的忙碌状态要用忙碌。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88146, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这里的情况是紧急，请大家马上撤离。", "corrected_sentence": "这里的情况很紧急，请大家马上撤离。", "error_description": "形容词“紧急”作谓语前应加程度副词“很”，不能用“是”直接接形容词；应为“很紧急”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88146, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "病人的情况紧急下来，医生只好立即手术。", "corrected_sentence": "病人的情况紧急起来，医生只好立即手术。", "error_description": "“紧急”后应接趋向补语“起来”，表示情况开始变得危急；说“紧急下来”不对。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
