INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88147, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "上好是很好很好，比一般的好很多。", "primary_collocate": null, "pronunciation": "shàng hǎo", "ipa": "ʂɑŋ˥˩ xɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "客人来了，他泡了一壶上好的茶。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服是上好的羊毛做的。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说这是上好的药材。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他脚上的皮鞋是上好的牛皮做的。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这套茶具是上好的瓷器。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷收藏了几块上好的石头。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条围巾用的是上好的布料。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一些上好的水果送给老师。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅选了上好的竹子来做椅子。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年的时候，我们吃了上好的羊肉。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上好的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "程度上远好于一般，表示非常好的上等品", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7334b5cb-6336-4b25-86db-f1f85bdb5c03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88147, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上好", "is_correct": true, "explanation": "正确答案：上好（shàng hǎo），指远好于一般的上等品。"}, {"text": "商号", "is_correct": false, "explanation": "商号（shānghào）：两个音节声调都不同，意思是商店的名称。"}, {"text": "上海", "is_correct": false, "explanation": "上海（shànghǎi）：末字 hǎo 与 hǎi 韵母不同，意思是中国城市名。"}, {"text": "上号", "is_correct": false, "explanation": "上号（shànghào）：末字声调不同（第三声与第四声），意思是登录游戏账号。"}], "explanations": {"上好": "正确答案：上好（shàng hǎo），指远好于一般的上等品。", "商号": "商号（shānghào）：两个音节声调都不同，意思是商店的名称。", "上海": "上海（shànghǎi）：末字 hǎo 与 hǎi 韵母不同，意思是中国城市名。", "上号": "上号（shànghào）：末字声调不同（第三声与第四声），意思是登录游戏账号。"}, "sentence_index": null, "correct_answer": "上好"}, "level_3": {"options": [{"text": "上好", "is_correct": true, "explanation": "正确：上好表示远好于一般的上等品，修饰茶，与“客人来了”的待客语境相符。"}, {"text": "脏", "is_correct": false, "explanation": "语义：脏表示不干净，与客人来了要用好茶招待的语境相反。"}, {"text": "硬", "is_correct": false, "explanation": "搭配：硬多用于固体的质地，茶是液体，不能说“硬的茶”。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：高大形容形体，不能用来修饰茶或茶水。"}], "explanations": {"上好": "正确：上好表示远好于一般的上等品，修饰茶，与“客人来了”的待客语境相符。", "脏": "语义：脏表示不干净，与客人来了要用好茶招待的语境相反。", "硬": "搭配：硬多用于固体的质地，茶是液体，不能说“硬的茶”。", "高大": "体貌：高大形容形体，不能用来修饰茶或茶水。"}, "sentence_index": 0, "correct_answer": "上好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一名上好的员工，工作非常认真。", "explanation": "这里应该用〈优秀〉。上好只用于说物品的质量，形容人的能力要用优秀。"}, {"text": "听到这个上好的消息，大家都高兴地跳了起来。", "explanation": "这里应该用〈好〉。上好只用于说物品的质量，消息令人高兴要说好消息。"}, {"text": "他的身体上好，很少生病。", "explanation": "这里应该用〈健康〉。上好只用于说物品的质量，人的身体状况要说健康。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88147, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上好", "is_correct": true, "explanation": "正确：上好表示远好于一般的上等品，修饰布料，与围巾用料的语境相符。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：瘦形容人或动物的身形，布料没有身形，不能说“瘦的布料”。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：冷清用于形容场所或气氛，不能修饰布料。"}, {"text": "辣", "is_correct": false, "explanation": "语义：辣说的是味道，布料没有味道，这样说毫无意义。"}], "explanations": {"上好": "正确：上好表示远好于一般的上等品，修饰布料，与围巾用料的语境相符。", "瘦": "体貌：瘦形容人或动物的身形，布料没有身形，不能说“瘦的布料”。", "冷清": "搭配：冷清用于形容场所或气氛，不能修饰布料。", "辣": "语义：辣说的是味道，布料没有味道，这样说毫无意义。"}, "sentence_index": 6, "correct_answer": "上好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的记性上好，一年前的事都还记得。", "explanation": "这里应该用〈好〉。上好只用于说物品的质量，人的记性要说好。"}, {"text": "他积累了上好的经验，经常帮助新人。", "explanation": "这里应该用〈丰富〉。上好修饰物品，经验的多少要说丰富。"}, {"text": "他做出了上好的决定，帮公司避免了损失。", "explanation": "这里应该用〈明智〉。上好说物品的质量，判断和选择的正确合理要说明智。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88147, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每次出差都会带一套上好地茶具。", "corrected_sentence": "他每次出差都会带一套上好的茶具。", "error_description": "错误：“上好地茶具”中的“地”用错。上好修饰名词“茶具”，应使用结构助词“的”。“地”用于修饰动词。正确形式：“上好的茶具”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88147, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈买了一些上好地牛肉，准备晚上炖汤。", "corrected_sentence": "妈妈买了一些上好的牛肉，准备晚上炖汤。", "error_description": "错误：“上好地牛肉”中的“地”用错。上好修饰名词“牛肉”，应使用结构助词“的”。“地”用于修饰动词。正确形式：“上好的牛肉”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
