INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88148, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "质量或品质特别好的。", "primary_collocate": null, "pronunciation": "shàng hǎo", "ipa": "ʂɑŋ˥˩ xɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这是上好的龙井茶，你尝一尝。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送了我一块上好的丝绸。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这张桌子用的是上好的木头。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板拿出了上好的白酒招待客人。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店的牛肉都是上好的。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶给我做了一件上好的棉衣。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这批苹果是上好的，一个也没有坏。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他买了一块上好的玉送给妈妈。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的米是上好的东北大米。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们用上好的材料盖了这座房子。", "target_word": "上好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上好的", "label": "定语形式"}], "register": "书面", "sense_fingerprint": "形容物品质量、品质特别好，常作定语", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, ARRAY['sentence 0 above tier T1: 3 words above tier T1 (max 2): 龙井 (Zipf 3.07), 尝 (Zipf 3.91), 尝 (Zipf 3.91)']::text[], '7334b5cb-6336-4b25-86db-f1f85bdb5c03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88148, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "上好", "is_correct": true, "explanation": "正确答案：上好（shàng hǎo），指质量特别好。"}, {"text": "商号", "is_correct": false, "explanation": "商号（shānghào）：两个音节声调都不同，意思是商店的名称。"}, {"text": "上海", "is_correct": false, "explanation": "上海（shànghǎi）：末字 hǎo 与 hǎi 韵母不同，意思是中国城市名。"}, {"text": "上号", "is_correct": false, "explanation": "上号（shànghào）：末字声调不同（第三声与第四声），意思是登录游戏账号。"}], "explanations": {"上好": "正确答案：上好（shàng hǎo），指质量特别好。", "商号": "商号（shānghào）：两个音节声调都不同，意思是商店的名称。", "上海": "上海（shànghǎi）：末字 hǎo 与 hǎi 韵母不同，意思是中国城市名。", "上号": "上号（shànghào）：末字声调不同（第三声与第四声），意思是登录游戏账号。"}, "sentence_index": null, "correct_answer": "上好"}, "level_3": {"options": [{"text": "上好", "is_correct": true, "explanation": "正确：上好表示质量特别好，修饰龙井茶，与“你尝一尝”的推荐语境相符。"}, {"text": "陈旧", "is_correct": false, "explanation": "语义：陈旧指东西放久了、不新鲜，与邀请对方品尝的语境相反。"}, {"text": "辣", "is_correct": false, "explanation": "语义：辣说的是味觉刺激，龙井茶的味道不用“辣”来形容。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：高大形容人或物的形体，不能用来评价茶叶的品质。"}], "explanations": {"上好": "正确：上好表示质量特别好，修饰龙井茶，与“你尝一尝”的推荐语境相符。", "陈旧": "语义：陈旧指东西放久了、不新鲜，与邀请对方品尝的语境相反。", "辣": "语义：辣说的是味觉刺激，龙井茶的味道不用“辣”来形容。", "高大": "体貌：高大形容人或物的形体，不能用来评价茶叶的品质。"}, "sentence_index": 0, "correct_answer": "上好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位上好的学生，成绩一直很稳定。", "explanation": "这里应该用〈优秀〉。上好只用于形容物品或材料的质量，形容人的品行和能力要用优秀。"}, {"text": "他被提拔到了一个上好的职位，负责公司的全部业务。", "explanation": "这里应该用〈高级〉。上好用于说物品的质量，职位的级别要说高级。"}, {"text": "她的身子骨上好，爬山从不喊累。", "explanation": "这里应该用〈硬朗〉。上好只用于说物品的质量，人的身体状况要说硬朗。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88148, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上好", "is_correct": true, "explanation": "正确：上好表示质量特别好，修饰苹果，与后半句“一个也没有坏”的语境相符。"}, {"text": "坏", "is_correct": false, "explanation": "语义：坏与后半句“一个也没有坏”自相矛盾，不能作为苹果的品质描述。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：瘦形容人或动物的身形，不能用来形容苹果。"}, {"text": "冷清", "is_correct": false, "explanation": "搭配：冷清形容场所或气氛，不用于修饰苹果。"}], "explanations": {"上好": "正确：上好表示质量特别好，修饰苹果，与后半句“一个也没有坏”的语境相符。", "坏": "语义：坏与后半句“一个也没有坏”自相矛盾，不能作为苹果的品质描述。", "瘦": "体貌：瘦形容人或动物的身形，不能用来形容苹果。", "冷清": "搭配：冷清形容场所或气氛，不用于修饰苹果。"}, "sentence_index": 6, "correct_answer": "上好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "今天的天气上好，我们去公园散步吧。", "explanation": "这里应该用〈很好〉。上好只用于说物品或材料的质量，天气好要说很好。"}, {"text": "他积累了上好的经验，能帮你解决很多问题。", "explanation": "这里应该用〈丰富〉。上好修饰物品，经验的多少要说丰富。"}, {"text": "这位科学家的脑子上好，一眼就看出了问题。", "explanation": "这里应该用〈灵光〉。上好只用于说物品的质量，人的头脑灵活要说灵光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88148, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家店卖的都是上好地布料，价格也很合理。", "corrected_sentence": "这家店卖的都是上好的布料，价格也很合理。", "error_description": "错误：“上好地布料”中的“地”用错。上好修饰名词“布料”，应使用结构助词“的”。“地”用于修饰动词，不能用在这里。正确形式：“上好的布料”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88148, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这批大米是上好地，颗粒饱满。", "corrected_sentence": "这批大米是上好的，颗粒饱满。", "error_description": "错误：“上好地”中的“地”用错。这里“上好”指代“大米”这类物品，应使用“的”。“地”用于修饰动词，不能放在这里。正确形式：“上好的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
