INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88149, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "摘要是把长文章里最主要的话挑出来写成短的。", "primary_collocate": null, "pronunciation": "zhāi yào", "ipa": "ʈʂaɪ˥˥ jaʊ˥˩", "syllable_count": 2, "sentences": [{"text": "这份摘要是我自己写的。", "target_word": "摘要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她给每一章都写了摘要。", "target_word": "摘要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "好的摘要应该短而清楚。", "target_word": "摘要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "写摘要要先读懂整篇文章。", "target_word": "摘要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这个摘要把重点都说出来了。", "target_word": "摘要", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我用三句话写完了摘要。", "target_word": "摘要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "杂志上每篇文章都有摘要。", "target_word": "摘要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你能帮我看看这个摘要吗？", "target_word": "摘要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "他的摘要比原文短很多。", "target_word": "摘要", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "摘要里没有写具体的例子。", "target_word": "摘要", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "份", "label": "量词"}, {"form": "篇", "label": "量词"}, {"form": "内容摘要", "label": "复合"}], "register": "书面", "sense_fingerprint": "把长文章的主要内容挑出来写成的短文", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d850554-45f7-4ce0-b18d-6b02b303fbf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88149, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "摘要", "is_correct": true, "explanation": "符合语境：摘要是可以“写”出来的文字，“我自己写的”说得通。"}, {"text": "蛋糕", "is_correct": false, "explanation": "配价：“写”的对象应是文字，蛋糕不能“写”，应说“做”。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不是写出来的，“我自己写的房子”说不通。"}, {"text": "照片", "is_correct": false, "explanation": "语义：照片是拍出来的，不是写的。"}], "explanations": {"摘要": "符合语境：摘要是可以“写”出来的文字，“我自己写的”说得通。", "蛋糕": "配价：“写”的对象应是文字，蛋糕不能“写”，应说“做”。", "房子": "语义：房子不是写出来的，“我自己写的房子”说不通。", "照片": "语义：照片是拍出来的，不是写的。"}, "sentence_index": 0, "correct_answer": "摘要"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我用摘要查生词，每个词都有解释。", "explanation": "这里应该用〈字典〉。摘要是对长文的概括，不能逐条查生词；查生词要用字典。"}, {"text": "这份摘要是我从网上下载的，可以播放。", "explanation": "这里应该用〈视频〉。摘要是文字，不能播放；可以播放的是视频。"}, {"text": "我用摘要末尾的人名表查到了这个人。", "explanation": "这里应该用〈索引〉。按人名排列以便查找的是索引；摘要只概括要点，没有人名表。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88149, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "摘要", "is_correct": true, "explanation": "符合语境：每篇文章都有概括要点的摘要。"}, {"text": "座位", "is_correct": false, "explanation": "语义：文章没有座位，“每篇文章都有座位”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "配价：“有价格”要求主语是可以标价的商品，文章不能这样。"}, {"text": "眼睛", "is_correct": false, "explanation": "语义：文章没有眼睛，“每篇文章都有眼睛”说不通。"}], "explanations": {"摘要": "符合语境：每篇文章都有概括要点的摘要。", "座位": "语义：文章没有座位，“每篇文章都有座位”说不通。", "价格": "配价：“有价格”要求主语是可以标价的商品，文章不能这样。", "眼睛": "语义：文章没有眼睛，“每篇文章都有眼睛”说不通。"}, "sentence_index": 6, "correct_answer": "摘要"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这本书的摘要很清楚，我能找到每一章。", "explanation": "这里应该用〈目录〉。目录用来查找章节位置，摘要只概括内容，不能用来找章节。"}, {"text": "他把摘要煮熟了，端上了桌。", "explanation": "这里应该用〈食材〉。摘要是文字，不能当食材去煮；能煮熟、端上桌的是食材。"}, {"text": "他用摘要拍了一张照片。", "explanation": "这里应该用〈相机〉。摘要是文字内容，不能拿来拍照；拍照要用相机。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88149, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们每人要写一头摘要。", "corrected_sentence": "我们每人要写一份摘要。", "error_description": "量词错误：“摘要”是文字材料，应用量词“份”，不能用“头”（“头”用于牛、猪等动物）。应改为“一份摘要”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88149, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我还没读懂这只摘要。", "corrected_sentence": "我还没读懂这个摘要。", "error_description": "量词错误：“摘要”是文字材料，不能用量词“只”（“只”多用于动物等）。应改为“这个摘要”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
