INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88151, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "雕塑是用石头、木头或泥做出来的好看的东西。", "primary_collocate": null, "pronunciation": "diāo sù", "ipa": "tjau̯˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "广场上有一座白色的雕塑。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷用木头做了一个小雕塑。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个雕塑是用泥做的。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把雕塑放在书桌上了。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他送给我一个小小的雕塑。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们围着雕塑拍照。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河边的石头雕塑很好看。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那座雕塑像一只大鸟。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妹妹用泥做了一个小雕塑。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雕塑上落了很多雪。", "target_word": "雕塑", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "座", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "雕塑家", "label": "复合词"}, {"form": "雕塑作品", "label": "复合词"}], "register": "中性", "sense_fingerprint": "用石头、木头或泥做成的好看的实物摆件", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be7a67a-0052-4629-80f6-eca6c3881ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88151, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "书桌", "is_correct": false, "explanation": "搭配：量词「座」不用于书桌，应说「一张书桌」，「一座白色的书桌」不成立。"}, {"text": "雕塑", "is_correct": true, "explanation": "雕塑是用石头、木头或泥做成的摆件，可以是白色的，「一座白色的雕塑」搭配自然。"}, {"text": "声音", "is_correct": false, "explanation": "语义：声音没有颜色，不能说「白色的声音」，也不能摆在广场上。"}, {"text": "天空", "is_correct": false, "explanation": "语义：天空是自然景象，不是可以用「一座」计量的物体，不会「立」在广场上。"}], "explanations": {"书桌": "搭配：量词「座」不用于书桌，应说「一张书桌」，「一座白色的书桌」不成立。", "雕塑": "雕塑是用石头、木头或泥做成的摆件，可以是白色的，「一座白色的雕塑」搭配自然。", "声音": "语义：声音没有颜色，不能说「白色的声音」，也不能摆在广场上。", "天空": "语义：天空是自然景象，不是可以用「一座」计量的物体，不会「立」在广场上。"}, "sentence_index": 0, "correct_answer": "雕塑"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在市场买了一只雕塑。", "explanation": "这里应该用〈个〉。〈只〉用于动物或成对物品中的一个，不能用于这种摆件。"}, {"text": "客厅的桌子上放着一条雕塑。", "explanation": "这里应该用〈个〉或〈座〉。〈条〉用于细长的东西，不能用于这种摆件。"}, {"text": "墙上挂着一张雕塑。", "explanation": "这里应该用〈个〉。〈张〉用于平面的东西，雕塑是立体的，不能用〈张〉计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88151, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "云", "is_correct": false, "explanation": "语义：云不是石头做的，与句中的「石头」相矛盾，也不会是「河边的石头」的一部分。"}, {"text": "手续", "is_correct": false, "explanation": "语义：「手续」是办事的程序，不是用石头做成的东西，不能说「石头手续」，也谈不上好看。"}, {"text": "雕塑", "is_correct": true, "explanation": "雕塑是用石头做的摆件，「石头雕塑很好看」搭配自然，符合句意。"}, {"text": "面条", "is_correct": false, "explanation": "语义：面条是食物，不是石头做的东西，与「石头」相矛盾。"}], "explanations": {"云": "语义：云不是石头做的，与句中的「石头」相矛盾，也不会是「河边的石头」的一部分。", "手续": "语义：「手续」是办事的程序，不是用石头做成的东西，不能说「石头手续」，也谈不上好看。", "雕塑": "雕塑是用石头做的摆件，「石头雕塑很好看」搭配自然，符合句意。", "面条": "语义：面条是食物，不是石头做的东西，与「石头」相矛盾。"}, "sentence_index": 6, "correct_answer": "雕塑"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他是一名雕塑，每天在工厂里工作。", "explanation": "这里应该用〈雕塑家〉。〈雕塑〉指石头、木头或泥做的摆件，不指人；指人要用〈雕塑家〉。"}, {"text": "我把这个雕塑喂给了小狗。", "explanation": "这里把〈雕塑〉当成了食物，它是石头、木头或泥做的摆件，不能用来喂动物。"}, {"text": "这个雕塑昨天生病了，今天去了医院。", "explanation": "这里把〈雕塑〉当成了有生命的人。雕塑是无生命的摆件，不会生病，也不会去医院。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88151, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我家阳台上放着一根小雕塑。", "corrected_sentence": "我家阳台上放着一个小雕塑。", "error_description": "量词错误：摆件类的“雕塑”应使用量词“个”，“根”用于细长的东西，这里用错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88151, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "孩子们围着一只石头雕塑拍照。", "corrected_sentence": "孩子们围着一座石头雕塑拍照。", "error_description": "量词错误：“雕塑”应使用量词“座”（或“个”），“只”用于动物或成对物品中的一个，这里用错了。正确：“一座石头雕塑”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
