INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88153, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "美好是又好又漂亮，让人心里高兴。", "primary_collocate": null, "pronunciation": "měi hǎo", "ipa": "meɪ̯˨˩˦ xɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "春天的公园里，一切都很美好。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们在海边度过了美好的一天。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她对未来有很多美好的想法。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是一个美好的早晨。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小时候的日子真美好。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "愿你的生活越来越美好。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些照片让我想起了美好的过去。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友们一起唱歌，气氛很美好。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他给孩子们讲了一个美好的故事。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新年到了，祝大家有一个美好的开始。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "美好的", "label": "定语形式"}, {"form": "更美好", "label": "比较"}, {"form": "最美好", "label": "最高级"}], "register": "中性", "sense_fingerprint": "又好又漂亮、让人心里高兴的事物或感受", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7334b5cb-6336-4b25-86db-f1f85bdb5c03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88153, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美好", "is_correct": true, "explanation": "正确：美好形容令人愉快的事物，修饰春天公园的景象，与语境相符。"}, {"text": "寒冷", "is_correct": false, "explanation": "语义：寒冷指气温低，与春天和温暖的场景相反。"}, {"text": "枯萎", "is_correct": false, "explanation": "搭配：枯萎说植物凋谢，不能用来形容整个公园的状况。"}, {"text": "狰狞", "is_correct": false, "explanation": "体貌：狰狞形容面容或凶兽凶恶的样子，不能用来形容景色。"}], "explanations": {"美好": "正确：美好形容令人愉快的事物，修饰春天公园的景象，与语境相符。", "寒冷": "语义：寒冷指气温低，与春天和温暖的场景相反。", "枯萎": "搭配：枯萎说植物凋谢，不能用来形容整个公园的状况。", "狰狞": "体貌：狰狞形容面容或凶兽凶恶的样子，不能用来形容景色。"}, "sentence_index": 0, "correct_answer": "美好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的脾气很美好，动不动就发火。", "explanation": "这里应该用〈温和〉。美好用于事物或感受，性格的平和要说温和；且与“动不动就发火”矛盾。"}, {"text": "他的听力很美好，能听清很远的声音。", "explanation": "这里应该用〈灵敏〉。美好不用来形容感官的灵敏度，听觉的敏锐要说灵敏。"}, {"text": "这辆车的马力很美好，爬坡毫不费力。", "explanation": "这里应该用〈强劲〉。美好不用来形容机械的动力，马力大要说强劲。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88153, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美好", "is_correct": true, "explanation": "正确：美好形容令人愉快的事物或感受，修饰回忆中的过去，与语境相符。"}, {"text": "陌生", "is_correct": false, "explanation": "语义：陌生指不熟悉，与“想起”过去的语境相矛盾。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：高大形容形体，不能用来形容过去。"}, {"text": "辣", "is_correct": false, "explanation": "语义：辣描述味道，不能用来形容过去的经历。"}], "explanations": {"美好": "正确：美好形容令人愉快的事物或感受，修饰回忆中的过去，与语境相符。", "陌生": "语义：陌生指不熟悉，与“想起”过去的语境相矛盾。", "高大": "体貌：高大形容形体，不能用来形容过去。", "辣": "语义：辣描述味道，不能用来形容过去的经历。"}, "sentence_index": 6, "correct_answer": "美好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的酒量很美好，一杯就醉了。", "explanation": "这里应该用〈浅〉。美好不用来形容酒量，酒量小要说浅；且与后半句矛盾。"}, {"text": "他的口才很美好，说话常常结巴。", "explanation": "这里应该用〈流利〉。美好不用来形容口才，说话清楚顺畅要说流利；且与“结巴”矛盾。"}, {"text": "这座桥的承重能力很美好，能承受十吨的重量。", "explanation": "这里应该用〈强〉。美好形容令人愉快的事物或感受，不用来说承重能力，承重能力的高低要说强。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88153, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个假期我们一家人度过了美好地时光。", "corrected_sentence": "这个假期我们一家人度过了美好的时光。", "error_description": "错误：“美好地时光”中的“地”用错。美好修饰名词“时光”，应使用结构助词“的”。“地”用于修饰动词。正确形式：“美好的时光”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88153, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "愿这次旅行给你留下美好地回忆。", "corrected_sentence": "愿这次旅行给你留下美好的回忆。", "error_description": "错误：“美好地回忆”中的“地”用错。美好修饰名词“回忆”，应使用结构助词“的”。“地”用于修饰动词。正确形式：“美好的回忆”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
