INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88154, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "好的；令人愉快的。", "primary_collocate": null, "pronunciation": "měi hǎo", "ipa": "meɪ̯˨˩˦ xɑʊ̯˨˩˦", "syllable_count": 2, "sentences": [{"text": "这里的夜晚十分美好，让人不想离开。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我永远记得那段美好的时光。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的婚礼很美好。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "和家人在一起是最美好的事。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她留给大家的印象很美好。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我希望你有一个美好的周末。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那天晚上的音乐美好极了。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都在为美好的明天努力。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，读书是一件美好的事情。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市给我留下了美好的回忆。", "target_word": "美好", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "美好的", "label": "定语形式"}, {"form": "更美好", "label": "比较"}, {"form": "最美好", "label": "最高级"}], "register": "中性", "sense_fingerprint": "形容好的、令人愉快的时光、回忆、愿望等", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7334b5cb-6336-4b25-86db-f1f85bdb5c03') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88154, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "美好", "is_correct": true, "explanation": "正确：美好表示令人愉快，修饰夜晚，与后半句“让人不想离开”相符。"}, {"text": "可怕", "is_correct": false, "explanation": "语义：可怕令人想逃离，与“让人不想离开”相矛盾。"}, {"text": "狭窄", "is_correct": false, "explanation": "搭配：狭窄说空间小，不能用来形容夜晚。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：高大用于人或物的形体，不能形容夜晚。"}], "explanations": {"美好": "正确：美好表示令人愉快，修饰夜晚，与后半句“让人不想离开”相符。", "可怕": "语义：可怕令人想逃离，与“让人不想离开”相矛盾。", "狭窄": "搭配：狭窄说空间小，不能用来形容夜晚。", "高大": "体貌：高大用于人或物的形体，不能形容夜晚。"}, "sentence_index": 0, "correct_answer": "美好"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他惹上了一个美好的麻烦，让人很头疼。", "explanation": "这里应该用〈大〉。美好表示令人愉快，不能修饰“麻烦”这类负面的事情；麻烦严重要说大麻烦。"}, {"text": "他跑步的速度很美好，每次都是最后一名。", "explanation": "这里应该用〈快〉。美好不用来形容速度，跑得快要说快；且与“最后一名”矛盾。"}, {"text": "他的个子很美好，是班里最高的学生。", "explanation": "这里应该用〈高〉。美好表示令人愉快，不用来形容身高，个子高要说高。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88154, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "美好", "is_correct": true, "explanation": "正确：美好表示令人愉快，修饰音乐，与“那天晚上”的美好感受相符。"}, {"text": "枯萎", "is_correct": false, "explanation": "搭配：枯萎说植物凋谢，不能用来形容音乐。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：瘦形容人或动物的形体，音乐没有形体。"}, {"text": "湿漉漉", "is_correct": false, "explanation": "语义：湿漉漉形容物体沾了水，不能用来形容音乐。"}], "explanations": {"美好": "正确：美好表示令人愉快，修饰音乐，与“那天晚上”的美好感受相符。", "枯萎": "搭配：枯萎说植物凋谢，不能用来形容音乐。", "瘦": "体貌：瘦形容人或动物的形体，音乐没有形体。", "湿漉漉": "语义：湿漉漉形容物体沾了水，不能用来形容音乐。"}, "sentence_index": 6, "correct_answer": "美好"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他们买了一套房子，面积很美好，有一百二十平方米。", "explanation": "这里应该用〈宽敞〉。美好表示令人愉快，不用来说面积大小，房子面积大要说宽敞。"}, {"text": "这次考试的成绩很美好，他连一道题都没做对。", "explanation": "这里应该用〈优异〉。美好不用来形容学习成绩，成绩出色要说优异；且与后半句矛盾。"}, {"text": "这道菜的味道很美好，他吃了一口就吐了出来。", "explanation": "这里应该用〈可口〉。美好不用来形容味觉，味道好要说可口；且与后半句矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88154, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那几年的校园生活充满了美好地瞬间。", "corrected_sentence": "那几年的校园生活充满了美好的瞬间。", "error_description": "错误：“美好地瞬间”中的“地”用错。美好修饰名词“瞬间”，应使用结构助词“的”。“地”用于修饰动词。正确形式：“美好的瞬间”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88154, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们一起过了一个美好地周末。", "corrected_sentence": "他们一起过了一个美好的周末。", "error_description": "错误：“美好地周末”中的“地”用错。美好修饰名词“周末”，应使用结构助词“的”。“地”用于修饰动词。正确形式：“美好的周末”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '08bae48c-bdbd-4008-9ada-ec916504e82b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
