INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88156, 1, 'prompt1_core', '{"pos": "连词", "semantic_class": "function", "definition": "连词，表示在任何条件下结果都不改变；无论。", "primary_collocate": null, "pronunciation": "bù guǎn", "ipa": "pu˥˩ ku̯an˨˩˦", "syllable_count": 2, "sentences": [{"text": "不管天气怎么样，我都去跑步。", "target_word": "不管", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管多忙，他都会给妈妈打电话。", "target_word": "不管", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管你喜不喜欢，这件事都要做。", "target_word": "不管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管走到哪里，我都会想家。", "target_word": "不管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管路有多远，我们都要走过去。", "target_word": "不管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管谁来问，你都不要告诉他。", "target_word": "不管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管学习多累，她每天都坚持看书。", "target_word": "不管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管明天下不下雨，比赛都不会改。", "target_word": "不管", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不管怎么说，他都是我的朋友。", "target_word": "不管", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "不管价钱多高，他也要买这台电脑。", "target_word": "不管", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "不管怎样", "label": "复合"}], "register": "口语", "sense_fingerprint": "无论条件如何，结果都不变", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2634a1f-e0ef-4c1b-853c-f701f33e6317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88156, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "不管", "is_correct": true, "explanation": "正确。“不管”表示无论条件如何，结果都不变。"}, {"text": "不关", "is_correct": false, "explanation": "guān 与 guǎn 声调不同（第一声与第三声），意思是不关心、不相干。"}, {"text": "不惯", "is_correct": false, "explanation": "guàn 与 guǎn 声调不同（第四声与第三声），意思是不习惯。"}, {"text": "木管", "is_correct": false, "explanation": "mù 与 bù 声母不同（m 与 b），意思是木制的管，如木管乐器。"}], "explanations": {"不管": "正确。“不管”表示无论条件如何，结果都不变。", "不关": "guān 与 guǎn 声调不同（第一声与第三声），意思是不关心、不相干。", "不惯": "guàn 与 guǎn 声调不同（第四声与第三声），意思是不习惯。", "木管": "mù 与 bù 声母不同（m 与 b），意思是木制的管，如木管乐器。"}, "sentence_index": null, "correct_answer": "不管"}, "level_3": {"options": [{"text": "不管", "is_correct": true, "explanation": "正确。“不管”引出未定的条件“天气怎么样”，表示结果不变。"}, {"text": "因为", "is_correct": false, "explanation": "语义：“因为”引出确定的原因，“天气怎么样”是未定的情况，不能作原因。"}, {"text": "所以", "is_correct": false, "explanation": "语义：“所以”引出结果，前面不能接未定的“天气怎么样”。"}, {"text": "而且", "is_correct": false, "explanation": "搭配：“而且”表示递进，不能接“天气怎么样”这种疑问式小句，句子不通。"}], "explanations": {"不管": "正确。“不管”引出未定的条件“天气怎么样”，表示结果不变。", "因为": "语义：“因为”引出确定的原因，“天气怎么样”是未定的情况，不能作原因。", "所以": "语义：“所以”引出结果，前面不能接未定的“天气怎么样”。", "而且": "搭配：“而且”表示递进，不能接“天气怎么样”这种疑问式小句，句子不通。"}, "sentence_index": 0, "correct_answer": "不管"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "不管天气不好，我们还是出发了。", "explanation": "这里应该用〈尽管〉。“不管”后面要接未定的情况，表示无论怎样结果都不变；“天气不好”是已经发生的事实，要用表示让步的“尽管”。"}, {"text": "不管我已经很累了，我也要去。", "explanation": "这里应该用〈虽然〉。“不管”需接未定的情况；“我已经很累了”是确定的事实，应用表示让步的“虽然”，后面可说“但我还是要去”。"}, {"text": "不管天气变热，我们的食欲变好了。", "explanation": "这里应该用〈随着〉。“随着”表示伴随变化，“不管”表示结果不随条件改变，不能用来说明事情随之变化。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88156, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "不管", "is_correct": true, "explanation": "正确。“不管”表示无论条件如何，结果都不变。"}, {"text": "笔管", "is_correct": false, "explanation": "bǐ 与 bù 韵母和声调都不同（i/u，第三声与第四声），意思是笔杆。"}, {"text": "库管", "is_correct": false, "explanation": "kù 与 bù 声母不同（k 与 b），意思是仓库保管员。"}, {"text": "闭馆", "is_correct": false, "explanation": "bì 与 bù 韵母不同（i 与 u），意思是关闭馆舍。"}], "explanations": {"不管": "正确。“不管”表示无论条件如何，结果都不变。", "笔管": "bǐ 与 bù 韵母和声调都不同（i/u，第三声与第四声），意思是笔杆。", "库管": "kù 与 bù 声母不同（k 与 b），意思是仓库保管员。", "闭馆": "bì 与 bù 韵母不同（i 与 u），意思是关闭馆舍。"}, "sentence_index": null, "correct_answer": "不管"}, "level_3": {"options": [{"text": "不管", "is_correct": true, "explanation": "正确。“不管”表示无论学习多累，结果都不变。"}, {"text": "因此", "is_correct": false, "explanation": "语义：“因此”引出结果，前句“学习多累”不能作为“坚持看书”的原因。"}, {"text": "由于", "is_correct": false, "explanation": "语域：“由于”是书面语的原因连词，且“多累”与“坚持”之间没有因果关系，句子不通。"}, {"text": "然后", "is_correct": false, "explanation": "搭配：“然后”表示时间先后，不能接“学习多累”这样的状态小句。"}], "explanations": {"不管": "正确。“不管”表示无论学习多累，结果都不变。", "因此": "语义：“因此”引出结果，前句“学习多累”不能作为“坚持看书”的原因。", "由于": "语域：“由于”是书面语的原因连词，且“多累”与“坚持”之间没有因果关系，句子不通。", "然后": "搭配：“然后”表示时间先后，不能接“学习多累”这样的状态小句。"}, "sentence_index": 6, "correct_answer": "不管"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "不管价钱合适，他就买这台电脑。", "explanation": "这里应该用〈只要〉。“只要……就……”表示条件与结果相连；“不管”表示结果不随条件改变，不能与“就”搭配表示条件结果。"}, {"text": "不管这台电脑很贵，他还是买了。", "explanation": "这里应该用〈虽然〉。“不管”后面要接未定的情况；“这台电脑很贵”是确定的事实，要用让步的“虽然”。"}, {"text": "不管有钱，他才会买这台电脑。", "explanation": "这里应该用〈除非〉。“除非……才……”表示唯一条件，“不管”表示结果不随条件改变，不能和“才”搭配表示限定。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88156, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "不管谁来，我不开门。", "corrected_sentence": "不管谁来，我都不开门。", "error_description": "“不管”引出的条件小句后，主句要用“都”或“也”呼应，应说“我都不开门”，不能只说“我不开门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88156, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "不管他说什么，都我不信。", "corrected_sentence": "不管他说什么，我都不信。", "error_description": "“都”应放在主语后、动词前，应说“我都不信”，不能说“都我不信”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
