INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88157, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "数值是用数字表示出来的大小。", "primary_collocate": null, "pronunciation": "shù zhí", "ipa": "ʂu˥˩ ʈʂɨ˧˥", "syllable_count": 2, "sentences": [{"text": "这个数值太高了，要小心。", "target_word": "数值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请把测量的数值写在表格里。", "target_word": "数值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体温的数值正常，你不用担心。", "target_word": "数值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "屏幕上显示的数值一直在变。", "target_word": "数值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生看了血压的数值，说没问题。", "target_word": "数值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "数值越大，说明污染越严重。", "target_word": "数值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台机器的数值已经调好了。", "target_word": "数值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我记下了每天的数值。", "target_word": "数值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两次数值差得很多，要再测一次。", "target_word": "数值", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个数值是用仪器测出来的。", "target_word": "数值", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "中性", "sense_fingerprint": "数值：测量或计算得到的、用数字表示出来的大小", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '119ba6ca-7230-41f9-9941-35fce59bfea3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88157, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "数值", "is_correct": true, "explanation": "数值：测量或计算得到的、用数字表示的大小"}, {"text": "树枝", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是树的枝条"}, {"text": "数十", "is_correct": false, "explanation": "shí（第二声）与 zhí（第二声）声母不同（sh 与 zh），意思是几十"}, {"text": "树脂", "is_correct": false, "explanation": "zhī（第一声）与 zhí（第二声）声调不同，意思是树脂"}, {"text": "数制", "is_correct": false, "explanation": "zhì（第四声）与 zhí（第二声）声调不同，意思是进位制度"}], "explanations": {"数值": "数值：测量或计算得到的、用数字表示的大小", "树枝": "zhī（第一声）与 zhí（第二声）声调不同，意思是树的枝条", "数十": "shí（第二声）与 zhí（第二声）声母不同（sh 与 zh），意思是几十", "树脂": "zhī（第一声）与 zhí（第二声）声调不同，意思是树脂", "数制": "zhì（第四声）与 zhí（第二声）声调不同，意思是进位制度"}, "sentence_index": null, "correct_answer": "数值"}, "level_3": {"options": [{"text": "名字", "is_correct": false, "explanation": "语义：“名字”是称呼，没有高低之分，与“太高了”讲不通"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“天气”不能说“太高”，气温才可以说高，与“太高了”不搭"}, {"text": "句子", "is_correct": false, "explanation": "语义：“句子”指语言单位，没有高低大小，与“太高了，要小心”矛盾"}, {"text": "数值", "is_correct": true, "explanation": "数值：这里指测得的数字大小，“太高了”正说明数值偏大"}], "explanations": {"名字": "语义：“名字”是称呼，没有高低之分，与“太高了”讲不通", "天气": "搭配：“天气”不能说“太高”，气温才可以说高，与“太高了”不搭", "句子": "语义：“句子”指语言单位，没有高低大小，与“太高了，要小心”矛盾", "数值": "数值：这里指测得的数字大小，“太高了”正说明数值偏大"}, "sentence_index": 0, "correct_answer": "数值"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个班的数值是四十人。", "explanation": "这里应该用〈数量〉。数值指测得或算出的数字大小，班里有多少人只说数量"}, {"text": "他看了一本数值。", "explanation": "这里应该用〈个〉。“本”用于书册，数值是抽象的数字，不能用“本”计量"}, {"text": "这个数值很甜，我想尝一尝。", "explanation": "这里应该用〈食物〉。“数值”是抽象的数字，不是可以品尝的东西"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88157, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "语义：“年龄”只用于人或动物，机器没有年龄，无法“调好”"}, {"text": "性别", "is_correct": false, "explanation": "语义：“性别”是生物的属性，机器没有性别，与“调好”无关"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“调”用于参数、设置，不能用于“窗户”"}, {"text": "数值", "is_correct": true, "explanation": "数值：机器测得或设定的数字，可以“调好”"}], "explanations": {"年龄": "语义：“年龄”只用于人或动物，机器没有年龄，无法“调好”", "性别": "语义：“性别”是生物的属性，机器没有性别，与“调好”无关", "窗户": "搭配：“调”用于参数、设置，不能用于“窗户”", "数值": "数值：机器测得或设定的数字，可以“调好”"}, "sentence_index": 6, "correct_answer": "数值"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个数值是我的电话号码。", "explanation": "这里应该用〈数字〉。数值指测得或算得的量，电话号码只是一串数字，不说“数值”"}, {"text": "他的数值是二十岁。", "explanation": "这里应该用〈年龄〉。数值指测得或算得的量，人的岁数只说年龄"}, {"text": "我们周末去数值旅游。", "explanation": "语义：“数值”是抽象的数字，不是地点，不能说“去……旅游”"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88157, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这台数值正常，不用担心。", "corrected_sentence": "这个数值正常，不用担心。", "error_description": "量词错误：“数值”应说“这个数值”，“台”多用于机器设备，不能修饰抽象的“数值”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88157, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我把数值记了对。", "corrected_sentence": "我把数值记对了。", "error_description": "补语位置错误：结果补语“对”应紧跟动词“记”，应说“记对了”，不能说“记了对”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c20252ae-df1c-4e13-8e4b-57efe378e5ac') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
