INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88159, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "震动是东西一下一下地抖。", "primary_collocate": null, "pronunciation": "zhèn dòng", "ipa": "ʈʂən˥˩ tʊŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我的手机在桌子上震动。", "target_word": "震动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机一转，地板就开始震动。", "target_word": "震动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机震动了两下，是妈妈打来的。", "target_word": "震动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车开得很快，座位一直在震动。", "target_word": "震动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上课时请让手机震动，不要响。", "target_word": "震动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大卡车从门前开过，窗玻璃震动着。", "target_word": "震动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他按了一下按钮，椅子就震动起来。", "target_word": "震动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "桌上的杯子轻轻震动，水也在抖。", "target_word": "震动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车进站时，站台微微震动。", "target_word": "震动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "音箱的声音很大，墙都在震动。", "target_word": "震动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "震动了", "label": "体标"}, {"form": "震动着", "label": "体标"}, {"form": "震动过", "label": "体标"}], "register": "中性", "sense_fingerprint": "东西一下一下地抖动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d977b55-e838-4148-b0e4-160dae9a063e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88159, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "震动", "is_correct": true, "explanation": "正确：震动指东西一下一下地抖。"}, {"text": "镇痛", "is_correct": false, "explanation": "tòng（第四声）与 dòng 声母不同（t 与 d），意思是镇痛，即止痛。"}, {"text": "镇定", "is_correct": false, "explanation": "dìng（第四声）与 dòng 韵母不同（ing 与 ong），意思是镇定，表示冷静、稳定。"}, {"text": "正东", "is_correct": false, "explanation": "zhèng dōng 与 zhèn dòng 韵母不同（eng 与 en），第二字声调也不同，意思是正东方向。"}], "explanations": {"震动": "正确：震动指东西一下一下地抖。", "镇痛": "tòng（第四声）与 dòng 声母不同（t 与 d），意思是镇痛，即止痛。", "镇定": "dìng（第四声）与 dòng 韵母不同（ing 与 ong），意思是镇定，表示冷静、稳定。", "正东": "zhèng dōng 与 zhèn dòng 韵母不同（eng 与 en），第二字声调也不同，意思是正东方向。"}, "sentence_index": null, "correct_answer": "震动"}, "level_3": {"options": [{"text": "震动", "is_correct": true, "explanation": "正确：“手机在桌子上震动”表示手机一下一下地抖，符合句意。"}, {"text": "散步", "is_correct": false, "explanation": "语义：手机不会散步，“散步”需要能走动的主体。"}, {"text": "念书", "is_correct": false, "explanation": "配价：“念书”需要人作主语，手机不能念书。"}, {"text": "微笑", "is_correct": false, "explanation": "语义：手机不会微笑，与句子的主语不符。"}], "explanations": {"震动": "正确：“手机在桌子上震动”表示手机一下一下地抖，符合句意。", "散步": "语义：手机不会散步，“散步”需要能走动的主体。", "念书": "配价：“念书”需要人作主语，手机不能念书。", "微笑": "语义：手机不会微笑，与句子的主语不符。"}, "sentence_index": 0, "correct_answer": "震动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他冷得一直在震动。", "explanation": "这里应该用〈发抖〉。“震动”指东西一下一下地抖，人冷得发抖要说“发抖”，不能用“震动”。"}, {"text": "她把桌布震动干净。", "explanation": "这里应该用〈抖〉。“震动”不能带结果补语“干净”表示抖掉灰尘；把桌布抖干净要用“抖”。"}, {"text": "星星在夜空里震动。", "explanation": "这里应该用〈闪烁〉。星星忽明忽暗要说“闪烁”；“震动”指东西一下一下地抖，不能用来形容星光。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88159, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "震动", "is_correct": true, "explanation": "正确：震动指东西一下一下地抖。"}, {"text": "阵痛", "is_correct": false, "explanation": "tòng（第四声）与 dòng 声母不同（t 与 d），意思是阵痛，指一阵阵的疼痛。"}, {"text": "震荡", "is_correct": false, "explanation": "dàng 与 dòng 韵母不同（ang 与 ong），意思是来回晃荡、动荡。"}, {"text": "正东", "is_correct": false, "explanation": "zhèng dōng 与 zhèn dòng 的韵母不同（eng 与 en）且声调不同，意思是正东方向，表示方位。"}], "explanations": {"震动": "正确：震动指东西一下一下地抖。", "阵痛": "tòng（第四声）与 dòng 声母不同（t 与 d），意思是阵痛，指一阵阵的疼痛。", "震荡": "dàng 与 dòng 韵母不同（ang 与 ong），意思是来回晃荡、动荡。", "正东": "zhèng dōng 与 zhèn dòng 的韵母不同（eng 与 en）且声调不同，意思是正东方向，表示方位。"}, "sentence_index": null, "correct_answer": "震动"}, "level_3": {"options": [{"text": "震动", "is_correct": true, "explanation": "正确：“椅子就震动起来”表示椅子开始一下一下地抖。"}, {"text": "咳嗽", "is_correct": false, "explanation": "语义：椅子不会咳嗽，与句意不符。"}, {"text": "演讲", "is_correct": false, "explanation": "配价：“演讲”需要人作主语，椅子不能演讲。"}, {"text": "歌唱", "is_correct": false, "explanation": "语义：椅子不能唱歌，“歌唱起来”说不通。"}], "explanations": {"震动": "正确：“椅子就震动起来”表示椅子开始一下一下地抖。", "咳嗽": "语义：椅子不会咳嗽，与句意不符。", "演讲": "配价：“演讲”需要人作主语，椅子不能演讲。", "歌唱": "语义：椅子不能唱歌，“歌唱起来”说不通。"}, "sentence_index": 6, "correct_answer": "震动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他害怕得全身震动。", "explanation": "这里应该用〈颤抖〉。“震动”多指物体一下一下地抖，人因害怕发抖要说“颤抖”。"}, {"text": "老师听懂了，向我震动了一下头。", "explanation": "这里应该用〈点〉。表示同意时头上下动要说“点头”；“震动”指东西一下一下地抖，不能用于点头。"}, {"text": "风一吹，湖面上震动起一圈圈水波。", "explanation": "这里应该用〈泛〉。水面起波纹要说“泛起水波”；“震动”指东西一下一下地抖，不能带“水波”作宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88159, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他刚站起来，椅子就震动了一个下。", "corrected_sentence": "他刚站起来，椅子就震动了一下。", "error_description": "量词错误：动量补语“一下”的量词是“下”，不能说“一个下”，应说“震动了一下”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88159, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "洗衣机转起来，地板震动的厉害。", "corrected_sentence": "洗衣机转起来，地板震动得厉害。", "error_description": "补语标记错误：应说“震动得厉害”，动词与补语之间要用“得”引出补语；不能用“的”，说“震动的厉害”是错的。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
