INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88162, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "副词，表示好像、仿佛，带有推测的意思。", "primary_collocate": null, "pronunciation": "sì hū", "ipa": "sɨ˥˩ xu˥", "syllable_count": 2, "sentences": [{"text": "天空很暗，似乎要下雨了。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走得很慢，似乎有心事。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，她似乎很吃惊。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯还亮着，他似乎还没睡。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路似乎没有尽头。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她看了我一眼，似乎想说什么。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟似乎对新玩具不感兴趣。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的话似乎有道理。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都笑了，只有他似乎不明白。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的变化似乎很大。", "target_word": "似乎", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "表示好像、仿佛，带推测", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ac39683-0e14-4009-8f9a-c5a67e844ca1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88162, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "似乎", "is_correct": true, "explanation": "正确：“似乎”表示对将要下雨的推测，与“天空很暗”的表象相符。"}, {"text": "只好", "is_correct": false, "explanation": "语义：“只好”表示无可奈何只能如此，与“天空很暗”的推测不搭。"}, {"text": "连忙", "is_correct": false, "explanation": "搭配：“连忙”修饰人的动作，不修饰“要下雨”这种自然现象。"}, {"text": "特意", "is_correct": false, "explanation": "搭配：“特意”表示有意而为，不能用于自然现象“下雨”。"}], "explanations": {"似乎": "正确：“似乎”表示对将要下雨的推测，与“天空很暗”的表象相符。", "只好": "语义：“只好”表示无可奈何只能如此，与“天空很暗”的推测不搭。", "连忙": "搭配：“连忙”修饰人的动作，不修饰“要下雨”这种自然现象。", "特意": "搭配：“特意”表示有意而为，不能用于自然现象“下雨”。"}, "sentence_index": 0, "correct_answer": "似乎"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这根绳子似乎有三米长，我刚才量过了。", "explanation": "这里应该用〈确实〉。“似乎”表示推测；“我刚才量过了”说明长度是确定的，应说“这根绳子确实有三米长”。"}, {"text": "我已经毕业两年了，似乎毕业了。", "explanation": "这里应该用〈确实〉。毕业是说话人清楚的已发生事实，“似乎”表示推测，这里应说“我确实毕业了”。"}, {"text": "这个蛋糕是我自己做的，我似乎做了这个蛋糕。", "explanation": "这里应该用〈确实〉。蛋糕是说话人自己做的，是确知的事实，“似乎”表示推测，不能用，应说“我确实做了这个蛋糕”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88162, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "似乎", "is_correct": true, "explanation": "正确：“似乎”表示推测，与“弟弟对新玩具不感兴趣”的表现相符。"}, {"text": "赶紧", "is_correct": false, "explanation": "搭配：“赶紧”修饰动作，不修饰“不感兴趣”这样的心理状态。"}, {"text": "纷纷", "is_correct": false, "explanation": "配价：“纷纷”要求复数的主语，句中主语“弟弟”只有一人。"}, {"text": "急忙", "is_correct": false, "explanation": "搭配：“急忙”修饰动作，与“不感兴趣”这样的状态不搭配。"}], "explanations": {"似乎": "正确：“似乎”表示推测，与“弟弟对新玩具不感兴趣”的表现相符。", "赶紧": "搭配：“赶紧”修饰动作，不修饰“不感兴趣”这样的心理状态。", "纷纷": "配价：“纷纷”要求复数的主语，句中主语“弟弟”只有一人。", "急忙": "搭配：“急忙”修饰动作，与“不感兴趣”这样的状态不搭配。"}, "sentence_index": 6, "correct_answer": "似乎"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是我的家，我似乎可以进去。", "explanation": "这里应该用〈当然〉。“似乎”表示不确定的推测，而“这是我的家”是说话人确信的事实。"}, {"text": "这张画是我昨天亲手画的，它似乎是我画的。", "explanation": "这里应该用〈确实〉。“亲手画的”说明说话人完全确定，“似乎”表示不确定的推测，两者矛盾，应说“它确实是我画的”。"}, {"text": "麻烦你似乎把这份文件交给老师。", "explanation": "这里应该用〈请〉。请求需要明确表达，“似乎”会使请求变得含糊，应说“请你把这份文件交给老师”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88162, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他站在窗前，似乎了在想事情。", "corrected_sentence": "他站在窗前，似乎在想事情。", "error_description": "“了”用错。“似乎”是副词，后面不能接“了”，应写作“他站在窗前，似乎在想事情”；“似乎了”不通。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88162, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "厨房里似乎地有声音，有人在做饭。", "corrected_sentence": "厨房里似乎有声音，有人在做饭。", "error_description": "“地”用错。“似乎”是副词，后面不能加“地”，应写作“似乎有声音”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
