INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88164, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "茎干柔软、较矮小的植物的统称。", "primary_collocate": null, "pronunciation": "cǎo", "ipa": "tsʰau̯˨˩˦", "syllable_count": 1, "sentences": [{"text": "这种草可以做药。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上有各种各样的草和花。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "草和树不一样，草比较矮。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在花园里种了几种草。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种草冬天也不会死。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们看了几种草的图片。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "沙漠里很少有草。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这片土地太干了，连草都不长。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说这种草泡水喝对身体好。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把草的叶子放在书里做书签。", "target_word": "草", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一种草", "label": "量词"}, {"form": "一棵草", "label": "量词"}, {"form": "草原", "label": "复合"}, {"form": "草药", "label": "复合"}], "register": "中性", "sense_fingerprint": "草：茎干柔软、较矮小的植物的统称（与树相对的一类植物）", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '314b788a-db43-4be2-9cd0-4c586b32fd88') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88164, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "草", "is_correct": true, "explanation": "正确答案：草，指茎干柔软、较矮小的植物。"}, {"text": "跑", "is_correct": false, "explanation": "pǎo 与 cǎo 的声母不同（p 与 c），意思是奔跑。"}, {"text": "保", "is_correct": false, "explanation": "bǎo 与 cǎo 的声母不同（b 与 c），意思是保护。"}, {"text": "脑", "is_correct": false, "explanation": "nǎo 与 cǎo 的声母不同（n 与 c），意思是大脑。"}, {"text": "搞", "is_correct": false, "explanation": "gǎo 与 cǎo 的声母不同（g 与 c），意思是做、搞。"}, {"text": "操", "is_correct": false, "explanation": "cāo（第一声）与 cǎo 的声调不同，意思是操作。"}], "explanations": {"草": "正确答案：草，指茎干柔软、较矮小的植物。", "跑": "pǎo 与 cǎo 的声母不同（p 与 c），意思是奔跑。", "保": "bǎo 与 cǎo 的声母不同（b 与 c），意思是保护。", "脑": "nǎo 与 cǎo 的声母不同（n 与 c），意思是大脑。", "搞": "gǎo 与 cǎo 的声母不同（g 与 c），意思是做、搞。", "操": "cāo（第一声）与 cǎo 的声调不同，意思是操作。"}, "sentence_index": null, "correct_answer": "草"}, "level_3": {"options": [{"text": "草", "is_correct": true, "explanation": "正确：这种草可以入药，符合语境。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：电脑是机器，不能做药。"}, {"text": "玻璃", "is_correct": false, "explanation": "语义：玻璃是矿物制品，不能做药。"}, {"text": "衣服", "is_correct": false, "explanation": "搭配：“做药”通常说草药、药材，不搭配“衣服”。"}], "explanations": {"草": "正确：这种草可以入药，符合语境。", "电脑": "语义：电脑是机器，不能做药。", "玻璃": "语义：玻璃是矿物制品，不能做药。", "衣服": "搭配：“做药”通常说草药、药材，不搭配“衣服”。"}, "sentence_index": 0, "correct_answer": "草"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在花园里种了几只草。", "explanation": "这里应该用〈种〉。“只”用于动物，说草的种类要用“种”。"}, {"text": "他在花园里种了几座草。", "explanation": "这里应该用〈种〉。“座”用于山、房屋等，不用于草的种类。"}, {"text": "他在花园里种了几首草。", "explanation": "这里应该用〈种〉。“首”用于诗歌、歌曲，不用于草的种类。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88164, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "草", "is_correct": true, "explanation": "正确答案：草，指茎干柔软、较矮小的植物。"}, {"text": "讨", "is_correct": false, "explanation": "tǎo 与 cǎo 的声母不同（t 与 c），意思是讨论。"}, {"text": "倒", "is_correct": false, "explanation": "dǎo 与 cǎo 的声母不同（d 与 c），意思是倒下。"}, {"text": "惨", "is_correct": false, "explanation": "cǎn 与 cǎo 的韵母不同（an 与 ao），意思是悲惨。"}, {"text": "糙", "is_correct": false, "explanation": "cāo（第一声）与 cǎo 的声调不同，意思是粗糙。"}], "explanations": {"草": "正确答案：草，指茎干柔软、较矮小的植物。", "讨": "tǎo 与 cǎo 的声母不同（t 与 c），意思是讨论。", "倒": "dǎo 与 cǎo 的声母不同（d 与 c），意思是倒下。", "惨": "cǎn 与 cǎo 的韵母不同（an 与 ao），意思是悲惨。", "糙": "cāo（第一声）与 cǎo 的声调不同，意思是粗糙。"}, "sentence_index": null, "correct_answer": "草"}, "level_3": {"options": [{"text": "草", "is_correct": true, "explanation": "正确：沙漠里少有草，符合语境。"}, {"text": "空气", "is_correct": false, "explanation": "语义：沙漠里一直有空气，不能说“很少有空气”。"}, {"text": "大海", "is_correct": false, "explanation": "语义：沙漠中没有大海，说“很少有大海”与语境矛盾。"}, {"text": "脚", "is_correct": false, "explanation": "搭配：“很少有”不用于人的身体部位，不说“很少有脚”。"}], "explanations": {"草": "正确：沙漠里少有草，符合语境。", "空气": "语义：沙漠里一直有空气，不能说“很少有空气”。", "大海": "语义：沙漠中没有大海，说“很少有大海”与语境矛盾。", "脚": "搭配：“很少有”不用于人的身体部位，不说“很少有脚”。"}, "sentence_index": 6, "correct_answer": "草"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "妈妈炒了一盘草，我们都吃得很香。", "explanation": "这里应该用〈菜〉。草不是人吃的食物，炒着吃的要说〈菜〉。"}, {"text": "这些草很硬，可以拿来做桌子。", "explanation": "这里应该用〈木头〉。草茎柔软，“很硬”和“做桌子”要用〈木头〉，草不能这样用。"}, {"text": "孩子们在操场上吃草，笑得很开心。", "explanation": "这里应该用〈饭〉。“吃草”只用于牲畜，人吃东西要说“吃饭”，草不是人吃的东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88164, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只草茎很软，可以编篮子。", "corrected_sentence": "这种草茎很软，可以编篮子。", "error_description": "错误在量词：说草的种类要用“种”，“只”用于动物，不能用于草。正确说法是“这种草”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88164, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "沙漠边缘偶尔能看到一些草们。", "corrected_sentence": "沙漠边缘偶尔能看到一些草。", "error_description": "错误在名词后缀：“们”只用于指人的名词，草不能加“们”。应说“一些草”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6729c4de-d3c2-4b1f-973e-a29fc495a78d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
