INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88166, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "研究某一学科或领域所用方法的理论。", "primary_collocate": null, "pronunciation": "fāng fǎ xué", "ipa": "faŋ˥ fa˨˩ ɕɥɛ˧˥", "syllable_count": 3, "sentences": [{"text": "这篇文章讲的是历史研究的方法学。", "target_word": "方法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医学研究也有自己的方法学。", "target_word": "方法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在做研究前，先读了方法学的书。", "target_word": "方法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个实验的方法学有问题。", "target_word": "方法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "教授请我们说说社会调查的方法学。", "target_word": "方法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老师的方法学课，讲的是怎么做研究。", "target_word": "方法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家们讨论了新的研究方法学。", "target_word": "方法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她写了一篇关于语言学方法学的论文。", "target_word": "方法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "方法学能让研究更清楚，也更可靠。", "target_word": "方法学", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书介绍了心理学的方法学。", "target_word": "方法学", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "门", "label": "量词"}], "register": "书面", "sense_fingerprint": "某学科或领域所用研究方法的理论", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed86873-7118-420e-9ec1-966e4a14f6b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88166, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "方法学", "is_correct": true, "explanation": "方法学：某一学科所用研究方法的理论，符合句意。"}, {"text": "数学", "is_correct": false, "explanation": "语义：“数学”不是历史研究所用的方法理论，历史研究不用“数学的方法学”来说。"}, {"text": "化学", "is_correct": false, "explanation": "语义：“化学”研究物质变化，与历史研究的方法无关。"}, {"text": "体育", "is_correct": false, "explanation": "搭配：“历史研究的体育”不成立，体育不是研究方法。"}], "explanations": {"方法学": "方法学：某一学科所用研究方法的理论，符合句意。", "数学": "语义：“数学”不是历史研究所用的方法理论，历史研究不用“数学的方法学”来说。", "化学": "语义：“化学”研究物质变化，与历史研究的方法无关。", "体育": "搭配：“历史研究的体育”不成立，体育不是研究方法。"}, "sentence_index": 0, "correct_answer": "方法学"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在大学里参观了方法学。", "explanation": "这里应该用〈学习〉。方法学是学问，不能参观，要说学习方法学。"}, {"text": "他写了一把方法学。", "explanation": "量词错误。方法学是理论，量词应用“门”，“把”不对。"}, {"text": "这个实验的方法学很甜。", "explanation": "这里应该用〈清楚〉。方法学是理论，只能说清楚或可靠，不能用味觉词“甜”来形容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88166, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "方法学", "is_correct": true, "explanation": "方法学：某一学科所用研究方法的理论，可以被科学家讨论，符合句意。"}, {"text": "语文", "is_correct": false, "explanation": "语义：“语文”是学科，不是研究方法，不能说“新的研究语文”。"}, {"text": "面包", "is_correct": false, "explanation": "语义：“面包”是食物，不能作“研究”的对象。"}, {"text": "脸色", "is_correct": false, "explanation": "语义：“脸色”指人脸上的颜色或表情，不是研究方法的理论，“新的研究脸色”说不通。"}], "explanations": {"方法学": "方法学：某一学科所用研究方法的理论，可以被科学家讨论，符合句意。", "语文": "语义：“语文”是学科，不是研究方法，不能说“新的研究语文”。", "面包": "语义：“面包”是食物，不能作“研究”的对象。", "脸色": "语义：“脸色”指人脸上的颜色或表情，不是研究方法的理论，“新的研究脸色”说不通。"}, "sentence_index": 6, "correct_answer": "方法学"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我种了方法学以后，做事更有条理了。", "explanation": "这里应该用〈学习〉。方法学是学问，不能种，要说学习方法学。"}, {"text": "这本书的方法学坏了，要拿去修。", "explanation": "方法学是研究方法的理论，不是机器，不能说“坏了”“拿去修”；可以说方法学“有问题”，需要改进。"}, {"text": "这本书介绍了一张心理学的方法学。", "explanation": "量词错误。方法学是理论，量词应用“门”，“张”不对。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88166, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她这学期选了一只方法学课。", "corrected_sentence": "她这学期选了一门方法学课。", "error_description": "量词错误。“方法学课”是课程，量词应用“门”，“一只”错误，正确为“一门方法学课”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88166, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这只方法学对研究很有帮助。", "corrected_sentence": "这门方法学对研究很有帮助。", "error_description": "量词错误。“方法学”是学科名，量词应用“门”，“只”不对，正确为“这门方法学”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88167, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "饱", "is_correct": true, "explanation": "反义：“饥饿”是想吃东西的状态，“饱”是吃足了不再想吃的状态，二者相对。"}, {"text": "柔软", "is_correct": false, "explanation": "无反义关系：“柔软”形容质地，与饥饿无关。"}, {"text": "明亮", "is_correct": false, "explanation": "无反义关系：“明亮”形容光线，与饥饿无关。"}, {"text": "平坦", "is_correct": false, "explanation": "无反义关系：“平坦”形容地面，与饥饿无关。"}], "correct_answer": "饱", "explanations": {"饱": "反义：“饥饿”是想吃东西的状态，“饱”是吃足了不再想吃的状态，二者相对。", "柔软": "无反义关系：“柔软”形容质地，与饥饿无关。", "明亮": "无反义关系：“明亮”形容光线，与饥饿无关。", "平坦": "无反义关系：“平坦”形容地面，与饥饿无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88167, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "饱", "is_correct": true, "explanation": "反义：“饥饿”指肚子空、想吃东西，“饱”指吃足了，二者相对。"}, {"text": "整洁", "is_correct": false, "explanation": "无反义关系：“整洁”形容干净有序，与饥饿无关。"}, {"text": "温暖", "is_correct": false, "explanation": "无反义关系：“温暖”形容温度，与饥饿这种生理状态无关。"}, {"text": "干燥", "is_correct": false, "explanation": "无反义关系：“干燥”形容湿度或质地，与饥饿无关。"}], "correct_answer": "饱", "explanations": {"饱": "反义：“饥饿”指肚子空、想吃东西，“饱”指吃足了，二者相对。", "整洁": "无反义关系：“整洁”形容干净有序，与饥饿无关。", "温暖": "无反义关系：“温暖”形容温度，与饥饿这种生理状态无关。", "干燥": "无反义关系：“干燥”形容湿度或质地，与饥饿无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88167, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "饥饿是肚子空空的，很想吃东西。", "primary_collocate": null, "pronunciation": "jī è", "ipa": "tɕi˥ ɤ˥˩", "syllable_count": 2, "sentences": [{"text": "肚子咕咕叫，我现在特别饥饿。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他饥饿地看着桌上的饭菜。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子放学回来，又累又饥饿。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饥饿的我一进门就找吃的。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你饥饿的时候，可以先吃点水果。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "减肥的时候，我常常觉得很饥饿。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟在雪地里饥饿地找虫子。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太饥饿了，我一下子吃了两个包子。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他没吃早饭，上课时越来越饥饿。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈知道孩子饥饿，马上做了面条。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "饥饿感", "label": "复合"}, {"form": "飢餓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "肚子空空、很想吃东西的感觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c7cd60d-49d3-4555-ad26-87a589e81504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88167, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饥饿", "is_correct": true, "explanation": "饥饿说明很想吃东西，与“肚子咕咕叫”一致，适合放在“特别”之后。"}, {"text": "饱", "is_correct": false, "explanation": "语义：“饱”指吃足了，与“肚子咕咕叫”矛盾。"}, {"text": "满足", "is_correct": false, "explanation": "语义：“满足”指需求已得到满足，与“肚子咕咕叫”的状态相反。"}, {"text": "饱满", "is_correct": false, "explanation": "搭配：“饱满”多形容果实或精神充沛，不用来描述“肚子咕咕叫”的饿感，“我现在特别饱满”与语境不符。"}], "explanations": {"饥饿": "饥饿说明很想吃东西，与“肚子咕咕叫”一致，适合放在“特别”之后。", "饱": "语义：“饱”指吃足了，与“肚子咕咕叫”矛盾。", "满足": "语义：“满足”指需求已得到满足，与“肚子咕咕叫”的状态相反。", "饱满": "搭配：“饱满”多形容果实或精神充沛，不用来描述“肚子咕咕叫”的饿感，“我现在特别饱满”与语境不符。"}, "sentence_index": 0, "correct_answer": "饥饿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在太阳下走了两个小时，现在饥饿得嗓子直冒烟。", "explanation": "这里应该用〈渴〉。饥饿指想吃东西，口干想喝水要说“渴”，不能用“饥饿”。"}, {"text": "见到多年不见的老朋友，我饥饿得紧紧拥抱了对方。", "explanation": "这里应该用〈激动〉。饥饿指想吃东西，见到老友的心情要说“激动”，不能用“饥饿”。"}, {"text": "夏天太热了，我饥饿得直冒汗。", "explanation": "这里应该用〈热〉。饥饿指想吃东西，天热出汗要说“热”，句子的原因是天气。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88167, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饥饿", "is_correct": true, "explanation": "饥饿指想吃东西，小鸟在雪地里找虫子的动机正是觅食，与句意相符。"}, {"text": "温暖", "is_correct": false, "explanation": "语义：“温暖”与“雪地”的寒冷环境矛盾，句子不通。"}, {"text": "香甜", "is_correct": false, "explanation": "搭配：“香甜”多形容食物或睡眠，不用来形容找虫子的动作。"}, {"text": "安逸", "is_correct": false, "explanation": "语义：“安逸”指舒适轻松，与雪地里艰苦觅食的情境矛盾。"}], "explanations": {"饥饿": "饥饿指想吃东西，小鸟在雪地里找虫子的动机正是觅食，与句意相符。", "温暖": "语义：“温暖”与“雪地”的寒冷环境矛盾，句子不通。", "香甜": "搭配：“香甜”多形容食物或睡眠，不用来形容找虫子的动作。", "安逸": "语义：“安逸”指舒适轻松，与雪地里艰苦觅食的情境矛盾。"}, "sentence_index": 6, "correct_answer": "饥饿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我吃坏了东西，肚子饥饿得厉害。", "explanation": "这里应该用〈疼〉。吃坏东西后肚子不舒服要说“疼”，饥饿指想吃东西。"}, {"text": "他被吵得很饥饿，一直皱着眉头。", "explanation": "这里应该用〈烦〉。被吵得心烦要说“烦”，饥饿指想吃东西。"}, {"text": "孩子考了一百分，饥饿得跳起来。", "explanation": "这里应该用〈开心〉。考了好成绩而高兴要说“开心”，饥饿指想吃东西。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88167, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他饥饿的盯着冰箱门。", "corrected_sentence": "他饥饿地盯着冰箱门。", "error_description": "“饥饿”修饰动词“盯”时要用“地”，不能用“的”，应说“饥饿地盯着冰箱门”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88167, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他午饭没吃，现在饥饿的厉害。", "corrected_sentence": "他午饭没吃，现在饥饿得厉害。", "error_description": "“饥饿”后面表示程度的补语要用“得”，不能用“的”。应说“现在饥饿得厉害”，不能说“现在饥饿的厉害”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
