INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88168, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "很长时间没有吃东西，感到非常想吃东西的状态。", "primary_collocate": null, "pronunciation": "jī è", "ipa": "tɕi˥ ɤ˥˩", "syllable_count": 2, "sentences": [{"text": "孩子一整天没吃饭，感到非常饥饿。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饥饿的小狗在门口等着主人。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他很饥饿，一口气吃了三碗饭。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "长时间不吃东西，人会觉得很饥饿。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只饥饿的猫一直叫个不停。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我早上没吃饭，到中午已经饥饿难忍了。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饥饿的人看到面包，眼睛都亮了。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他走了一天山路，又冷又饥饿。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灾区的人们又冷又饥饿，急需食物。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "饥饿的时候，什么饭都觉得好吃。", "target_word": "饥饿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "饥饿感", "label": "复合"}, {"form": "飢餓", "label": "繁体"}], "register": "中性", "sense_fingerprint": "长时间没吃东西而感到非常想吃的状态", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '1c7cd60d-49d3-4555-ad26-87a589e81504') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88168, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "饥饿", "is_correct": true, "explanation": "饥饿指长时间没吃东西而非常想吃，正符合“一整天没吃饭”的情况。"}, {"text": "饱", "is_correct": false, "explanation": "语义：“饱”指吃足了，与“一整天没吃饭”矛盾。"}, {"text": "瘦弱", "is_correct": false, "explanation": "语义：“瘦弱”描述身体瘦而弱的体形，不是没吃饭时想吃东西的感受，与句意不符。"}, {"text": "满足", "is_correct": false, "explanation": "语义：“满足”指需求已得到满足，与“没吃饭”的情况相反。"}], "explanations": {"饥饿": "饥饿指长时间没吃东西而非常想吃，正符合“一整天没吃饭”的情况。", "饱": "语义：“饱”指吃足了，与“一整天没吃饭”矛盾。", "瘦弱": "语义：“瘦弱”描述身体瘦而弱的体形，不是没吃饭时想吃东西的感受，与句意不符。", "满足": "语义：“满足”指需求已得到满足，与“没吃饭”的情况相反。"}, "sentence_index": 0, "correct_answer": "饥饿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我一天没喝水，现在特别饥饿。", "explanation": "这里应该用〈渴〉。饥饿指想吃东西，缺水时要说“渴”，两者不能互换。"}, {"text": "外面下着大雪，我没穿外套，饥饿得直发抖。", "explanation": "这里应该用〈冷〉。饥饿指想吃东西，没穿外套、在雪天发抖要说“冷”，不能用“饥饿”。"}, {"text": "我昨晚熬夜到凌晨，现在饥饿得眼皮直打架。", "explanation": "这里应该用〈困〉。饥饿指想吃东西，熬夜后眼皮打架、想睡觉要说“困”，不能用“饥饿”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88168, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "饥饿", "is_correct": true, "explanation": "饥饿修饰“人”，表示很想吃东西的状态，能解释看到面包眼睛发亮。"}, {"text": "厌烦", "is_correct": false, "explanation": "语义：“厌烦”指不喜欢、不想要，与“看到面包，眼睛都亮了”的喜欢和期待相反。"}, {"text": "香甜", "is_correct": false, "explanation": "搭配：“香甜”多形容食物或睡眠，不用来修饰人，“香甜的人”不通。"}, {"text": "冷静", "is_correct": false, "explanation": "语义：“冷静”指情绪平稳，与“眼睛都亮了”的兴奋状态相矛盾。"}], "explanations": {"饥饿": "饥饿修饰“人”，表示很想吃东西的状态，能解释看到面包眼睛发亮。", "厌烦": "语义：“厌烦”指不喜欢、不想要，与“看到面包，眼睛都亮了”的喜欢和期待相反。", "香甜": "搭配：“香甜”多形容食物或睡眠，不用来修饰人，“香甜的人”不通。", "冷静": "语义：“冷静”指情绪平稳，与“眼睛都亮了”的兴奋状态相矛盾。"}, "sentence_index": 6, "correct_answer": "饥饿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "大热天里，我饥饿得直冒汗。", "explanation": "这里应该用〈热〉。饥饿指想吃东西，天热出汗要说“热”，句子的原因是天气而不是饥饿。"}, {"text": "他摔伤了膝盖，一走路就很饥饿。", "explanation": "这里应该用〈疼〉。饥饿指想吃东西，膝盖受伤要说“疼”。"}, {"text": "这道题做了很久，他饥饿得直撕纸。", "explanation": "这里应该用〈烦〉。饥饿指想吃东西，题目做不出来让人心烦要说“烦”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88168, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "孩子一整天没吃饭，饥饿的等着开饭。", "corrected_sentence": "孩子一整天没吃饭，饥饿地等着开饭。", "error_description": "“地”是形容词作状语的标记。“饥饿”修饰动词“等”时要用“地”，不能用“的”，应说“饥饿地等着开饭”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88168, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他这两天饥饿的几乎不想说话。", "corrected_sentence": "他这两天饥饿得几乎不想说话。", "error_description": "“饥饿”后面表示程度的补语要用“得”，不能用“的”。应说“饥饿得几乎不想说话”，不能说“饥饿的几乎不想说话”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ffe354a4-8c5a-49b1-8966-b8dafce8806d') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88169, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "桌子", "is_correct": false, "explanation": "“桌子”是名词，与“来日”没有反义关系。"}, {"text": "河流", "is_correct": false, "explanation": "“河流”是名词，与“来日”的任何义项都没有反义关系。"}, {"text": "石头", "is_correct": false, "explanation": "“石头”是名词，与“来日”没有反义关系。"}, {"text": "往日", "is_correct": true, "explanation": "“往日”指过去的日子，与“来日”指将来的日子正好相反。"}], "correct_answer": "往日", "explanations": {"桌子": "“桌子”是名词，与“来日”没有反义关系。", "河流": "“河流”是名词，与“来日”的任何义项都没有反义关系。", "石头": "“石头”是名词，与“来日”没有反义关系。", "往日": "“往日”指过去的日子，与“来日”指将来的日子正好相反。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88169, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "书包", "is_correct": false, "explanation": "“书包”是名词，与“来日”没有反义关系。"}, {"text": "海洋", "is_correct": false, "explanation": "“海洋”是名词，与“来日”的任何义项都没有反义关系。"}, {"text": "窗户", "is_correct": false, "explanation": "“窗户”是名词，与“来日”没有反义关系。"}, {"text": "往日", "is_correct": true, "explanation": "“往日”指过去的日子，与“来日”指将来的日子正好相反。"}], "correct_answer": "往日", "explanations": {"书包": "“书包”是名词，与“来日”没有反义关系。", "海洋": "“海洋”是名词，与“来日”的任何义项都没有反义关系。", "窗户": "“窗户”是名词，与“来日”没有反义关系。", "往日": "“往日”指过去的日子，与“来日”指将来的日子正好相反。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88169, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "来日是还没有到的日子。", "primary_collocate": null, "pronunciation": "lái rì", "ipa": "lai̯˧˥ ʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "今天先说到这里，来日我们再聊。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说来日一定会报答你的帮助。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在多努力，来日才会过得好。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来日的事谁也不知道，别想太多。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这次没成功，来日还有机会。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老朋友告别时说：“来日再见！”", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们约好来日一起去海边玩。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他心里想着来日要开一家小店。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在存点钱，是为了来日用。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别怕失败，来日的路还很长。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "来日方长", "label": "成语"}], "register": "书面", "sense_fingerprint": "还没有到的日子，指将来", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ac39683-0e14-4009-8f9a-c5a67e844ca1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88169, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指已经过去的日子，与“我们再聊”所指的将来相冲突。"}, {"text": "当初", "is_correct": false, "explanation": "语义：“当初”指过去的时候，不能用来表示以后再聊。"}, {"text": "来日", "is_correct": true, "explanation": "“来日”指还没到的日子，与“再聊”的将来语境相符。"}, {"text": "河边", "is_correct": false, "explanation": "搭配：“河边”是地点，不能充当“再聊”的时间状语。"}], "explanations": {"昨天": "语义：“昨天”指已经过去的日子，与“我们再聊”所指的将来相冲突。", "当初": "语义：“当初”指过去的时候，不能用来表示以后再聊。", "来日": "“来日”指还没到的日子，与“再聊”的将来语境相符。", "河边": "搭配：“河边”是地点，不能充当“再聊”的时间状语。"}, "sentence_index": 0, "correct_answer": "来日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老人喜欢回忆来日的童年。", "explanation": "这里应该用“往昔”。“来日”指还没到的时间，不能用于回忆已经过去的童年。"}, {"text": "这件事来日已经解决了。", "explanation": "这里不用“来日”。“来日”指还没到的日子，不能用于已经完成的事情。"}, {"text": "我们住在来日附近。", "explanation": "这里不用“来日”。“来日”是时间词，不能表示地点，应换成“城市”这类地点名词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88169, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "昔日", "is_correct": false, "explanation": "语义：“昔日”指很久以前的日子，不能用于“约好”之后要做的事。"}, {"text": "公园", "is_correct": false, "explanation": "搭配：“公园”是地点，不能作时间状语，与“约好……一起去海边玩”不搭配。"}, {"text": "来日", "is_correct": true, "explanation": "“来日”指还没到的日子，与“约好”之后的将来安排相符。"}, {"text": "往昔", "is_correct": false, "explanation": "语义：“往昔”指过去，与约定好的将来安排冲突。"}], "explanations": {"昔日": "语义：“昔日”指很久以前的日子，不能用于“约好”之后要做的事。", "公园": "搭配：“公园”是地点，不能作时间状语，与“约好……一起去海边玩”不搭配。", "来日": "“来日”指还没到的日子，与“约好”之后的将来安排相符。", "往昔": "语义：“往昔”指过去，与约定好的将来安排冲突。"}, "sentence_index": 6, "correct_answer": "来日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我买了一个来日。", "explanation": "这里不用“来日”。“来日”指还没到的时间，是抽象的时段，不是可以买的东西。"}, {"text": "妈妈的来日很温柔。", "explanation": "这里不用“来日”。“来日”指还没到的时间，不能用来形容人的性格。"}, {"text": "他把来日放进了书包。", "explanation": "这里不用“来日”。“来日”是时间，不是具体的物品，不能用“把……放进”处置。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88169, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "来日了我们一起出发。", "corrected_sentence": "来日我们一起出发。", "error_description": "“来日”指将来，其后不能加“了”。“来日了我们一起出发”错误，应为“来日我们一起出发”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
