INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88170, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "将来的日子；也指第二天。", "primary_collocate": null, "pronunciation": "lái rì", "ipa": "lai̯˧˥ ʐ̩˥˩", "syllable_count": 2, "sentences": [{"text": "天色已晚，来日再谈这件事吧。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天太累了，来日再去看你。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他答应来日把书还给我。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来日的天气会比今天更好。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我不知道来日会发生什么。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她希望来日能当一名医生。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今天的工作做完了，来日继续。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你放心，来日我一定来帮你。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "来日的计划，我们明天再讨论。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天努力，只为来日过上好日子。", "target_word": "来日", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "来日方长", "label": "成语"}], "register": "书面", "sense_fingerprint": "将来的日子，也指第二天", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8ac39683-0e14-4009-8f9a-c5a67e844ca1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88170, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上周", "is_correct": false, "explanation": "语义：“上周”指已经过去的一周，与“再谈”的将来不符。"}, {"text": "桌上", "is_correct": false, "explanation": "搭配：“桌上”是地点，不能作时间状语。"}, {"text": "来日", "is_correct": true, "explanation": "“来日”指将来，与“再谈这件事”的后续安排相符。"}, {"text": "昨夜", "is_correct": false, "explanation": "语义：“昨夜”指已经过去的夜晚，与“再谈”冲突。"}], "explanations": {"上周": "语义：“上周”指已经过去的一周，与“再谈”的将来不符。", "桌上": "搭配：“桌上”是地点，不能作时间状语。", "来日": "“来日”指将来，与“再谈这件事”的后续安排相符。", "昨夜": "语义：“昨夜”指已经过去的夜晚，与“再谈”冲突。"}, "sentence_index": 0, "correct_answer": "来日"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我昨天就来日出发了。", "explanation": "这里不用“来日”。“来日”指将来或第二天，与“昨天就……了”的已完成语境相冲突。"}, {"text": "书本放在来日上了。", "explanation": "这里不用“来日”。“来日”是时间词，不能表示放置东西的地点或平面。"}, {"text": "这位老师的来日很严肃。", "explanation": "这里不用“来日”。“来日”不能用来形容人的性格，描述人应该用别的词。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88170, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "书桌", "is_correct": false, "explanation": "搭配：“书桌”是地点，不能作时间状语，与“继续”的时间安排不搭配。"}, {"text": "昨晚", "is_correct": false, "explanation": "语义：“昨晚”指已经过去的夜晚，与“继续”的后续安排冲突。"}, {"text": "来日", "is_correct": true, "explanation": "“来日”指将来，与“做完了……继续”的后续安排相符。"}, {"text": "当年", "is_correct": false, "explanation": "语义：“当年”指过去的某一年，与“继续”的后续安排冲突。"}], "explanations": {"书桌": "搭配：“书桌”是地点，不能作时间状语，与“继续”的时间安排不搭配。", "昨晚": "语义：“昨晚”指已经过去的夜晚，与“继续”的后续安排冲突。", "来日": "“来日”指将来，与“做完了……继续”的后续安排相符。", "当年": "语义：“当年”指过去的某一年，与“继续”的后续安排冲突。"}, "sentence_index": 6, "correct_answer": "来日"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "书架上摆着一个来日。", "explanation": "这里不用“来日”。“来日”指还没到的时间，是抽象的时段，不是可以摆放的具体物品。"}, {"text": "他去年来日就已经结婚了。", "explanation": "这里不用“来日”。“来日”指还没到的日子，不能用于已经发生的过去事件。"}, {"text": "他把来日送给了朋友。", "explanation": "这里不用“来日”。“来日”是时间，不是可以赠送的物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '16d65e25-72b9-4cf0-9326-67cdc132f9fa') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
