INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88171, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "阶级是社会里钱和工作差不多的一群人。", "primary_collocate": null, "pronunciation": "jiē jí", "ipa": "tɕjɛ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "住在这里的人都是同一个阶级，钱和工作都差不多。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们家和他们家不是一个阶级。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说，有钱人是一个阶级，工人是另一个阶级。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这部电影讲了两个阶级的人的故事。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她和他不属于同一个阶级，所以家人不同意。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里把社会分成了几个阶级。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "同一个阶级的人，生活常常差不多。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们属于不同的阶级，住的地方也不一样。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你觉得自己属于哪个阶级？", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们说说自己家是哪个阶级。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "阶级社会", "label": "复合"}, {"form": "工人阶级", "label": "复合"}, {"form": "中产阶级", "label": "复合"}, {"form": "階級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "社会里钱和工作差不多的一群人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c528a757-cc74-4946-831f-bf1e90a388f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88171, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "阶级", "is_correct": true, "explanation": "正确答案：阶级（jiē jí），指社会里钱和工作差不多的一群人。"}, {"text": "接机", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是到机场迎接乘客。"}, {"text": "接济", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是在经济上帮助他人。"}, {"text": "结集", "is_correct": false, "explanation": "jié（第二声）与 jiē（第一声）声调不同，意思是把人或东西聚集起来。"}], "explanations": {"阶级": "正确答案：阶级（jiē jí），指社会里钱和工作差不多的一群人。", "接机": "jī（第一声）与 jí（第二声）声调不同，意思是到机场迎接乘客。", "接济": "jì（第四声）与 jí（第二声）声调不同，意思是在经济上帮助他人。", "结集": "jié（第二声）与 jiē（第一声）声调不同，意思是把人或东西聚集起来。"}, "sentence_index": null, "correct_answer": "阶级"}, "level_3": {"options": [{"text": "阶级", "is_correct": true, "explanation": "阶级：钱和工作差不多的一群人，与“住在这里的人都是同一个阶级”相合。"}, {"text": "房间", "is_correct": false, "explanation": "语义：房间是空间，不是一群人，“同一个房间”的人不能说钱和工作差不多。"}, {"text": "体重", "is_correct": false, "explanation": "体貌：体重是个人身体特征，与“钱和工作都差不多”无关。"}, {"text": "动物", "is_correct": false, "explanation": "语义：住在这里的人不是动物，不能说是同一个动物。"}], "explanations": {"阶级": "阶级：钱和工作差不多的一群人，与“住在这里的人都是同一个阶级”相合。", "房间": "语义：房间是空间，不是一群人，“同一个房间”的人不能说钱和工作差不多。", "体重": "体貌：体重是个人身体特征，与“钱和工作都差不多”无关。", "动物": "语义：住在这里的人不是动物，不能说是同一个动物。"}, "sentence_index": 0, "correct_answer": "阶级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次活动分成了两个阶级，各自完成任务。", "explanation": "这里应该用〈小组〉。阶级指社会集团，不能指为完成活动临时分出的小组。"}, {"text": "这家工厂有两个阶级，各自生产不同的产品。", "explanation": "这里应该用〈车间〉。阶级指社会里经济地位相近的人群，不能用来指工厂里分出的生产单位；工厂里的生产单位应说车间。"}, {"text": "我们班分成了四个阶级，每个阶级负责打扫一间教室。", "explanation": "这里应该用〈小组〉。阶级指社会里经济地位相近的一群人，不能指班里为分配任务临时分出的小组。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88171, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阶级", "is_correct": true, "explanation": "阶级：社会中经济地位相同的人构成的群体，与“生活常常差不多”相合。"}, {"text": "星星", "is_correct": false, "explanation": "语义：星星不是人，不能说“同一个星星的人”。"}, {"text": "树", "is_correct": false, "explanation": "语义：树不是人，没有生活可以“差不多”，与句意不合。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材是体形特征，与“生活常常差不多”无关，不能用来划分群体。"}], "explanations": {"阶级": "阶级：社会中经济地位相同的人构成的群体，与“生活常常差不多”相合。", "星星": "语义：星星不是人，不能说“同一个星星的人”。", "树": "语义：树不是人，没有生活可以“差不多”，与句意不合。", "身材": "体貌：身材是体形特征，与“生活常常差不多”无关，不能用来划分群体。"}, "sentence_index": 6, "correct_answer": "阶级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这所学校有十个阶级，每班四十人。", "explanation": "这里应该用〈班级〉。阶级指经济地位相同的人构成的社会集团，不指学校里的班。"}, {"text": "他家有一个阶级，每天上班都要开它。", "explanation": "这里应该用〈车〉。阶级指社会中经济地位相近的人群，不能用来指可以驾驶的车辆；〈辆〉用于车。"}, {"text": "这个阶级有五个成员，经常一起排练。", "explanation": "这里应该用〈乐队〉。阶级是按经济地位划分的社会集团，不是为了排练而组成的团体。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88171, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这些人都属于同一条阶级，所以生活差不多。", "corrected_sentence": "这些人都属于同一个阶级，所以生活差不多。", "error_description": "量词误用：“阶级”要用“个”，不能用“条”（条多用于细长的东西）。应说：同一个阶级。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88171, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这阶级的人，生活常常比较苦。", "corrected_sentence": "这个阶级的人，生活常常比较苦。", "error_description": "量词缺失：指示词“这”之后要加量词“个”，应说“这个阶级”，不能说“这阶级”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
