INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88172, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "在一定社会中，由经济地位相同的人构成的社会集团。", "primary_collocate": null, "pronunciation": "jiē jí", "ipa": "tɕjɛ˥ tɕi˧˥", "syllable_count": 2, "sentences": [{"text": "这个社会里有很多不同的阶级。", "target_word": "阶级", "complexity_tier": "T3", "furigana": "jiē jí", "sentence_source": "generated"}, {"text": "不同阶级的人，经济地位也不一样。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在旧社会里，有钱人和穷人属于不同的阶级。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书里常常说到阶级的问题。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们的社会里，阶级之间的界限越来越模糊了。", "target_word": "阶级", "complexity_tier": "T3", "furigana": "jiē jí", "sentence_source": "generated"}, {"text": "他从小就知道自己属于哪个阶级。", "target_word": "阶级", "complexity_tier": "T3", "furigana": "jiē jí", "sentence_source": "generated"}, {"text": "老师给我们讲了社会各阶级的生活。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不同的阶级有不同的想法。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个阶级的经济地位差别很大。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想让不同阶级的人都能上学。", "target_word": "阶级", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "阶级社会", "label": "复合"}, {"form": "工人阶级", "label": "复合"}, {"form": "中产阶级", "label": "复合"}, {"form": "階級", "label": "繁体"}], "register": "中性", "sense_fingerprint": "社会中经济地位相同的人构成的集团", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c528a757-cc74-4946-831f-bf1e90a388f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88172, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "阶级", "is_correct": true, "explanation": "正确答案：阶级（jiē jí），指社会中经济地位相同的人构成的集团。"}, {"text": "接机", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是到机场迎接乘客。"}, {"text": "接济", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是在经济上帮助他人。"}, {"text": "结集", "is_correct": false, "explanation": "jié（第二声）与 jiē（第一声）声调不同，意思是把人或东西聚集起来。"}], "explanations": {"阶级": "正确答案：阶级（jiē jí），指社会中经济地位相同的人构成的集团。", "接机": "jī（第一声）与 jí（第二声）声调不同，意思是到机场迎接乘客。", "接济": "jì（第四声）与 jí（第二声）声调不同，意思是在经济上帮助他人。", "结集": "jié（第二声）与 jiē（第一声）声调不同，意思是把人或东西聚集起来。"}, "sentence_index": null, "correct_answer": "阶级"}, "level_3": {"options": [{"text": "阶级", "is_correct": true, "explanation": "阶级：在社会中经济地位相同的人构成的集团，与“社会里有很多不同的”相合。"}, {"text": "颜色", "is_correct": false, "explanation": "语义：社会里的人群不能按颜色划分，“不同的颜色”与社会语境不合。"}, {"text": "季节", "is_correct": false, "explanation": "语义：季节是时间的划分，不是社会中的人群。"}, {"text": "身高", "is_correct": false, "explanation": "体貌：身高是个人的体貌特征，不能用来划分社会群体。"}], "explanations": {"阶级": "阶级：在社会中经济地位相同的人构成的集团，与“社会里有很多不同的”相合。", "颜色": "语义：社会里的人群不能按颜色划分，“不同的颜色”与社会语境不合。", "季节": "语义：季节是时间的划分，不是社会中的人群。", "身高": "体貌：身高是个人的体貌特征，不能用来划分社会群体。"}, "sentence_index": 0, "correct_answer": "阶级"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "喜欢画画的同学组成了一个阶级，每周一起画画。", "explanation": "这里应该用〈小组〉。阶级指经济地位相同的人构成的社会集团，不能指因共同兴趣组成、一起活动的同学群体。"}, {"text": "人生有几个不同的阶级。", "explanation": "这里应该用〈阶段〉。阶级指社会集团，不能指人生的时期；人生的时期要用阶段。"}, {"text": "这所学校分成了两个阶级，分别上课。", "explanation": "这里应该用〈年级〉。阶级指经济地位相同的人构成的社会集团，不能用来指学校里按学业划分的年级。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88172, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "阶级", "is_correct": true, "explanation": "阶级：社会中的人群，“各阶级的生活”指不同群体的生活，与句意相合。"}, {"text": "制度", "is_correct": false, "explanation": "语义：制度是规章体系，不会有“生活”，与句中的人群语境不合。"}, {"text": "天气", "is_correct": false, "explanation": "语义：天气不是人群，不能说“各天气的生活”。"}, {"text": "课程", "is_correct": false, "explanation": "语义：课程是教学内容，没有“生活”，与“社会各…的生活”不合。"}], "explanations": {"阶级": "阶级：社会中的人群，“各阶级的生活”指不同群体的生活，与句意相合。", "制度": "语义：制度是规章体系，不会有“生活”，与句中的人群语境不合。", "天气": "语义：天气不是人群，不能说“各天气的生活”。", "课程": "语义：课程是教学内容，没有“生活”，与“社会各…的生活”不合。"}, "sentence_index": 6, "correct_answer": "阶级"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家医院有五个阶级，看不同的病。", "explanation": "这里应该用〈科室〉。阶级指社会里经济地位相同的人构成的集团，不能指医院里按病种划分的科室。"}, {"text": "这所大学有十个阶级，各有各的专业。", "explanation": "这里应该用〈学院〉。阶级指社会里经济地位相同的人群，不能用来指按专业划分的学院。"}, {"text": "这次考试的成绩分成了三个阶级。", "explanation": "这里应该用〈级别〉。阶级指社会里经济地位相同的人构成的集团，不用于考试成绩的等次。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88172, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "工人和资本家属于两条不同的阶级，利益常常不一样。", "corrected_sentence": "工人和资本家属于两个不同的阶级，利益常常不一样。", "error_description": "量词误用：“阶级”要用“个”，不能用“条”（条多用于细长的东西）。应改为：两个不同的阶级。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88172, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他说自己属于一阶级，所以生活很辛苦。", "corrected_sentence": "他说自己属于一个阶级，所以生活很辛苦。", "error_description": "量词缺失：“一”和“阶级”之间要加量词“个”，应说“一个阶级”，不能说“一阶级”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
