INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88173, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "日后是以后的日子，现在还没到。", "primary_collocate": null, "pronunciation": "rì hòu", "ipa": "ʐ̩˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "日后你会明白我的心意。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人生的路还很长，日后有的是机会，别着急。", "target_word": "日后", "complexity_tier": "T3", "furigana": "rén shēng de lù hái hěn cháng, rì hòu yǒu de shì jī huì, bié zháo jí.", "sentence_source": "generated"}, {"text": "现在多存点钱，日后用得上。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日后有机会，我一定去看你。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事日后再说吧。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他说日后会常常回来看看。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天帮了我，日后我一定帮你。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日后遇到难题，可以来找我。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "好好学习，日后才能找到好工作。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日后天气变冷了，记得多穿衣服。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "还没到的以后的日子，用于说将来会发生的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a96547-d1a2-4444-8d6e-1252fc20d0d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88173, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日后", "is_correct": true, "explanation": "正确。“日后”指以后的日子，与“会明白”的将来语境相符。"}, {"text": "昨天", "is_correct": false, "explanation": "语义：“昨天”指过去，与“会”表示的将来冲突。"}, {"text": "当初", "is_correct": false, "explanation": "搭配：“当初”多用于回顾过去，不与表示将来的“会”搭配。"}, {"text": "从前", "is_correct": false, "explanation": "语义：“从前”指过去的时期，与“会明白”的将来含义不合。"}], "explanations": {"日后": "正确。“日后”指以后的日子，与“会明白”的将来语境相符。", "昨天": "语义：“昨天”指过去，与“会”表示的将来冲突。", "当初": "搭配：“当初”多用于回顾过去，不与表示将来的“会”搭配。", "从前": "语义：“从前”指过去的时期，与“会明白”的将来含义不合。"}, "sentence_index": 0, "correct_answer": "日后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我小时候的日后很快乐，常和朋友一起玩。", "explanation": "这里应该用〈以前〉。“日后”只指将来，不能用来指小时候这样的过去时期。"}, {"text": "他去年还是学生，日后已经当上了老师。", "explanation": "这里应该用〈后来〉。“日后”指将来，不能和“已经”一起叙述已经发生的事。"}, {"text": "我当时没有钱，日后只好走路回家。", "explanation": "这里应该用〈最后〉。“日后”指将来，不能用来叙述过去已经发生的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88173, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日后", "is_correct": true, "explanation": "正确。“日后”指将来，与“一定帮你”的承诺语境相符。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”已经过去，与“一定帮你”的将来承诺不合。"}, {"text": "去年", "is_correct": false, "explanation": "语义：“去年”指过去的一年，与将来的承诺冲突。"}, {"text": "当年", "is_correct": false, "explanation": "搭配：“当年”多指过去某段岁月，不与“一定帮你”这类将来承诺搭配。"}], "explanations": {"日后": "正确。“日后”指将来，与“一定帮你”的承诺语境相符。", "上周": "语义：“上周”已经过去，与“一定帮你”的将来承诺不合。", "去年": "语义：“去年”指过去的一年，与将来的承诺冲突。", "当年": "搭配：“当年”多指过去某段岁月，不与“一定帮你”这类将来承诺搭配。"}, "sentence_index": 6, "correct_answer": "日后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "日后就要下雨了，你快回家吧。", "explanation": "这里应该用〈马上〉。“日后”指很久以后，不能用来说眼前马上要发生的事。"}, {"text": "他日后的脸色很红，一定是生气了。", "explanation": "这里应该用〈现在〉。“日后”只指将来，不能用来描述眼前的状态。"}, {"text": "这封信是我写的，日后寄出去了。", "explanation": "这里应该用〈已经〉。“日后”指将来，不能说已经寄出去的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88173, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你日后的会慢慢明白我的心意。", "corrected_sentence": "你日后会慢慢明白我的心意。", "error_description": "结构助词用错：“的”插在时间状语“日后”和动词“会”之间，句子结构不通，应说“你日后会慢慢明白我的心意”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88173, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "你今天帮了我，我日后日后一定帮你。", "corrected_sentence": "你今天帮了我，我日后一定帮你。", "error_description": "词语重复：“日后”只需说一次，“我日后日后一定帮你”多出一个“日后”，应说“我日后一定帮你”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
