INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88174, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "将来；以后。", "primary_collocate": null, "pronunciation": "rì hòu", "ipa": "ʐ̩˥˩ xoʊ˥˩", "syllable_count": 2, "sentences": [{"text": "她日后想当一名医生。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日后孩子长大了，会感谢你的。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路日后会变成大马路。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们日后还要一起工作。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日后的生活会越来越好。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们约好日后每年见一次面。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在不用担心日后的生活。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，日后你会用到这些知识。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "日后有变化，我会告诉你。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子日后一定有出息。", "target_word": "日后", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "书面", "sense_fingerprint": "将来、以后的时间，说人或事以后的情况", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a96547-d1a2-4444-8d6e-1252fc20d0d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88174, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "日后", "is_correct": true, "explanation": "正确。“日后”指将来，与“想当一名医生”这种长远愿望相符。"}, {"text": "当场", "is_correct": false, "explanation": "语义：“当场”指就在那一刻，与“想当一名医生”这种长期愿望不合。"}, {"text": "午后", "is_correct": false, "explanation": "语义：“午后”指一天中的时段，不能用来说长期的职业愿望。"}, {"text": "眼前", "is_correct": false, "explanation": "搭配：“眼前”多修饰眼下的情景，不与“想当……”这类长远目标搭配。"}], "explanations": {"日后": "正确。“日后”指将来，与“想当一名医生”这种长远愿望相符。", "当场": "语义：“当场”指就在那一刻，与“想当一名医生”这种长期愿望不合。", "午后": "语义：“午后”指一天中的时段，不能用来说长期的职业愿望。", "眼前": "搭配：“眼前”多修饰眼下的情景，不与“想当……”这类长远目标搭配。"}, "sentence_index": 0, "correct_answer": "日后"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们日后一起工作过，那段时光很开心。", "explanation": "这里应该用〈以前〉。“日后”只指将来，不能用来叙述已经发生过的经历。"}, {"text": "这次考试我们日后已经考完了。", "explanation": "这里应该用〈刚才〉。“日后”指将来，不能与“已经考完了”一起说已发生的事。"}, {"text": "我们当时是同事，日后曾经在一个办公室。", "explanation": "这里应该用〈过去〉。“日后”只指将来，不能和“曾经”一起说过去的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88174, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "日后", "is_correct": true, "explanation": "正确。“日后”指将来，与“不用担心”的未来生活相符。"}, {"text": "从前", "is_correct": false, "explanation": "语义：“从前”指过去的时期，不是需要担心的未来生活。"}, {"text": "年前", "is_correct": false, "explanation": "语义：“年前”指过年之前的一段时间，与长远的生活担忧不合。"}, {"text": "清晨", "is_correct": false, "explanation": "搭配：“清晨”指一天的早上，不能修饰需要长远担心的“生活”。"}], "explanations": {"日后": "正确。“日后”指将来，与“不用担心”的未来生活相符。", "从前": "语义：“从前”指过去的时期，不是需要担心的未来生活。", "年前": "语义：“年前”指过年之前的一段时间，与长远的生活担忧不合。", "清晨": "搭配：“清晨”指一天的早上，不能修饰需要长远担心的“生活”。"}, "sentence_index": 6, "correct_answer": "日后"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个孩子日后正在睡觉，你别吵他。", "explanation": "这里应该用〈现在〉。“日后”指将来，不能和“正在”一起描述正在进行的事。"}, {"text": "这个孩子日后就要放学了，你快去接他。", "explanation": "这里应该用〈马上〉。“日后”指很久以后，与“就要放学”的眼前时间冲突。"}, {"text": "这个孩子日后只有三岁，还不会说话。", "explanation": "这里应该用〈现在〉。“日后”指将来，不能用来说现在的年龄。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
