INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88174, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们日后日后还要一起努力。", "corrected_sentence": "我们日后还要一起努力。", "error_description": "词语重复：“日后”只需说一次，“我们日后日后还要一起努力”多出一个“日后”，应说“我们日后还要一起努力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
