INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88176, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "用烟草等卷成的细长圆筒，点燃后吸入烟雾。", "primary_collocate": null, "pronunciation": "xiāng yān", "ipa": "ɕiaŋ˥ jɛn˥", "syllable_count": 2, "sentences": [{"text": "桌子上放着一包香烟。", "target_word": "香烟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从口袋里拿出一支香烟。", "target_word": "香烟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种香烟又细又长。", "target_word": "香烟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他用火柴点燃了香烟。", "target_word": "香烟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "香烟里面有烟草。", "target_word": "香烟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "商店里卖各种各样的香烟。", "target_word": "香烟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把香烟放进嘴里，慢慢吸了一口。", "target_word": "香烟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地上有一根没抽完的香烟。", "target_word": "香烟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条香烟很贵，要五百块。", "target_word": "香烟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我朋友给了我一根香烟，我没要。", "target_word": "香烟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一支香烟", "label": "量词（支）"}, {"form": "一根香烟", "label": "量词（根）"}, {"form": "一条香烟", "label": "量词（条）"}, {"form": "香煙", "label": "繁体"}], "register": "中性", "sense_fingerprint": "烟草卷成的细长圆筒，点燃后吸入烟雾", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ca57c2-ac8c-47f7-b168-f786db53d8e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88176, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "香烟", "is_correct": true, "explanation": "正确：香烟（xiāng yān）指卷成细长圆筒、点燃后吸烟雾的东西。"}, {"text": "乡音", "is_correct": false, "explanation": "xiāng yīn（乡音）与 xiāng yān（香烟）只差韵母 an/in，意思是家乡口音。"}, {"text": "香艳", "is_correct": false, "explanation": "xiāng yàn（香艳）与 xiāng yān（香烟）只差声调，意思是华丽艳丽。"}, {"text": "相沿", "is_correct": false, "explanation": "xiāng yán（相沿）与 xiāng yān（香烟）只差声调，意思是沿袭下来。"}], "explanations": {"香烟": "正确：香烟（xiāng yān）指卷成细长圆筒、点燃后吸烟雾的东西。", "乡音": "xiāng yīn（乡音）与 xiāng yān（香烟）只差韵母 an/in，意思是家乡口音。", "香艳": "xiāng yàn（香艳）与 xiāng yān（香烟）只差声调，意思是华丽艳丽。", "相沿": "xiāng yán（相沿）与 xiāng yān（香烟）只差声调，意思是沿袭下来。"}, "sentence_index": null, "correct_answer": "香烟"}, "level_3": {"options": [{"text": "香烟", "is_correct": true, "explanation": "正确：一包香烟可以放在桌子上，与句意相合。"}, {"text": "空气", "is_correct": false, "explanation": "语义：空气不能装成一包放在桌上。"}, {"text": "阳光", "is_correct": false, "explanation": "语义：阳光无法装包放在桌上。"}, {"text": "雨水", "is_correct": false, "explanation": "搭配：「一包」用于袋装或包装的东西，不说一包雨水。"}], "explanations": {"香烟": "正确：一包香烟可以放在桌子上，与句意相合。", "空气": "语义：空气不能装成一包放在桌上。", "阳光": "语义：阳光无法装包放在桌上。", "雨水": "搭配：「一包」用于袋装或包装的东西，不说一包雨水。"}, "sentence_index": 0, "correct_answer": "香烟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他每天早上都洗香烟。", "explanation": "「香烟」是烟草制品，不能清洗；清洗的应是〈衣服〉。"}, {"text": "他用一根香烟给花浇了水。", "explanation": "「香烟」不能用来浇花；这里应说〈水〉。"}, {"text": "他每天早上用香烟刷牙。", "explanation": "「香烟」不能用来刷牙；这里应说〈牙膏〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88176, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "香烟", "is_correct": true, "explanation": "正确：香烟可以放进嘴里再吸一口，与句意相合。"}, {"text": "口香糖", "is_correct": false, "explanation": "搭配：口香糖只能嚼，不能说“吸一口”。"}, {"text": "饼干", "is_correct": false, "explanation": "搭配：饼干应说咬一口，不用“吸”。"}, {"text": "烟灰", "is_correct": false, "explanation": "语义：烟灰不能放进嘴里吸，句意不通。"}], "explanations": {"香烟": "正确：香烟可以放进嘴里再吸一口，与句意相合。", "口香糖": "搭配：口香糖只能嚼，不能说“吸一口”。", "饼干": "搭配：饼干应说咬一口，不用“吸”。", "烟灰": "语义：烟灰不能放进嘴里吸，句意不通。"}, "sentence_index": 6, "correct_answer": "香烟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "孩子把香烟当成玩具，拿着玩。", "explanation": "「香烟」是烟草制品，不是玩具；这里应说〈玩具〉。"}, {"text": "天太冷了，他穿上了一根香烟。", "explanation": "「香烟」是烟草制品，不能穿；天冷时穿的应是〈外套〉。"}, {"text": "他把香烟当成了笔，在纸上写字。", "explanation": "「香烟」不能当笔用；这里应说〈笔〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88176, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "桌子上还剩一只香烟。", "corrected_sentence": "桌子上还剩一根香烟。", "error_description": "量词错误：香烟用「根」「支」「包」，不能用「只」（「只」多用于动物）。“一只香烟”应改为“一根香烟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88176, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他抽完了一根的香烟，就去睡觉了。", "corrected_sentence": "他抽完了一根香烟，就去睡觉了。", "error_description": "结构错误：数量短语修饰名词时不加“的”。“一根的香烟”应改为“一根香烟”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
