INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88177, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "兄弟是哥哥和弟弟。", "primary_collocate": null, "pronunciation": "xiōng dì", "ipa": "ɕjʊŋ˥ ti˥˩", "syllable_count": 2, "sentences": [{"text": "他们兄弟两个都喜欢踢足球。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家有兄弟三个。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟俩一起去上学。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这对兄弟长得很像。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他和哥哥是亲兄弟。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟俩之间要互相帮助。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们兄弟三人住在北京。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没有兄弟，只有一个姐姐。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "兄弟两人每天一起吃饭。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这两个兄弟的名字很特别。", "target_word": "兄弟", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "名词；哥哥和弟弟；亲兄弟", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e59cd1e-273a-489b-abf0-17bb4fcc0b71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88177, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "兄弟", "is_correct": true, "explanation": "兄弟：指哥哥和弟弟，此处是“他们”这两个兄弟。"}, {"text": "三胞胎", "is_correct": false, "explanation": "语义：“三胞胎”指三个孩子，与“两个”的数量相矛盾。"}, {"text": "老人", "is_correct": false, "explanation": "搭配：“老人”不能与“他们”和“两个”组成“他们老人两个”这样的说法。"}, {"text": "陌生人", "is_correct": false, "explanation": "搭配：“陌生人”不是可以由“他们”统称的一组人，不能说“他们陌生人两个”。"}], "explanations": {"兄弟": "兄弟：指哥哥和弟弟，此处是“他们”这两个兄弟。", "三胞胎": "语义：“三胞胎”指三个孩子，与“两个”的数量相矛盾。", "老人": "搭配：“老人”不能与“他们”和“两个”组成“他们老人两个”这样的说法。", "陌生人": "搭配：“陌生人”不是可以由“他们”统称的一组人，不能说“他们陌生人两个”。"}, "sentence_index": 0, "correct_answer": "兄弟"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他和妹妹是兄弟。", "explanation": "这里应该用〈兄妹〉。兄弟只指哥哥和弟弟，“妹妹”是女性，不能用兄弟，应说“他和妹妹是兄妹”。"}, {"text": "我和叔叔是兄弟。", "explanation": "这里应该用〈叔侄〉。兄弟指哥哥和弟弟，“叔叔”是“我”父亲的弟弟，与“我”是叔侄关系，不能说兄弟。"}, {"text": "爷爷和奶奶是兄弟。", "explanation": "这里应该用〈夫妻〉。兄弟指哥哥和弟弟，“爷爷”和“奶奶”是夫妻，不能说兄弟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88177, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "兄弟", "is_correct": true, "explanation": "兄弟：指哥哥和弟弟等，此处是“他们”的三个兄弟。"}, {"text": "夫妻", "is_correct": false, "explanation": "语义：“夫妻”只指两人，与“三人”的数量相矛盾。"}, {"text": "母女", "is_correct": false, "explanation": "语义：“母女”通常指母亲和女儿两人，不能说“他们母女三人”指三个男子。"}, {"text": "情侣", "is_correct": false, "explanation": "语义：“情侣”通常只指两人，与“三人”的数量相矛盾。"}], "explanations": {"兄弟": "兄弟：指哥哥和弟弟等，此处是“他们”的三个兄弟。", "夫妻": "语义：“夫妻”只指两人，与“三人”的数量相矛盾。", "母女": "语义：“母女”通常指母亲和女儿两人，不能说“他们母女三人”指三个男子。", "情侣": "语义：“情侣”通常只指两人，与“三人”的数量相矛盾。"}, "sentence_index": 6, "correct_answer": "兄弟"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "她和姐姐是兄弟。", "explanation": "这里应该用〈姐妹〉。兄弟指哥哥和弟弟，“她”和“姐姐”都是女性，不能用兄弟。"}, {"text": "我的儿子和我是兄弟。", "explanation": "这里应该用〈父子〉（或母子）。兄弟指哥哥和弟弟，“儿子”是“我”的下一代，与“我”是父子或母子关系，不能说兄弟。"}, {"text": "我的侄子是我的兄弟。", "explanation": "这里应该用〈叔侄〉。兄弟指哥哥和弟弟，“侄子”是“我”的晚辈，与“我”是叔侄关系，不能说兄弟。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88177, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他家有三个兄弟们，都很优秀。", "corrected_sentence": "他家有三个兄弟，都很优秀。", "error_description": "错误：数量词“三个”后又加了“们”。“们”表示复数，不能与数词同用；应为“三个兄弟”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88177, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们兄弟的三人都是医生。", "corrected_sentence": "他们兄弟三人都是医生。", "error_description": "错误：“兄弟”与数量词“三人”之间多加了“的”。修饰数量时不能加“的”，应为“兄弟三人”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
