INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88179, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "高速是速度特别快。", "primary_collocate": null, "pronunciation": "gāo sù", "ipa": "kaʊ˥ su˥˩", "syllable_count": 2, "sentences": [{"text": "这辆车正在高速行驶。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "飞机在天上高速飞行。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个城市这几年高速发展。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风扇在高速转动，声音很大。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "火车高速经过了小城。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑着车高速冲下山坡。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "机器高速运转，要注意安全。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "经济高速增长，大家的收入也高了。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电脑高速处理着大量的数据。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "球高速飞过来，他没有接住。", "target_word": "高速", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高速公路", "label": "复合"}], "register": "中性", "sense_fingerprint": "速度特别快，多修饰行驶、发展、运转等动作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6ba22e3-4e03-4c26-838e-beb10be1ee6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88179, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高速", "is_correct": true, "explanation": "正确。高速：速度特别快。"}, {"text": "高数", "is_correct": false, "explanation": "shù（第四声）与 sù（第四声）声母不同，意思是高等数学，是口语说法。"}, {"text": "高度", "is_correct": false, "explanation": "dù（第四声）与 sù（第四声）声母不同，意思是高低的程度。"}, {"text": "告诉", "is_correct": false, "explanation": "gào（第四声）与 gāo（第一声）声调不同，意思是把事情讲给别人知道。"}], "explanations": {"高速": "正确。高速：速度特别快。", "高数": "shù（第四声）与 sù（第四声）声母不同，意思是高等数学，是口语说法。", "高度": "dù（第四声）与 sù（第四声）声母不同，意思是高低的程度。", "告诉": "gào（第四声）与 gāo（第一声）声调不同，意思是把事情讲给别人知道。"}, "sentence_index": null, "correct_answer": "高速"}, "level_3": {"options": [{"text": "高速", "is_correct": true, "explanation": "正确。“高速行驶”指速度特别快地行驶，符合语境。"}, {"text": "高大", "is_correct": false, "explanation": "体貌：“高大”描述身材或体形，不能修饰“行驶”。"}, {"text": "柔软", "is_correct": false, "explanation": "语义：“柔软”描述质地，不能描述车辆行驶的状态。"}, {"text": "粗壮", "is_correct": false, "explanation": "体貌：“粗壮”描述人或动物的体格，不用于车辆行驶。"}], "explanations": {"高速": "正确。“高速行驶”指速度特别快地行驶，符合语境。", "高大": "体貌：“高大”描述身材或体形，不能修饰“行驶”。", "柔软": "语义：“柔软”描述质地，不能描述车辆行驶的状态。", "粗壮": "体貌：“粗壮”描述人或动物的体格，不用于车辆行驶。"}, "sentence_index": 0, "correct_answer": "高速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家店的服务很高速。", "explanation": "这里应该用〈快〉。高速指运动或发展的速度特别快，不用来形容服务的效率。"}, {"text": "这棵树的高速有十米。", "explanation": "这里应该用〈高度〉。“高速”指速度特别快，不用来说树的高矮。"}, {"text": "这把椅子很高速。", "explanation": "这里应该用〈结实〉。“高速”指速度特别快，不用来形容椅子结不结实。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88179, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高速", "is_correct": true, "explanation": "正确。高速：速度特别快。"}, {"text": "高处", "is_correct": false, "explanation": "chù（第四声）与 sù 声母不同，意思是较高的地方。"}, {"text": "高祖", "is_correct": false, "explanation": "zǔ（第三声）与 sù（第四声）声母和声调都不同，意思是曾祖父的父亲。"}, {"text": "高足", "is_correct": false, "explanation": "zú（第二声）与 sù（第四声）声母和声调都不同，意思是别人的得意学生。"}], "explanations": {"高速": "正确。高速：速度特别快。", "高处": "chù（第四声）与 sù 声母不同，意思是较高的地方。", "高祖": "zǔ（第三声）与 sù（第四声）声母和声调都不同，意思是曾祖父的父亲。", "高足": "zú（第二声）与 sù（第四声）声母和声调都不同，意思是别人的得意学生。"}, "sentence_index": null, "correct_answer": "高速"}, "level_3": {"options": [{"text": "高速", "is_correct": true, "explanation": "正确。“高速运转”指速度特别快地运转，符合语境。"}, {"text": "活泼", "is_correct": false, "explanation": "语义：“活泼”形容人的性情，不能描述机器的运转。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容人的性情，机器不能“温柔”地运转。"}, {"text": "瘦", "is_correct": false, "explanation": "体貌：“瘦”描述人或动物的体形，不用于机器的运转。"}], "explanations": {"高速": "正确。“高速运转”指速度特别快地运转，符合语境。", "活泼": "语义：“活泼”形容人的性情，不能描述机器的运转。", "温柔": "语义：“温柔”形容人的性情，机器不能“温柔”地运转。", "瘦": "体貌：“瘦”描述人或动物的体形，不用于机器的运转。"}, "sentence_index": 6, "correct_answer": "高速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这家公司的技术很高速。", "explanation": "这里应该用〈高级〉。高速指速度特别快，不用来说技术的水平。"}, {"text": "这首歌的音调很高速，听起来很刺耳。", "explanation": "这里应该用〈高〉。“高速”指速度，不用来说音调的高低。"}, {"text": "这个人的性格很高速。", "explanation": "这里应该用〈急〉。高速指速度，不用来形容性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88179, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只鸟飞的高速很快。", "corrected_sentence": "那只鸟飞的速度很快。", "error_description": "错误在词性。“高速”是形容词，不能当名词表示速度，应说“速度”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88179, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "列车高速的驶过了小镇。", "corrected_sentence": "列车高速驶过了小镇。", "error_description": "错误在修饰词。“高速”修饰动词时不用“的”，直接放在动词前面即可，或用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
