INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88180, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "高速", "is_correct": true, "explanation": "正确。高速：速度很高的。"}, {"text": "高度", "is_correct": false, "explanation": "dù（第四声）与 sù（第四声）声母不同，意思是高低的程度。"}, {"text": "告诉", "is_correct": false, "explanation": "gào（第四声）与 gāo（第一声）声调不同，意思是把事情讲给别人知道。"}, {"text": "高数", "is_correct": false, "explanation": "shù（第四声）与 sù（第四声）声母不同，意思是高等数学，是口语说法。"}], "explanations": {"高速": "正确。高速：速度很高的。", "高度": "dù（第四声）与 sù（第四声）声母不同，意思是高低的程度。", "告诉": "gào（第四声）与 gāo（第一声）声调不同，意思是把事情讲给别人知道。", "高数": "shù（第四声）与 sù（第四声）声母不同，意思是高等数学，是口语说法。"}, "sentence_index": null, "correct_answer": "高速"}, "level_3": {"options": [{"text": "高速", "is_correct": true, "explanation": "正确。“高速的电机”指速度很高的电机，符合语境。"}, {"text": "温柔", "is_correct": false, "explanation": "语义：“温柔”形容人的性情，不能修饰电机。"}, {"text": "害羞", "is_correct": false, "explanation": "语义：“害羞”形容人的心理状态，不能修饰电机。"}, {"text": "粗壮", "is_correct": false, "explanation": "体貌：“粗壮”描述人或动物的体格，不能修饰电机。"}], "explanations": {"高速": "正确。“高速的电机”指速度很高的电机，符合语境。", "温柔": "语义：“温柔”形容人的性情，不能修饰电机。", "害羞": "语义：“害羞”形容人的心理状态，不能修饰电机。", "粗壮": "体貌：“粗壮”描述人或动物的体格，不能修饰电机。"}, "sentence_index": 0, "correct_answer": "高速"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这座大楼是高速的。", "explanation": "这里应该用〈高〉。“高速”指速度很高，不指建筑物的高度。"}, {"text": "这块石头的高速很大，搬起来很费劲。", "explanation": "这里应该用〈重〉。“高速”指速度很高，不用来说物体的轻重。"}, {"text": "这种花的颜色很高速。", "explanation": "“高速”指速度很高，不用来形容颜色。这里应该用〈鲜艳〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88180, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "高速", "is_correct": true, "explanation": "正确。高速：速度很高的。"}, {"text": "高处", "is_correct": false, "explanation": "chù（第四声）与 sù 声母不同，意思是较高的地方。"}, {"text": "高祖", "is_correct": false, "explanation": "zǔ（第三声）与 sù（第四声）声母和声调都不同，意思是曾祖父的父亲。"}, {"text": "高足", "is_correct": false, "explanation": "zú（第二声）与 sù（第四声）声母和声调都不同，意思是别人的得意学生。"}], "explanations": {"高速": "正确。高速：速度很高的。", "高处": "chù（第四声）与 sù 声母不同，意思是较高的地方。", "高祖": "zǔ（第三声）与 sù（第四声）声母和声调都不同，意思是曾祖父的父亲。", "高足": "zú（第二声）与 sù（第四声）声母和声调都不同，意思是别人的得意学生。"}, "sentence_index": null, "correct_answer": "高速"}, "level_3": {"options": [{"text": "高速", "is_correct": true, "explanation": "正确。“高速的水流”指速度很高的水流，符合语境。"}, {"text": "困倦", "is_correct": false, "explanation": "语义：“困倦”形容人的状态，不能修饰水流。"}, {"text": "瘦小", "is_correct": false, "explanation": "体貌：“瘦小”描述体形，不能修饰水流。"}, {"text": "懒惰", "is_correct": false, "explanation": "语义：“懒惰”形容人的品性，不能修饰水流。"}], "explanations": {"高速": "正确。“高速的水流”指速度很高的水流，符合语境。", "困倦": "语义：“困倦”形容人的状态，不能修饰水流。", "瘦小": "体貌：“瘦小”描述体形，不能修饰水流。", "懒惰": "语义：“懒惰”形容人的品性，不能修饰水流。"}, "sentence_index": 6, "correct_answer": "高速"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这碗汤很高速，喝的时候要小心。", "explanation": "这里应该用〈烫〉。“高速”指速度，不用来说汤的冷热。"}, {"text": "他的力气是高速的。", "explanation": "这里应该用〈大〉。“高速”指速度，不用来说力气的大小。"}, {"text": "这种茶的味道很高速。", "explanation": "这里应该用〈浓〉。“高速”指速度，不用来形容味道。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88180, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这是一台高速地打印机。", "corrected_sentence": "这是一台高速的打印机。", "error_description": "错误在修饰词。“高速”修饰名词“打印机”时要用“的”，不能用“地”。正确形式为“高速的打印机”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88180, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "子弹高速的射出，打中了目标。", "corrected_sentence": "子弹高速射出，打中了目标。", "error_description": "错误在修饰词。“高速”修饰动词“射出”时不用“的”，直接放在动词前面即可，或用“地”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
