INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88181, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "智力是人动脑筋、学习东西的本事。", "primary_collocate": null, "pronunciation": "zhì lì", "ipa": "ʈʂɨ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "这个孩子的智力很好，学东西特别快。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "玩这种游戏可以锻炼孩子的智力。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明的智力和别的孩子差不多，只是不爱读书。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷说多动脑筋，智力才不会变差。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说他的智力完全正常。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子的智力会随着年龄慢慢增长。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的智力不比别人差，就是太懒了。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "吃好睡好，对孩子智力的发展很重要。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种玩具能帮助孩子发展智力。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "成绩好不好，不只看智力，也要看努力。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "智力测验", "label": "复合词"}, {"form": "智力游戏", "label": "复合词"}, {"form": "智力开发", "label": "复合词"}], "register": "中性", "sense_fingerprint": "智力|动脑筋学东西的本事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8a3557-0c41-45ec-8b3a-0a993a565589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88181, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "智力", "is_correct": true, "explanation": "智力（zhì lì）：人动脑筋、学东西的本事。"}, {"text": "治理", "is_correct": false, "explanation": "zhìlǐ 第二个音节是第三声，与 zhìlì 的第四声声调不同，意思是治理。"}, {"text": "直立", "is_correct": false, "explanation": "zhílì 第一个音节是第二声，与 zhìlì 的第四声声调不同，意思是直立。"}, {"text": "自立", "is_correct": false, "explanation": "zì 与 zhì 声母不同（z 与 zh），意思是自立。"}, {"text": "市立", "is_correct": false, "explanation": "shìlì 与 zhìlì 声母不同（sh 与 zh），意思是市立。"}], "explanations": {"智力": "智力（zhì lì）：人动脑筋、学东西的本事。", "治理": "zhìlǐ 第二个音节是第三声，与 zhìlì 的第四声声调不同，意思是治理。", "直立": "zhílì 第一个音节是第二声，与 zhìlì 的第四声声调不同，意思是直立。", "自立": "zì 与 zhì 声母不同（z 与 zh），意思是自立。", "市立": "shìlì 与 zhìlì 声母不同（sh 与 zh），意思是市立。"}, "sentence_index": null, "correct_answer": "智力"}, "level_3": {"options": [{"text": "延长", "is_correct": false, "explanation": "搭配：“延长”用于期限、时间，不能与“智力很好”呼应。"}, {"text": "智力", "is_correct": true, "explanation": "智力：动脑筋、学东西的本事，与“学东西特别快”相符。"}, {"text": "身高", "is_correct": false, "explanation": "语义：“身高”与“学东西特别快”无关，句子意思不通。"}, {"text": "收入", "is_correct": false, "explanation": "语义：“收入”指挣来的钱，孩子没有收入，也与学习快慢无关。"}], "explanations": {"延长": "搭配：“延长”用于期限、时间，不能与“智力很好”呼应。", "智力": "智力：动脑筋、学东西的本事，与“学东西特别快”相符。", "身高": "语义：“身高”与“学东西特别快”无关，句子意思不通。", "收入": "语义：“收入”指挣来的钱，孩子没有收入，也与学习快慢无关。"}, "sentence_index": 0, "correct_answer": "智力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的游泳智力很强。", "explanation": "这里应该用〈能力〉。智力指动脑筋的本事，游泳这类技能要说能力。"}, {"text": "他的智力很好，能看清远处。", "explanation": "这里应该用〈视力〉。智力指动脑筋的本事，能看清远处要说视力。"}, {"text": "他的智力很丰富，什么都懂。", "explanation": "这里应该用〈知识〉。知识可以丰富，智力是能力，不说智力丰富。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88181, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "年龄", "is_correct": false, "explanation": "搭配：“年龄”指岁数，不能说“不比别人差”，句子不通。"}, {"text": "天气", "is_correct": false, "explanation": "语义：“天气”不是人具有的东西，不能说“他的天气不比别人差”。"}, {"text": "智力", "is_correct": true, "explanation": "智力：动脑筋的本事，与“不比别人差，就是太懒了”的转折相符。"}, {"text": "房价", "is_correct": false, "explanation": "搭配：“房价”是房子的价格，不能用来说人的能力。"}], "explanations": {"年龄": "搭配：“年龄”指岁数，不能说“不比别人差”，句子不通。", "天气": "语义：“天气”不是人具有的东西，不能说“他的天气不比别人差”。", "智力": "智力：动脑筋的本事，与“不比别人差，就是太懒了”的转折相符。", "房价": "搭配：“房价”是房子的价格，不能用来说人的能力。"}, "sentence_index": 6, "correct_answer": "智力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这首歌的智力很好听。", "explanation": "这里应该用〈声音〉。智力是动脑筋的本事，歌好不好听要说声音。"}, {"text": "他的智力很开阔。", "explanation": "这里应该用〈眼界〉。智力指认识和解决问题的能力，见识开阔要说眼界。"}, {"text": "这朵花的智力很鲜艳。", "explanation": "这里应该用〈颜色〉。智力不能形容鲜艳，花的鲜艳指颜色。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88181, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他有一只很特别的智力。", "corrected_sentence": "他有一种很特别的智力。", "error_description": "“智力”是抽象名词，量词应用“种”，不能用“只”。“只”多用于动物或成对、单个的具体事物。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88181, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "老师用游戏把孩子的智力开发。", "corrected_sentence": "老师用游戏把孩子的智力开发了。", "error_description": "“把”字句的动词后要有补语或“了”等成分。“把孩子的智力开发”结构不完整，应说“开发了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
