INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88182, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "人认识、理解客观事物并运用知识解决问题的能力。", "primary_collocate": null, "pronunciation": "zhì lì", "ipa": "ʈʂɨ˥˩ li˥˩", "syllable_count": 2, "sentences": [{"text": "心理学家用试题来测量人的智力。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "智力包括记忆、思考和解决问题的能力。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "研究发现，智力水平和家庭环境有关系。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位科学家的智力远远高于一般人。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "遇到难题，他靠智力而不是靠运气。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "人的智力需要在学习和生活中不断提高。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "动物也有一定的智力，比如聪明的乌鸦。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家认为，智力不是天生不变的。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他运用自己的智力，解决了这个难题。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题考的是智力，而不是记忆。", "target_word": "智力", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "智力测验", "label": "复合词"}, {"form": "智力游戏", "label": "复合词"}, {"form": "智力开发", "label": "复合词"}], "register": "中性", "sense_fingerprint": "智力|认识理解事物解决问题的能力", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8a3557-0c41-45ec-8b3a-0a993a565589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88182, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "智力", "is_correct": true, "explanation": "智力（zhì lì）：认识、理解事物并运用知识解决问题的能力。"}, {"text": "治理", "is_correct": false, "explanation": "zhìlǐ 第二个音节是第三声，与 zhìlì 的第四声声调不同，意思是治理。"}, {"text": "直立", "is_correct": false, "explanation": "zhílì 第一个音节是第二声，与 zhìlì 的第四声声调不同，意思是直立。"}, {"text": "自立", "is_correct": false, "explanation": "zì 与 zhì 声母不同（z 与 zh），意思是自立。"}, {"text": "市立", "is_correct": false, "explanation": "shìlì 与 zhìlì 声母不同（sh 与 zh），意思是市立。"}], "explanations": {"智力": "智力（zhì lì）：认识、理解事物并运用知识解决问题的能力。", "治理": "zhìlǐ 第二个音节是第三声，与 zhìlì 的第四声声调不同，意思是治理。", "直立": "zhílì 第一个音节是第二声，与 zhìlì 的第四声声调不同，意思是直立。", "自立": "zì 与 zhì 声母不同（z 与 zh），意思是自立。", "市立": "shìlì 与 zhìlì 声母不同（sh 与 zh），意思是市立。"}, "sentence_index": null, "correct_answer": "智力"}, "level_3": {"options": [{"text": "价格", "is_correct": false, "explanation": "语义：“价格”是东西值多少钱，人没有价格，试题也测不出价格。"}, {"text": "体力", "is_correct": false, "explanation": "语义：试题不能测量体力，句子里的测量对象是认识能力。"}, {"text": "智力", "is_correct": true, "explanation": "智力：认识、理解事物并解决问题的能力，正是试题测量的对象。"}, {"text": "香味", "is_correct": false, "explanation": "搭配：“测量”后面接“香味”不合适，这里的测量对象是能力。"}], "explanations": {"价格": "语义：“价格”是东西值多少钱，人没有价格，试题也测不出价格。", "体力": "语义：试题不能测量体力，句子里的测量对象是认识能力。", "智力": "智力：认识、理解事物并解决问题的能力，正是试题测量的对象。", "香味": "搭配：“测量”后面接“香味”不合适，这里的测量对象是能力。"}, "sentence_index": 0, "correct_answer": "智力"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位科学家的智力很丰富。", "explanation": "这里应该用〈知识〉。知识可以丰富，智力是能力本身，不说丰富。"}, {"text": "这位歌手的智力很清亮。", "explanation": "这里应该用〈嗓音〉。智力指认识和解决问题的能力，不能形容声音清亮，形容歌手的声音要说嗓音。"}, {"text": "这辆车的智力很快。", "explanation": "这里应该用〈速度〉。智力是人的能力，车的快慢要说速度。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88182, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "颜色", "is_correct": false, "explanation": "语义：“颜色”与“聪明的乌鸦”无关，句子在说动物的智力。"}, {"text": "智力", "is_correct": true, "explanation": "智力：认识和解决问题的能力，与“聪明的乌鸦”相符。"}, {"text": "学费", "is_correct": false, "explanation": "搭配：“学费”是学生交的钱，动物没有学费，不能这样说。"}, {"text": "房价", "is_correct": false, "explanation": "搭配：“房价”是房子的价格，不能用来说动物。"}], "explanations": {"颜色": "语义：“颜色”与“聪明的乌鸦”无关，句子在说动物的智力。", "智力": "智力：认识和解决问题的能力，与“聪明的乌鸦”相符。", "学费": "搭配：“学费”是学生交的钱，动物没有学费，不能这样说。", "房价": "搭配：“房价”是房子的价格，不能用来说动物。"}, "sentence_index": 6, "correct_answer": "智力"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的智力很熟练，几天就学会了。", "explanation": "这里应该用〈技能〉。智力是能力本身，不能说熟练，熟练要用来形容技能。"}, {"text": "他对家乡很有智力。", "explanation": "这里应该用〈感情〉。智力指认识和解决问题的能力，对家乡的情感要说感情。"}, {"text": "他的智力很勇敢，什么都敢做。", "explanation": "这里应该用〈胆量〉。智力不表示勇敢，敢做事要说有胆量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88182, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他智力解决了这个难题。", "corrected_sentence": "他用智力解决了这个难题。", "error_description": "“智力”在这里作工具，前面要加动词“用”，应说“用智力解决”，不能直接说“智力解决”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88182, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "人智力会随着年龄增长。", "corrected_sentence": "人的智力会随着年龄增长。", "error_description": "“人”和“智力”之间要用“的”连接。“人智力”不成词，应说“人的智力”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
