INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88183, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "体育活动是跑步、跳绳、打球这些让身体动起来的事。", "primary_collocate": null, "pronunciation": "tǐ yù huó dòng", "ipa": "tʰi˨˩˦ y˥˩ xwo˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "跑步、跳绳都是体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下课以后，孩子们在操场上做体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我每天晚上都做一点体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打球是我最喜欢的体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小明不爱写作业，只爱做体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天气好的时候，我们在公园里做体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说，吃完饭可以做点轻松的体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跳绳不用很大地方，是简单的体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "周末我常和朋友一起做体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天太冷，很多人不想出门做体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项体育活动", "label": "量词"}, {"form": "一次体育活动", "label": "量词"}, {"form": "户外体育活动", "label": "复合词"}], "register": "中性", "sense_fingerprint": "跑步、跳绳、打球等日常让身体动起来的事", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8adc4d6f-ebb2-4854-98ad-9066d9a002e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88183, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体育活动", "is_correct": true, "explanation": "“体育活动”指跑步、跳绳、打球等让身体动起来的事，符合“跑步、跳绳都是……”。"}, {"text": "水果", "is_correct": false, "explanation": "语义：水果是食物，跑步和跳绳不是水果。"}, {"text": "课题", "is_correct": false, "explanation": "语域：课题多用于科研或学术语境，“跑步、跳绳都是课题”不合语境。"}, {"text": "乐器", "is_correct": false, "explanation": "语义：乐器是演奏用具，与跑步、跳绳无关。"}], "explanations": {"体育活动": "“体育活动”指跑步、跳绳、打球等让身体动起来的事，符合“跑步、跳绳都是……”。", "水果": "语义：水果是食物，跑步和跳绳不是水果。", "课题": "语域：课题多用于科研或学术语境，“跑步、跳绳都是课题”不合语境。", "乐器": "语义：乐器是演奏用具，与跑步、跳绳无关。"}, "sentence_index": 0, "correct_answer": "体育活动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她每天的体育活动是写日记。", "explanation": "这里用错了词义。体育活动指身体动起来的活动，写日记是静坐的事，不算体育活动。"}, {"text": "我最喜欢的体育活动是躺在床上看手机。", "explanation": "这里用错了词义。体育活动指让身体动起来的事，躺着看手机不算体育活动。"}, {"text": "我最喜欢的体育活动是读书。", "explanation": "读书不让身体动起来，不属于体育活动，这里用错了词义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88183, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体育活动", "is_correct": true, "explanation": "“体育活动”指让身体动起来的活动，符合“做点轻松的……”。"}, {"text": "饮食", "is_correct": false, "explanation": "语义：饮食指吃喝，不能说“做点轻松的饮食”。"}, {"text": "午睡", "is_correct": false, "explanation": "搭配：午睡一般说“睡午觉”，不说“做午睡”。"}, {"text": "电影", "is_correct": false, "explanation": "语义：电影是影片，不能说“做点轻松的电影”。"}], "explanations": {"体育活动": "“体育活动”指让身体动起来的活动，符合“做点轻松的……”。", "饮食": "语义：饮食指吃喝，不能说“做点轻松的饮食”。", "午睡": "搭配：午睡一般说“睡午觉”，不说“做午睡”。", "电影": "语义：电影是影片，不能说“做点轻松的电影”。"}, "sentence_index": 6, "correct_answer": "体育活动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "冬天太冷，很多人不想出门，体育活动就是在家睡觉。", "explanation": "这里用错了词义。体育活动指身体动起来的活动，在家睡觉不算体育活动。"}, {"text": "这本书的体育活动很有趣，讲的是一个侦探故事。", "explanation": "体育活动指身体动起来的事，不能指书的内容。"}, {"text": "这个冬天，我们的体育活动是做作业。", "explanation": "这里用错了词义。体育活动指身体动起来的活动，做作业是坐着动脑的事，不属于体育活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88183, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "今天下午学校有一座体育活动。", "corrected_sentence": "今天下午学校有一项体育活动。", "error_description": "量词错误：“座”用于山、楼等，活动应用“项”或“次”，应说“一项体育活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88183, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们每周都做三只体育活动。", "corrected_sentence": "我们每周都做三次体育活动。", "error_description": "量词错误：活动应用“次”或“项”，“只”不用于活动，应说“三次体育活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
