INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88184, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "以增强体质、娱乐竞赛为目的的身体活动。", "primary_collocate": null, "pronunciation": "tǐ yù huó dòng", "ipa": "tʰi˨˩˦ y˥˩ xwo˧˥ tʊŋ˥˩", "syllable_count": 4, "sentences": [{"text": "经常参加体育活动，对身体很好。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校每周有三次体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他喜欢各种体育活动，特别是游泳。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老人每天早上也参加体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "体育活动能让人身体更健康。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个周末，社区组织了一项体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生说，孩子要多参加户外体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "公司为员工办了不少体育活动，大家都很高兴。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "篮球比赛是同学们最喜欢的体育活动。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "因为下雨，今天的体育活动改到了明天。", "target_word": "体育活动", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一项体育活动", "label": "量词"}, {"form": "一次体育活动", "label": "量词"}, {"form": "户外体育活动", "label": "复合词"}], "register": "中性", "sense_fingerprint": "为增强体质或娱乐、比赛而进行的身体活动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8adc4d6f-ebb2-4854-98ad-9066d9a002e2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88184, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "体育活动", "is_correct": true, "explanation": "“体育活动”指增强体质或娱乐竞赛的身体活动，符合“经常参加……对身体很好”。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验，与“对身体很好”不搭配。"}, {"text": "葬礼", "is_correct": false, "explanation": "语义：葬礼是丧事，不能说对身体有益。"}, {"text": "手术", "is_correct": false, "explanation": "语义：手术是医疗操作，不能说“经常参加手术对身体很好”，与锻炼身体的语境不合。"}], "explanations": {"体育活动": "“体育活动”指增强体质或娱乐竞赛的身体活动，符合“经常参加……对身体很好”。", "考试": "语义：考试是测验，与“对身体很好”不搭配。", "葬礼": "语义：葬礼是丧事，不能说对身体有益。", "手术": "语义：手术是医疗操作，不能说“经常参加手术对身体很好”，与锻炼身体的语境不合。"}, "sentence_index": 0, "correct_answer": "体育活动"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这台机器的体育活动很平稳。", "explanation": "这里应该用〈运动〉。体育活动指为健身或竞赛而做的身体活动，机器的运动不是这个意思，不能说“体育活动很平稳”。"}, {"text": "老人每天早上的体育活动是坐着喝茶。", "explanation": "这里用错了词义。体育活动指锻炼身体的活动，坐着喝茶不算体育活动。"}, {"text": "这首歌的体育活动很好听。", "explanation": "体育活动指身体活动，不能指歌曲的内容。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88184, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "体育活动", "is_correct": true, "explanation": "“体育活动”指增强体质的身体活动，符合“医生说孩子要多参加户外……”。"}, {"text": "答辩", "is_correct": false, "explanation": "语义：答辩指论文或学位答辩，与户外活动不相关。"}, {"text": "牙膏", "is_correct": false, "explanation": "语义：牙膏是日用品，不能“参加”。"}, {"text": "账单", "is_correct": false, "explanation": "语义：账单是账目单据，不能用于“多参加”的活动。"}], "explanations": {"体育活动": "“体育活动”指增强体质的身体活动，符合“医生说孩子要多参加户外……”。", "答辩": "语义：答辩指论文或学位答辩，与户外活动不相关。", "牙膏": "语义：牙膏是日用品，不能“参加”。", "账单": "语义：账单是账目单据，不能用于“多参加”的活动。"}, "sentence_index": 6, "correct_answer": "体育活动"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天的体育活动就是在沙发上看电视。", "explanation": "这里用错了词义。体育活动指身体动起来的活动，在沙发上看电视是静坐，不算体育活动。"}, {"text": "体育活动是一本书，我们每天读一章。", "explanation": "体育活动指身体动起来的活动，不是书，不能“读一章”。"}, {"text": "今天的体育活动是数学题。", "explanation": "这里用错了词义。体育活动指身体动起来的活动，数学题是脑力作业，不属于体育活动。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88184, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他每天放学后都做一只体育活动，身体很好。", "corrected_sentence": "他每天放学后都做一项体育活动，身体很好。", "error_description": "量词错误：活动应用“项”或“次”，“一只”的“只”多用于动物，应说“一项体育活动”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88184, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他们每周都做两张体育活动。", "corrected_sentence": "他们每周都做两次体育活动。", "error_description": "量词错误：“张”用于平面的东西，体育活动应用“次”或“项”计量，应说“两次体育活动”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c4800114-7876-4847-9a37-f4b844e70c66') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
