INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88185, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "公里是量很远的路的单位。", "primary_collocate": null, "pronunciation": "gōng lǐ", "ipa": "kʊŋ˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "我家离学校只有两公里。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这儿到火车站有五公里。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天早上跑步跑五公里。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路一共有十公里。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "前面三公里有一个加油站。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们走了八公里才到山顶。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开车去机场要走三十公里。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他骑自行车一小时能骑二十公里。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "从这里去海边还有多少公里？", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "昨天我走了很远的路，一共十二公里。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方公里", "label": "复合词"}, {"form": "公里数", "label": "复合词"}], "register": "中性", "sense_fingerprint": "量路程远近的单位，用在数词后面，如五公里", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2634a1f-e0ef-4c1b-853c-f701f33e6317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88185, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厘米", "is_correct": false, "explanation": "语义：“厘米”是很小的长度单位，“离学校只有两厘米”与常理不符。"}, {"text": "公里", "is_correct": true, "explanation": "“公里”是量路程的单位，“离学校只有两公里”表示距离，符合语境。"}, {"text": "公斤", "is_correct": false, "explanation": "搭配：“公斤”用来量重量，不能用来量距离。"}, {"text": "吨", "is_correct": false, "explanation": "搭配：“吨”用来量重量，不能说离学校有多少吨。"}], "explanations": {"厘米": "语义：“厘米”是很小的长度单位，“离学校只有两厘米”与常理不符。", "公里": "“公里”是量路程的单位，“离学校只有两公里”表示距离，符合语境。", "公斤": "搭配：“公斤”用来量重量，不能用来量距离。", "吨": "搭配：“吨”用来量重量，不能说离学校有多少吨。"}, "sentence_index": 0, "correct_answer": "公里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块地有十公里。", "explanation": "这里应该用〈平方公里〉。“公里”量长度，量面积要用“平方公里”。"}, {"text": "这箱苹果重十公里。", "explanation": "这里应该用〈公斤〉。“公里”量距离，量重量要用“公斤”。"}, {"text": "我等了他十公里。", "explanation": "这里应该用〈分钟〉。“公里”只量距离，表示等待的时长要用“分钟”或“小时”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88185, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "米", "is_correct": false, "explanation": "语义：“三十米”太短，与“开车去机场”的远距离不符。"}, {"text": "亩", "is_correct": false, "explanation": "搭配：“亩”是面积单位，不能用来量路程。"}, {"text": "公里", "is_correct": true, "explanation": "“三十公里”表示开车到机场的距离，符合常理，填入此处正确。"}, {"text": "斤", "is_correct": false, "explanation": "搭配：“斤”是重量单位，不能用来量路程。"}], "explanations": {"米": "语义：“三十米”太短，与“开车去机场”的远距离不符。", "亩": "搭配：“亩”是面积单位，不能用来量路程。", "公里": "“三十公里”表示开车到机场的距离，符合常理，填入此处正确。", "斤": "搭配：“斤”是重量单位，不能用来量路程。"}, "sentence_index": 6, "correct_answer": "公里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这瓶水有五公里。", "explanation": "这里应该用〈升〉。“公里”只量长度，量液体的容量要用“升”。"}, {"text": "他的身高是两公里。", "explanation": "这里应该用〈米〉。“公里”不用来量身高，身高要用“米”或“厘米”。"}, {"text": "这份报告有十公里。", "explanation": "这里应该用〈页〉。“公里”只用来量路程，文件的数量要用“页”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88185, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "从我家到地铁站大约有两个公里。", "corrected_sentence": "从我家到地铁站大约有两公里。", "error_description": "错误在“公里”前面多加了“个”。“公里”是量词，数词后面直接接它，不能再加“个”，应说“两公里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88185, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "从超市走到车站要三本公里。", "corrected_sentence": "从超市走到车站要三公里。", "error_description": "错误在“公里”前面的数词后多加了量词“本”。“本”用于书册，不能用来计量距离，应说“要三公里”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
