INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88186, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "长度单位，一公里等于一千米。", "primary_collocate": null, "pronunciation": "gōng lǐ", "ipa": "kʊŋ˥ li˨˩˦", "syllable_count": 2, "sentences": [{"text": "一公里等于一千米。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一公里是一千米，不是一百米。", "target_word": "公里", "complexity_tier": "T3", "furigana": "yì gōng lǐ shì yì qiān mǐ, bú shì yì bǎi mǐ.", "sentence_source": "generated"}, {"text": "地图上的一厘米代表一公里。", "target_word": "公里", "complexity_tier": "T3", "furigana": "dì tú shàng de yì lí mǐ dài biǎo yì gōng lǐ.", "sentence_source": "generated"}, {"text": "老师说，一千米就是一公里。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条河长三公里，也就是三千米。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "五公里等于五千米。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥长两公里，也就是两千米。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个公园的环形步道一圈是一公里。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我把三公里换成了三千米。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一公里比一百米长得多。", "target_word": "公里", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "平方公里", "label": "复合词"}, {"form": "公里数", "label": "复合词"}], "register": "中性", "sense_fingerprint": "国际通用的长度单位，一公里等于一千米", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2634a1f-e0ef-4c1b-853c-f701f33e6317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88186, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厘米", "is_correct": false, "explanation": "语义：“一厘米”远小于一千米，“一厘米等于一千米”与事实不符。"}, {"text": "米", "is_correct": false, "explanation": "语义：“一米”也不等于一千米，数值关系不成立。"}, {"text": "公里", "is_correct": true, "explanation": "“公里”是长度单位，“一公里等于一千米”的换算正确，填入此处合适。"}, {"text": "吨", "is_correct": false, "explanation": "搭配：“吨”是重量单位，不能与长度单位“千米”相等。"}], "explanations": {"厘米": "语义：“一厘米”远小于一千米，“一厘米等于一千米”与事实不符。", "米": "语义：“一米”也不等于一千米，数值关系不成立。", "公里": "“公里”是长度单位，“一公里等于一千米”的换算正确，填入此处合适。", "吨": "搭配：“吨”是重量单位，不能与长度单位“千米”相等。"}, "sentence_index": 0, "correct_answer": "公里"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块草地的面积有五公里。", "explanation": "这里应该用〈平方公里〉。“公里”量长度，面积要用“平方公里”。"}, {"text": "我迟到了三公里。", "explanation": "这里应该用〈分钟〉。“公里”量距离，迟到的时长要用“分钟”。"}, {"text": "这包饼干重五公里。", "explanation": "这里应该用〈克〉。“公里”量长度，重量要用“克”或“公斤”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88186, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毫米", "is_correct": false, "explanation": "语义：“两毫米”与后半句“也就是两千米”数值矛盾。"}, {"text": "斤", "is_correct": false, "explanation": "搭配：“斤”是重量单位，不能用来量桥的长度。"}, {"text": "公里", "is_correct": true, "explanation": "“公里”与“千米”同为长度单位，“两公里，也就是两千米”换算正确，填入此处合适。"}, {"text": "亩", "is_correct": false, "explanation": "搭配：“亩”是面积单位，不能用来量桥的长度。"}], "explanations": {"毫米": "语义：“两毫米”与后半句“也就是两千米”数值矛盾。", "斤": "搭配：“斤”是重量单位，不能用来量桥的长度。", "公里": "“公里”与“千米”同为长度单位，“两公里，也就是两千米”换算正确，填入此处合适。", "亩": "搭配：“亩”是面积单位，不能用来量桥的长度。"}, "sentence_index": 6, "correct_answer": "公里"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这罐牛奶有一公里。", "explanation": "这里应该用〈升〉。“公里”只量长度，量液体要用“升”或“毫升”。"}, {"text": "这套书一共有十公里。", "explanation": "这里应该用〈本〉。“公里”量路程，书的数量要用“本”。"}, {"text": "他的年龄是三公里。", "explanation": "这里应该用〈岁〉。“公里”不能表示年龄，年龄要用“岁”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88186, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条马路大概有三条公里长。", "corrected_sentence": "这条马路大概有三公里长。", "error_description": "错误在“公里”前面的数词后多加了量词“条”。“公里”本身就是量词，数词后直接接它，应说“三公里”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
