INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明亮", "is_correct": true, "explanation": "“明亮”指有光、亮堂，与“黑暗”在没有光的意义上相对。"}, {"text": "聪明", "is_correct": false, "explanation": "“聪明”形容头脑灵活，与“黑暗”没有反义关系。"}, {"text": "寒冷", "is_correct": false, "explanation": "“寒冷”与“温暖”相对，与“黑暗”没有反义关系。"}, {"text": "整齐", "is_correct": false, "explanation": "“整齐”指排列有序，与“黑暗”没有反义关系。"}], "correct_answer": "明亮", "explanations": {"明亮": "“明亮”指有光、亮堂，与“黑暗”在没有光的意义上相对。", "聪明": "“聪明”形容头脑灵活，与“黑暗”没有反义关系。", "寒冷": "“寒冷”与“温暖”相对，与“黑暗”没有反义关系。", "整齐": "“整齐”指排列有序，与“黑暗”没有反义关系。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "明亮", "is_correct": true, "explanation": "“明亮”指有光、亮堂，与“黑暗”在没有光的意义上相对。"}, {"text": "安静", "is_correct": false, "explanation": "“安静”指没有声音，与“黑暗”没有反义关系。"}, {"text": "热闹", "is_correct": false, "explanation": "“热闹”指人多声杂，与“黑暗”没有反义关系。"}, {"text": "甜蜜", "is_correct": false, "explanation": "“甜蜜”形容味道或感情美好，与“黑暗”没有反义关系。"}], "correct_answer": "明亮", "explanations": {"明亮": "“明亮”指有光、亮堂，与“黑暗”在没有光的意义上相对。", "安静": "“安静”指没有声音，与“黑暗”没有反义关系。", "热闹": "“热闹”指人多声杂，与“黑暗”没有反义关系。", "甜蜜": "“甜蜜”形容味道或感情美好，与“黑暗”没有反义关系。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "黑暗是没有光，什么也看不见。", "primary_collocate": null, "pronunciation": "hēi àn", "ipa": "xei˥ an˥˩", "syllable_count": 2, "sentences": [{"text": "黑暗里什么也看不见。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "停电后，屋子里很黑暗。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子怕黑暗，不敢一个人睡。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洞里又冷又黑暗。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她在黑暗中慢慢往前走。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天黑了，路上越来越黑暗。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我打开灯，黑暗不见了。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地下室很黑暗，要带手电。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "黑暗的房间里没有一点声音。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在黑暗中找到了门。", "target_word": "黑暗", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "中性", "sense_fingerprint": "形容词；没有光；什么也看不见", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e59cd1e-273a-489b-abf0-17bb4fcc0b71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "耀眼", "is_correct": false, "explanation": "语义：“耀眼”指光很强，与“什么也看不见”矛盾。"}, {"text": "黑暗", "is_correct": true, "explanation": "正确：“黑暗”指没有光，与“什么也看不见”一致。"}, {"text": "雪白", "is_correct": false, "explanation": "语义：“雪白”描述可见的颜色，与“什么也看不见”矛盾。"}, {"text": "温暖", "is_correct": false, "explanation": "搭配：“温暖”描述温度或气氛，不能作为“里”前的处所词。"}], "explanations": {"耀眼": "语义：“耀眼”指光很强，与“什么也看不见”矛盾。", "黑暗": "正确：“黑暗”指没有光，与“什么也看不见”一致。", "雪白": "语义：“雪白”描述可见的颜色，与“什么也看不见”矛盾。", "温暖": "搭配：“温暖”描述温度或气氛，不能作为“里”前的处所词。"}, "sentence_index": 0, "correct_answer": "黑暗"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这块布料是黑暗的，做窗帘正好。", "explanation": "这里应该用〈漆黑〉。“黑暗”指没有光，不用来形容布料的颜色；颜色深要用“漆黑”。"}, {"text": "台灯亮着，屋里的光线很黑暗。", "explanation": "这里应该用〈昏暗〉。灯亮着时光线只能是昏暗，“黑暗”指完全没有光，与亮着的台灯矛盾。"}, {"text": "晒了一个夏天，他的胳膊很黑暗。", "explanation": "这里应该用〈黝黑〉。“黑暗”不用来说皮肤的颜色，晒得很深的皮肤要用“黝黑”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "光亮", "is_correct": false, "explanation": "语义：开了灯，光亮应当出现，不会“不见了”，与“打开灯”矛盾。"}, {"text": "黑暗", "is_correct": true, "explanation": "正确：开灯后黑暗会消失，“不见了”与之搭配。"}, {"text": "干净", "is_correct": false, "explanation": "搭配：“干净”指没有污垢的状态，不能作为会“不见了”的事物。"}, {"text": "宽敞", "is_correct": false, "explanation": "搭配：“宽敞”形容空间，不能用作“不见了”的主语。"}], "explanations": {"光亮": "语义：开了灯，光亮应当出现，不会“不见了”，与“打开灯”矛盾。", "黑暗": "正确：开灯后黑暗会消失，“不见了”与之搭配。", "干净": "搭配：“干净”指没有污垢的状态，不能作为会“不见了”的事物。", "宽敞": "搭配：“宽敞”形容空间，不能用作“不见了”的主语。"}, "sentence_index": 6, "correct_answer": "黑暗"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他一听这话，脸色立刻黑暗下来。", "explanation": "这里应该用〈阴沉〉。“黑暗”指缺少光线，形容脸色要用“阴沉”或说“脸色黑下来”。"}, {"text": "节日晚会的气氛很黑暗，大家都在唱歌跳舞。", "explanation": "这里应该用〈热闹〉。“黑暗”指没有光，与唱歌跳舞的气氛矛盾；形容场面欢快要用“热闹”。"}, {"text": "这间教室的窗户很大，阳光很好，里面黑暗得很。", "explanation": "这里应该用〈明亮〉。窗户大、阳光好，屋里应当明亮，“黑暗”指没有光，与语境矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "山洞里黑暗的什么也看不见。", "corrected_sentence": "山洞里黑暗得什么也看不见。", "error_description": "错误形式“黑暗的什么也看不见”，正确形式“黑暗得什么也看不见”。“什么也看不见”是表示程度的补语，要用“得”，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88187, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "楼道里太黑暗地，我看不清台阶。", "corrected_sentence": "楼道里太黑暗了，我看不清台阶。", "error_description": "错误形式“太黑暗地”，正确形式“太黑暗了”。“太……了”是固定格式，表示程度很高；“地”用在修饰动词的词语后面，不能用在这里的句末位置。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
