INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88190, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "改变，变更（多指制度、办法）。", "primary_collocate": null, "pronunciation": "gēng zhāng", "ipa": "kɤŋ˥ ʈʂɑŋ˥", "syllable_count": 2, "sentences": [{"text": "这项制度已经更张了好几次。", "target_word": "更张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的政策一旦更张，大家都会知道。", "target_word": "更张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "学校的规定不能随便更张。", "target_word": "更张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "旧制度不合时宜，必须更张。", "target_word": "更张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些年来，公司的做法几次更张。", "target_word": "更张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他主张更张现行的办法，可是没人同意。", "target_word": "更张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新校长来了以后，学校的制度更张了不少。", "target_word": "更张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条法令用了很久，还没有更张过。", "target_word": "更张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们要更张的是办法，不是目标。", "target_word": "更张", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要想让工作做得更好，旧制度就得更张。", "target_word": "更张", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "更张了", "label": "完成体"}, {"form": "更张过", "label": "经历体"}, {"form": "改弦更张", "label": "成语"}], "register": "书面语", "sense_fingerprint": "更张|改变制度办法", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'aa8a3557-0c41-45ec-8b3a-0a993a565589') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88190, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "唱", "is_correct": false, "explanation": "搭配：“唱”的对象是歌曲，制度不能用唱。"}, {"text": "更张", "is_correct": true, "explanation": "更张：改变制度，与“已经……了好几次”相符。"}, {"text": "晾晒", "is_correct": false, "explanation": "搭配：“晾晒”用于衣物、粮食，不能用于制度。"}, {"text": "浇灌", "is_correct": false, "explanation": "搭配：“浇灌”用于植物，不能用于制度。"}], "explanations": {"唱": "搭配：“唱”的对象是歌曲，制度不能用唱。", "更张": "更张：改变制度，与“已经……了好几次”相符。", "晾晒": "搭配：“晾晒”用于衣物、粮食，不能用于制度。", "浇灌": "搭配：“浇灌”用于植物，不能用于制度。"}, "sentence_index": 0, "correct_answer": "更张"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "老师让我们更张作业里的错误。", "explanation": "这里应该用〈改正〉。更张是改变制度、办法，改掉作业里的错误要说改正。"}, {"text": "学校正在更张教学楼。", "explanation": "这里应该用〈整修〉。更张用于制度、办法，不用于楼房的修缮，整修教学楼要说整修。"}, {"text": "我每天都要更张一次衣服。", "explanation": "这里应该用〈换〉。更张指改变制度、办法，换衣服要说换，不能用更张。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88190, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "保持", "is_correct": false, "explanation": "语义：“保持”是维持原样，与“新校长来了以后”带来的变化相反。"}, {"text": "栽培", "is_correct": false, "explanation": "搭配：“栽培”用于植物或人才，不能说栽培制度。"}, {"text": "更张", "is_correct": true, "explanation": "更张：改变制度，与“新校长来了以后”和“不少”相符。"}, {"text": "充电", "is_correct": false, "explanation": "搭配：“充电”用于电器、电池，“学校的制度”不能充电。"}], "explanations": {"保持": "语义：“保持”是维持原样，与“新校长来了以后”带来的变化相反。", "栽培": "搭配：“栽培”用于植物或人才，不能说栽培制度。", "更张": "更张：改变制度，与“新校长来了以后”和“不少”相符。", "充电": "搭配：“充电”用于电器、电池，“学校的制度”不能充电。"}, "sentence_index": 6, "correct_answer": "更张"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把这首诗更张成了英文。", "explanation": "这里应该用〈翻译〉。更张是换掉旧办法，不表示把作品译成另一种语言，应说翻译。"}, {"text": "季节更张了，天气也冷了。", "explanation": "这里应该用〈变化〉。更张要求人有意换掉旧办法，季节的变化不是这种意义，应说变化。"}, {"text": "园丁更张了树枝。", "explanation": "这里应该用〈修剪〉。更张用于办法、制度，不用于修剪树枝，应说修剪。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88190, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们几年来一直没有更张了这项制度。", "corrected_sentence": "我们几年来一直没有更张这项制度。", "error_description": "“没有”表示未发生，不能与表示完成的“了”同用。“没有更张了”是错误形式，应说“没有更张”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88190, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "大家早就更张了过这个制度。", "corrected_sentence": "大家早就更张过这个制度。", "error_description": "“了”与“过”不能同用。表示经历用“过”，去掉“了”，应说“更张过这个制度”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4b1afb66-c79d-40ef-a6aa-a4d63f9c1e44') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88191, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低帮", "is_correct": true, "explanation": "正确：“低帮”与“高帮”相对，指鞋帮低。"}, {"text": "厚", "is_correct": false, "explanation": "无关：“厚”说厚度，与鞋帮高低无关。"}, {"text": "软", "is_correct": false, "explanation": "无关：“软”说质地，与鞋帮高低无关。"}, {"text": "宽", "is_correct": false, "explanation": "无关：“宽”说宽窄，与鞋帮高低无关。"}], "correct_answer": "低帮", "explanations": {"低帮": "正确：“低帮”与“高帮”相对，指鞋帮低。", "厚": "无关：“厚”说厚度，与鞋帮高低无关。", "软": "无关：“软”说质地，与鞋帮高低无关。", "宽": "无关：“宽”说宽窄，与鞋帮高低无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88191, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低帮", "is_correct": true, "explanation": "正确：“低帮”与“高帮”相对，指鞋帮低。"}, {"text": "松", "is_correct": false, "explanation": "无关：“松”说松紧，与鞋帮高低无关。"}, {"text": "硬", "is_correct": false, "explanation": "无关：“硬”说质地，与鞋帮高低无关。"}, {"text": "短", "is_correct": false, "explanation": "无关：“短”说长度，与鞋帮高低无关。"}], "correct_answer": "低帮", "explanations": {"低帮": "正确：“低帮”与“高帮”相对，指鞋帮低。", "松": "无关：“松”说松紧，与鞋帮高低无关。", "硬": "无关：“硬”说质地，与鞋帮高低无关。", "短": "无关：“短”说长度，与鞋帮高低无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88191, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "高帮是鞋子高高的，能盖住脚踝。", "primary_collocate": null, "pronunciation": "gāo bāng", "ipa": "kɑʊ˥ pɑŋ˥", "syllable_count": 2, "sentences": [{"text": "这双鞋是高帮的，穿着很暖和。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想买一双鞋，要高帮的，这样脚不冷。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的球鞋是高帮的，能盖住脚踝。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双黑鞋是高帮的，穿着很结实。", "target_word": "高帮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "爬山时最好穿高帮的鞋。", "target_word": "高帮", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "妹妹的白鞋是高帮的，上面还有小花。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨天，我穿了高帮的雨鞋，脚一点也没湿。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥打篮球的时候，总是穿高帮的球鞋。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "比起低帮的，我更喜欢高帮的，走路更稳。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "店员说这双鞋是高帮的，不容易崴脚。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高帮鞋", "label": "复合"}, {"form": "高幫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "鞋子的鞋帮很高，能盖住脚踝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '572e04e2-6b86-4c93-ad0e-9ef951c337f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88191, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高帮", "is_correct": true, "explanation": "正确：“高帮”指鞋帮高，这里描述这双鞋，能保暖。"}, {"text": "凉快", "is_correct": false, "explanation": "语义：“凉快”表示凉爽，与后面的“穿着很暖和”相矛盾。"}, {"text": "薄", "is_correct": false, "explanation": "语义：“薄”说厚度小，鞋子薄就不暖和，与“很暖和”矛盾。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不能用来形容鞋子。"}], "explanations": {"高帮": "正确：“高帮”指鞋帮高，这里描述这双鞋，能保暖。", "凉快": "语义：“凉快”表示凉爽，与后面的“穿着很暖和”相矛盾。", "薄": "语义：“薄”说厚度小，鞋子薄就不暖和，与“很暖和”矛盾。", "甜": "搭配：“甜”说味道，不能用来形容鞋子。"}, "sentence_index": 0, "correct_answer": "高帮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家新买的椅子是高帮的，坐着很舒服。", "explanation": "这里把“高帮”用成了椅背高的意思，但高帮只指鞋子的鞋帮高，不能形容椅子。"}, {"text": "这件衣服的领子很高，是高帮的。", "explanation": "这里应该用〈高领〉。领子高要说高领，高帮只用于鞋子的鞋帮高。"}, {"text": "这辆车的车门很高，是高帮的。", "explanation": "这里说的是车门高，应该用〈高〉之类的说法。高帮只用于鞋子，不能形容车门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88191, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高帮", "is_correct": true, "explanation": "正确：“高帮”指鞋帮高，雨鞋鞋帮高，脚才不会湿。"}, {"text": "低帮", "is_correct": false, "explanation": "语义：鞋帮低，雨水容易进去，与“脚一点也没湿”矛盾。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”说温度，不能用来形容雨鞋。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不能用来形容雨鞋。"}], "explanations": {"高帮": "正确：“高帮”指鞋帮高，雨鞋鞋帮高，脚才不会湿。", "低帮": "语义：鞋帮低，雨水容易进去，与“脚一点也没湿”矛盾。", "烫": "搭配：“烫”说温度，不能用来形容雨鞋。", "甜": "搭配：“甜”说味道，不能用来形容雨鞋。"}, "sentence_index": 6, "correct_answer": "高帮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这条裤子的腰很高，是高帮的。", "explanation": "这里应该用〈高腰〉。高帮只说鞋帮高，裤子腰高要用高腰。"}, {"text": "他的个子很高，是高帮的。", "explanation": "这里说的是人身材高，应该用〈高〉。高帮只用于鞋子。"}, {"text": "这张桌子的腿很高，是高帮的。", "explanation": "这里说的是桌腿高，高帮只能形容鞋子的鞋帮高，不能用来形容桌子。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88191, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我想买一双高帮了的鞋，适合爬山。", "corrected_sentence": "我想买一双高帮的鞋，适合爬山。", "error_description": "错误：“高帮”修饰名词“鞋”时要用“的”，不能在它后面加“了”。应说“高帮的鞋”，不能说“高帮了的鞋”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88191, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "店员推荐了一双高帮了鞋，很适合爬山。", "corrected_sentence": "店员推荐了一双高帮的鞋，很适合爬山。", "error_description": "错误：“高帮”修饰名词“鞋”时要用“的”，不能用“了”。应说“高帮的鞋”，不能说“高帮了鞋”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88192, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低帮", "is_correct": true, "explanation": "正确：“低帮”与“高帮”相对，指鞋帮低。"}, {"text": "紧", "is_correct": false, "explanation": "无关：“紧”说松紧，与鞋帮高低无关。"}, {"text": "松", "is_correct": false, "explanation": "无关：“松”说松紧，与鞋帮高低无关。"}, {"text": "硬", "is_correct": false, "explanation": "无关：“硬”说质地，与鞋帮高低无关。"}], "correct_answer": "低帮", "explanations": {"低帮": "正确：“低帮”与“高帮”相对，指鞋帮低。", "紧": "无关：“紧”说松紧，与鞋帮高低无关。", "松": "无关：“松”说松紧，与鞋帮高低无关。", "硬": "无关：“硬”说质地，与鞋帮高低无关。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88192, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "低帮", "is_correct": true, "explanation": "正确：“低帮”与“高帮”相对，指鞋帮低。"}, {"text": "宽", "is_correct": false, "explanation": "无关：“宽”说宽窄，与鞋帮高低无关。"}, {"text": "短", "is_correct": false, "explanation": "无关：“短”说长度，与鞋帮高低无关。"}, {"text": "亮", "is_correct": false, "explanation": "无关：“亮”说光线或颜色，与鞋帮高低无关。"}], "correct_answer": "低帮", "explanations": {"低帮": "正确：“低帮”与“高帮”相对，指鞋帮低。", "宽": "无关：“宽”说宽窄，与鞋帮高低无关。", "短": "无关：“短”说长度，与鞋帮高低无关。", "亮": "无关：“亮”说光线或颜色，与鞋帮高低无关。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88192, 1, 'prompt1_core', '{"pos": "形容词", "semantic_class": "property", "definition": "（鞋子）鞋帮较高的，能包住脚踝。", "primary_collocate": null, "pronunciation": "gāo bāng", "ipa": "kɑʊ˥ pɑŋ˥", "syllable_count": 2, "sentences": [{"text": "我的帆布鞋是高帮的，能包住脚踝。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "滑雪的时候，要穿高帮的鞋来保护脚踝。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟刚学走路，妈妈给他买了高帮的小鞋。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老张的皮鞋是高帮的，冬天雪水不会进去。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "跑步时我选低帮的，爬山时我选高帮的。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店卖的运动鞋大多是高帮的。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她把裤腿塞进高帮的球鞋里，免得沾上泥。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我扭过脚，以后只穿高帮的鞋。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这双鞋是高帮的，穿的时候要系好鞋带。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今天穿的是高帮的，走山路很稳。", "target_word": "高帮", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "高帮鞋", "label": "复合"}, {"form": "高幫", "label": "繁体"}], "register": "中性", "sense_fingerprint": "（鞋子）鞋帮较高的，能包住脚踝", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '572e04e2-6b86-4c93-ad0e-9ef951c337f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88192, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "高帮", "is_correct": true, "explanation": "正确：“高帮”指鞋帮高，能包住脚踝，这里描述帆布鞋。"}, {"text": "低帮", "is_correct": false, "explanation": "语义：鞋帮低，不能包住脚踝，与后半句“能包住脚踝”矛盾。"}, {"text": "香", "is_correct": false, "explanation": "搭配：“香”说气味，不能用来形容鞋子。"}, {"text": "甜", "is_correct": false, "explanation": "搭配：“甜”说味道，不能用来形容鞋子。"}], "explanations": {"高帮": "正确：“高帮”指鞋帮高，能包住脚踝，这里描述帆布鞋。", "低帮": "语义：鞋帮低，不能包住脚踝，与后半句“能包住脚踝”矛盾。", "香": "搭配：“香”说气味，不能用来形容鞋子。", "甜": "搭配：“甜”说味道，不能用来形容鞋子。"}, "sentence_index": 0, "correct_answer": "高帮"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把伞是高帮的，下雨时很挡雨。", "explanation": "这里把“高帮”用成了伞面高、遮雨多的意思，但高帮只指鞋帮高，不能形容伞。"}, {"text": "这座房子的门很高，是高帮的。", "explanation": "这里说的是门高，应该用〈高〉。高帮只用于鞋子，不能形容房门。"}, {"text": "这个水杯的杯身很高，是高帮的。", "explanation": "这里说的是杯身高，应该用〈高〉。高帮只指鞋帮高，不能形容水杯。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88192, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "高帮", "is_correct": true, "explanation": "正确：高帮的球鞋能把裤腿塞进去，不让泥沾上，这里描述球鞋。"}, {"text": "低帮", "is_correct": false, "explanation": "语义：低帮的鞋鞋帮低，裤腿塞不进去，起不到“免得沾上泥”的作用。"}, {"text": "烫", "is_correct": false, "explanation": "搭配：“烫”说温度，不能用来形容球鞋。"}, {"text": "响", "is_correct": false, "explanation": "搭配：“响”说声音，不能用来形容球鞋。"}], "explanations": {"高帮": "正确：高帮的球鞋能把裤腿塞进去，不让泥沾上，这里描述球鞋。", "低帮": "语义：低帮的鞋鞋帮低，裤腿塞不进去，起不到“免得沾上泥”的作用。", "烫": "搭配：“烫”说温度，不能用来形容球鞋。", "响": "搭配：“响”说声音，不能用来形容球鞋。"}, "sentence_index": 6, "correct_answer": "高帮"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件毛衣的领子很高，是高帮的。", "explanation": "这里应该用〈高领〉。领子高要说高领，高帮只用于鞋子。"}, {"text": "这座山很高，是高帮的。", "explanation": "这里说的是山高，应该用〈高〉。高帮只用于鞋，不能形容山。"}, {"text": "这辆车的车身很高，是高帮的。", "explanation": "这里说的是车身高，高帮只能用来形容鞋帮，不能形容车。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88192, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "滑雪的时候，他穿了一双高帮了靴子。", "corrected_sentence": "滑雪的时候，他穿了一双高帮的靴子。", "error_description": "错误：“高帮”修饰名词“靴子”时要用“的”，不能用“了”。应说“高帮的靴子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88192, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她的球鞋是高帮地，穿着很舒服。", "corrected_sentence": "她的球鞋是高帮的，穿着很舒服。", "error_description": "错误：“的”写成了“地”。“是……的”结构中要用“的”，“地”用来修饰动作或状态，这里不用。应说“她的球鞋是高帮的，穿着很舒服。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fc4c3068-c7ea-4d2c-bc87-6e527f09faa2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
