INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88194, 1, 'prompt1_core', '{"pos": "助词", "semantic_class": "function", "definition": "语气词，用在句末，表示疑问、感叹或使语气缓和。", "primary_collocate": null, "pronunciation": "ya", "ipa": "ja", "syllable_count": 1, "sentences": [{"text": "你怎么还不睡呀？", "target_word": "呀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这是谁的鞋呀？", "target_word": "呀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你在看什么呀？", "target_word": "呀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这里的风景多美呀！", "target_word": "呀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今天去哪儿呀？", "target_word": "呀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是谁呀？", "target_word": "呀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个孩子真可爱呀！", "target_word": "呀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你好呀，好久不见！", "target_word": "呀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别客气呀，多吃一点儿。", "target_word": "呀", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你怎么不说话呀？", "target_word": "呀", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "呀：句末语气词，表示疑问、感叹或缓和语气", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'fe9756ff-4b06-4a9a-9345-22a235fc21d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88194, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "牙", "is_correct": false, "explanation": "牙（yá，第二声）与呀（ya，轻声）声调不同，意思是牙齿。"}, {"text": "哑", "is_correct": false, "explanation": "哑（yǎ，第三声）与呀声调不同，意思是不能出声。"}, {"text": "呀", "is_correct": true, "explanation": "正确答案。呀作句末语气词时轻声读 ya。"}, {"text": "雅", "is_correct": false, "explanation": "雅（yǎ，第三声）与呀声调不同，意思是文雅。"}], "explanations": {"牙": "牙（yá，第二声）与呀（ya，轻声）声调不同，意思是牙齿。", "哑": "哑（yǎ，第三声）与呀声调不同，意思是不能出声。", "呀": "正确答案。呀作句末语气词时轻声读 ya。", "雅": "雅（yǎ，第三声）与呀声调不同，意思是文雅。"}, "sentence_index": null, "correct_answer": "呀"}, "level_3": {"options": [{"text": "而已", "is_correct": false, "explanation": "搭配：“而已”表示限定，不能用于“怎么……”的追问。"}, {"text": "呗", "is_correct": false, "explanation": "语义：“呗”表示无奈或随意，与追问“怎么还不睡”的语气不合。"}, {"text": "呀", "is_correct": true, "explanation": "正确：句末语气词，使追问的语气柔和。"}, {"text": "罢了", "is_correct": false, "explanation": "搭配：“罢了”表示限定，“你怎么还不睡罢了”说不通。"}], "explanations": {"而已": "搭配：“而已”表示限定，不能用于“怎么……”的追问。", "呗": "语义：“呗”表示无奈或随意，与追问“怎么还不睡”的语气不合。", "呀": "正确：句末语气词，使追问的语气柔和。", "罢了": "搭配：“罢了”表示限定，“你怎么还不睡罢了”说不通。"}, "sentence_index": 0, "correct_answer": "呀"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "本公司于二〇二六年成立呀。", "explanation": "公司简介是陈述性书面文字，句末用句号；“呀”这类口语语气词不适合用在这里。"}, {"text": "根据调查，该产品存在质量问题呀。", "explanation": "调查报告用书面陈述，句末用句号；语气词“呀”只用于日常口语。"}, {"text": "现将有关事项通知如下呀。", "explanation": "通知的正文应用句号收尾，“通知如下”后不接语气词“呀”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88194, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "芽", "is_correct": false, "explanation": "芽（yá，第二声）与呀声调不同，意思是植物的芽。"}, {"text": "痒", "is_correct": false, "explanation": "痒（yǎng，第三声）与呀韵母不同，多了 -ng，意思是发痒。"}, {"text": "呀", "is_correct": true, "explanation": "正确答案。呀作句末语气词时轻声读 ya。"}, {"text": "样", "is_correct": false, "explanation": "样（yàng，第四声）与呀韵母不同，多了 -ng，意思是样子。"}], "explanations": {"芽": "芽（yá，第二声）与呀声调不同，意思是植物的芽。", "痒": "痒（yǎng，第三声）与呀韵母不同，多了 -ng，意思是发痒。", "呀": "正确答案。呀作句末语气词时轻声读 ya。", "样": "样（yàng，第四声）与呀韵母不同，多了 -ng，意思是样子。"}, "sentence_index": null, "correct_answer": "呀"}, "level_3": {"options": [{"text": "的", "is_correct": false, "explanation": "搭配：“真可爱的”不能单独作句末，“的”不能用作感叹句尾。"}, {"text": "吗", "is_correct": false, "explanation": "语义：“吗”表示疑问，与“真可爱”的感叹语气不符。"}, {"text": "呀", "is_correct": true, "explanation": "正确：句末语气词，使感叹的语气柔和。"}, {"text": "矣", "is_correct": false, "explanation": "语域：“矣”是文言助词，与口语的感叹句语域不符。"}], "explanations": {"的": "搭配：“真可爱的”不能单独作句末，“的”不能用作感叹句尾。", "吗": "语义：“吗”表示疑问，与“真可爱”的感叹语气不符。", "呀": "正确：句末语气词，使感叹的语气柔和。", "矣": "语域：“矣”是文言助词，与口语的感叹句语域不符。"}, "sentence_index": 6, "correct_answer": "呀"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "第十条规定了处罚标准呀。", "explanation": "规定条文的句末用句号，语气词“呀”不用于法条。"}, {"text": "实验数据表明该方法行之有效呀。", "explanation": "实验结论用陈述语气，句末用句号；“呀”的口语语气与学术写作不符。"}, {"text": "甲乙双方特此签订本协议呀。", "explanation": "协议条款是正式书面语，句末用句号，不加语气词“呀”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88194, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "你的手机在哪儿吗呀？", "corrected_sentence": "你的手机在哪儿呀？", "error_description": "“吗”和“呀”都是疑问语气词，不能叠用。这里只用“呀”，正确说法是“你的手机在哪儿呀？”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88194, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "今天天气真好呀，咱们出去玩呀吧。", "corrected_sentence": "今天天气真好呀，咱们出去玩吧。", "error_description": "语气词位置错误：“呀”不能插在动词“玩”和语气词“吧”之间，语气词只放在句末。正确说法是“今天天气真好呀，咱们出去玩吧。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c54eb874-fdd6-49ea-9453-a002bd5ff0d8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
