INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88195, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "今晚是今天的夜里。", "primary_collocate": null, "pronunciation": "jīn wǎn", "ipa": "tɕin˥ wan˨˩", "syllable_count": 2, "sentences": [{"text": "今晚我们去吃火锅吧。", "target_word": "今晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚的月亮又大又圆。", "target_word": "今晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈说今晚要早点睡觉。", "target_word": "今晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚天气很冷，多穿点衣服。", "target_word": "今晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他今晚不回家吃饭。", "target_word": "今晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚有一场足球比赛。", "target_word": "今晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我今晚想看一部新电影。", "target_word": "今晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚的作业太多了。", "target_word": "今晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你今晚有空吗？", "target_word": "今晚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "今晚她要给朋友打电话。", "target_word": "今晚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "今天的夜里，表示时间的名词", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6ba22e3-4e03-4c26-838e-beb10be1ee6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88195, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "今晚", "is_correct": true, "explanation": "正确。“今晚”指今天夜里，与后面的提议“去吃火锅吧”相配。"}, {"text": "昨晚", "is_correct": false, "explanation": "语义：“昨晚”指昨天夜里，与后面表示提议的“吧”相冲突。"}, {"text": "前天", "is_correct": false, "explanation": "语义：“前天”指过去的日子，不能用来提出将来去吃饭的建议。"}, {"text": "上周", "is_correct": false, "explanation": "语义：“上周”指过去的一段时间，与后面表示提议的“吧”相冲突，不能用来提出即将去吃饭的建议。"}], "explanations": {"今晚": "正确。“今晚”指今天夜里，与后面的提议“去吃火锅吧”相配。", "昨晚": "语义：“昨晚”指昨天夜里，与后面表示提议的“吧”相冲突。", "前天": "语义：“前天”指过去的日子，不能用来提出将来去吃饭的建议。", "上周": "语义：“上周”指过去的一段时间，与后面表示提议的“吧”相冲突，不能用来提出即将去吃饭的建议。"}, "sentence_index": 0, "correct_answer": "今晚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今晚早上七点起床。", "explanation": "“今晚”指今天夜里，不能和“早上”同时使用，早上应说“今天早上”，这里的时间说法不对。"}, {"text": "他总是在今晚写作业。", "explanation": "这里应该用〈晚上〉。“今晚”只指今天夜里这一次，不能表示经常发生的事。"}, {"text": "我们每个今晚都去散步。", "explanation": "“今晚”指一个特定的夜晚，不能用量词“个”来计数，表示每天应说“每天晚上”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88195, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "今晚", "is_correct": true, "explanation": "正确。“今晚”是时间词，表示“想看电影”的时间，句子通顺。"}, {"text": "晚饭", "is_correct": false, "explanation": "语义：“晚饭”是饭食，不是时间，不能表示想看电影的时间。"}, {"text": "饭店", "is_correct": false, "explanation": "搭配：“饭店”是场所，不能作时间状语，“我饭店想看电影”说不通。"}, {"text": "食堂", "is_correct": false, "explanation": "语义：“食堂”指吃饭的地方，不是时间，不能用在这里。"}], "explanations": {"今晚": "正确。“今晚”是时间词，表示“想看电影”的时间，句子通顺。", "晚饭": "语义：“晚饭”是饭食，不是时间，不能表示想看电影的时间。", "饭店": "搭配：“饭店”是场所，不能作时间状语，“我饭店想看电影”说不通。", "食堂": "语义：“食堂”指吃饭的地方，不是时间，不能用在这里。"}, "sentence_index": 6, "correct_answer": "今晚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他今晚一整天都在工作。", "explanation": "这里应该用〈今天〉。“今晚”只指今天夜里，不能表示整个今天，说整天要用“今天”。"}, {"text": "我今晚十五岁了。", "explanation": "这里说的是年龄，不能用“今晚”这个时间词来表示，应说“我十五岁了”，“今晚”不适用。"}, {"text": "我们去超市买了今晚。", "explanation": "“今晚”是时间，不是可以购买的东西，不能作“买”的宾语。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88195, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个今晚我们去逛街吧。", "corrected_sentence": "今晚我们去逛街吧。", "error_description": "指示词错误：“今晚”是表示时间的词，不能与“这个”搭配。应直接说“今晚我们去逛街吧”，不能说“这个今晚我们去逛街吧”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88195, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们今晚的八点去散步吧。", "corrected_sentence": "我们今晚八点去散步吧。", "error_description": "“今晚”和“八点”之间多了“的”。时间状语之间不能加“的”，应说“今晚八点”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
