INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88197, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "会子是一小段时间，一会儿。", "primary_collocate": null, "pronunciation": "huì zi", "ipa": "xuei˥˩ tsɿ", "syllable_count": 2, "sentences": [{"text": "你先坐一会子，饭马上就好。", "target_word": "会子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他刚睡了一会子，你别吵他。", "target_word": "会子", "complexity_tier": "T3", "furigana": "huì zi", "sentence_source": "generated"}, {"text": "我等了好一会子，车还没来。", "target_word": "会子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我在门口站了会子才敲门。", "target_word": "会子", "complexity_tier": "T3", "furigana": "huì zi", "sentence_source": "generated"}, {"text": "妈妈出去了一会子就回来了。", "target_word": "会子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "天太热，咱们在树下歇会子吧。", "target_word": "会子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他看了会子书，又去打球了。", "target_word": "会子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "雨下了会子就停了，咱们走吧。", "target_word": "会子", "complexity_tier": "T3", "furigana": "huì zi", "sentence_source": "generated"}, {"text": "你再多等会子，他一定会来。", "target_word": "会子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们聊了会子，他突然就生气了。", "target_word": "会子", "complexity_tier": "T3", "furigana": "huì zi", "sentence_source": "generated"}], "morphological_forms": [{"form": "这会子", "label": "复合"}, {"form": "那会子", "label": "复合"}], "register": "方言口语", "sense_fingerprint": "会子：口语里指很短的一段时间，一会儿", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '648adbef-73b9-41d7-be59-ee2aa0548fdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88197, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "会子", "is_correct": true, "explanation": "正确：“会子”是口语里指一小段时间，与“饭马上就好”的语境相合。"}, {"text": "天", "is_correct": false, "explanation": "语义：“坐一天”指很长的时间，与“饭马上就好”矛盾。"}, {"text": "年", "is_correct": false, "explanation": "语义：“坐一年”指很长的时间，与“饭马上就好”矛盾。"}, {"text": "顿", "is_correct": false, "explanation": "搭配：“顿”用于饭、责骂等，不说“坐一顿”来表示时长。"}], "explanations": {"会子": "正确：“会子”是口语里指一小段时间，与“饭马上就好”的语境相合。", "天": "语义：“坐一天”指很长的时间，与“饭马上就好”矛盾。", "年": "语义：“坐一年”指很长的时间，与“饭马上就好”矛盾。", "顿": "搭配：“顿”用于饭、责骂等，不说“坐一顿”来表示时长。"}, "sentence_index": 0, "correct_answer": "会子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这次会子开得很成功，大家都很满意。", "explanation": "这里应该用〈会议〉。〈会子〉表示一小段时间，不指会议；“开得很成功”说的是会议，不能用〈会子〉。"}, {"text": "我在门口站了一个会子才敲门。", "explanation": "这里不能用量词“个”。〈会子〉前只用数词“一”，应说“站了一会子”。"}, {"text": "周末的会子很热闹，大家都去了。", "explanation": "这里应该用〈聚会〉。〈会子〉表示一小段时间，不指聚会，“很热闹”的聚会要说〈聚会〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88197, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "会子", "is_correct": true, "explanation": "正确：“看了会子书”表示看了一小段时间，与后文“又去打球了”相接。"}, {"text": "一口", "is_correct": false, "explanation": "搭配：“口”用于吃喝的量，不能说“看了一口书”。"}, {"text": "一顿", "is_correct": false, "explanation": "搭配：“顿”用于饭、责骂等，不说“看了一顿书”。"}, {"text": "一张", "is_correct": false, "explanation": "搭配：“张”不用于“书”，不能说“看了一张书”。"}], "explanations": {"会子": "正确：“看了会子书”表示看了一小段时间，与后文“又去打球了”相接。", "一口": "搭配：“口”用于吃喝的量，不能说“看了一口书”。", "一顿": "搭配：“顿”用于饭、责骂等，不说“看了一顿书”。", "一张": "搭配：“张”不用于“书”，不能说“看了一张书”。"}, "sentence_index": 6, "correct_answer": "会子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这是难得的会子，千万别错过。", "explanation": "这里应该用〈机会〉。〈会子〉指一小段时间，不指“机会”，“难得的机会”要说〈机会〉。"}, {"text": "他是公司的会子，专门负责管账。", "explanation": "这里应该用〈会计〉。〈会子〉不指人，不能用来说“管账的人”，应说〈会计〉。"}, {"text": "这台会子很好用，我已经用了两年。", "explanation": "这里应该用〈机器〉。〈会子〉不指机器，不能用“这台”来指它，应说〈机器〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88197, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我在沙发上坐了三个会子，就去做饭。", "corrected_sentence": "我在沙发上坐了会子，就去做饭。", "error_description": "错误在“三个”。“会子”本身表示一小段时间，是不定的量，前面不用个体量词计数。错误形式是“坐了三个会子”，正确形式是“坐了会子”或“坐了一会子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88197, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他看了会子了书，就去睡了。", "corrected_sentence": "他看了会子书，就去睡了。", "error_description": "错误在“了”的位置。“会子”后面直接接宾语“书”，中间不能再加“了”。错误形式是“看了会子了书”，正确形式是“看了会子书”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
