INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88199, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "点选是用手指或鼠标点一下，把想要的选出来。", "primary_collocate": null, "pronunciation": "diǎn xuǎn", "ipa": "tjɛn˨˩˦ ɕɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "请在屏幕上点选你喜欢的颜色。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以用手指点选图片。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点选“确定”以后，页面就关了。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在列表里点选一个城市。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师让我们用鼠标点选正确答案。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在手机上点选想看的电影。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请先点选头像，再输入名字。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子用小手点选屏幕上的小动物。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在菜单里点选了一杯咖啡。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "把想买的东西点选一下就行。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点选了", "label": "体标"}, {"form": "点选过", "label": "体标"}], "register": "通用", "sense_fingerprint": "用手指或鼠标点一下，选出想要的", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '707ca56f-bdbb-4406-b7c2-70c46bd994b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88199, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "擦", "is_correct": false, "explanation": "语义：“擦”是抹去的意思，不能用来挑选颜色。"}, {"text": "点选", "is_correct": true, "explanation": "点选：用手指或鼠标点一下，把喜欢的颜色选出来，符合句意。"}, {"text": "关", "is_correct": false, "explanation": "搭配：“关”的对象是灯、门、窗等，不说关颜色。"}, {"text": "删", "is_correct": false, "explanation": "语义：“删”是去掉的意思，不表示在屏幕上挑选颜色。"}], "explanations": {"擦": "语义：“擦”是抹去的意思，不能用来挑选颜色。", "点选": "点选：用手指或鼠标点一下，把喜欢的颜色选出来，符合句意。", "关": "搭配：“关”的对象是灯、门、窗等，不说关颜色。", "删": "语义：“删”是去掉的意思，不表示在屏幕上挑选颜色。"}, "sentence_index": 0, "correct_answer": "点选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用打火机点选了蜡烛。", "explanation": "这里应该用〈点燃〉。点燃是使东西着起来，点选是在屏幕或选项中做选择，不能用来点火。"}, {"text": "他用手指点选了一下黑板，把灰尘去掉了。", "explanation": "这里应该用〈擦〉。擦是用手或布抹去灰尘污垢，点选是在选项中做选择，不能用来去掉黑板上的灰尘。"}, {"text": "他用力点选了三下，才把门打开。", "explanation": "这里应该用〈推〉。推是用力使东西移动，点选是在选项中挑选，不能用来推门。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88199, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "浇", "is_correct": false, "explanation": "搭配：“浇”的对象是植物或土地，不说浇头像。"}, {"text": "唱", "is_correct": false, "explanation": "语义：“唱”指发出歌声，与在界面上选头像的动作无关。"}, {"text": "点选", "is_correct": true, "explanation": "点选：用手指或鼠标点一下，选出头像，符合句意。"}, {"text": "扔", "is_correct": false, "explanation": "语义：“扔”是抛掉的意思，不能表示选择头像。"}], "explanations": {"浇": "搭配：“浇”的对象是植物或土地，不说浇头像。", "唱": "语义：“唱”指发出歌声，与在界面上选头像的动作无关。", "点选": "点选：用手指或鼠标点一下，选出头像，符合句意。", "扔": "语义：“扔”是抛掉的意思，不能表示选择头像。"}, "sentence_index": 6, "correct_answer": "点选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "节日的灯笼点选着整条街道。", "explanation": "这里应该用〈点缀〉。点缀是装饰，灯笼装饰街道要用〈点缀〉；点选是在选项中挑选，不能表示装饰。"}, {"text": "老师点选了桌上的那堆作业，逐张数清楚。", "explanation": "这里应该用〈数〉。点选是在屏幕或选项中做选择，不能用来逐张清点实物的数目。"}, {"text": "他轻轻一按，把屏幕点选了。", "explanation": "这里应该用〈点亮〉。点亮是使屏幕发光；点选是挑选，不能表示让屏幕亮起来。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88199, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请用鼠标没点选想听的歌曲。", "corrected_sentence": "请用鼠标点选想听的歌曲。", "error_description": "错误形式是“没点选想听的歌曲”，正确形式是“点选想听的歌曲”。“请”后面是祈使句，表示要求做的动作，不能用“没”否定。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88199, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他还没点选了想看的视频。", "corrected_sentence": "他还没点选想看的视频。", "error_description": "错误形式是“还没点选了”，正确形式是“还没点选”。“没”表示动作还没有发生，与表示完成的“了”不能同时用在“点选”后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
