INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88200, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "用鼠标或手指点击以选择。", "primary_collocate": null, "pronunciation": "diǎn xuǎn", "ipa": "tjɛn˨˩˦ ɕɥɛn˨˩˦", "syllable_count": 2, "sentences": [{"text": "游戏开始前，先点选你的角色。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "网页上有三个选项，请点选一个。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她点选了第二张照片。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请用鼠标点选下面的语言。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在地图上点选你家的位置。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点选完成后，请按“提交”。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机屏幕太小，我很难准确点选按钮。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在表格里点选了自己的年级。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请在下拉菜单中点选你的出生年份。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶学会了在手机上点选照片。", "target_word": "点选", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "点选了", "label": "体标"}, {"form": "点选过", "label": "体标"}], "register": "通用", "sense_fingerprint": "点击屏幕上的选项以作出选择", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '707ca56f-bdbb-4406-b7c2-70c46bd994b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88200, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "洗", "is_correct": false, "explanation": "语义：“洗”是清洗的意思，不能用来选择角色。"}, {"text": "喂", "is_correct": false, "explanation": "搭配：“喂”的对象是人或动物，不说喂角色。"}, {"text": "点选", "is_correct": true, "explanation": "点选：点击以选择，游戏开始前选出自己的角色，符合句意。"}, {"text": "关", "is_correct": false, "explanation": "语义：“关”是关闭的意思，不表示挑选角色。"}], "explanations": {"洗": "语义：“洗”是清洗的意思，不能用来选择角色。", "喂": "搭配：“喂”的对象是人或动物，不说喂角色。", "点选": "点选：点击以选择，游戏开始前选出自己的角色，符合句意。", "关": "语义：“关”是关闭的意思，不表示挑选角色。"}, "sentence_index": 0, "correct_answer": "点选"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用打火机点选了炉子。", "explanation": "这里应该用〈点燃〉。点燃是使东西着火，点选是在选项中挑选，不能用来生火。"}, {"text": "他一按开关，就把房间点选了。", "explanation": "这里应该用〈点亮〉。点亮是使灯或屏幕发光，点选是挑选，不能表示让房间亮起来。"}, {"text": "她把苹果点选了皮，再切成块。", "explanation": "这里应该用〈削〉。削是用刀去掉表皮，点选是在屏幕或选项中做选择，不能用来去掉苹果皮。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88200, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "缩", "is_correct": false, "explanation": "语义：“缩”是变小、收拢的意思，不表示在屏幕上选择按钮，句意不通。"}, {"text": "切", "is_correct": false, "explanation": "搭配：“切”的对象是食物等，不说切按钮。"}, {"text": "点选", "is_correct": true, "explanation": "点选：用手指或鼠标点击以选择，符合“很难准确点选按钮”的句意。"}, {"text": "咬", "is_correct": false, "explanation": "搭配：“咬”的对象是食物或身体部位，不说咬按钮。"}], "explanations": {"缩": "语义：“缩”是变小、收拢的意思，不表示在屏幕上选择按钮，句意不通。", "切": "搭配：“切”的对象是食物等，不说切按钮。", "点选": "点选：用手指或鼠标点击以选择，符合“很难准确点选按钮”的句意。", "咬": "搭配：“咬”的对象是食物或身体部位，不说咬按钮。"}, "sentence_index": 6, "correct_answer": "点选"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "春天的花朵点选着山坡。", "explanation": "这里应该用〈点缀〉。点缀是装饰，花朵装饰山坡要用〈点缀〉；点选是挑选，不能表示装饰。"}, {"text": "妈妈一个一个点选着盘子里的鸡蛋，看看有没有裂开。", "explanation": "这里应该用〈检查〉。检查是看有没有问题，点选是在选项中挑选，不能用来查看鸡蛋有没有裂开。"}, {"text": "他把眼镜点选干净了。", "explanation": "这里应该用〈擦〉。擦是用布抹去污垢，点选是在选项中挑选，不能把眼镜点选干净。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88200, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "请用手指点选了你想看的视频。", "corrected_sentence": "请用手指点选你想看的视频。", "error_description": "错误形式是“点选了你想看的视频”，正确形式是“点选你想看的视频”。“请”后面是祈使句，表示要求做的动作，“点选”后不能加“了”表示已完成。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88200, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妈妈正在用平板电脑点选了一首歌。", "corrected_sentence": "我妈妈正在用平板电脑点选一首歌。", "error_description": "错误形式是「正在点选了」，正确形式是「正在点选」。「正在」表示动作正在进行，与表示完成的「了」不能同用，应去掉「了」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
