INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88201, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "会晤是两个重要的人见面谈话。", "primary_collocate": null, "pronunciation": "huì wù", "ipa": "xu̯eɪ̯˥˩ u˥˩", "syllable_count": 2, "sentences": [{"text": "两国领导人在海边会晤了。", "target_word": "会晤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "总统和首相今天下午会晤。", "target_word": "会晤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位总统将在首都会晤。", "target_word": "会晤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们两位领导人去年会晤过一次。", "target_word": "会晤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "首相明天要会晤来访的总统。", "target_word": "会晤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两国元首在北京会晤，谈了很久。", "target_word": "会晤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "市长会晤了那位大公司的老板。", "target_word": "会晤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位大使约好周五会晤。", "target_word": "会晤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王会晤了来访的首相。", "target_word": "会晤", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "两位领导人握手后开始会晤。", "target_word": "会晤", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "会晤了", "label": "完成体"}, {"form": "会晤过", "label": "经历体"}], "register": "正式", "sense_fingerprint": "重要人物之间见面谈话", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '3ed86873-7118-420e-9ec1-966e4a14f6b3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88201, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "会晤", "is_correct": true, "explanation": "正确答案：会晤 huìwù，指重要人物之间正式见面谈话。"}, {"text": "货物", "is_correct": false, "explanation": "货物 huòwù：第一个音节 huò 与 huì 只差韵母（o 与 i），意思是货物。"}, {"text": "挥舞", "is_correct": false, "explanation": "挥舞 huīwǔ：huī 与 huì 声调不同（第一声与第四声），wǔ 与 wù 声调也不同（第三声与第四声），意思是挥动。"}, {"text": "灰雾", "is_correct": false, "explanation": "灰雾 huīwù：第一个音节 huī（第一声）与 huì（第四声）声调不同，意思是灰色的雾。"}], "explanations": {"会晤": "正确答案：会晤 huìwù，指重要人物之间正式见面谈话。", "货物": "货物 huòwù：第一个音节 huò 与 huì 只差韵母（o 与 i），意思是货物。", "挥舞": "挥舞 huīwǔ：huī 与 huì 声调不同（第一声与第四声），wǔ 与 wù 声调也不同（第三声与第四声），意思是挥动。", "灰雾": "灰雾 huīwù：第一个音节 huī（第一声）与 huì（第四声）声调不同，意思是灰色的雾。"}, "sentence_index": null, "correct_answer": "会晤"}, "level_3": {"options": [{"text": "会晤", "is_correct": true, "explanation": "正确：会晤指重要人物正式见面，与两国领导人的身份相符。"}, {"text": "打架", "is_correct": false, "explanation": "语义：“打架”指斗殴，与两国领导人在海边的正式会见不符。"}, {"text": "干架", "is_correct": false, "explanation": "语域：“干架”是口语，指吵架或动手，不适用于两国领导人的场合。"}, {"text": "哭闹", "is_correct": false, "explanation": "语义：“哭闹”多指小孩的行为，与国家领导人的身份不符。"}], "explanations": {"会晤": "正确：会晤指重要人物正式见面，与两国领导人的身份相符。", "打架": "语义：“打架”指斗殴，与两国领导人在海边的正式会见不符。", "干架": "语域：“干架”是口语，指吵架或动手，不适用于两国领导人的场合。", "哭闹": "语义：“哭闹”多指小孩的行为，与国家领导人的身份不符。"}, "sentence_index": 0, "correct_answer": "会晤"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我去年和老同学会晤过一次。", "explanation": "这里应该用〈见面〉。会晤语体正式，用于重要人物之间，与老同学见面要用见面。"}, {"text": "我们在线上会晤了一下想法。", "explanation": "这里应该用〈交流〉。会晤的对象是人，不能说会晤想法，应说交流想法。"}, {"text": "我和朋友在公园会晤了一会儿。", "explanation": "这里应该用〈闲聊〉。会晤是正式的会见，朋友在公园闲聊不能用会晤。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88201, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "会晤", "is_correct": true, "explanation": "正确答案：会晤 huìwù，指重要人物之间正式见面谈话。"}, {"text": "黑雾", "is_correct": false, "explanation": "黑雾 hēiwù：第一个音节 hēi（第一声）与 huì（第四声）的韵母和声调都不同，意思是黑色的雾。"}, {"text": "活物", "is_correct": false, "explanation": "活物 huówù：第一个音节 huó（第二声）与 huì（第四声）的韵母和声调不同，意思是活的东西。"}, {"text": "悔悟", "is_correct": false, "explanation": "悔悟 huǐwù：第一个音节 huǐ（第三声）与 huì（第四声）声调不同，第二个音节相同，意思是认识到错误而后悔。"}], "explanations": {"会晤": "正确答案：会晤 huìwù，指重要人物之间正式见面谈话。", "黑雾": "黑雾 hēiwù：第一个音节 hēi（第一声）与 huì（第四声）的韵母和声调都不同，意思是黑色的雾。", "活物": "活物 huówù：第一个音节 huó（第二声）与 huì（第四声）的韵母和声调不同，意思是活的东西。", "悔悟": "悔悟 huǐwù：第一个音节 huǐ（第三声）与 huì（第四声）声调不同，第二个音节相同，意思是认识到错误而后悔。"}, "sentence_index": null, "correct_answer": "会晤"}, "level_3": {"options": [{"text": "会晤", "is_correct": true, "explanation": "正确：会晤指正式会见，市长会见大公司老板符合身份。"}, {"text": "雇佣", "is_correct": false, "explanation": "语义：“雇佣”是雇人做事，市长不能雇用大公司的老板。"}, {"text": "揍", "is_correct": false, "explanation": "语域：“揍”是口语，指殴打，与市长的正式身份和场合不符。"}, {"text": "监禁", "is_correct": false, "explanation": "语义：“监禁”须由司法机关执行，市长不能监禁企业老板。"}], "explanations": {"会晤": "正确：会晤指正式会见，市长会见大公司老板符合身份。", "雇佣": "语义：“雇佣”是雇人做事，市长不能雇用大公司的老板。", "揍": "语域：“揍”是口语，指殴打，与市长的正式身份和场合不符。", "监禁": "语义：“监禁”须由司法机关执行，市长不能监禁企业老板。"}, "sentence_index": 6, "correct_answer": "会晤"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我下班后在超市会晤了妈妈。", "explanation": "这里应该用〈碰见〉。会晤是重要人物之间的正式会见，在超市遇见妈妈应说碰见。"}, {"text": "同学们周末一起会晤。", "explanation": "这里应该用〈聚会〉。会晤是两个重要的人之间的正式见面谈话，同学周末一起相聚应说聚会。"}, {"text": "我们在会议室会晤计划。", "explanation": "这里应该用〈讨论〉。会晤的对象是人，不能说会晤计划，讨论计划才是正确搭配。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88201, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "两国领导人明天下午将会晤了。", "corrected_sentence": "两国领导人明天下午将会晤。", "error_description": "错误：“会晤了”表示已经发生，与“明天下午将”的将来时间矛盾，应去掉“了”，说“将会晤”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88201, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "市长下周与外国代表会晤一个。", "corrected_sentence": "市长下周与外国代表会晤一次。", "error_description": "错误：会晤的次数要用量词“次”，说“会晤一次”，不能说“会晤一个”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '532372a9-4ae8-40df-80f4-c8ae5364f0d1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
