INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88203, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "上床是爬到床上去，要睡觉了。", "primary_collocate": null, "pronunciation": "shàng chuáng", "ipa": "ʂaŋ˥˩ ʈʂʰuaŋ˧˥", "syllable_count": 2, "sentences": [{"text": "小女孩穿着拖鞋就上床了。", "target_word": "上床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "脱了鞋再上床，别把床弄脏。", "target_word": "上床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "弟弟爬着上床，想去找妈妈。", "target_word": "上床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "上床以后，他盖好被子关了灯。", "target_word": "上床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "灯一关，孩子们就乖乖上床。", "target_word": "上床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "哥哥踩着小凳子上床。", "target_word": "上床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我刚上床，手机就响了。", "target_word": "上床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他困得睁不开眼，赶紧上床。", "target_word": "上床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "先洗脚，再上床睡觉。", "target_word": "上床", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "床太高了，奶奶上床很费劲。", "target_word": "上床", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "上了床", "label": "体标"}, {"form": "上过床", "label": "体标"}], "register": "口语", "sense_fingerprint": "身体爬到床上去，要睡觉", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '707ca56f-bdbb-4406-b7c2-70c46bd994b1') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88203, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "上床", "is_correct": true, "explanation": "「就上床了」表示穿着拖鞋直接爬上床睡觉，与句意相符。"}, {"text": "开车", "is_correct": false, "explanation": "语义：小女孩不能开车，句中说的是要上床，「就开车了」句意不通。"}, {"text": "喝酒", "is_correct": false, "explanation": "语义：小女孩不能喝酒，与「穿着拖鞋就……」的睡前情境相矛盾。"}, {"text": "上班", "is_correct": false, "explanation": "搭配：「穿着拖鞋就上班」的搭配不通，上班需要换衣、出门，与句中情境不合。"}], "explanations": {"上床": "「就上床了」表示穿着拖鞋直接爬上床睡觉，与句意相符。", "开车": "语义：小女孩不能开车，句中说的是要上床，「就开车了」句意不通。", "喝酒": "语义：小女孩不能喝酒，与「穿着拖鞋就……」的睡前情境相矛盾。", "上班": "搭配：「穿着拖鞋就上班」的搭配不通，上班需要换衣、出门，与句中情境不合。"}, "sentence_index": 0, "correct_answer": "上床"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "骑车的人上床爬坡。", "explanation": "这里应该用〈上坡〉。「上床」指躺上床铺，骑车爬坡要用上坡。"}, {"text": "乘客上床后买票。", "explanation": "这里应该用〈上车〉。「上床」只表示躺上床铺，乘坐交通工具要用上车。"}, {"text": "他们上床采药。", "explanation": "这里应该用〈上山〉。「上床」指躺上床铺，去山里采药要用上山。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88203, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "上床", "is_correct": true, "explanation": "「我刚上床，手机就响了」表示刚躺到床上，手机便响了，与句意相符。"}, {"text": "出生", "is_correct": false, "explanation": "语义：「出生」指刚降生，与「手机就响了」的日常场景不合。"}, {"text": "诞生", "is_correct": false, "explanation": "语域：「诞生」多用于书面或庄重语境，与这句口语化的日常叙述不合。"}, {"text": "去世", "is_correct": false, "explanation": "语义：「去世」与「手机就响了」的日常情境冲突，句意不通。"}], "explanations": {"上床": "「我刚上床，手机就响了」表示刚躺到床上，手机便响了，与句意相符。", "出生": "语义：「出生」指刚降生，与「手机就响了」的日常场景不合。", "诞生": "语域：「诞生」多用于书面或庄重语境，与这句口语化的日常叙述不合。", "去世": "语义：「去世」与「手机就响了」的日常情境冲突，句意不通。"}, "sentence_index": 6, "correct_answer": "上床"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "乘客上床太慢，飞机迟迟不能起飞。", "explanation": "这里应该用〈登机〉。「上床」指爬到床上睡觉，乘客登上飞机要用登机。"}, {"text": "运动员上床比赛。", "explanation": "这里应该用〈上场〉。「上床」只表示躺上床铺，运动员参加比赛要用上场。"}, {"text": "学生上床很认真。", "explanation": "这里应该用〈上课〉。「上床」指躺上床铺，学生学习要用上课。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88203, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "弟弟洗完脚就上床着。", "corrected_sentence": "弟弟洗完脚就上床了。", "error_description": "错误形式：上床着；正确形式：上床了。「着」表示动作结束后的持续状态，这里说的是已经完成的动作，应用「了」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88203, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他困得睁不开眼，赶紧上床着。", "corrected_sentence": "他困得睁不开眼，赶紧上床。", "error_description": "错误形式：上床着；正确形式：上床。「赶紧」表示马上去做某个动作，「上床」后不能加表示持续状态的「着」，应去掉「着」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8132c6b7-13b0-40ca-87af-19cb43275fdb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
