INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88205, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "优惠是比平常便宜，让人少花钱。", "primary_collocate": null, "pronunciation": "yōu huì", "ipa": "jou˥ xweɪ˥˩", "syllable_count": 2, "sentences": [{"text": "这家店今天有优惠。", "target_word": "优惠", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "买两件衣服有优惠吗？", "target_word": "优惠", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这个周末超市有很多优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "用这张卡可以享受优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "学生去电影院看电影有优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "买得多，优惠也多。", "target_word": "优惠", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "在网上买东西常常有优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想等有优惠的时候再买。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这家饭店晚上八点以后有优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "老人坐公共汽车可以得到优惠。", "target_word": "优惠", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "优惠券", "label": "复合词"}, {"form": "优惠价", "label": "复合词"}], "register": "通用", "sense_fingerprint": "优惠：商店、网上买东西时比平常便宜的价格，让人少花钱，常说“有优惠”", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6ba22e3-4e03-4c26-838e-beb10be1ee6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88205, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "优惠", "is_correct": true, "explanation": "正确。优惠：比平常便宜，让人少花钱。"}, {"text": "优化", "is_correct": false, "explanation": "huà（第四声）与 huì 韵母不同，意思是优化，使更好。"}, {"text": "诱惑", "is_correct": false, "explanation": "yòu huò 与 yōu huì 声调和韵母都不同，意思是吸引人去做某事。"}, {"text": "邮汇", "is_correct": false, "explanation": "yóu（第二声）与 yōu（第一声）声调不同，意思是邮政汇款。"}], "explanations": {"优惠": "正确。优惠：比平常便宜，让人少花钱。", "优化": "huà（第四声）与 huì 韵母不同，意思是优化，使更好。", "诱惑": "yòu huò 与 yōu huì 声调和韵母都不同，意思是吸引人去做某事。", "邮汇": "yóu（第二声）与 yōu（第一声）声调不同，意思是邮政汇款。"}, "sentence_index": null, "correct_answer": "优惠"}, "level_3": {"options": [{"text": "优惠", "is_correct": true, "explanation": "正确。“优惠”指比平常便宜，符合店里“今天有”的语境。"}, {"text": "考试", "is_correct": false, "explanation": "语义：考试是测验，店铺不会“有”考试，句子不通。"}, {"text": "身材", "is_correct": false, "explanation": "体貌：身材只用于人或动物的体形，不能用于店铺。"}, {"text": "病毒", "is_correct": false, "explanation": "语义：病毒是微生物，不是店铺可以拥有或提供的东西。"}], "explanations": {"优惠": "正确。“优惠”指比平常便宜，符合店里“今天有”的语境。", "考试": "语义：考试是测验，店铺不会“有”考试，句子不通。", "身材": "体貌：身材只用于人或动物的体形，不能用于店铺。", "病毒": "语义：病毒是微生物，不是店铺可以拥有或提供的东西。"}, "sentence_index": 0, "correct_answer": "优惠"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "吃蔬菜对身体有很多优惠。", "explanation": "这里应该用〈好处〉。优惠指价格或待遇上的便宜，不用来说吃蔬菜对身体的益处。"}, {"text": "我们队的优惠是速度快，所以经常取胜。", "explanation": "这里应该用〈优势〉。优惠指价格或待遇上的便宜，不用来说球队的长处；“优势”才指有利的条件。"}, {"text": "这位老师很优惠，大家都愿意和她接触。", "explanation": "这里应该用〈和气〉。优惠只用于价格、待遇、政策等方面，不用来形容人的性格。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88205, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "优惠", "is_correct": true, "explanation": "正确。优惠：比平常便宜，让人少花钱。"}, {"text": "油灰", "is_correct": false, "explanation": "yóu（第二声）与 yōu（第一声）、huī（第一声）与 huì（第四声）声调均不同，意思是一种用油调成的腻子。"}, {"text": "有为", "is_correct": false, "explanation": "yǒu（第三声）与 yōu（第一声）声调不同，wéi 与 huì 读音不同，意思是能做出成绩。"}, {"text": "油画", "is_correct": false, "explanation": "yóu（第二声）与 yōu（第一声）声调不同，huà 与 huì 韵母不同，意思是用油彩画的画。"}], "explanations": {"优惠": "正确。优惠：比平常便宜，让人少花钱。", "油灰": "yóu（第二声）与 yōu（第一声）、huī（第一声）与 huì（第四声）声调均不同，意思是一种用油调成的腻子。", "有为": "yǒu（第三声）与 yōu（第一声）声调不同，wéi 与 huì 读音不同，意思是能做出成绩。", "油画": "yóu（第二声）与 yōu（第一声）声调不同，huà 与 huì 韵母不同，意思是用油彩画的画。"}, "sentence_index": null, "correct_answer": "优惠"}, "level_3": {"options": [{"text": "优惠", "is_correct": true, "explanation": "正确。“优惠”指网购时比平常便宜的价格，符合“常常有”的语境。"}, {"text": "地震", "is_correct": false, "explanation": "语义：地震是自然灾害，网上买东西时不会“有”地震。"}, {"text": "雨水", "is_correct": false, "explanation": "语义：雨水是天气现象，网上买东西时不会“有”雨水，句子不通。"}, {"text": "骨折", "is_correct": false, "explanation": "语义：骨折是身体受伤，与网上买东西无关，搭配不成立。"}], "explanations": {"优惠": "正确。“优惠”指网购时比平常便宜的价格，符合“常常有”的语境。", "地震": "语义：地震是自然灾害，网上买东西时不会“有”地震。", "雨水": "语义：雨水是天气现象，网上买东西时不会“有”雨水，句子不通。", "骨折": "语义：骨折是身体受伤，与网上买东西无关，搭配不成立。"}, "sentence_index": 6, "correct_answer": "优惠"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的汉语有很大优惠。", "explanation": "这里应该用〈进步〉。优惠指价格或待遇上的便宜，不用来说能力的提高。"}, {"text": "这次事故的优惠很大，大家都很难过。", "explanation": "这里应该用〈损失〉。优惠是对人有利的价格或待遇，不能用来说事故造成的损失。"}, {"text": "这项任务有很大优惠。", "explanation": "这里应该用〈困难〉。优惠指对人有利的价格或待遇，不用来说任务的困难。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88205, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们去年享受过学生优惠过。", "corrected_sentence": "我们去年享受过学生优惠。", "error_description": "体标位置错误：“过”只能紧跟动词“享受”，句末“优惠过”多出一个“过”。正确形式为“享受过学生优惠”，不能说“享受过学生优惠过”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88205, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "学生去电影院时可以享受一只优惠。", "corrected_sentence": "学生去电影院时可以享受一项优惠。", "error_description": "量词错误：“优惠”是抽象的待遇，应搭配量词“项”，不能用“只”。“只”用于动物或成对器官等具体事物，应说“享受一项优惠”，不能说“享受一只优惠”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
