INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88207, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "月子是妈妈生了宝宝以后，要在家休息的一个月。", "primary_collocate": null, "pronunciation": "yuè zi", "ipa": "ɥe˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "宝宝出生后，妈妈要坐月子。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈说，月子一定要好好过。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月子里，妈妈不用做饭。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她回娘家坐月子，妈妈天天给她做饭。", "target_word": "月子", "complexity_tier": "T3", "furigana": "tā huí niángjiā zuò yuèzi, māma tiāntiān gěi tā zuò fàn.", "sentence_source": "generated"}, {"text": "月子最重要的是多睡觉。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "为了坐月子，她提前买好了很多东西。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "姐姐的月子是婆婆帮忙照顾的。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我家宝宝出生了，我正在坐月子。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月子里的妈妈需要有人照顾。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "朋友生了宝宝，我去看她，她正在坐月子。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "妈妈生了宝宝后要在家休息的那一个月", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a96547-d1a2-4444-8d6e-1252fc20d0d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88207, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "飞机", "is_correct": false, "explanation": "语义：飞机是交通工具，产后妈妈要休养，不会去“坐飞机”。"}, {"text": "滑板", "is_correct": false, "explanation": "语义：“滑板”不是可以“坐”的东西，句子不通。"}, {"text": "大海", "is_correct": false, "explanation": "搭配：“坐”后面接的是座位或交通工具，“坐大海”不能这样说。"}, {"text": "月子", "is_correct": true, "explanation": "语义：“坐月子”指产后在家休养一段时间，与“宝宝出生后”的语境相符。"}], "explanations": {"飞机": "语义：飞机是交通工具，产后妈妈要休养，不会去“坐飞机”。", "滑板": "语义：“滑板”不是可以“坐”的东西，句子不通。", "大海": "搭配：“坐”后面接的是座位或交通工具，“坐大海”不能这样说。", "月子": "语义：“坐月子”指产后在家休养一段时间，与“宝宝出生后”的语境相符。"}, "sentence_index": 0, "correct_answer": "月子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她放了月子，回娘家住。", "explanation": "这里应该用〈假期〉。“放”的是假，月子是产后休养的时期，不能说“放月子”。"}, {"text": "宝宝月子那天，全家人都很高兴。", "explanation": "这里应该用〈满月〉。满月指宝宝出生满一个月的那一天，月子是产后休养的时期，不能用来指某一天。"}, {"text": "她生完宝宝，坐了一只月子。", "explanation": "量词用错。〈只〉多用于动物，不能修饰月子；应说“坐了一个月的月子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88207, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "时间", "is_correct": false, "explanation": "语义：时间不是能被“照顾”的对象，句子意思不通。"}, {"text": "学历", "is_correct": false, "explanation": "语义：学历是个人的学习经历，不能被“照顾”。"}, {"text": "考试", "is_correct": false, "explanation": "搭配：“照顾”不接“考试”，这种组合不成立。"}, {"text": "月子", "is_correct": true, "explanation": "语义：“月子”指产后休养的一段时间，由婆婆照顾，符合句意。"}], "explanations": {"时间": "语义：时间不是能被“照顾”的对象，句子意思不通。", "学历": "语义：学历是个人的学习经历，不能被“照顾”。", "考试": "搭配：“照顾”不接“考试”，这种组合不成立。", "月子": "语义：“月子”指产后休养的一段时间，由婆婆照顾，符合句意。"}, "sentence_index": 6, "correct_answer": "月子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友在月子里生了宝宝，我去看她。", "explanation": "这里应该用〈医院〉。生孩子的地点要说医院，月子是产后休养的时期，不能作为地点。"}, {"text": "周末我们去海边月子。", "explanation": "这里应该用〈休假〉。去海边是休假，月子是产后在家休养的时期，不能说“去海边月子”。"}, {"text": "宝宝出生时的月子是三公斤。", "explanation": "这里应该用〈体重〉。宝宝出生时的重量要说〈体重〉，月子是休养的一段时间，不能用来计量。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88207, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "宝宝出生以后，妈妈要在家坐一座月子。", "corrected_sentence": "宝宝出生以后，妈妈要在家坐月子。", "error_description": "量词“座”用于山、桥、楼等大型固定建筑，不能修饰月子；应去掉量词，说“坐月子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88207, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我妹妹坐完一只月子，身体恢复得很好。", "corrected_sentence": "我妹妹坐完月子，身体恢复得很好。", "error_description": "错误形式“一只月子”，正确形式为“坐完月子”，不加量词。“只”多用于动物，不能修饰月子。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
