INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88208, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "妇女分娩后一个月左右的休养时期。", "primary_collocate": null, "pronunciation": "yuè zi", "ipa": "ɥe˥˩ tsɨ", "syllable_count": 2, "sentences": [{"text": "她生完孩子，在家坐月子。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坐月子的时候，不能吹冷风。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "妈妈来我家照顾我坐月子。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "月子里要多吃热的东西，多休息。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的月子过得很舒服。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多中国女人生孩子后都要坐月子。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他请了假，在家照顾妻子的月子。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她坐完月子，身体慢慢好起来了。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奶奶说月子里不能洗冷水。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她的月子快坐完了，身体好多了。", "target_word": "月子", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "妇女生孩子后一个月左右的休养时期", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a96547-d1a2-4444-8d6e-1252fc20d0d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88208, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "地铁", "is_correct": false, "explanation": "语义：地铁是交通工具，不能在家里“坐”。"}, {"text": "火车", "is_correct": false, "explanation": "语义：“坐火车”要去车站乘车，“在家坐火车”不合常理。"}, {"text": "冰", "is_correct": false, "explanation": "搭配：“坐”后面接的是座位或交通工具，“坐冰”不成立。"}, {"text": "月子", "is_correct": true, "explanation": "语义：“坐月子”指产后在家休养一个月左右，与“生完孩子，在家”相符。"}], "explanations": {"地铁": "语义：地铁是交通工具，不能在家里“坐”。", "火车": "语义：“坐火车”要去车站乘车，“在家坐火车”不合常理。", "冰": "搭配：“坐”后面接的是座位或交通工具，“坐冰”不成立。", "月子": "语义：“坐月子”指产后在家休养一个月左右，与“生完孩子，在家”相符。"}, "sentence_index": 0, "correct_answer": "月子"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她请了月子，在家休息。", "explanation": "这里应该用〈产假〉。请假的是“产假”，月子是产后休养的时期，不能说“请月子”。"}, {"text": "宝宝月子那天，全家人都很高兴。", "explanation": "这里应该用〈满月〉。满月指宝宝出生满一个月的那一天，月子是产后休养的时期，不能用来指某一天。"}, {"text": "这个月子天气很冷，要多穿衣服。", "explanation": "这里应该用〈月份〉。月份指日历上的一个月，月子是产后休养的时期，不能用来指日历上的月。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88208, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "足球", "is_correct": false, "explanation": "语义：“足球”不是需要“照顾”的对象，句子意思不通。"}, {"text": "彩虹", "is_correct": false, "explanation": "语义：彩虹是天空中的自然现象，不能被“照顾”。"}, {"text": "作业", "is_correct": false, "explanation": "搭配：“照顾”后面接的是人或需要照料的事物，不说“照顾妻子的作业”。"}, {"text": "月子", "is_correct": true, "explanation": "语义：“月子”指妻子分娩后的休养期，“在家照顾”正是照顾产后休养的妻子。"}], "explanations": {"足球": "语义：“足球”不是需要“照顾”的对象，句子意思不通。", "彩虹": "语义：彩虹是天空中的自然现象，不能被“照顾”。", "作业": "搭配：“照顾”后面接的是人或需要照料的事物，不说“照顾妻子的作业”。", "月子": "语义：“月子”指妻子分娩后的休养期，“在家照顾”正是照顾产后休养的妻子。"}, "sentence_index": 6, "correct_answer": "月子"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "医生说她的月子是下个月五号，孩子那天出生。", "explanation": "这里应该用〈预产期〉。预产期指预计分娩的日子，月子是分娩后的休养时期，不能指孩子出生的那一天。"}, {"text": "她月子已经八个月了。", "explanation": "这里应该用〈怀孕〉。“八个月”指怀孕的时间，月子只指产后一个月左右，不能说“月子八个月”。"}, {"text": "她过了一块月子，身体很快好了。", "explanation": "量词用错。〈块〉用于块状物，不能修饰时期；应说“坐了一个月的月子”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88208, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她这次坐了一座月子，身体恢复得很快。", "corrected_sentence": "她这次坐了月子，身体恢复得很快。", "error_description": "量词“座”用于山、桥、楼等大型建筑，不能修饰月子；应去掉量词，说“坐完月子”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88208, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她坐过一条月子，很有经验。", "corrected_sentence": "她坐过月子，很有经验。", "error_description": "量词“条”用于细长的东西，不能修饰月子；应去掉量词，说“坐过月子”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
