INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88209, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "中央政府是管整个国家大事的最大的政府。", "primary_collocate": null, "pronunciation": "zhōng yāng zhèng fǔ", "ipa": "tʂʊŋ˥ jɑŋ˥ tʂɤŋ˥˩ fu˨˩˦", "syllable_count": 4, "sentences": [{"text": "中央政府管着整个国家的大事。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府是全国最大的政府。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新闻里说，中央政府要提高工资。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府的决定对全国都有用。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各个省的政府都要听中央政府的话。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府每年都会发布新的计划。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师给我们介绍了中央政府的工作。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府为受灾的地区送去了粮食。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我爷爷常看中央政府的新闻。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府决定在全国种更多树。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "正式", "sense_fingerprint": "管全国大事的最大的政府", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be7a67a-0052-4629-80f6-eca6c3881ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88209, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "厨房", "is_correct": false, "explanation": "语义：厨房是房间，不能管理国家大事，与「整个国家」不相称。"}, {"text": "水", "is_correct": false, "explanation": "配价：「管着」需要有管理权的主体，水不能作主语管理国家大事。"}, {"text": "中央政府", "is_correct": true, "explanation": "中央政府是管理整个国家大事的最大政府，作主语「管着整个国家的大事」符合句意。"}, {"text": "教室", "is_correct": false, "explanation": "语义：教室是学习的场所，不管国家大事，与「整个国家」不相称。"}], "explanations": {"厨房": "语义：厨房是房间，不能管理国家大事，与「整个国家」不相称。", "水": "配价：「管着」需要有管理权的主体，水不能作主语管理国家大事。", "中央政府": "中央政府是管理整个国家大事的最大政府，作主语「管着整个国家的大事」符合句意。", "教室": "语义：教室是学习的场所，不管国家大事，与「整个国家」不相称。"}, "sentence_index": 0, "correct_answer": "中央政府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "每个国家都有一朵中央政府。", "explanation": "这里应该用〈个〉。〈朵〉用于花朵、云朵等，不能用于机构。"}, {"text": "我们国家有一只中央政府。", "explanation": "这里应该用〈个〉。〈只〉用于动物或成对物品中的一个，不能用于机构。"}, {"text": "老师讲了一条中央政府的历史。", "explanation": "这里应该用〈个〉。〈条〉用于细长的东西，不能用于机构；可说「一个中央政府」。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88209, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "镜子", "is_correct": false, "explanation": "语义：镜子是物品，不是可以被介绍工作的机构，与句中的「工作」不搭。"}, {"text": "中央政府", "is_correct": true, "explanation": "中央政府的工作是可以向学生介绍的内容，「介绍了中央政府的工作」符合句意。"}, {"text": "苹果", "is_correct": false, "explanation": "语义：苹果是水果，不是可以介绍工作的对象，与句意不符。"}, {"text": "饼干", "is_correct": false, "explanation": "配价：「……的工作」需要有工作能力的人或机构作主体，饼干不能有「工作」。"}], "explanations": {"镜子": "语义：镜子是物品，不是可以被介绍工作的机构，与句中的「工作」不搭。", "中央政府": "中央政府的工作是可以向学生介绍的内容，「介绍了中央政府的工作」符合句意。", "苹果": "语义：苹果是水果，不是可以介绍工作的对象，与句意不符。", "饼干": "配价：「……的工作」需要有工作能力的人或机构作主体，饼干不能有「工作」。"}, "sentence_index": 6, "correct_answer": "中央政府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中央政府负责规划本地的公交路线。", "explanation": "这里应该用〈地方政府〉。〈中央政府〉管全国大事，不负责规划某一地区的公交路线。"}, {"text": "中央政府负责组织本县的小学招生。", "explanation": "这里应该用〈县政府〉。〈中央政府〉的职权范围是全国，不直接组织某一县的招生。"}, {"text": "中央政府决定在本区修建一个公园。", "explanation": "这里应该用〈区政府〉。〈中央政府〉管全国大事，不决定某一区的具体建设项目。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88209, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家只有一只中央政府。", "corrected_sentence": "这个国家只有一个中央政府。", "error_description": "量词错误：“中央政府”应使用量词“个”，“只”用于动物或成对物品中的一个，这里用错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88209, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们需要一个高效地中央政府。", "corrected_sentence": "我们需要一个高效的中央政府。", "error_description": "结构助词错误：修饰名词“中央政府”时应用结构助词“的”，“地”用于修饰动词，这里用错了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
