INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88210, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "一国的最高行政机关，统辖地方政府。", "primary_collocate": null, "pronunciation": "zhōng yāng zhèng fǔ", "ipa": "tʂʊŋ˥ jɑŋ˥ tʂɤŋ˥˩ fu˨˩˦", "syllable_count": 4, "sentences": [{"text": "中央政府给这个省拨了一笔钱。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "地方政府要听中央政府的安排。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府在北京办公。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府今天发布了新的规定。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家的大事由中央政府来决定。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府派人去调查这件事。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的市政府归中央政府管。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府要求各地保护环境。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府计划修一条新铁路。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "中央政府和地方政府一起帮助农民。", "target_word": "中央政府", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}], "register": "正式", "sense_fingerprint": "一国最高的行政机关，管理并领导各级地方政府", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be7a67a-0052-4629-80f6-eca6c3881ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88210, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "小学", "is_correct": false, "explanation": "语义：小学没有权力给一个省级地区拨款，与句中的中央层级不符。"}, {"text": "中央政府", "is_correct": true, "explanation": "中央政府是国家最高行政机关，有权给各省拨款，符合句意。"}, {"text": "空气", "is_correct": false, "explanation": "配价：「拨钱」的主语必须是有权力的机构或人，空气不能作拨款的主体。"}, {"text": "大海", "is_correct": false, "explanation": "配价：「拨钱」的主语必须是有权力的机构或人，大海不能作拨款的主体。"}], "explanations": {"小学": "语义：小学没有权力给一个省级地区拨款，与句中的中央层级不符。", "中央政府": "中央政府是国家最高行政机关，有权给各省拨款，符合句意。", "空气": "配价：「拨钱」的主语必须是有权力的机构或人，空气不能作拨款的主体。", "大海": "配价：「拨钱」的主语必须是有权力的机构或人，大海不能作拨款的主体。"}, "sentence_index": 0, "correct_answer": "中央政府"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我在电视上看到一只中央政府。", "explanation": "这里应该用〈个〉。〈只〉用于动物或成对物品中的一个，不能用于机构。"}, {"text": "这个国家有一朵中央政府。", "explanation": "这里应该用〈个〉。〈朵〉用于花朵、云朵等，不能用于机构。"}, {"text": "我在书上读到一条中央政府。", "explanation": "这里应该用〈个〉。〈条〉用于细长的东西，不能用于机构。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88210, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "石头", "is_correct": false, "explanation": "配价：「归……管」要求有管理权的主体，石头不能管理市政府。"}, {"text": "学校", "is_correct": false, "explanation": "语义：学校的管辖范围不包括政府机构，「市政府归学校管」不成立。"}, {"text": "冰箱", "is_correct": false, "explanation": "语义：冰箱是家用电器，不能管理市政府，与句中的管辖关系不符。"}, {"text": "中央政府", "is_correct": true, "explanation": "中央政府是国家最高行政机关，市政府归它管辖，符合句意。"}], "explanations": {"石头": "配价：「归……管」要求有管理权的主体，石头不能管理市政府。", "学校": "语义：学校的管辖范围不包括政府机构，「市政府归学校管」不成立。", "冰箱": "语义：冰箱是家用电器，不能管理市政府，与句中的管辖关系不符。", "中央政府": "中央政府是国家最高行政机关，市政府归它管辖，符合句意。"}, "sentence_index": 6, "correct_answer": "中央政府"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "中央政府负责修缮本市的道路。", "explanation": "这里应该用〈市政府〉。〈中央政府〉管全国大事，不直接负责某个市的道路修缮。"}, {"text": "中央政府负责调解本乡的土地纠纷。", "explanation": "这里应该用〈乡政府〉。〈中央政府〉的职权范围是全国，不处理某一乡的具体纠纷。"}, {"text": "中央政府负责修理本村的水井。", "explanation": "这里应该用〈村委会〉。〈中央政府〉统管全国大事，不负责某一个村的水井。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88210, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家设有一只中央政府。", "corrected_sentence": "这个国家设有一个中央政府。", "error_description": "量词错误：机构“中央政府”应使用量词“个”，“只”用于动物或成对物品中的一个，这里用错了。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88210, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "全国需要一个强大地中央政府。", "corrected_sentence": "全国需要一个强大的中央政府。", "error_description": "结构助词错误：修饰名词“中央政府”时应用结构助词“的”，“地”用于修饰动词，这里用错了。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
