INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88211, 1, 'prompt1_core', '{"pos": "量词", "semantic_class": "function", "definition": "吨是称很重很重的东西时用的单位，一吨是一千公斤。", "primary_collocate": null, "pronunciation": "dūn", "ipa": "tuən˥", "syllable_count": 1, "sentences": [{"text": "这辆卡车能装五吨煤。", "target_word": "吨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们村今年卖了一吨大米。", "target_word": "吨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这头大象有四吨重。", "target_word": "吨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "工人们搬了三吨水泥。", "target_word": "吨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条船一次能运十吨货。", "target_word": "吨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一吨的东西很重，要用大车运。", "target_word": "吨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "厂里每天要用一吨水。", "target_word": "吨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那块大石头有两吨。", "target_word": "吨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "农民今年收了八吨西瓜。", "target_word": "吨", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座桥不让超过十吨的车过。", "target_word": "吨", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "噸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "称很重的东西时用的重量单位，一吨为一千公斤", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c6ba22e3-4e03-4c26-838e-beb10be1ee6b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88211, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "吨", "is_correct": true, "explanation": "正确。吨是称很重的东西时用的重量单位，一吨等于一千公斤。"}, {"text": "顿", "is_correct": false, "explanation": "顿（dùn，第四声）与吨（dūn，第一声）只有声调不同，顿指一餐或次数，不是重量单位。"}, {"text": "吞", "is_correct": false, "explanation": "吞（tūn）与吨（dūn）声母不同，d 与 t，吞的意思是咽下，不是重量单位。"}, {"text": "单", "is_correct": false, "explanation": "单（dān）与吨（dūn）韵母不同，单的意思是单独，不是重量单位。"}, {"text": "炖", "is_correct": false, "explanation": "炖（dùn，第四声）与吨（dūn，第一声）只有声调不同，炖是一种做菜的方法，不是重量单位。"}], "explanations": {"吨": "正确。吨是称很重的东西时用的重量单位，一吨等于一千公斤。", "顿": "顿（dùn，第四声）与吨（dūn，第一声）只有声调不同，顿指一餐或次数，不是重量单位。", "吞": "吞（tūn）与吨（dūn）声母不同，d 与 t，吞的意思是咽下，不是重量单位。", "单": "单（dān）与吨（dūn）韵母不同，单的意思是单独，不是重量单位。", "炖": "炖（dùn，第四声）与吨（dūn，第一声）只有声调不同，炖是一种做菜的方法，不是重量单位。"}, "sentence_index": null, "correct_answer": "吨"}, "level_3": {"options": [{"text": "吨", "is_correct": true, "explanation": "正确。吨是重量单位，可以计量五吨煤。"}, {"text": "辆", "is_correct": false, "explanation": "语义：“辆”用于车辆，煤不是车，不能说五辆煤。"}, {"text": "只", "is_correct": false, "explanation": "搭配：“只”多用于动物或成对的小件，煤不能用“只”计量。"}, {"text": "张", "is_correct": false, "explanation": "搭配：“张”用于平面的东西，煤不能用“张”计量。"}], "explanations": {"吨": "正确。吨是重量单位，可以计量五吨煤。", "辆": "语义：“辆”用于车辆，煤不是车，不能说五辆煤。", "只": "搭配：“只”多用于动物或成对的小件，煤不能用“只”计量。", "张": "搭配：“张”用于平面的东西，煤不能用“张”计量。"}, "sentence_index": 0, "correct_answer": "吨"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这个西瓜重五吨。", "explanation": "这里应该用〈公斤〉。吨是很大的重量单位，一个西瓜的重量要用公斤。"}, {"text": "这本词典有三吨厚。", "explanation": "这里应该用〈厘米〉。吨是重量单位，说厚度要用厘米，不能用吨。"}, {"text": "我等了三吨时间才见到他。", "explanation": "这里应该用〈小时〉。吨是重量单位，计量等待的时长要用小时，不能用吨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88211, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "吨", "is_correct": true, "explanation": "正确。吨是称很重的东西时用的重量单位，一吨等于一千公斤。"}, {"text": "钝", "is_correct": false, "explanation": "钝（dùn，第四声）与吨（dūn，第一声）只有声调不同，钝的意思是不锋利，不是重量单位。"}, {"text": "堆", "is_correct": false, "explanation": "堆（duī）与吨（dūn）韵母末尾不同，堆的意思是堆积，不是重量单位。"}, {"text": "婚", "is_correct": false, "explanation": "婚（hūn）与吨（dūn）声母不同，d 与 h，婚的意思是结婚，不是重量单位。"}, {"text": "担", "is_correct": false, "explanation": "担（dān）与吨（dūn）韵母不同，担的意思是挑或担心，不是重量单位。"}], "explanations": {"吨": "正确。吨是称很重的东西时用的重量单位，一吨等于一千公斤。", "钝": "钝（dùn，第四声）与吨（dūn，第一声）只有声调不同，钝的意思是不锋利，不是重量单位。", "堆": "堆（duī）与吨（dūn）韵母末尾不同，堆的意思是堆积，不是重量单位。", "婚": "婚（hūn）与吨（dūn）声母不同，d 与 h，婚的意思是结婚，不是重量单位。", "担": "担（dān）与吨（dūn）韵母不同，担的意思是挑或担心，不是重量单位。"}, "sentence_index": null, "correct_answer": "吨"}, "level_3": {"options": [{"text": "吨", "is_correct": true, "explanation": "正确。吨是重量单位，“一吨水”是正确的说法。"}, {"text": "座", "is_correct": false, "explanation": "语义：“座”用于山、桥等大型固定的东西，水不能用“座”计量。"}, {"text": "个", "is_correct": false, "explanation": "搭配：“一个水”不是常见说法，“个”不能直接与“水”搭配。"}, {"text": "件", "is_correct": false, "explanation": "语义：“件”用于衣物、事情等，水不属于这一类。"}], "explanations": {"吨": "正确。吨是重量单位，“一吨水”是正确的说法。", "座": "语义：“座”用于山、桥等大型固定的东西，水不能用“座”计量。", "个": "搭配：“一个水”不是常见说法，“个”不能直接与“水”搭配。", "件": "语义：“件”用于衣物、事情等，水不属于这一类。"}, "sentence_index": 6, "correct_answer": "吨"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个班有五十吨学生。", "explanation": "这里应该用〈名〉。吨是重量单位，学生要按人数计量，不能用吨。"}, {"text": "这件衣服卖了三吨钱。", "explanation": "这里应该用〈元〉。吨是重量单位，说价钱要用元，不能用吨。"}, {"text": "这条路长五吨。", "explanation": "这里应该用〈公里〉。吨是重量单位，说路的长短要用公里，不能用吨。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88211, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这批化肥一共六个吨。", "corrected_sentence": "这批化肥一共六吨。", "error_description": "“六个吨”多了量词“个”。吨本身就是量词，后面不能再接“个”，应说“六吨”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88211, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这艘货船每趟能运吨三。", "corrected_sentence": "这艘货船每趟能运三吨。", "error_description": "“吨三”语序颠倒。数量词要放在量词前面，应说“三吨”，不能说“吨三”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd76affc5-5d36-4fee-9032-b922d0c0d656') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
