INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88213, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "服务业是帮别人做事、不是做东西的行业，比如饭店。", "primary_collocate": null, "pronunciation": "fú wù yè", "ipa": "fu˧˥ u˥˩ jɛ˥˩", "syllable_count": 3, "sentences": [{"text": "饭店和酒店都属于服务业。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务业的工作是帮客人做事。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他在服务业工作，每天都要对客人笑。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "开饭店属于服务业，不是做东西的工作。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "现在很多年轻人想去服务业工作。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务业不做东西，主要是帮别人做事。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "理发店、饭店和商店都是服务业。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "服务业的人要对客人很客气。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我妈妈在服务业工作了十年。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个城市的服务业很发达，饭店特别多。", "target_word": "服务业", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "服務業", "label": "繁体"}], "register": "中性", "sense_fingerprint": "帮别人做事而不做东西的行业，如饭店", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6e59cd1e-273a-489b-abf0-17bb4fcc0b71') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88213, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "工业", "is_correct": false, "explanation": "语义：饭店和酒店不属于工业，这个说法与事实相反。"}, {"text": "服务业", "is_correct": true, "explanation": "正确：饭店和酒店是帮人做事、不做东西的行业，属于服务业。"}, {"text": "农业", "is_correct": false, "explanation": "语义：饭店和酒店不属于农业，与事实相反。"}, {"text": "工厂", "is_correct": false, "explanation": "搭配：“属于”后接行业类别，“工厂”是场所，不能作类别。"}], "explanations": {"工业": "语义：饭店和酒店不属于工业，这个说法与事实相反。", "服务业": "正确：饭店和酒店是帮人做事、不做东西的行业，属于服务业。", "农业": "语义：饭店和酒店不属于农业，与事实相反。", "工厂": "搭配：“属于”后接行业类别，“工厂”是场所，不能作类别。"}, "sentence_index": 0, "correct_answer": "服务业"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这家饭店的服务业很好，客人都很满意。", "explanation": "这里应该用〈服务〉。“服务业”是行业名称，说某家店的服务质量要用“服务”。"}, {"text": "饭店里的服务业很热情，一直招呼客人。", "explanation": "这里应该用〈服务员〉。“服务业”指行业，不指人，说站在那里招呼客人的人要用“服务员”。"}, {"text": "我的服务业是老师，在学校教书。", "explanation": "这里应该用〈职业〉。“服务业”指一类行业，不指个人的工作；说自己做什么工作要用“职业”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88213, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "建筑业", "is_correct": false, "explanation": "语义：理发店、饭店和商店不属于建筑业，与事实相反。"}, {"text": "服务业", "is_correct": true, "explanation": "正确：理发店、饭店和商店都是帮人做事、不做东西的行业。"}, {"text": "矿业", "is_correct": false, "explanation": "语义：理发店、饭店和商店不属于矿业，与事实相反。"}, {"text": "汽车", "is_correct": false, "explanation": "搭配：“汽车”是产品，不是行业，不能用“都是”来指类别。"}], "explanations": {"建筑业": "语义：理发店、饭店和商店不属于建筑业，与事实相反。", "服务业": "正确：理发店、饭店和商店都是帮人做事、不做东西的行业。", "矿业": "语义：理发店、饭店和商店不属于矿业，与事实相反。", "汽车": "搭配：“汽车”是产品，不是行业，不能用“都是”来指类别。"}, "sentence_index": 6, "correct_answer": "服务业"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个城市的服务业很多，市民可以在那里办手续。", "explanation": "这里应该用〈服务中心〉。“服务业”指行业，不指可以办事的地方。"}, {"text": "机场的服务业就在一楼，可以帮你问路。", "explanation": "这里应该用〈服务台〉。“服务业”是行业，不能指设在一楼、可以问路的地方。"}, {"text": "这家健身房的服务业很多，有游泳和瑜伽。", "explanation": "这里应该用〈服务项目〉。“服务项目”指提供的具体项目，“服务业”是行业，不能列出游泳和瑜伽。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88213, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个城市的服务业们很发达，年轻人很多。", "corrected_sentence": "这个城市的服务业很发达，年轻人很多。", "error_description": "错误形式“服务业们”，正确形式“服务业”。“服务业”是行业名称，不能加“们”表示复数；“们”一般只用于指人的名词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88213, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "表哥服务业工作了三年。", "corrected_sentence": "表哥在服务业工作了三年。", "error_description": "错误形式“服务业工作”，正确形式“在服务业工作”。“服务业”作工作的场所时要用介词“在”引出，缺“在”句子不通。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'abbf11d7-21ba-4d62-8ad8-5eca8fea2c32') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
