INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88215, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "主页是网站打开后看到的第一页。", "primary_collocate": null, "pronunciation": "zhǔ yè", "ipa": "ʈʂu˨˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "打开网站，你先看到的是主页。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请点一下主页上的红色按钮。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个网站的主页很干净，只有一张图。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我想把这张照片放在主页上。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你找不到新闻，就回主页再看看。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主页上有今天的天气和新闻。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机上的这个网站，主页打开得很快。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他每天先看这家报纸的主页。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "点这里，就能回到主页。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主页的最上面有一个搜索框。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "主頁", "label": "繁体"}, {"form": "网站主页", "label": "复合"}], "register": "中性", "sense_fingerprint": "网站打开后的第一页", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd548b280-89df-4fe8-9d81-fedf7fde6e45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88215, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主页", "is_correct": true, "explanation": "zhǔyè 指网站打开后看到的第一页，是本词的意思。"}, {"text": "竹叶", "is_correct": false, "explanation": "zhúyè 与 zhǔyè 声调不同（第二声与第三声），意思是竹子的叶子。"}, {"text": "主要", "is_correct": false, "explanation": "zhǔyào 与 zhǔyè 韵母不同（yao 与 ye），意思是重要。"}, {"text": "主意", "is_correct": false, "explanation": "zhǔyì 与 zhǔyè 韵母不同（i 与 e），意思是主意、办法。"}, {"text": "祖业", "is_correct": false, "explanation": "zǔyè 与 zhǔyè 声母不同（z 与 zh），意思是祖上传下来的产业。"}], "explanations": {"主页": "zhǔyè 指网站打开后看到的第一页，是本词的意思。", "竹叶": "zhúyè 与 zhǔyè 声调不同（第二声与第三声），意思是竹子的叶子。", "主要": "zhǔyào 与 zhǔyè 韵母不同（yao 与 ye），意思是重要。", "主意": "zhǔyì 与 zhǔyè 韵母不同（i 与 e），意思是主意、办法。", "祖业": "zǔyè 与 zhǔyè 声母不同（z 与 zh），意思是祖上传下来的产业。"}, "sentence_index": null, "correct_answer": "主页"}, "level_3": {"options": [{"text": "书页", "is_correct": false, "explanation": "语义：“书页”是纸质书的页，不是网站打开后看到的页面。"}, {"text": "主页", "is_correct": true, "explanation": "“主页”指网站打开后看到的第一页，符合“打开网站先看到”的语境。"}, {"text": "页码", "is_correct": false, "explanation": "语义：“页码”是页面的编号，不能作为打开网站后先看到的内容。"}, {"text": "网线", "is_correct": false, "explanation": "搭配：“网线”是连接设备的线缆，不能说先看到网线。"}], "explanations": {"书页": "语义：“书页”是纸质书的页，不是网站打开后看到的页面。", "主页": "“主页”指网站打开后看到的第一页，符合“打开网站先看到”的语境。", "页码": "语义：“页码”是页面的编号，不能作为打开网站后先看到的内容。", "网线": "搭配：“网线”是连接设备的线缆，不能说先看到网线。"}, "sentence_index": 0, "correct_answer": "主页"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这份合同的主页上盖着公司的印章。", "explanation": "这里应该用〈第一页〉。主页指网站打开后看到的第一页，纸质合同的第一页不叫主页。"}, {"text": "我家的主页朝南，屋里很亮堂。", "explanation": "这里应该用〈正房〉。主页指网站打开后看到的第一页，房屋的朝向要说正房。"}, {"text": "这本书的主页写着作者的名字。", "explanation": "这里应该用〈扉页〉。主页指网站的首页，书的第一页要说扉页。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88215, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "报纸", "is_correct": false, "explanation": "语义：“报纸”是纸质媒体，与手机上的网站不符，不能说打开得快。"}, {"text": "海报", "is_correct": false, "explanation": "语义：“海报”是张贴的宣传画，不是可以打开的网站内容。"}, {"text": "主页", "is_correct": true, "explanation": "“主页”是网站的首页，符合“手机上的网站，打开得很快”的语境。"}, {"text": "戏票", "is_correct": false, "explanation": "搭配：“戏票”不能被说成打开得很快，与“网站”搭配不通。"}], "explanations": {"报纸": "语义：“报纸”是纸质媒体，与手机上的网站不符，不能说打开得快。", "海报": "语义：“海报”是张贴的宣传画，不是可以打开的网站内容。", "主页": "“主页”是网站的首页，符合“手机上的网站，打开得很快”的语境。", "戏票": "搭配：“戏票”不能被说成打开得很快，与“网站”搭配不通。"}, "sentence_index": 6, "correct_answer": "主页"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下班后我回到主页，躺下就睡了。", "explanation": "这里应该用〈家〉。主页指网站打开后看到的第一页，回住处要说家。"}, {"text": "这间屋子的主页上有一张床。", "explanation": "主页只指网站打开后看到的第一页，屋子里不能有主页，这里用错了对象。"}, {"text": "妈妈把主页放进了冰箱，又拿出来。", "explanation": "主页是网络上的页面，不是能放进冰箱的实物，这里用错了对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88215, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这家公司有三主页，分别给不同部门用。", "corrected_sentence": "这家公司有三个主页，分别给不同部门用。", "error_description": "错误：数词“三”后缺少量词“个”。正确说法是“三个主页”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88215, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我设计了一台新主页，给朋友看。", "corrected_sentence": "我设计了一个新主页，给朋友看。", "error_description": "错误：“主页”不用“台”作量词，应说“一个新主页”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
