INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88216, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "网站或网络应用的首页，也指个人网页的主要页面。", "primary_collocate": null, "pronunciation": "zhǔ yè", "ipa": "ʈʂu˨˩ jɛ˥˩", "syllable_count": 2, "sentences": [{"text": "他的个人主页上有很多旅行照片。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个应用的主页有三个小图标。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我给自己的主页换了一张新图片。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师在班级主页发了一个通知。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她常常更新自己的主页。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你可以在我的主页留言。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家公司的主页做得很漂亮。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "打开应用，主页上先出现一首歌。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把自己的作品都放在主页上。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请看公司主页，那里有电话和地址。", "target_word": "主页", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "主頁", "label": "繁体"}, {"form": "个人主页", "label": "复合"}], "register": "中性", "sense_fingerprint": "网站、应用或个人网页的首页", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'd548b280-89df-4fe8-9d81-fedf7fde6e45') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88216, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "主页", "is_correct": true, "explanation": "zhǔyè 指网站、应用或个人网页的首页，是本词的意思。"}, {"text": "主义", "is_correct": false, "explanation": "zhǔyì 与 zhǔyè 韵母不同（i 与 e），意思是主义、思想体系。"}, {"text": "祖业", "is_correct": false, "explanation": "zǔyè 与 zhǔyè 声母不同（z 与 zh），意思是祖上传下来的产业。"}, {"text": "竹叶", "is_correct": false, "explanation": "zhúyè 与 zhǔyè 声调不同（第二声与第三声），意思是竹子的叶子。"}, {"text": "主要", "is_correct": false, "explanation": "zhǔyào 与 zhǔyè 韵母不同（yao 与 ye），意思是重要。"}], "explanations": {"主页": "zhǔyè 指网站、应用或个人网页的首页，是本词的意思。", "主义": "zhǔyì 与 zhǔyè 韵母不同（i 与 e），意思是主义、思想体系。", "祖业": "zǔyè 与 zhǔyè 声母不同（z 与 zh），意思是祖上传下来的产业。", "竹叶": "zhúyè 与 zhǔyè 声调不同（第二声与第三声），意思是竹子的叶子。", "主要": "zhǔyào 与 zhǔyè 韵母不同（yao 与 ye），意思是重要。"}, "sentence_index": null, "correct_answer": "主页"}, "level_3": {"options": [{"text": "书页", "is_correct": false, "explanation": "语义：书页是纸质书的页，与个人网页不符。"}, {"text": "工资", "is_correct": false, "explanation": "语义：“工资”是劳动报酬，不能说“个人工资上有很多旅行照片”。"}, {"text": "饭盒", "is_correct": false, "explanation": "语义：饭盒是盛饭的器具，不能说“个人饭盒上有很多旅行照片”。"}, {"text": "主页", "is_correct": true, "explanation": "“个人主页”是个人网页，符合“主页上有旅行照片”的语境。"}], "explanations": {"书页": "语义：书页是纸质书的页，与个人网页不符。", "工资": "语义：“工资”是劳动报酬，不能说“个人工资上有很多旅行照片”。", "饭盒": "语义：饭盒是盛饭的器具，不能说“个人饭盒上有很多旅行照片”。", "主页": "“个人主页”是个人网页，符合“主页上有旅行照片”的语境。"}, "sentence_index": 0, "correct_answer": "主页"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这本杂志的主页印得很清楚。", "explanation": "这里应该用〈封面〉。主页指网站或应用的首页，杂志的第一页要说封面。"}, {"text": "他坐在主页上看书。", "explanation": "这里应该用〈椅子〉。主页是网页，不能拿来坐。"}, {"text": "这个观点的主页很有道理。", "explanation": "这里应该用〈论点〉。主页指网站或应用的首页，观点的核心要说论点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88216, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "病房", "is_correct": false, "explanation": "语义：“病房”属于医院，与“这家公司的主页”不符。"}, {"text": "校舍", "is_correct": false, "explanation": "语义：“校舍”属于学校，公司不会有校舍，语境不合。"}, {"text": "药方", "is_correct": false, "explanation": "搭配：“药方”不能说做得很漂亮，与“做得很漂亮”搭配不通。"}, {"text": "主页", "is_correct": true, "explanation": "“公司主页”指公司网站的首页，符合“做得很漂亮”的语境。"}], "explanations": {"病房": "语义：“病房”属于医院，与“这家公司的主页”不符。", "校舍": "语义：“校舍”属于学校，公司不会有校舍，语境不合。", "药方": "搭配：“药方”不能说做得很漂亮，与“做得很漂亮”搭配不通。", "主页": "“公司主页”指公司网站的首页，符合“做得很漂亮”的语境。"}, "sentence_index": 6, "correct_answer": "主页"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "下班回到主页，我洗了澡就睡了。", "explanation": "这里应该用〈家〉。主页指网站或应用的首页，回住处要说家。"}, {"text": "这个主页很喜欢吃饭。", "explanation": "主页是网页，不会喜欢或吃饭，这里把它当成了人，用错了对象。"}, {"text": "把主页搬到楼下去。", "explanation": "主页是网页，不能搬动，这里用错了对象。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88216, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他们一共做了两主页，分别介绍产品和招聘。", "corrected_sentence": "他们一共做了两个主页，分别介绍产品和招聘。", "error_description": "错误：数词“两”后缺少量词“个”。正确说法是“两个主页”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88216, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我设计了一台新的应用主页，给大家看。", "corrected_sentence": "我设计了一个新的应用主页，给大家看。", "error_description": "错误：“主页”不用“台”作量词，应说“一个新的应用主页”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '95b3648b-c21c-4755-ba19-01cb3a6ccf85') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "在野", "is_correct": true, "explanation": "正确：“在野”指不担任政府职务，与“执政”相对，如“在野党”与“执政党”相对。"}, {"text": "游泳", "is_correct": false, "explanation": "与“执政”没有反义关系，二者意思无关。"}, {"text": "思考", "is_correct": false, "explanation": "与“执政”没有反义关系，“思考”指用脑子考虑问题。"}, {"text": "旅行", "is_correct": false, "explanation": "与“执政”没有反义关系，“旅行”指外出游览。"}], "correct_answer": "在野", "explanations": {"在野": "正确：“在野”指不担任政府职务，与“执政”相对，如“在野党”与“执政党”相对。", "游泳": "与“执政”没有反义关系，二者意思无关。", "思考": "与“执政”没有反义关系，“思考”指用脑子考虑问题。", "旅行": "与“执政”没有反义关系，“旅行”指外出游览。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "在野", "is_correct": true, "explanation": "正确：“在野”指不担任政府职务，与“执政”相对，如“在野党”与“执政党”相对。"}, {"text": "出版", "is_correct": false, "explanation": "与“执政”没有反义关系，“出版”指印刷发行书刊。"}, {"text": "跳舞", "is_correct": false, "explanation": "与“执政”没有反义关系，二者意思无关。"}, {"text": "散步", "is_correct": false, "explanation": "与“执政”没有反义关系，“散步”指随意地走动。"}], "correct_answer": "在野", "explanations": {"在野": "正确：“在野”指不担任政府职务，与“执政”相对，如“在野党”与“执政党”相对。", "出版": "与“执政”没有反义关系，“出版”指印刷发行书刊。", "跳舞": "与“执政”没有反义关系，二者意思无关。", "散步": "与“执政”没有反义关系，“散步”指随意地走动。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "执政是管理一个国家，做主要的决定。", "primary_collocate": null, "pronunciation": "zhí zhèng", "ipa": "tʂɨ³⁵ tʂɤŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "这个党已经执政十年了。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新总统执政以后，做了很多改变。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他希望自己的党以后能执政。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位领导人执政的时候，国家很安定。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个政党想执政，就要得到人民的支持。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个国家由一个政党长期执政。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他执政五年，经济发展得很快。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老百姓希望执政的人多为大家想想。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个国家的政党轮流执政。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他是在什么时候开始执政的？", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "执政了", "label": "体标"}, {"form": "执政过", "label": "体标"}, {"form": "执政党", "label": "复合"}], "register": "书面", "sense_fingerprint": "执政：管理国家并做主要决定", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd449a6-9c7f-4543-8b31-149e4d1ca677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "执政", "is_correct": true, "explanation": "正确：执政（zhí zhèng）是管理国家、做主要决定，就是这个词。"}, {"text": "指正", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是指出错误并加以改正。"}, {"text": "指证", "is_correct": false, "explanation": "zhǐ 与 zhí 声调不同，意思是指认并作证。"}, {"text": "持证", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch 与 zh），意思是持有证件。"}, {"text": "时政", "is_correct": false, "explanation": "shí 与 zhí 声母不同（sh 与 zh），意思是当前的政治事务。"}], "explanations": {"执政": "正确：执政（zhí zhèng）是管理国家、做主要决定，就是这个词。", "指正": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是指出错误并加以改正。", "指证": "zhǐ 与 zhí 声调不同，意思是指认并作证。", "持证": "chí 与 zhí 声母不同（ch 与 zh），意思是持有证件。", "时政": "shí 与 zhí 声母不同（sh 与 zh），意思是当前的政治事务。"}, "sentence_index": null, "correct_answer": "执政"}, "level_3": {"options": [{"text": "执政", "is_correct": true, "explanation": "正确：“执政”指管理国家，与“已经……十年了”相符。"}, {"text": "游泳", "is_correct": false, "explanation": "语义：党不能“游泳”，句意不通。"}, {"text": "出版", "is_correct": false, "explanation": "语义：党不能“出版”，句意不通。"}, {"text": "退役", "is_correct": false, "explanation": "搭配：“退役”多用于军人或装备，不说党“退役”。"}], "explanations": {"执政": "正确：“执政”指管理国家，与“已经……十年了”相符。", "游泳": "语义：党不能“游泳”，句意不通。", "出版": "语义：党不能“出版”，句意不通。", "退役": "搭配：“退役”多用于军人或装备，不说党“退役”。"}, "sentence_index": 0, "correct_answer": "执政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他在报社执政了十年。", "explanation": "这里应该用〈任职〉。执政指掌握国家政权、管理国家，报社的职务要说〈任职〉。"}, {"text": "他在这家公司执政了五年。", "explanation": "这里应该用〈工作〉。执政用于国家或政党，不用于公司。"}, {"text": "他在这所学校执政多年。", "explanation": "这里应该用〈当校长〉。执政指掌握国家政权，在学校当领导要说〈当校长〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "执政", "is_correct": true, "explanation": "正确：“执政”指管理国家，与“经济发展得很快”相符。"}, {"text": "绘画", "is_correct": false, "explanation": "语义：“绘画”与经济发展无关，句意不通。"}, {"text": "睡觉", "is_correct": false, "explanation": "语义：“睡觉”不能带来经济的快速发展，句意不通。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“失眠”不能带来经济的快速发展，句意不通。"}], "explanations": {"执政": "正确：“执政”指管理国家，与“经济发展得很快”相符。", "绘画": "语义：“绘画”与经济发展无关，句意不通。", "睡觉": "语义：“睡觉”不能带来经济的快速发展，句意不通。", "失眠": "语义：“失眠”不能带来经济的快速发展，句意不通。"}, "sentence_index": 6, "correct_answer": "执政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在这家饭店执政了十年。", "explanation": "这里应该用〈经营〉。执政指掌握国家政权，饭店的经营要说〈经营〉。"}, {"text": "他在会议上执政了一个下午。", "explanation": "这里应该用〈主持〉。执政用于国家，会议的主持要说〈主持〉。"}, {"text": "他在这个小区执政了三十年。", "explanation": "这里应该用〈管理〉。执政用于国家，小区的管理要说〈管理〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个党已经执政着五年了。", "corrected_sentence": "这个党已经执政五年了。", "error_description": "体标错误：表示已经执政的时长时，“执政”后不能加“着”，应说“执政五年了”。错误形式“执政着五年了”，正确形式“执政五年了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88217, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他被执政三年，经济发展得很快。", "corrected_sentence": "他执政三年，经济发展得很快。", "error_description": "被字句错误：“执政”不能用“被”字句，应直接说“他执政三年”，或用“由……执政”。错误形式“他被执政”，正确形式“他执政”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
