INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88218, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "掌握国家政权，管理国家。", "primary_collocate": null, "pronunciation": "zhí zhèng", "ipa": "tʂɨ³⁵ tʂɤŋ⁵¹", "syllable_count": 2, "sentences": [{"text": "这个国家现在由谁执政？", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们的政党在这个国家执政多年。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王年轻时就开始执政了。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "执政的人必须为人民做事。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位女总统执政时，新建了很多学校。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "选举以后，新的政党开始执政。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们想让国家好起来，所以努力争取执政。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个政党执政了二十年才下台。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家怎么样，要看谁来执政。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "以前这里由军人执政，现在不是了。", "target_word": "执政", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "执政了", "label": "体标"}, {"form": "执政过", "label": "体标"}, {"form": "执政者", "label": "复合"}], "register": "书面", "sense_fingerprint": "执政：掌握国家政权", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8dd449a6-9c7f-4543-8b31-149e4d1ca677') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88218, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "执政", "is_correct": true, "explanation": "正确：执政（zhí zhèng）是掌握国家政权、管理国家，就是这个词。"}, {"text": "指正", "is_correct": false, "explanation": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是指出错误并加以改正。"}, {"text": "指证", "is_correct": false, "explanation": "zhǐ 与 zhí 声调不同，意思是指认并作证。"}, {"text": "持证", "is_correct": false, "explanation": "chí 与 zhí 声母不同（ch 与 zh），意思是持有证件。"}, {"text": "时政", "is_correct": false, "explanation": "shí 与 zhí 声母不同（sh 与 zh），意思是当前的政治事务。"}], "explanations": {"执政": "正确：执政（zhí zhèng）是掌握国家政权、管理国家，就是这个词。", "指正": "zhǐ（第三声）与 zhí（第二声）声调不同，意思是指出错误并加以改正。", "指证": "zhǐ 与 zhí 声调不同，意思是指认并作证。", "持证": "chí 与 zhí 声母不同（ch 与 zh），意思是持有证件。", "时政": "shí 与 zhí 声母不同（sh 与 zh），意思是当前的政治事务。"}, "sentence_index": null, "correct_answer": "执政"}, "level_3": {"options": [{"text": "执政", "is_correct": true, "explanation": "正确：“执政”指掌握政权、管理国家，与“由谁”相符。"}, {"text": "唱歌", "is_correct": false, "explanation": "语义：“由谁唱歌”不成句意，唱歌不能管理国家。"}, {"text": "种植", "is_correct": false, "explanation": "语义：“由谁种植”不成句意，种植不能管理国家。"}, {"text": "散步", "is_correct": false, "explanation": "语义：“由谁散步”不成句意，散步与管理国家无关。"}], "explanations": {"执政": "正确：“执政”指掌握政权、管理国家，与“由谁”相符。", "唱歌": "语义：“由谁唱歌”不成句意，唱歌不能管理国家。", "种植": "语义：“由谁种植”不成句意，种植不能管理国家。", "散步": "语义：“由谁散步”不成句意，散步与管理国家无关。"}, "sentence_index": 0, "correct_answer": "执政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "她在这家公司执政了十年。", "explanation": "这里应该用〈掌管〉。执政指掌握国家政权，公司的事务要说〈掌管〉。"}, {"text": "他在这所医院执政了三十年。", "explanation": "这里应该用〈服务〉。执政用于国家政权，在医院工作要说〈服务〉。"}, {"text": "他在这家工厂执政了十年。", "explanation": "这里应该用〈经营〉。执政用于国家，工厂的经营要说〈经营〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88218, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "执政", "is_correct": true, "explanation": "正确：“执政”指掌握政权，与“努力争取”“让国家好起来”相符。"}, {"text": "绘画", "is_correct": false, "explanation": "语义：“绘画”与让国家好起来无关，句意不通。"}, {"text": "失眠", "is_correct": false, "explanation": "语义：“失眠”与让国家好起来无关，句意不通。"}, {"text": "游泳", "is_correct": false, "explanation": "搭配：“争取”的对象多是机会、权利，不说“争取游泳”。"}], "explanations": {"执政": "正确：“执政”指掌握政权，与“努力争取”“让国家好起来”相符。", "绘画": "语义：“绘画”与让国家好起来无关，句意不通。", "失眠": "语义：“失眠”与让国家好起来无关，句意不通。", "游泳": "搭配：“争取”的对象多是机会、权利，不说“争取游泳”。"}, "sentence_index": 6, "correct_answer": "执政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他在图书馆执政了五年。", "explanation": "这里应该用〈工作〉。执政指掌握国家政权，在图书馆做事要说〈工作〉。"}, {"text": "他在这家银行执政了八年。", "explanation": "这里应该用〈工作〉。执政指掌握国家政权，在银行上班要说〈工作〉。"}, {"text": "他在这家商店执政了十年。", "explanation": "这里应该用〈工作〉。执政用于国家政权，在商店上班要说〈工作〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88218, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他曾经执政着三年。", "corrected_sentence": "他曾经执政过三年。", "error_description": "体标错误：表示曾经经历时要用“过”；“着”表示持续的状态，“执政”是动作动词，不能用“着”表示曾经。错误形式“曾经执政着三年”，正确形式“曾经执政过三年”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '56a27368-be5d-4c39-9e19-0d3e038689a7') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
