INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88219, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "束缚是用绳子捆住，让人不能自由动。", "primary_collocate": null, "pronunciation": "shù fù", "ipa": "ʂu˥˩ fu˥˩", "syllable_count": 2, "sentences": [{"text": "警察用绳子束缚了他的双手。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绳子束缚着他的手脚，他动不了。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "粗绳子紧紧束缚着他的身体。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生用带子束缚了病人的手，免得他乱动。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绳子束缚着小狗，它跑不了。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "坏人束缚了他的手脚，把他关在屋里。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "请不要用绳子束缚孩子的手。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "电影里，坏人束缚过一个女孩。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "绳子束缚着那匹马，它走不开。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想动，可是绳子束缚着他的手腕。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "束缚着", "label": "体标（着）"}, {"form": "束缚了", "label": "体标（了）"}, {"form": "束缚过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "用绳子等东西捆住人或动物的身体，使其不能动", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a55c6fd-35f4-4c8a-92f0-78d112ddc57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88219, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "叔父", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是叔叔（父亲的弟弟）。"}, {"text": "束缚", "is_correct": true, "explanation": "正确选项，即目标词，读 shù fù。"}, {"text": "税负", "is_correct": false, "explanation": "shuì（第四声）比 shù 多了一个韵母 i，意思是税收负担。"}, {"text": "舒服", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，fu（轻声）与 fù（第四声）声调不同，意思是舒适。"}], "explanations": {"叔父": "shū（第一声）与 shù（第四声）声调不同，意思是叔叔（父亲的弟弟）。", "束缚": "正确选项，即目标词，读 shù fù。", "税负": "shuì（第四声）比 shù 多了一个韵母 i，意思是税收负担。", "舒服": "shū（第一声）与 shù（第四声）声调不同，fu（轻声）与 fù（第四声）声调不同，意思是舒适。"}, "sentence_index": null, "correct_answer": "束缚"}, "level_3": {"options": [{"text": "束缚", "is_correct": true, "explanation": "正确：用绳子捆住人的双手，与“用绳子”搭配。"}, {"text": "擦", "is_correct": false, "explanation": "搭配：“擦”用于清洁物体表面，不能用绳子擦手。"}, {"text": "编", "is_correct": false, "explanation": "语义：“编”是编织，绳子不能编人的双手，与语境不合。"}, {"text": "挠", "is_correct": false, "explanation": "语义：“挠”是抓挠，与绳子捆住身体的意思不符。"}], "explanations": {"束缚": "正确：用绳子捆住人的双手，与“用绳子”搭配。", "擦": "搭配：“擦”用于清洁物体表面，不能用绳子擦手。", "编": "语义：“编”是编织，绳子不能编人的双手，与语境不合。", "挠": "语义：“挠”是抓挠，与绳子捆住身体的意思不符。"}, "sentence_index": 0, "correct_answer": "束缚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他用手束缚了桌布，怕它被风吹走。", "explanation": "这里应该用〈按住〉。束缚的对象通常是人或动物，压住桌布要用“按住”。"}, {"text": "他把绳子束缚在树上，免得被风吹倒。", "explanation": "这里应该用〈系〉。束缚的对象是人或动物，把绳子绑在树上要用“系”。"}, {"text": "一片落叶束缚了他的脚。", "explanation": "这里应该用〈绊〉。落叶不能束缚人的脚，要说“一片落叶绊住了他的脚”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88219, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "束缚", "is_correct": true, "explanation": "正确：用绳子捆住孩子的手，与“请不要用绳子”搭配。"}, {"text": "夸", "is_correct": false, "explanation": "搭配：“用绳子夸”说不通；“夸”是赞扬，与捆绑的动作无关。"}, {"text": "烤", "is_correct": false, "explanation": "语义：“烤”是加热，绳子不能烤孩子的手，与语境不合。"}, {"text": "绣", "is_correct": false, "explanation": "搭配：“绣”是用针线做图案，不能用绳子绣孩子的手。"}], "explanations": {"束缚": "正确：用绳子捆住孩子的手，与“请不要用绳子”搭配。", "夸": "搭配：“用绳子夸”说不通；“夸”是赞扬，与捆绑的动作无关。", "烤": "语义：“烤”是加热，绳子不能烤孩子的手，与语境不合。", "绣": "搭配：“绣”是用针线做图案，不能用绳子绣孩子的手。"}, "sentence_index": 6, "correct_answer": "束缚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他想动，可是一阵风束缚了他的手腕。", "explanation": "这里应该用〈吹〉。束缚指用绳索等把人或动物捆住，风不能这样束缚手腕；此处的风只能说“吹”。"}, {"text": "他用绳子束缚住箱子。", "explanation": "这里应该用〈捆住〉。束缚的对象是人或动物，捆箱子要用“捆”。"}, {"text": "她用皮筋束缚了自己的头发。", "explanation": "这里应该用〈扎〉。束缚指捆住人或动物使其不能自由动，把头发拢起来要说“扎头发”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88219, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "绳子束缚得那只受伤的小鸟。", "corrected_sentence": "绳子束缚着那只受伤的小鸟。", "error_description": "错误：“着”误作“得”。应为“束缚着”，表示动作持续的“着”紧跟动词；“得”后须接补语，不能直接接宾语。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88219, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "绳子束缚了住那只羊的前腿，它站不稳。", "corrected_sentence": "绳子束缚住了那只羊的前腿，它站不稳。", "error_description": "错误：结果补语“住”与动态助词“了”的顺序颠倒。应为“束缚住了”，结果补语“住”紧跟动词，“了”放在其后。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88220, 1, 'llm_types_A', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放", "is_correct": true, "explanation": "正确：在“约束人、使人不能自由”这一义项上，“解放”与“束缚”是反义关系。"}, {"text": "修建", "is_correct": false, "explanation": "与“束缚”无反义或近义关系，“修建”指建造。"}, {"text": "收藏", "is_correct": false, "explanation": "与“束缚”无反义或近义关系，“收藏”指保存物品。"}, {"text": "欢迎", "is_correct": false, "explanation": "与“束缚”无反义或近义关系，“欢迎”指热情接待。"}], "correct_answer": "解放", "explanations": {"解放": "正确：在“约束人、使人不能自由”这一义项上，“解放”与“束缚”是反义关系。", "修建": "与“束缚”无反义或近义关系，“修建”指建造。", "收藏": "与“束缚”无反义或近义关系，“收藏”指保存物品。", "欢迎": "与“束缚”无反义或近义关系，“欢迎”指热情接待。"}, "sentence_index": 3}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88220, 1, 'llm_types_B', '{"synonym_antonym_match": {"relation": "antonym", "options": [{"text": "解放", "is_correct": true, "explanation": "正确：在“限制人的自由”这一义项上，“解放”与“束缚”是反义关系。"}, {"text": "购买", "is_correct": false, "explanation": "与“束缚”无反义或近义关系，“购买”指付款取得物品。"}, {"text": "观察", "is_correct": false, "explanation": "与“束缚”无反义或近义关系，“观察”指仔细察看。"}, {"text": "组织", "is_correct": false, "explanation": "与“束缚”无反义或近义关系，“组织”指安排、管理。"}], "correct_answer": "解放", "explanations": {"解放": "正确：在“限制人的自由”这一义项上，“解放”与“束缚”是反义关系。", "购买": "与“束缚”无反义或近义关系，“购买”指付款取得物品。", "观察": "与“束缚”无反义或近义关系，“观察”指仔细察看。", "组织": "与“束缚”无反义或近义关系，“组织”指安排、管理。"}, "sentence_index": 9}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88220, 1, 'prompt1_core', '{"pos": "动词", "semantic_class": "action", "definition": "使受到约束而不能自由行动或思考。", "primary_collocate": null, "pronunciation": "shù fù", "ipa": "ʂu˥˩ fu˥˩", "syllable_count": 2, "sentences": [{"text": "别让旧习惯束缚你。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她不想让婚姻束缚自己。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "规定太多，会束缚孩子的想法。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他觉得这份工作束缚了他的自由。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老观念一直束缚着农村的年轻人。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些规矩把大家束缚得很紧。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "不要用考试成绩束缚孩子的兴趣。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "钱从来没有束缚过他的生活。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太多的规则束缚着我们的想象力。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她觉得时间表束缚了自己，所以不再用。", "target_word": "束缚", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "束缚着", "label": "体标（着）"}, {"form": "束缚了", "label": "体标（了）"}, {"form": "束缚过", "label": "体标（过）"}], "register": "书面", "sense_fingerprint": "用规矩、习惯、观念等限制人，使人不能自由行动或思考", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a55c6fd-35f4-4c8a-92f0-78d112ddc57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88220, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "叔父", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，意思是叔叔（父亲的弟弟）。"}, {"text": "束缚", "is_correct": true, "explanation": "正确选项，即目标词，读 shù fù。"}, {"text": "税负", "is_correct": false, "explanation": "shuì（第四声）比 shù 多了一个韵母 i，意思是税收负担。"}, {"text": "舒服", "is_correct": false, "explanation": "shū（第一声）与 shù（第四声）声调不同，fu（轻声）与 fù（第四声）声调不同，意思是舒适。"}], "explanations": {"叔父": "shū（第一声）与 shù（第四声）声调不同，意思是叔叔（父亲的弟弟）。", "束缚": "正确选项，即目标词，读 shù fù。", "税负": "shuì（第四声）比 shù 多了一个韵母 i，意思是税收负担。", "舒服": "shū（第一声）与 shù（第四声）声调不同，fu（轻声）与 fù（第四声）声调不同，意思是舒适。"}, "sentence_index": null, "correct_answer": "束缚"}, "level_3": {"options": [{"text": "束缚", "is_correct": true, "explanation": "正确：与“别让”搭配，表示旧习惯限制人，使人不能自由。"}, {"text": "照顾", "is_correct": false, "explanation": "搭配：“照顾”需要有生命的照料者，旧习惯不能照顾人。"}, {"text": "鼓舞", "is_correct": false, "explanation": "语义：“鼓舞”是激励，旧习惯不会激励人，“别让旧习惯鼓舞你”与语境不合。"}, {"text": "扶持", "is_correct": false, "explanation": "语义：“扶持”是帮助支持，与旧习惯的消极含义相反。"}], "explanations": {"束缚": "正确：与“别让”搭配，表示旧习惯限制人，使人不能自由。", "照顾": "搭配：“照顾”需要有生命的照料者，旧习惯不能照顾人。", "鼓舞": "语义：“鼓舞”是激励，旧习惯不会激励人，“别让旧习惯鼓舞你”与语境不合。", "扶持": "语义：“扶持”是帮助支持，与旧习惯的消极含义相反。"}, "sentence_index": 0, "correct_answer": "束缚"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "新规定束缚了每人的购买数量。", "explanation": "这里应该用〈限制〉。束缚指使人或其行动不能自由，不用于数量；购买数量要用“限制”。"}, {"text": "他的话束缚了我的思想，让我思路开阔。", "explanation": "这里应该用〈解放〉。束缚表示限制、不自由，与后句“让我思路开阔”的语境相反。"}, {"text": "大雾束缚了飞机的起飞。", "explanation": "这里应该用〈阻止〉。束缚的对象是人或其自由、思想，大雾不能束缚飞机起飞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88220, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "束缚", "is_correct": true, "explanation": "正确：表示用考试成绩限制孩子兴趣的发展，与“不要”搭配。"}, {"text": "支付", "is_correct": false, "explanation": "搭配：“支付”的宾语是钱款或费用，不能说“支付兴趣”。"}, {"text": "照料", "is_correct": false, "explanation": "搭配：“照料”的对象是人或动植物，兴趣不能被照料。"}, {"text": "装饰", "is_correct": false, "explanation": "语义：“装饰”是美化外观，用于兴趣说不通，与考试成绩的语境不合。"}], "explanations": {"束缚": "正确：表示用考试成绩限制孩子兴趣的发展，与“不要”搭配。", "支付": "搭配：“支付”的宾语是钱款或费用，不能说“支付兴趣”。", "照料": "搭配：“照料”的对象是人或动植物，兴趣不能被照料。", "装饰": "语义：“装饰”是美化外观，用于兴趣说不通，与考试成绩的语境不合。"}, "sentence_index": 6, "correct_answer": "束缚"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "朋友的话束缚了他的勇气，让他越来越有信心。", "explanation": "这里应该用〈增强〉。束缚是限制，与“越来越有信心”矛盾，应说“增强”勇气。"}, {"text": "老师束缚学生大胆地提问。", "explanation": "这里应该用〈鼓励〉。束缚是限制，与“大胆地提问”所表达的鼓励语境矛盾。"}, {"text": "他蹲下来束缚了鞋带。", "explanation": "这里应该用〈系〉。束缚指捆住人或动物使其不能自由，鞋带要用“系”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88220, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "旧观念束缚的很多女性的选择。", "corrected_sentence": "旧观念束缚了很多女性的选择。", "error_description": "错误：“了”误作结构助词“的”。应为“束缚了”，动态助词“了”表示动作已经发生，不能用“的”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88220, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这些规矩把大家束缚了喘不过气。", "corrected_sentence": "这些规矩把大家束缚得喘不过气。", "error_description": "错误：程度补语前用错了“了”，应为“得”。应说“束缚得喘不过气”，“得”连接动词与表示程度结果的补语。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
