INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88221, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "不是亲生、但像女儿一样对待的女孩子。", "primary_collocate": null, "pronunciation": "gān nǚ ér", "ipa": "kan˥ ny˨˩ əɻ˧˥", "syllable_count": 3, "sentences": [{"text": "她没有孩子，把小美当干女儿。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我有一个干女儿，今年六岁。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老王很疼他的干女儿。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干女儿今天来看我了。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "王阿姨每个周末都带干女儿去公园。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的干女儿叫小红，很可爱。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "过年时，干女儿给我写了一张卡片。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她虽然是干女儿，但和亲女儿一样。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "李老师想认一个干女儿。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我的干女儿爱吃我做的菜。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个干女儿", "label": "量词（个）"}, {"form": "一位干女儿", "label": "量词（位）"}, {"form": "乾女兒", "label": "繁体"}], "register": "口语", "sense_fingerprint": "非亲生、被当作女儿疼爱的女孩", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ca57c2-ac8c-47f7-b168-f786db53d8e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88221, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干女儿", "is_correct": true, "explanation": "正确：干女儿指没有血缘、却被当作女儿疼爱的女孩，与“没有孩子”的语境相合。"}, {"text": "女朋友", "is_correct": false, "explanation": "语义：女朋友指恋爱对象，与“没有孩子，把小美当……”所指的家人式疼爱不合。"}, {"text": "女婿", "is_correct": false, "explanation": "语义：女婿指女儿的丈夫，是男性；小美是女性，不能被当作女婿。"}, {"text": "女公子", "is_correct": false, "explanation": "语域：女公子是书面敬称，指别人的女儿，口语中不这样说。"}], "explanations": {"干女儿": "正确：干女儿指没有血缘、却被当作女儿疼爱的女孩，与“没有孩子”的语境相合。", "女朋友": "语义：女朋友指恋爱对象，与“没有孩子，把小美当……”所指的家人式疼爱不合。", "女婿": "语义：女婿指女儿的丈夫，是男性；小美是女性，不能被当作女婿。", "女公子": "语域：女公子是书面敬称，指别人的女儿，口语中不这样说。"}, "sentence_index": 0, "correct_answer": "干女儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的干女儿是我妈妈。", "explanation": "干女儿是认作的晚辈，不能是自己的长辈；这里应该用〈干妈〉。"}, {"text": "他们认了一个干女儿，是个男孩。", "explanation": "这里应该用〈干儿子〉。干女儿指女性，认下的是男孩时要说〈干儿子〉，不能说〈干女儿〉。"}, {"text": "我和父母有血缘关系，我是他们的干女儿。", "explanation": "这里应该用〈亲生女儿〉。干女儿指没有血缘关系的人，与“有血缘关系”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88221, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干女儿", "is_correct": true, "explanation": "正确：干女儿是人，可以给我写卡片，与“过年时”的语境相合。"}, {"text": "石头", "is_correct": false, "explanation": "语义：石头不会写字，不能给我写卡片。"}, {"text": "年夜饭", "is_correct": false, "explanation": "搭配：“写卡片”的施事必须是人，年夜饭是食物，不能这样搭配。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：窗户不会写字，不能给我写卡片。"}], "explanations": {"干女儿": "正确：干女儿是人，可以给我写卡片，与“过年时”的语境相合。", "石头": "语义：石头不会写字，不能给我写卡片。", "年夜饭": "搭配：“写卡片”的施事必须是人，年夜饭是食物，不能这样搭配。", "窗户": "语义：窗户不会写字，不能给我写卡片。"}, "sentence_index": 6, "correct_answer": "干女儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我的干女儿是我的奶奶。", "explanation": "干女儿是认作的晚辈，不能是祖辈；这里应该用〈干奶奶〉或直接说〈奶奶〉。"}, {"text": "我的干女儿是我的丈夫。", "explanation": "这里应该用〈配偶〉。干女儿是认作的晚辈，与婚姻无关，不能指夫妻关系。"}, {"text": "我们俩定了婚，她是我的干女儿。", "explanation": "这里不能用〈干女儿〉指婚约对象。干女儿是认作的晚辈，与婚约无关，应称〈未婚妻〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88221, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他去年认了一只干女儿，现在十岁了。", "corrected_sentence": "他去年认了一个干女儿，现在十岁了。", "error_description": "量词错误：干女儿指人，应用“个”或“位”，不能用“只”（“只”用于动物）。正确说法是“认了一个干女儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88221, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她十岁那年，父母认了一个的干女儿。", "corrected_sentence": "她十岁那年，父母认了一个干女儿。", "error_description": "结构错误：数量短语修饰名词时不加“的”。“一个的干女儿”应改为“一个干女儿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
