INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88222, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "认作女儿而无血缘关系的女子。", "primary_collocate": null, "pronunciation": "gān nǚ ér", "ipa": "kan˥ ny˨˩ əɻ˧˥", "syllable_count": 3, "sentences": [{"text": "他认了邻居的孩子做干女儿。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干女儿和他没有血缘关系。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "张先生有两个女儿和一个干女儿。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她是我妈妈的干女儿。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他们正式认她当干女儿。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "干女儿结婚那天，他特别高兴。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老板把她当成自己的干女儿。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她从小就是奶奶的干女儿。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位干女儿常常回来看他们。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对干女儿像对亲女儿一样好。", "target_word": "干女儿", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一个干女儿", "label": "量词（个）"}, {"form": "一位干女儿", "label": "量词（位）"}, {"form": "乾女兒", "label": "繁体"}], "register": "口语", "sense_fingerprint": "认作女儿、没有血缘关系的女子", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '41ca57c2-ac8c-47f7-b168-f786db53d8e5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88222, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "干女儿", "is_correct": true, "explanation": "正确：干女儿指认作女儿、没有血缘的女子，与“认了邻居的孩子”相合。"}, {"text": "亲生女儿", "is_correct": false, "explanation": "语义：认来的孩子不是亲生的，“做亲生女儿”与“认”的含义矛盾。"}, {"text": "女婿", "is_correct": false, "explanation": "语义：女婿指女儿的丈夫，是成年人的身份，邻居的孩子不能做女婿。"}, {"text": "女公子", "is_correct": false, "explanation": "语域：女公子是书面敬称，指别人的女儿，这句话的口语语境中不用。"}], "explanations": {"干女儿": "正确：干女儿指认作女儿、没有血缘的女子，与“认了邻居的孩子”相合。", "亲生女儿": "语义：认来的孩子不是亲生的，“做亲生女儿”与“认”的含义矛盾。", "女婿": "语义：女婿指女儿的丈夫，是成年人的身份，邻居的孩子不能做女婿。", "女公子": "语域：女公子是书面敬称，指别人的女儿，这句话的口语语境中不用。"}, "sentence_index": 0, "correct_answer": "干女儿"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他的干女儿比他大三十岁，是他的长辈。", "explanation": "干女儿是认作的晚辈，不能是长辈；这里应该用〈干妈〉。"}, {"text": "父母认了一个干女儿，是个小伙子。", "explanation": "这里应该用〈干儿子〉。干女儿指女性，认下的是小伙子时要说〈干儿子〉。"}, {"text": "她和爸爸妈妈有血缘，是他们的干女儿。", "explanation": "这里应该用〈亲生女儿〉。干女儿指没有血缘关系的人，与“有血缘”矛盾。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88222, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "干女儿", "is_correct": true, "explanation": "正确：干女儿是认作的女儿，老板可以把她当成自己的女儿，与句意相合。"}, {"text": "手机", "is_correct": false, "explanation": "语义：人不能被当成手机，“她”与“手机”的指代不合。"}, {"text": "令爱", "is_correct": false, "explanation": "语域：令爱是书面敬称，指别人的女儿，不能用于“自己的”。"}, {"text": "窗户", "is_correct": false, "explanation": "语义：人不能被当成窗户，“她”与“窗户”的指代不合。"}], "explanations": {"干女儿": "正确：干女儿是认作的女儿，老板可以把她当成自己的女儿，与句意相合。", "手机": "语义：人不能被当成手机，“她”与“手机”的指代不合。", "令爱": "语域：令爱是书面敬称，指别人的女儿，不能用于“自己的”。", "窗户": "语义：人不能被当成窗户，“她”与“窗户”的指代不合。"}, "sentence_index": 6, "correct_answer": "干女儿"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的干女儿是他的爷爷。", "explanation": "干女儿是认作的女性晚辈，不能是男性祖辈；这里应该用〈爷爷〉。"}, {"text": "他的干女儿现在是他的丈夫了。", "explanation": "这里应该用〈配偶〉。干女儿是认作的晚辈，与婚姻无关，不能指夫妻关系。"}, {"text": "我们刚订了婚，她却是我的干女儿。", "explanation": "这里不能用〈干女儿〉指婚约对象。干女儿是认作的晚辈，与婚约无关，应称〈未婚妻〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88222, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我们认作她干女儿。", "corrected_sentence": "我们认她作干女儿。", "error_description": "语序错误：“认”后直接带宾语，再用“作”引出身份，应说“认她作干女儿”，不说“认作她干女儿”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88222, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "我们家去年认了一只干女儿。", "corrected_sentence": "我们家去年认了一个干女儿。", "error_description": "量词错误：干女儿指人，应用“个”，不能用“只”（“只”用于动物）。正确说法是“认了一个干女儿”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'ccc5e7bc-2959-4a75-819f-2881da3639e3') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
