INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88223, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "大师是本领很高、大家都很佩服的人。", "primary_collocate": null, "pronunciation": "dà shī", "ipa": "ta˥˩ ʂʅ˥˥", "syllable_count": 2, "sentences": [{"text": "他是一位有名的功夫大师。", "target_word": "大师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大家都叫他大师。", "target_word": "大师", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这位大师做的茶很好喝。", "target_word": "大师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我想跟着大师学画画。", "target_word": "大师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那位大师住在山上。", "target_word": "大师", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "他练了二十年，成了大师。", "target_word": "大师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大师一出手，大家都不说话了。", "target_word": "大师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "比赛里来了很多大师。", "target_word": "大师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "我在电视上看过那位大师。", "target_word": "大师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大师做的每件事都很认真。", "target_word": "大师", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "个", "label": "量词"}, {"form": "大師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "本领很高、大家佩服的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d850554-45f7-4ce0-b18d-6b02b303fbf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88223, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大师", "is_correct": true, "explanation": "大师 dà shī，本领很高、大家都很佩服的人。"}, {"text": "大使", "is_correct": false, "explanation": "大使 dàshǐ 与 大师 dàshī 第二个音节声调不同（第三声与第一声），意思是驻外代表国家的外交官。"}, {"text": "大事", "is_correct": false, "explanation": "大事 dàshì 与 大师 dàshī 第二个音节声调不同（第四声与第一声），意思是重要的事情。"}, {"text": "打湿", "is_correct": false, "explanation": "打湿 dǎshī 与 大师 dàshī 第一个音节声调不同（第三声与第四声），意思是把东西弄湿。"}, {"text": "大石", "is_correct": false, "explanation": "大石 dàshí 与 大师 dàshī 第二个音节声调不同（第二声与第一声），意思是大块的石头。"}], "explanations": {"大师": "大师 dà shī，本领很高、大家都很佩服的人。", "大使": "大使 dàshǐ 与 大师 dàshī 第二个音节声调不同（第三声与第一声），意思是驻外代表国家的外交官。", "大事": "大事 dàshì 与 大师 dàshī 第二个音节声调不同（第四声与第一声），意思是重要的事情。", "打湿": "打湿 dǎshī 与 大师 dàshī 第一个音节声调不同（第三声与第四声），意思是把东西弄湿。", "大石": "大石 dàshí 与 大师 dàshī 第二个音节声调不同（第二声与第一声），意思是大块的石头。"}, "sentence_index": null, "correct_answer": "大师"}, "level_3": {"options": [{"text": "大师", "is_correct": true, "explanation": "大师：功夫高、有名望的人，符合句中“有名的功夫”的语境。"}, {"text": "游客", "is_correct": false, "explanation": "语义：游客是来旅游观光的人，与“功夫”无关，不能说“有名的功夫游客”。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人与“功夫”无关，不能说“有名的功夫病人”。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“功夫”修饰的应是会武术的人，不能修饰乘客。"}], "explanations": {"大师": "大师：功夫高、有名望的人，符合句中“有名的功夫”的语境。", "游客": "语义：游客是来旅游观光的人，与“功夫”无关，不能说“有名的功夫游客”。", "病人": "语义：病人与“功夫”无关，不能说“有名的功夫病人”。", "乘客": "搭配：“功夫”修饰的应是会武术的人，不能修饰乘客。"}, "sentence_index": 0, "correct_answer": "大师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我的大师每天在教室里哭着要妈妈。", "explanation": "这里应该用〈小朋友〉。大师指本领很高、大家都很佩服的人，不能用来指每天在教室里哭着要妈妈的小朋友。"}, {"text": "我的大师把车停在了马路中间。", "explanation": "这里应该用〈司机〉。大师指本领很高、大家都很佩服的人，不用来指把车停在马路中间的普通司机。"}, {"text": "我的大师每天早上在公司门口值班。", "explanation": "这里应该用〈保安〉。大师指本领很高、大家都很佩服的人，不用来指每天在公司门口值班的保安。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88223, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大师", "is_correct": true, "explanation": "大师 dà shī，本领很高、大家都很佩服的人。"}, {"text": "大势", "is_correct": false, "explanation": "大势 dàshì 与 大师 dàshī 第二个音节声调不同（第四声与第一声），意思是整体的发展趋势。"}, {"text": "大吃", "is_correct": false, "explanation": "大吃 dàchī 与 大师 dàshī 第二个音节声母不同（ch 与 sh），意思是大量地吃。"}, {"text": "大市", "is_correct": false, "explanation": "大市 dàshì 与 大师 dàshī 第二个音节声调不同（第四声与第一声），意思是整个市场的行情。"}], "explanations": {"大师": "大师 dà shī，本领很高、大家都很佩服的人。", "大势": "大势 dàshì 与 大师 dàshī 第二个音节声调不同（第四声与第一声），意思是整体的发展趋势。", "大吃": "大吃 dàchī 与 大师 dàshī 第二个音节声母不同（ch 与 sh），意思是大量地吃。", "大市": "大市 dàshì 与 大师 dàshī 第二个音节声调不同（第四声与第一声），意思是整个市场的行情。"}, "sentence_index": null, "correct_answer": "大师"}, "level_3": {"options": [{"text": "大师", "is_correct": true, "explanation": "大师：本领很高、能让人一出手就令众人折服的人，符合“一出手”的语境。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人不能施展本领令众人折服，“一出手”的语境不合。"}, {"text": "乞丐", "is_correct": false, "explanation": "语义：乞丐不是施展本领令人赞叹的人，与“大家都不说话了”的语境不合。"}, {"text": "清洁工", "is_correct": false, "explanation": "语义：清洁工的工作与“一出手”所指的非凡本领不相符。"}], "explanations": {"大师": "大师：本领很高、能让人一出手就令众人折服的人，符合“一出手”的语境。", "病人": "语义：病人不能施展本领令众人折服，“一出手”的语境不合。", "乞丐": "语义：乞丐不是施展本领令人赞叹的人，与“大家都不说话了”的语境不合。", "清洁工": "语义：清洁工的工作与“一出手”所指的非凡本领不相符。"}, "sentence_index": 6, "correct_answer": "大师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我请的大师每天都来打扫卫生。", "explanation": "这里应该用〈保姆〉。大师指本领很高、大家佩服的人，不用来称呼每天来家里打扫卫生的保姆。"}, {"text": "我的大师每天都在复习功课。", "explanation": "这里应该用〈学生〉。大师指本领很高的人，不用来称呼还在学习的学生。"}, {"text": "这个大师刚学会走路。", "explanation": "这里应该用〈小孩〉。大师指本领高的人，不能用来指刚学会走路的小孩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88223, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "那只大师的字写得非常好。", "corrected_sentence": "那位大师的字写得非常好。", "error_description": "量词错误：“大师”指人，应用量词“位”（那位大师）。“只”多用于动物，这里应改为“位”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88223, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他已经很大师了。", "corrected_sentence": "他已经是大师了。", "error_description": "词类错误：“大师”是名词，不能被“很”修饰，应用“是”作谓语，说“他已经是大师了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
