INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88224, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "在学问或艺术上有很高成就、为人所尊崇的人。", "primary_collocate": null, "pronunciation": "dà shī", "ipa": "ta˥˩ ʂʅ˥˥", "syllable_count": 2, "sentences": [{"text": "他是中国著名的国画大师。", "target_word": "大师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位文学大师写过很多书。", "target_word": "大师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大师的作品放在博物馆里。", "target_word": "大师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "那位音乐大师去世了。", "target_word": "大师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "她从小就想成为艺术大师。", "target_word": "大师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "大师的话让年轻人受益。", "target_word": "大师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "这位大师在大学里教过书。", "target_word": "大师", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多人来听大师的讲座。", "target_word": "大师", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "人们叫他一代大师。", "target_word": "大师", "complexity_tier": "T1", "sentence_source": "generated"}, {"text": "这幅画是一位大师画的。", "target_word": "大师", "complexity_tier": "T2", "sentence_source": "generated"}], "morphological_forms": [{"form": "位", "label": "量词"}, {"form": "国画大师", "label": "复合"}, {"form": "大師", "label": "繁体"}], "register": "中性", "sense_fingerprint": "学问或艺术上成就很高、受人尊崇的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '4d850554-45f7-4ce0-b18d-6b02b303fbf8') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88224, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "大师", "is_correct": true, "explanation": "大师 dà shī，在学问或艺术上成就很高、受人尊崇的人。"}, {"text": "大势", "is_correct": false, "explanation": "大势 dàshì 与 大师 dàshī 第二个音节声调不同（第四声与第一声），意思是事物发展的趋势。"}, {"text": "大使", "is_correct": false, "explanation": "大使 dàshǐ 与 大师 dàshī 第二个音节声调不同（第三声与第一声），意思是驻外代表国家的外交官。"}, {"text": "大石", "is_correct": false, "explanation": "大石 dàshí 与 大师 dàshī 第二个音节声调不同（第二声与第一声），意思是大块的石头。"}, {"text": "打湿", "is_correct": false, "explanation": "打湿 dǎshī 与 大师 dàshī 第一个音节声调不同（第三声与第四声），意思是把东西弄湿。"}], "explanations": {"大师": "大师 dà shī，在学问或艺术上成就很高、受人尊崇的人。", "大势": "大势 dàshì 与 大师 dàshī 第二个音节声调不同（第四声与第一声），意思是事物发展的趋势。", "大使": "大使 dàshǐ 与 大师 dàshī 第二个音节声调不同（第三声与第一声），意思是驻外代表国家的外交官。", "大石": "大石 dàshí 与 大师 dàshī 第二个音节声调不同（第二声与第一声），意思是大块的石头。", "打湿": "打湿 dǎshī 与 大师 dàshī 第一个音节声调不同（第三声与第四声），意思是把东西弄湿。"}, "sentence_index": null, "correct_answer": "大师"}, "level_3": {"options": [{"text": "大师", "is_correct": true, "explanation": "大师：在国画上成就很高、受人尊崇的人，符合“中国著名的国画”的语境。"}, {"text": "新手", "is_correct": false, "explanation": "语义：新手指刚入门的人，与“著名”矛盾，不能是著名的国画新手。"}, {"text": "病人", "is_correct": false, "explanation": "语义：病人与国画的艺术成就无关，不能说“中国著名的国画病人”。"}, {"text": "乘客", "is_correct": false, "explanation": "搭配：“国画”修饰的是画家、艺术家，不能修饰乘客。"}], "explanations": {"大师": "大师：在国画上成就很高、受人尊崇的人，符合“中国著名的国画”的语境。", "新手": "语义：新手指刚入门的人，与“著名”矛盾，不能是著名的国画新手。", "病人": "语义：病人与国画的艺术成就无关，不能说“中国著名的国画病人”。", "乘客": "搭配：“国画”修饰的是画家、艺术家，不能修饰乘客。"}, "sentence_index": 0, "correct_answer": "大师"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这位大师刚入门，还在练基本功。", "explanation": "这里应该用〈学徒〉。大师指在学问或艺术上成就很高、为人尊崇的人，不能用来指刚入门、还在练基本功的学徒。"}, {"text": "我的大师上周才第一次拿起画笔，画得很乱。", "explanation": "这里应该用〈新手〉。大师指在艺术上成就很高的人，不能用来指第一次拿起画笔、画得很乱的新手。"}, {"text": "这位大师每天晚上哭着要喝奶。", "explanation": "这里应该用〈婴儿〉。大师指在学问或艺术上有很高成就的人，不能用来指每天晚上哭着要喝奶的婴儿。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88224, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "大师", "is_correct": true, "explanation": "大师 dà shī，在学问或艺术上成就很高、受人尊崇的人。"}, {"text": "大吃", "is_correct": false, "explanation": "大吃 dàchī 与 大师 dàshī 第二个音节声母不同（ch 与 sh），意思是大量地吃。"}, {"text": "大输", "is_correct": false, "explanation": "大输 dàshū 与 大师 dàshī 第二个音节韵母不同（ū 与 ī），意思是输得很惨。"}, {"text": "大书", "is_correct": false, "explanation": "大书 dàshū 与 大师 dàshī 第二个音节韵母不同（ū 与 ī），意思是用大字书写。"}], "explanations": {"大师": "大师 dà shī，在学问或艺术上成就很高、受人尊崇的人。", "大吃": "大吃 dàchī 与 大师 dàshī 第二个音节声母不同（ch 与 sh），意思是大量地吃。", "大输": "大输 dàshū 与 大师 dàshī 第二个音节韵母不同（ū 与 ī），意思是输得很惨。", "大书": "大书 dàshū 与 大师 dàshī 第二个音节韵母不同（ū 与 ī），意思是用大字书写。"}, "sentence_index": null, "correct_answer": "大师"}, "level_3": {"options": [{"text": "大师", "is_correct": true, "explanation": "大师：在学问或艺术上成就很高、能在大学里教书的人，符合句意。"}, {"text": "婴儿", "is_correct": false, "explanation": "语义：婴儿刚出生不久，不可能在大学里教过书。"}, {"text": "小狗", "is_correct": false, "explanation": "语义：小狗是动物，不能教书，也不能用量词“位”。"}, {"text": "小孩", "is_correct": false, "explanation": "语义：小孩不可能在大学里教过书，与句意矛盾。"}], "explanations": {"大师": "大师：在学问或艺术上成就很高、能在大学里教书的人，符合句意。", "婴儿": "语义：婴儿刚出生不久，不可能在大学里教过书。", "小狗": "语义：小狗是动物，不能教书，也不能用量词“位”。", "小孩": "语义：小孩不可能在大学里教过书，与句意矛盾。"}, "sentence_index": 6, "correct_answer": "大师"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位大师每天在超市里收银。", "explanation": "这里应该用〈收银员〉。大师指在学问或艺术上成就很高的人，不能用来指在超市里收银的人。"}, {"text": "我的大师每天晚上都要陪我玩捉迷藏。", "explanation": "这里应该用〈玩伴〉。大师指在学问或艺术上成就很高的人，不能用来指陪我玩捉迷藏的小伙伴。"}, {"text": "这个大师刚学会走路。", "explanation": "这里应该用〈小孩〉。大师指学问或艺术成就很高的人，不能用来指刚学会走路的小孩。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88224, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位画家已经很大师了。", "corrected_sentence": "这位画家已经是大师了。", "error_description": "词类错误：“大师”是名词，不能被“很”修饰，应用“是”作谓语，说“已经是大师了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88224, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这是一位受人尊敬大师。", "corrected_sentence": "这是一位受人尊敬的大师。", "error_description": "结构助词错误：“受人尊敬”修饰“大师”时要用“的”，应说“受人尊敬的大师”，不能省略“的”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'f5186a37-f9e3-4c52-8db2-317d96357b07') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
