INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88226, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "利用核反应释放的巨大能量起杀伤破坏作用的武器。", "primary_collocate": null, "pronunciation": "hé wǔ qì", "ipa": "xɤ˧˥ u˨˩ tɕʰi˥˩", "syllable_count": 3, "sentences": [{"text": "核武器利用核反应放出的巨大能量。", "target_word": "核武器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "核武器能产生强大的爆炸和高温。", "target_word": "核武器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "科学家研究核反应，也研究核武器。", "target_word": "核武器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "核武器的杀伤和破坏作用非常大。", "target_word": "核武器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "联合国希望各国减少核武器的数量。", "target_word": "核武器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "专家说，核武器会长时间影响环境。", "target_word": "核武器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这座城市曾经遭受过核武器的攻击。", "target_word": "核武器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "各国签了协议，不再试验核武器。", "target_word": "核武器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "核武器爆炸时会放出很强的光和热。", "target_word": "核武器", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "保存核武器需要特别安全的地方。", "target_word": "核武器", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "种", "label": "量词"}, {"form": "核武器库", "label": "复合"}, {"form": "核武器试验", "label": "复合"}], "register": "书面", "sense_fingerprint": "核武器：靠核反应放出巨大能量来杀伤和破坏的武器", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '648adbef-73b9-41d7-be59-ee2aa0548fdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88226, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "核武器", "is_correct": true, "explanation": "核武器靠核反应放出巨大能量，与句中“利用核反应”的语境相符。"}, {"text": "歌曲", "is_correct": false, "explanation": "语义：歌曲不能利用核反应放出能量，与句中的科学原理冲突。"}, {"text": "课桌", "is_correct": false, "explanation": "语义：课桌不具有放出能量的功能，与句意冲突。"}, {"text": "鸡蛋", "is_correct": false, "explanation": "搭配：“利用核反应”不能与“鸡蛋”搭配，鸡蛋不会放出核能。"}], "explanations": {"核武器": "核武器靠核反应放出巨大能量，与句中“利用核反应”的语境相符。", "歌曲": "语义：歌曲不能利用核反应放出能量，与句中的科学原理冲突。", "课桌": "语义：课桌不具有放出能量的功能，与句意冲突。", "鸡蛋": "搭配：“利用核反应”不能与“鸡蛋”搭配，鸡蛋不会放出核能。"}, "sentence_index": 0, "correct_answer": "核武器"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "核武器是一种清洁能源。", "explanation": "这里应该用〈核能〉。核武器用于杀伤和破坏，不是清洁能源；说清洁能源要用〈核能〉。"}, {"text": "这个国家新造了一只核武器。", "explanation": "这里量词用错了。“只”多用于小动物、船只等，不用于核武器；核武器可说“一种”或“一枚”核武器。"}, {"text": "我每天早上喝核武器。", "explanation": "这里应该用〈果汁〉。核武器不能喝，早上喝的饮料要说〈果汁〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88226, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "核武器", "is_correct": true, "explanation": "核武器是造成攻击和破坏的武器，与“遭受过……的攻击”的语境相符。"}, {"text": "蛋糕", "is_correct": false, "explanation": "语义：蛋糕不会发动攻击，不能说“遭受过蛋糕的攻击”。"}, {"text": "诗歌", "is_correct": false, "explanation": "语义：诗歌不能发动攻击，与“攻击”的语义冲突。"}, {"text": "礼物", "is_correct": false, "explanation": "搭配：“遭受……的攻击”不能与“礼物”搭配，礼物不会构成攻击。"}], "explanations": {"核武器": "核武器是造成攻击和破坏的武器，与“遭受过……的攻击”的语境相符。", "蛋糕": "语义：蛋糕不会发动攻击，不能说“遭受过蛋糕的攻击”。", "诗歌": "语义：诗歌不能发动攻击，与“攻击”的语义冲突。", "礼物": "搭配：“遭受……的攻击”不能与“礼物”搭配，礼物不会构成攻击。"}, "sentence_index": 6, "correct_answer": "核武器"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我每天用核武器刷牙。", "explanation": "这里应该用〈牙刷〉。核武器不能用来刷牙，刷牙要用〈牙刷〉。"}, {"text": "我午饭吃核武器。", "explanation": "这里应该用〈米饭〉。核武器不能吃，午饭吃的主食要说〈米饭〉。"}, {"text": "他下午用核武器打篮球。", "explanation": "这里应该用〈篮球〉。核武器是用来杀伤破坏的武器，不是运动器材，打球要用〈篮球〉。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88226, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个国家拥有一只核武器。", "corrected_sentence": "这个国家拥有一枚核武器。", "error_description": "错误在量词“只”。“只”多用于小动物等，不用于核武器；数一件核武器常用“枚”。错误形式是“拥有一只核武器”，正确形式是“拥有一枚核武器”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88226, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "专家们正在评估核武器们的危害。", "corrected_sentence": "专家们正在评估核武器的危害。", "error_description": "“核武器”是事物名词，不能加“们”表示复数，应直接说“核武器”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
