INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88227, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "事主是遇到事情的那个人，比如东西被偷的人。", "primary_collocate": null, "pronunciation": "shì zhǔ", "ipa": "ʂɻ̩˥˩ ʈʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "警察问事主丢了什么东西。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事主发现钱包不见了，马上报警。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷偷了东西，事主很生气。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察把东西还给了事主。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事主说，那辆自行车是昨晚丢的。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事主回到家，看见门开着。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位事主在门口等警察来。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察请事主看看丢了哪些东西。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事主很着急，因为包里有身份证。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事主告诉警察，小偷是从窗户进来的。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位事主", "label": "量词"}, {"form": "一个事主", "label": "量词"}], "register": "书面", "sense_fingerprint": "遇到事情的人，如东西被偷的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d977b55-e838-4148-b0e4-160dae9a063e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88227, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事主", "is_correct": true, "explanation": "正确：句中问的是丢了东西的人，即遇到事情的当事人，只有「事主」符合。"}, {"text": "钱包", "is_correct": false, "explanation": "配价：「问」的对象须是人，钱包是物，不能被警察询问。"}, {"text": "桌子", "is_correct": false, "explanation": "配价：「问」的对象须是人，桌子不能被警察询问。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：「问」需要有生命的对象，窗户不能被警察询问。"}], "explanations": {"事主": "正确：句中问的是丢了东西的人，即遇到事情的当事人，只有「事主」符合。", "钱包": "配价：「问」的对象须是人，钱包是物，不能被警察询问。", "桌子": "配价：「问」的对象须是人，桌子不能被警察询问。", "窗户": "配价：「问」需要有生命的对象，窗户不能被警察询问。"}, "sentence_index": 0, "correct_answer": "事主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是这次晚会的事主，负责安排节目。", "explanation": "这里应该用〈主办方〉。事主指遇到事情的人，不指组织活动的人；安排节目的应说主办方。"}, {"text": "这套房子的事主是我，每个月都收房租。", "explanation": "这里应该用〈房东〉。事主指遇到事情的人，出租房子只是经营，没有事件时不能叫事主。"}, {"text": "小偷是这次偷窃案的事主。", "explanation": "这里应该用〈嫌疑人〉。事主是遇到事件而受害或失窃的一方；作案的人不能叫事主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88227, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事主", "is_correct": true, "explanation": "正确：「这位」指人，且句中是在门口等警察的人，即遇到事情的当事人，只有「事主」符合。"}, {"text": "证物", "is_correct": false, "explanation": "搭配：「这位」只用于人，「证物」是物品，不能说「这位证物」。"}, {"text": "猫", "is_correct": false, "explanation": "量词：「这位」只用于人，猫应说「这只」。"}, {"text": "房屋", "is_correct": false, "explanation": "语义：房屋是建筑，不能站在门口等警察来。"}], "explanations": {"事主": "正确：「这位」指人，且句中是在门口等警察的人，即遇到事情的当事人，只有「事主」符合。", "证物": "搭配：「这位」只用于人，「证物」是物品，不能说「这位证物」。", "猫": "量词：「这位」只用于人，猫应说「这只」。", "房屋": "语义：房屋是建筑，不能站在门口等警察来。"}, "sentence_index": 6, "correct_answer": "事主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这栋楼的事主都交了物业费。", "explanation": "这里应该用〈业主〉。事主指遇到事件的人；交物业费的是房产的主人，没有事件时不能叫事主。"}, {"text": "这笔保险金的事主是他的妻子。", "explanation": "这里应该用〈受益人〉。事主指遇到事件（如被偷、受害）的人；领取保险金的是受益人。"}, {"text": "小王是这家公司的事主。", "explanation": "这里应该用〈经理〉。事主指事件中的当事人，不表示职务。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88227, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察向一只事主了解钱包是什么时候丢的。", "corrected_sentence": "警察向一位事主了解钱包是什么时候丢的。", "error_description": "错误：「一只」。「事主」指人，量词应用「位」或「个」，「只」多用于动物。正确应说「一位事主」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88227, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "警察把钱包给还了事主。", "corrected_sentence": "警察把钱包还给了事主。", "error_description": "错误：「给还」。「还给」是固定的动词搭配，顺序不能颠倒；应说「还给了事主」。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
