INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88228, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "事件中的当事人，尤其指失窃或受害的一方。", "primary_collocate": null, "pronunciation": "shì zhǔ", "ipa": "ʂɻ̩˥˩ ʈʂu˨˩˦", "syllable_count": 2, "sentences": [{"text": "这起案子的事主是一位老人。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事主向警察说明了当时的情况。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察正在联系那起偷车案的事主。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事主受了伤，已经去医院了。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "记者想采访这起事件的事主。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事主不愿意说出自己的名字。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小偷抓到后，事主拿回了自己的手机。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这家店遭了小偷，事主是店老板。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "事主哭着说，所有的钱都没有了。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "警察一边安慰事主，一边记录情况。", "target_word": "事主", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位事主", "label": "量词"}, {"form": "一个事主", "label": "量词"}], "register": "书面", "sense_fingerprint": "事件的当事人，尤指失窃或受害的一方", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '5d977b55-e838-4148-b0e4-160dae9a063e') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88228, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "事主", "is_correct": true, "explanation": "正确：「一位老人」指人，句中的角色是这起案子中遭受损失的一方，只有「事主」符合。"}, {"text": "证据", "is_correct": false, "explanation": "搭配：「一位」只用于人，「证据」是物，不能说「一位证据」。"}, {"text": "凶器", "is_correct": false, "explanation": "语义：凶器是作案的工具，不可能是一位老人。"}, {"text": "监控", "is_correct": false, "explanation": "语义：监控是设备，不会是一位老人。"}], "explanations": {"事主": "正确：「一位老人」指人，句中的角色是这起案子中遭受损失的一方，只有「事主」符合。", "证据": "搭配：「一位」只用于人，「证据」是物，不能说「一位证据」。", "凶器": "语义：凶器是作案的工具，不可能是一位老人。", "监控": "语义：监控是设备，不会是一位老人。"}, "sentence_index": 0, "correct_answer": "事主"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这把伞的事主是我，我正借给朋友用。", "explanation": "这里应该用〈主人〉。事主指事件中失窃或受害的人；出借东西、没有事件时，不能叫事主。"}, {"text": "这场比赛的事主是两支球队。", "explanation": "这里应该用〈参赛者〉。事主指事件中失窃或受害的一方；比赛的参加方要说参赛者。"}, {"text": "他是这次活动的事主，负责发放奖品。", "explanation": "这里应该用〈组织者〉。事主指事件中受害或遭受损失的一方，不指组织活动的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88228, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "事主", "is_correct": true, "explanation": "正确：句中「拿回了自己的手机」的人是丢了东西的一方，即遇到事情的当事人，只有「事主」符合。"}, {"text": "手机", "is_correct": false, "explanation": "语义：手机是物品，不能「拿回了自己的手机」，句中的主语应是人。"}, {"text": "钱包", "is_correct": false, "explanation": "语义：钱包是物品，不能拿回「自己的手机」，主语应是人。"}, {"text": "窗户", "is_correct": false, "explanation": "配价：「拿回」需要能拿东西的人作主语，窗户不能。"}], "explanations": {"事主": "正确：句中「拿回了自己的手机」的人是丢了东西的一方，即遇到事情的当事人，只有「事主」符合。", "手机": "语义：手机是物品，不能「拿回了自己的手机」，句中的主语应是人。", "钱包": "语义：钱包是物品，不能拿回「自己的手机」，主语应是人。", "窗户": "配价：「拿回」需要能拿东西的人作主语，窗户不能。"}, "sentence_index": 6, "correct_answer": "事主"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "店员一边招待事主，一边推荐新款。", "explanation": "这里应该用〈顾客〉。事主指事件中失窃或受害的人；来店里选购的人要说顾客，与事件无关。"}, {"text": "歌手一边感谢事主，一边签名。", "explanation": "这里应该用〈粉丝〉。事主指遇到事件的人；来找歌手签名的是粉丝，与事件无关。"}, {"text": "小区的事主每个月都要交物业费。", "explanation": "这里应该用〈业主〉。事主指事件中的当事人，不指房屋的主人；每月交物业费的是业主。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88228, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "警察找到了一只事主，他很着急。", "corrected_sentence": "警察找到了一位事主，他很着急。", "error_description": "错误：「一只」。「事主」指人，量词应用「位」或「个」，「只」多用于动物。正确应说「一位事主」。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88228, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "事主把丢了的手机找回了来。", "corrected_sentence": "事主把丢了的手机找回来了。", "error_description": "错误：「找回了来」。趋向补语「来」应紧跟动词，应说「找回来了」，「了」放在句末。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a169f408-7f3b-4f23-b06f-b4e4a7f7c625') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
