INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88229, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "用在形容词后面，表示程度非常深。", "primary_collocate": null, "pronunciation": "jí le", "ipa": "tɕi˧˥ lə", "syllable_count": 2, "sentences": [{"text": "今天的天气热极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个电影有意思极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "刚跑完步，我渴极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这条路晚上安静极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的房间干净极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "第一次坐飞机，弟弟兴奋极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这道题简单极了，我一分钟就做完了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "外面冷极了，你多穿点儿衣服。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你做的饺子香极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "山上的风景美极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "放在形容词后面，表示非常非常", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '648adbef-73b9-41d7-be59-ee2aa0548fdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88229, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极了", "is_correct": true, "explanation": "极了 jí le，表示程度很深，与听到的读音一致。"}, {"text": "挤了", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤。"}, {"text": "寄了", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是寄出了。"}, {"text": "极乐", "is_correct": false, "explanation": "lè（第四声）与 le（轻声）声调不同，意思是极乐，指极其快乐的境界。"}], "explanations": {"极了": "极了 jí le，表示程度很深，与听到的读音一致。", "挤了": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤。", "寄了": "jì（第四声）与 jí（第二声）声调不同，意思是寄出了。", "极乐": "lè（第四声）与 le（轻声）声调不同，意思是极乐，指极其快乐的境界。"}, "sentence_index": null, "correct_answer": "极了"}, "level_3": {"options": [{"text": "极了", "is_correct": true, "explanation": "极了放在形容词后面，表示非常非常，符合“热”的句意。"}, {"text": "挺", "is_correct": false, "explanation": "配价：“挺”不能放在形容词之后作补语，“热挺”不成立。"}, {"text": "特别", "is_correct": false, "explanation": "搭配：“特别”一般放在形容词前面，不能放在句末表示程度。"}, {"text": "十分", "is_correct": false, "explanation": "语义：“十分”表示程度，但放在句末位置不对，与句意不符。"}], "explanations": {"极了": "极了放在形容词后面，表示非常非常，符合“热”的句意。", "挺": "配价：“挺”不能放在形容词之后作补语，“热挺”不成立。", "特别": "搭配：“特别”一般放在形容词前面，不能放在句末表示程度。", "十分": "语义：“十分”表示程度，但放在句末位置不对，与句意不符。"}, "sentence_index": 0, "correct_answer": "极了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这条路稍微宽极了。", "explanation": "这里不能用〈极了〉。“极了”表示程度很深，句子要表达的是程度不高，两者意思相反。"}, {"text": "这个房间不太干净极了。", "explanation": "这里不能用〈极了〉。“极了”表示程度很深，与句子要表达的程度不高相矛盾。"}, {"text": "这次考试的题目略为简单极了。", "explanation": "这里不能用〈极了〉。“极了”表示程度很深，句子要表达的是程度不高，两者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88229, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "极了", "is_correct": true, "explanation": "极了 jí le，表示程度很深，与听到的读音一致。"}, {"text": "积了", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是积累了。"}, {"text": "吉利", "is_correct": false, "explanation": "lì 与 le 韵母不同，jí 相同，意思是吉利。"}, {"text": "记了", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是记下了。"}], "explanations": {"极了": "极了 jí le，表示程度很深，与听到的读音一致。", "积了": "jī（第一声）与 jí（第二声）声调不同，意思是积累了。", "吉利": "lì 与 le 韵母不同，jí 相同，意思是吉利。", "记了": "jì（第四声）与 jí（第二声）声调不同，意思是记下了。"}, "sentence_index": null, "correct_answer": "极了"}, "level_3": {"options": [{"text": "极了", "is_correct": true, "explanation": "极了放在形容词后面，表示非常非常，符合“简单”的句意。"}, {"text": "很", "is_correct": false, "explanation": "配价：“很”不能放在形容词之后作补语，句中应说“简单极了”。"}, {"text": "太", "is_correct": false, "explanation": "语义：“太”表示过分，“简单太”不成立，与句意不符。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”要修饰形容词，不能放在形容词后面。"}], "explanations": {"极了": "极了放在形容词后面，表示非常非常，符合“简单”的句意。", "很": "配价：“很”不能放在形容词之后作补语，句中应说“简单极了”。", "太": "语义：“太”表示过分，“简单太”不成立，与句意不符。", "非常": "搭配：“非常”要修饰形容词，不能放在形容词后面。"}, "sentence_index": 6, "correct_answer": "极了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这个房间有点干净极了。", "explanation": "这里不能用〈极了〉。“极了”表示程度很深，句子要说的是程度不高，两者意思相反，应去掉〈极了〉。"}, {"text": "这本书并不有趣极了。", "explanation": "这里不能用〈极了〉。“极了”表示程度很深，句子要表达的是程度不高，两者意思相反。"}, {"text": "我一点也不渴极了。", "explanation": "这里不能用〈极了〉。“极了”表示程度很深，句子要说的是完全没有这种状态，两者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88229, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这双鞋贵极了了。", "corrected_sentence": "这双鞋贵极了。", "error_description": "错误在“了”。“极了”中的“了”只用一次，不能重复。错误形式是“贵极了了”，正确形式是“贵极了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88229, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他的文章写得很好极了。", "corrected_sentence": "他的文章写得好极了。", "error_description": "错误在“很”。“好极了”已表示程度很深，前面不能再加程度副词“很”，应去掉“很”，说“写得好极了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
