INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88230, 1, 'prompt1_core', '{"pos": "副词", "semantic_class": "function", "definition": "用在形容词或心理动词后，表示程度很深。", "primary_collocate": null, "pronunciation": "jí le", "ipa": "tɕi˧˥ lə", "syllable_count": 2, "sentences": [{"text": "这家饭店的菜好吃极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听到这个消息，我高兴极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他昨天加班到很晚，今天累极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这只小狗，妹妹喜欢极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他一个人住在国外，想家想极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "考试没通过，他难过极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件衣服的颜色漂亮极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "看到孩子们的笑脸，老师感动极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "听说明天要考试，同学们紧张极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这种天气又湿又热，我讨厌极了。", "target_word": "极了", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "程度补语：形容词或心理动词+极了，表示程度很深", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '648adbef-73b9-41d7-be59-ee2aa0548fdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88230, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "极了", "is_correct": true, "explanation": "极了 jí le，表示程度很深，与听到的读音一致。"}, {"text": "挤了", "is_correct": false, "explanation": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤。"}, {"text": "寄了", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是寄出了。"}, {"text": "极乐", "is_correct": false, "explanation": "lè（第四声）与 le（轻声）声调不同，意思是极乐，指极其快乐的境界。"}], "explanations": {"极了": "极了 jí le，表示程度很深，与听到的读音一致。", "挤了": "jǐ（第三声）与 jí（第二声）声调不同，意思是挤。", "寄了": "jì（第四声）与 jí（第二声）声调不同，意思是寄出了。", "极乐": "lè（第四声）与 le（轻声）声调不同，意思是极乐，指极其快乐的境界。"}, "sentence_index": null, "correct_answer": "极了"}, "level_3": {"options": [{"text": "极了", "is_correct": true, "explanation": "极了用在形容词后作补语，表示程度很深，符合“好吃”的句意。"}, {"text": "很", "is_correct": false, "explanation": "配价：“很”是副词，不能直接放在形容词之后作补语。"}, {"text": "太", "is_correct": false, "explanation": "语义：“太”表示过分，且不能放在形容词之后，与句意不符。"}, {"text": "非常", "is_correct": false, "explanation": "搭配：“非常”要放在形容词前面表示程度，不能放在句末。"}], "explanations": {"极了": "极了用在形容词后作补语，表示程度很深，符合“好吃”的句意。", "很": "配价：“很”是副词，不能直接放在形容词之后作补语。", "太": "语义：“太”表示过分，且不能放在形容词之后，与句意不符。", "非常": "搭配：“非常”要放在形容词前面表示程度，不能放在句末。"}, "sentence_index": 0, "correct_answer": "极了"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这道菜稍微咸极了。", "explanation": "这里不能用〈极了〉。“极了”表示程度很深，句子要表达的是程度不高，两者意思相反。"}, {"text": "这个饭店的菜不太好吃极了。", "explanation": "这里不能用〈极了〉。“极了”表示程度很深，与句子要表达的程度不高相矛盾。"}, {"text": "这场比赛的结果略微精彩极了。", "explanation": "这里不能用〈极了〉。“极了”表示程度很深，句子要表达的是程度不高，两者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88230, 1, 'prompt2_exercises_B', '{"level_1": {"options": [{"text": "极了", "is_correct": true, "explanation": "极了 jí le，表示程度很深，与听到的读音一致。"}, {"text": "积了", "is_correct": false, "explanation": "jī（第一声）与 jí（第二声）声调不同，意思是积累了。"}, {"text": "吉利", "is_correct": false, "explanation": "lì 与 le 韵母不同，jí 相同，意思是吉利。"}, {"text": "记了", "is_correct": false, "explanation": "jì（第四声）与 jí（第二声）声调不同，意思是记下了。"}], "explanations": {"极了": "极了 jí le，表示程度很深，与听到的读音一致。", "积了": "jī（第一声）与 jí（第二声）声调不同，意思是积累了。", "吉利": "lì 与 le 韵母不同，jí 相同，意思是吉利。", "记了": "jì（第四声）与 jí（第二声）声调不同，意思是记下了。"}, "sentence_index": null, "correct_answer": "极了"}, "level_3": {"options": [{"text": "极了", "is_correct": true, "explanation": "极了用在形容词后作补语，表示程度很深，符合“漂亮”的句意。"}, {"text": "十分", "is_correct": false, "explanation": "配价：“十分”是修饰形容词的副词，不能放在形容词之后作补语。"}, {"text": "特别", "is_correct": false, "explanation": "搭配：“特别”一般放在形容词前面，不能放在句末表示程度。"}, {"text": "挺", "is_correct": false, "explanation": "配价：“挺”不能放在形容词之后作补语，“漂亮挺”不成立。"}], "explanations": {"极了": "极了用在形容词后作补语，表示程度很深，符合“漂亮”的句意。", "十分": "配价：“十分”是修饰形容词的副词，不能放在形容词之后作补语。", "特别": "搭配：“特别”一般放在形容词前面，不能放在句末表示程度。", "挺": "配价：“挺”不能放在形容词之后作补语，“漂亮挺”不成立。"}, "sentence_index": 6, "correct_answer": "极了"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这件衣服有点漂亮极了。", "explanation": "这里不能用〈极了〉。“极了”表示程度很深，句子要说的是程度不高，两者意思相反，应去掉〈极了〉。"}, {"text": "这件事并不难极了。", "explanation": "这里不能用〈极了〉。“极了”表示程度很深，句子要表达的是程度不高，两者意思相反。"}, {"text": "我一点也不累极了。", "explanation": "这里不能用〈极了〉。“极了”表示程度很深，句子要说的是完全没有这种状态，两者意思相反。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88230, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这个苹果甜极了了。", "corrected_sentence": "这个苹果甜极了。", "error_description": "错误在“了”。“极了”是固定的补语形式，其中的“了”只用一次，不能重复。错误形式是“甜极了了”，正确形式是“甜极了”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88230, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "妈妈做的汤很咸极了。", "corrected_sentence": "妈妈做的汤咸极了。", "error_description": "错误在“很”。“极了”已表示程度很深，前面不能再加程度副词“很”，应去掉“很”，说“咸极了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
