INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88233, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "毛病是东西或人不好的地方。", "primary_collocate": null, "pronunciation": "máo bìng", "ipa": "maʊ˧˥ piŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他有个坏毛病，总是迟到。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爱睡懒觉是我的老毛病。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书很好，没有什么毛病。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他什么都好，就是有点小毛病。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "你这个毛病得改一改。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子写字时歪着头，这个毛病要改。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她爱挑别人的毛病，大家都不喜欢。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "别总找我的毛病，我已经很努力了。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这个计划有几个毛病，需要再想想。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我没发现他的什么毛病，人挺好的。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小毛病", "label": "复合"}, {"form": "老毛病", "label": "复合"}], "register": "口语", "sense_fingerprint": "毛病：人的坏习惯或事物不好的地方，即缺点", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '648adbef-73b9-41d7-be59-ee2aa0548fdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88233, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毛病", "is_correct": true, "explanation": "正确：“坏毛病”指不好的习惯，与“总是迟到”相合。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“坏脾气”说的是性情，与“总是迟到”这一行为不相合。"}, {"text": "饭量", "is_correct": false, "explanation": "搭配：“饭量”指吃饭的份量，不说“坏饭量”，“坏”不能修饰它。"}, {"text": "嗓子", "is_correct": false, "explanation": "搭配：“坏嗓子”指声音不好，不能用来描述总是迟到这种行为习惯，与句意不合。"}], "explanations": {"毛病": "正确：“坏毛病”指不好的习惯，与“总是迟到”相合。", "脾气": "语义：“坏脾气”说的是性情，与“总是迟到”这一行为不相合。", "饭量": "搭配：“饭量”指吃饭的份量，不说“坏饭量”，“坏”不能修饰它。", "嗓子": "搭配：“坏嗓子”指声音不好，不能用来描述总是迟到这种行为习惯，与句意不合。"}, "sentence_index": 0, "correct_answer": "毛病"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我们队的毛病是配合默契，所以很少失误。", "explanation": "这里应该用〈优点〉。〈毛病〉只指缺点，不能用来说配合默契这样的长处。"}, {"text": "他的毛病是守时，从不迟到。", "explanation": "这里应该用〈优点〉。〈毛病〉只指缺点，不能用来说守时这样的好品质。"}, {"text": "他的毛病是擅长画画，常常得奖。", "explanation": "这里应该用〈特长〉。〈毛病〉指不好的地方，不能用来说擅长的事。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88233, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毛病", "is_correct": true, "explanation": "正确：“挑毛病”指找别人的缺点，与“大家都不喜欢”相合。"}, {"text": "功劳", "is_correct": false, "explanation": "语义：“功劳”是别人做出的成绩，挑的应是缺点，“挑功劳”说不通。"}, {"text": "脚步", "is_correct": false, "explanation": "搭配：“挑”不能用于“脚步”，不说“挑脚步”。"}, {"text": "天气", "is_correct": false, "explanation": "搭配：“挑”不能用于“天气”，不说“挑天气”。"}], "explanations": {"毛病": "正确：“挑毛病”指找别人的缺点，与“大家都不喜欢”相合。", "功劳": "语义：“功劳”是别人做出的成绩，挑的应是缺点，“挑功劳”说不通。", "脚步": "搭配：“挑”不能用于“脚步”，不说“挑脚步”。", "天气": "搭配：“挑”不能用于“天气”，不说“挑天气”。"}, "sentence_index": 6, "correct_answer": "毛病"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他的毛病是很幽默，大家都喜欢和他聊天。", "explanation": "这里应该用〈特点〉。〈毛病〉只指缺点，不能用来说优点或好的特征。"}, {"text": "他的毛病是善于沟通。", "explanation": "这里应该用〈长处〉。〈毛病〉指缺点，不能用来说好的方面。"}, {"text": "他的毛病是钓鱼，周末常去河边。", "explanation": "这里应该用〈爱好〉。〈毛病〉指不好的地方，不能用来说兴趣爱好。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88233, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "她有一只坏毛病，老爱打断别人说话。", "corrected_sentence": "她有个坏毛病，老爱打断别人说话。", "error_description": "错误在“一只”。“毛病”的量词是“个”，错误形式是“有一只坏毛病”，正确形式是“有个坏毛病”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88233, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他终于改了掉这个毛病。", "corrected_sentence": "他终于改掉了这个毛病。", "error_description": "错误在“了”的位置。“改掉”是动补结构，“了”不能插在“改”和“掉”之间。错误形式是“改了掉”，正确形式是“改掉了”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
