INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88234, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "机器等的故障；人身体上的小病。", "primary_collocate": null, "pronunciation": "máo bìng", "ipa": "maʊ˧˥ piŋ˥˩", "syllable_count": 2, "sentences": [{"text": "我的电脑出毛病了，打不开。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这辆车又出了毛病，得去修。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "洗衣机有毛病，不能用了。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "手机没什么毛病，只是没电了。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "师傅说空调的毛病不大，很快就修好。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "爷爷的胃有点毛病，要多休息。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他的腰老有毛病，不能搬重东西。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这台电视机一直有毛病，换一台吧。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "医生检查了一下，说我的眼睛没毛病。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "车子出了毛病，我们只好走路回家。", "target_word": "毛病", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "小毛病", "label": "复合"}, {"form": "老毛病", "label": "复合"}], "register": "口语", "sense_fingerprint": "毛病：机器出的故障，或身体上的小病", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '648adbef-73b9-41d7-be59-ee2aa0548fdc') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88234, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "毛病", "is_correct": true, "explanation": "正确：“出毛病”指机器发生故障，与“打不开”相合。"}, {"text": "名", "is_correct": false, "explanation": "语义：电脑不会“出名”，与机器故障的语境不合。"}, {"text": "汗", "is_correct": false, "explanation": "搭配：“出汗”多指人或动物，或墙面等凝出水珠，说电脑出汗与“打不开”的故障语境不合。"}, {"text": "国", "is_correct": false, "explanation": "语义：电脑不能“出国”，与“打不开”的故障语境不合。"}], "explanations": {"毛病": "正确：“出毛病”指机器发生故障，与“打不开”相合。", "名": "语义：电脑不会“出名”，与机器故障的语境不合。", "汗": "搭配：“出汗”多指人或动物，或墙面等凝出水珠，说电脑出汗与“打不开”的故障语境不合。", "国": "语义：电脑不能“出国”，与“打不开”的故障语境不合。"}, "sentence_index": 0, "correct_answer": "毛病"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这件事给我添了毛病，我很累。", "explanation": "这里应该用〈麻烦〉，“添麻烦”是固定搭配；〈毛病〉指机器故障或身体小病、缺点，不指给人带来的麻烦。"}, {"text": "这间屋子的毛病是采光很好，住着很舒服。", "explanation": "这里应该用〈优点〉。〈毛病〉指故障或小病，不能用来说房子的好处。"}, {"text": "他的头上长了很多毛病。", "explanation": "这里应该用〈头发〉。〈毛病〉指机器故障或人的缺点、小病，不指头发。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88234, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "毛病", "is_correct": true, "explanation": "正确：“有毛病”指身体或机器有故障、小病，与“不能搬重东西”相合。"}, {"text": "脾气", "is_correct": false, "explanation": "语义：“脾气”指性情，不指身体部位的状况，与“腰”不合。"}, {"text": "力气", "is_correct": false, "explanation": "语义：“腰有力气”与“不能搬重东西”矛盾。"}, {"text": "颜色", "is_correct": false, "explanation": "搭配：“腰”不说有“颜色”来描述身体状况，搭配不当。"}], "explanations": {"毛病": "正确：“有毛病”指身体或机器有故障、小病，与“不能搬重东西”相合。", "脾气": "语义：“脾气”指性情，不指身体部位的状况，与“腰”不合。", "力气": "语义：“腰有力气”与“不能搬重东西”矛盾。", "颜色": "搭配：“腰”不说有“颜色”来描述身体状况，搭配不当。"}, "sentence_index": 6, "correct_answer": "毛病"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这辆车的毛病是速度很快，大家都喜欢。", "explanation": "这里应该用〈优点〉。〈毛病〉指故障或缺点，不能用来说好的方面。"}, {"text": "这台电视机最大的毛病是画面清晰。", "explanation": "这里应该用〈特点〉。〈毛病〉只指不好的地方，不能用来形容好的特征。"}, {"text": "这台机器的毛病是省电。", "explanation": "这里应该用〈长处〉。〈毛病〉指故障或缺点，不能用来说优点。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88234, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "我的手机出了一只毛病，充不上电。", "corrected_sentence": "我的手机出了毛病，充不上电。", "error_description": "错误在“一只”。“毛病”前不用“只”作量词，错误形式是“出了一只毛病”，正确形式是“出了毛病”或“出了一个毛病”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88234, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "这台机器做了毛病，得找人修。", "corrected_sentence": "这台机器出了毛病，得找人修。", "error_description": "错误在“做”。表示机器发生故障要说“出了毛病”，“做毛病”不通。错误形式是“做了毛病”，正确形式是“出了毛病”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '018a38af-8888-4fb7-aa17-65c339d6d016') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
