INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88235, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "奴隶是被人买来买去、不能自由、只能做活的人。", "primary_collocate": null, "pronunciation": "nú lì", "ipa": "nu˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "以前的奴隶可以像货物一样买卖。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奴隶没有自由，只能整天给主人干活。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "那个奴隶每天都要干很多活，从来不能休息。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "主人花钱买了一个奴隶。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奴隶想回家，可是主人不让他走。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小就是奴隶，不知道自由是什么。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位奴隶生病了，主人还要他去干活。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "很多年前，奴隶的孩子也是奴隶。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他终于不再是奴隶，可以自己决定去哪儿了。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "书里写了一个奴隶想要自由的故事。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "奴隶主", "label": "复合"}, {"form": "奴隶社会", "label": "复合"}, {"form": "奴隸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "被人买卖、没有自由、只能干活的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c528a757-cc74-4946-831f-bf1e90a388f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88235, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奴隶", "is_correct": true, "explanation": "奴隶：被人买卖、没有自由、只能干活的人，与“像货物一样买卖”的语境相合。"}, {"text": "朋友", "is_correct": false, "explanation": "语义：朋友是平等的情谊关系，不能像货物一样被买卖。"}, {"text": "感情", "is_correct": false, "explanation": "搭配：“买卖”不能搭配“感情”，感情不能被当作货物买卖。"}, {"text": "皇帝", "is_correct": false, "explanation": "语义：皇帝是拥有权力的统治者，不会被当作货物买卖。"}], "explanations": {"奴隶": "奴隶：被人买卖、没有自由、只能干活的人，与“像货物一样买卖”的语境相合。", "朋友": "语义：朋友是平等的情谊关系，不能像货物一样被买卖。", "感情": "搭配：“买卖”不能搭配“感情”，感情不能被当作货物买卖。", "皇帝": "语义：皇帝是拥有权力的统治者，不会被当作货物买卖。"}, "sentence_index": 0, "correct_answer": "奴隶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我家买了一个奴隶，每个月给他发工资。", "explanation": "这里应该用〈仆人〉。奴隶没有人身自由，是被买卖的人，不会按月领工资；领工资、替主人做事的人应说仆人。"}, {"text": "他是我家的奴隶，住了三天就走了。", "explanation": "这里应该用〈客人〉。奴隶是被买卖、没有人身自由的人，不能用来指来做客、可以自由离开的人。"}, {"text": "他们是多年的奴隶，一起走过很多路。", "explanation": "这里应该用〈同伴〉。奴隶没有人身自由，不能与人平等地结伴同行；平等相处的伙伴应说同伴。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88235, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奴隶", "is_correct": true, "explanation": "奴隶：没有自由、被主人使唤干活的人，与“主人还要他去干活”相合。"}, {"text": "小狗", "is_correct": false, "explanation": "搭配：“这位”只修饰人，不能说“这位小狗”，应说“这只小狗”。"}, {"text": "花", "is_correct": false, "explanation": "配价：“去干活”要求有能动、能干活的施事，花不能被主人派去干活。"}, {"text": "房子", "is_correct": false, "explanation": "语义：房子不会生病，也不能被主人要求去干活。"}], "explanations": {"奴隶": "奴隶：没有自由、被主人使唤干活的人，与“主人还要他去干活”相合。", "小狗": "搭配：“这位”只修饰人，不能说“这位小狗”，应说“这只小狗”。", "花": "配价：“去干活”要求有能动、能干活的施事，花不能被主人派去干活。", "房子": "语义：房子不会生病，也不能被主人要求去干活。"}, "sentence_index": 6, "correct_answer": "奴隶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "我们公司新来了一个奴隶，每个月都按时领工资。", "explanation": "这里应该用〈员工〉。奴隶没有人身自由，不能按时领工资；领固定工资的雇员应说员工。"}, {"text": "他是我的奴隶，我们一起去图书馆学习。", "explanation": "这里应该用〈同学〉。奴隶是被买卖、被迫劳动的人，不能用来指平等相处、一起学习的同学。"}, {"text": "他是这家公司的奴隶，每年分红很多。", "explanation": "这里应该用〈股东〉。奴隶没有人身自由，不能按股份分红；按股份获得分红的应说股东。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88235, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这条奴隶每天都要在田里干活，没有休息的时间。", "corrected_sentence": "这些奴隶每天都要在田里干活，没有休息的时间。", "error_description": "量词错误：“奴隶”指人，要用“个”或与复数搭配的“这些”，不能用“条”（条多用于蛇、河流、裤子等细长的东西）。应说：这些奴隶。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88235, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他小时候父母把他卖了，他就成了别人奴隶。", "corrected_sentence": "他小时候父母把他卖了，他就成了别人的奴隶。", "error_description": "“的”缺失：名词“奴隶”前用“别人”修饰时要加“的”，应说“别人的奴隶”，不能说“别人奴隶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
