INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88236, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88236, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "被奴隶主占有、没有人身自由、被迫劳动的人。", "primary_collocate": null, "pronunciation": "nú lì", "ipa": "nu˧˥ li˥˩", "syllable_count": 2, "sentences": [{"text": "古代的奴隶属于主人，没有人身自由。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奴隶在田里劳动，一天只能吃一顿饭。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "在奴隶社会里，奴隶要给奴隶主干活。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这些奴隶从早到晚都要在矿山里劳动。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "有的奴隶逃走了，可是主人又把他抓了回来。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "古罗马有很多奴隶，他们没有自己的家。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "奴隶们不愿再受苦，起来反抗主人。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "一个奴隶一辈子都不属于自己。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "历史书上说，奴隶的生活非常苦。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位老奴隶从小就在主人家劳动。", "target_word": "奴隶", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "个", "label": "量词"}, {"form": "名", "label": "量词"}, {"form": "奴隶主", "label": "复合"}, {"form": "奴隶社会", "label": "复合"}, {"form": "奴隸", "label": "繁体"}], "register": "中性", "sense_fingerprint": "奴隶社会中被奴隶主占有、被迫劳动的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c528a757-cc74-4946-831f-bf1e90a388f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88236, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "奴隶", "is_correct": true, "explanation": "奴隶：被奴隶主占有、没有人身自由的人，与“属于主人，没有人身自由”相合。"}, {"text": "公民", "is_correct": false, "explanation": "语义：公民享有人身自由，不会“属于主人”。"}, {"text": "土地", "is_correct": false, "explanation": "搭配：“人身自由”只用于人，不能用来修饰土地。"}, {"text": "学生", "is_correct": false, "explanation": "语义：学生不是被主人占有的人，与“属于主人”不合。"}], "explanations": {"奴隶": "奴隶：被奴隶主占有、没有人身自由的人，与“属于主人，没有人身自由”相合。", "公民": "语义：公民享有人身自由，不会“属于主人”。", "土地": "搭配：“人身自由”只用于人，不能用来修饰土地。", "学生": "语义：学生不是被主人占有的人，与“属于主人”不合。"}, "sentence_index": 0, "correct_answer": "奴隶"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这些奴隶每个月都能领到工资，还可以回家休息。", "explanation": "这里应该用〈雇工〉。奴隶没有人身自由，不能领工资，也不能随意回家休息；能领工资、按时休息的应说雇工。"}, {"text": "这些奴隶自愿来帮忙，不要任何报酬。", "explanation": "这里应该用〈志愿者〉。奴隶是被奴隶主占有、被迫劳动的人，不会自愿无偿来帮忙；自愿无偿帮忙的应说志愿者。"}, {"text": "我和他是多年的奴隶，常常平等地交流。", "explanation": "这里应该用〈朋友〉。奴隶没有人身自由，不能与人平等地交流；关系平等、常常交往的应说朋友。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88236, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "奴隶", "is_correct": true, "explanation": "奴隶：被迫劳动、没有自由的人，会因受苦而起来反抗主人。"}, {"text": "皇帝", "is_correct": false, "explanation": "语义：皇帝是统治者，不会因被奴役而受苦、起来反抗主人。"}, {"text": "神仙", "is_correct": false, "explanation": "语义：神仙不会被主人奴役、受苦，与“不愿再受苦”不合。"}, {"text": "石头", "is_correct": false, "explanation": "配价：“受苦”和“反抗”要求有感受、能行动的主语，石头不能做这些动作。"}], "explanations": {"奴隶": "奴隶：被迫劳动、没有自由的人，会因受苦而起来反抗主人。", "皇帝": "语义：皇帝是统治者，不会因被奴役而受苦、起来反抗主人。", "神仙": "语义：神仙不会被主人奴役、受苦，与“不愿再受苦”不合。", "石头": "配价：“受苦”和“反抗”要求有感受、能行动的主语，石头不能做这些动作。"}, "sentence_index": 6, "correct_answer": "奴隶"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这位老奴隶从小就在地主家干活，年底还能拿到工钱。", "explanation": "这里应该用〈长工〉。奴隶没有人身自由，不能按年领工钱；长期为地主干活并拿工钱的应说长工。"}, {"text": "这位老奴隶从小就在家族公司里长大，后来接管了企业。", "explanation": "这里应该用〈老板〉。奴隶没有人身自由，不能接管企业、做决定；拥有并管理企业的应说老板。"}, {"text": "他是班里的奴隶，每天认真听课。", "explanation": "这里应该用〈学生〉。奴隶是被买卖、被迫劳动的人，不能用来指在学校里自主学习的学生。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88236, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这只奴隶整天在矿山里劳动。", "corrected_sentence": "这些奴隶整天在矿山里劳动。", "error_description": "量词错误：“奴隶”指人，指示词应用“这些”（复数）或“这个”，不能用“这只”。“只”多用于动物，说人要用“这些”，应改为“这些奴隶”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88236, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他曾经当着奴隶，所以很怕别人管他。", "corrected_sentence": "他曾经当过奴隶，所以很怕别人管他。", "error_description": "体标错误：“过”表示曾经有过的经历，应紧跟动词“当”，说“当过奴隶”。“当着奴隶”中的“着”表示动作或状态的持续，与“曾经”的经历义矛盾，应改为“当过奴隶”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88237, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88237, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88237, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "民政是管老百姓生活里各种事情的工作。", "primary_collocate": null, "pronunciation": "mín zhèng", "ipa": "min˧˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "民政就是管老百姓生活的工作。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他想以后从事民政，帮助更多的人。", "target_word": "民政", "complexity_tier": "T3", "furigana": "tā xiǎng yǐhòu cóngshì mínzhèng, bāngzhù gèng duō de rén.", "sentence_source": "generated"}, {"text": "这个村的民政做得很好。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民政部门每年都会给老人发补助。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "搬家后，老人补助的手续也属于民政的工作。", "target_word": "民政", "complexity_tier": "T3", "furigana": "bānjiā hòu, lǎorén bǔzhù de shǒuxù yě shǔyú mínzhèng de gōngzuò.", "sentence_source": "generated"}, {"text": "她在民政工作了十年，认识很多老人。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民政的事情很多，每天都不轻松。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们社区的民政工作特别关心孤独老人。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民政要帮助生活有困难的人。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他爸爸一直做民政，很了解老百姓的难处。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "管老百姓日常生活里各种事情的工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a96547-d1a2-4444-8d6e-1252fc20d0d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88237, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "外交", "is_correct": false, "explanation": "语义：外交管的是国家之间的事务，与“老百姓生活”不相关。"}, {"text": "语文", "is_correct": false, "explanation": "语义：语文是一门学科，不是管老百姓生活的工作。"}, {"text": "民政", "is_correct": true, "explanation": "语义：民政指管理老百姓日常生活中各类事务的工作，与句中的定义相符。"}, {"text": "八卦", "is_correct": false, "explanation": "语域：“八卦”是口语，指闲话，不是正式的工作名称。"}], "explanations": {"外交": "语义：外交管的是国家之间的事务，与“老百姓生活”不相关。", "语文": "语义：语文是一门学科，不是管老百姓生活的工作。", "民政": "语义：民政指管理老百姓日常生活中各类事务的工作，与句中的定义相符。", "八卦": "语域：“八卦”是口语，指闲话，不是正式的工作名称。"}, "sentence_index": 0, "correct_answer": "民政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "政府每年都会为民政办实事。", "explanation": "这里应该用〈民众〉。“为……办实事”的对象是老百姓，要说〈民众〉；民政是管理社会事务的工作，不能作为服务的对象。"}, {"text": "这个社区实行民政选举，大家都很积极。", "explanation": "这里应该用〈民主〉。选举属于民主制度，不能用〈民政〉；民政指管理社会事务的工作。"}, {"text": "我们社区新添了一辆民政。", "explanation": "量词用错。〈辆〉用于车辆，不能修饰民政这样的工作领域；应说“一项民政工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88237, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "休闲", "is_correct": false, "explanation": "语义：“休闲”意味着轻松，与后半句“不轻松”相矛盾。"}, {"text": "童话", "is_correct": false, "explanation": "搭配：“童话”不能说“童话的事情很多”，这种组合不成立。"}, {"text": "民政", "is_correct": true, "explanation": "语义：民政指管理老百姓各种事情的工作，事情多、工作累，与“不轻松”相符。"}, {"text": "宇宙", "is_correct": false, "explanation": "语义：“宇宙”不是可以“每天不轻松”去管理的事务，句子不通。"}], "explanations": {"休闲": "语义：“休闲”意味着轻松，与后半句“不轻松”相矛盾。", "童话": "搭配：“童话”不能说“童话的事情很多”，这种组合不成立。", "民政": "语义：民政指管理老百姓各种事情的工作，事情多、工作累，与“不轻松”相符。", "宇宙": "语义：“宇宙”不是可以“每天不轻松”去管理的事务，句子不通。"}, "sentence_index": 6, "correct_answer": "民政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他爸爸每个月都在交民政，很了解老百姓的难处。", "explanation": "这里应该用〈社保〉。社会保险要按月缴纳，说“交社保”；民政是政府管理社会事务的工作，不能用来缴费。"}, {"text": "他爸爸一直在办理民政案件，很了解老百姓的难处。", "explanation": "这里应该用〈民事〉。民事案件指公民之间的纠纷，由法院审理；民政是政府的社会事务工作，不说“民政案件”。"}, {"text": "他爸爸一直做一本民政，很了解老百姓的难处。", "explanation": "量词用错。〈本〉用于书籍、册子，不能修饰民政这样的工作；应说“一项民政工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88237, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本民政工作很有成效。", "corrected_sentence": "这项民政工作很有成效。", "error_description": "错误形式“这本民政工作”，正确形式“这项民政工作”。“工作”前的量词应用“项”，“本”多用于书籍，不能修饰工作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88237, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他做了一条民政工作，很认真。", "corrected_sentence": "他做了一项民政工作，很认真。", "error_description": "量词“条”用于细长的东西，不能修饰工作；应说“一项民政工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88238, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88238, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88238, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "政府中有关社会救济、婚姻登记、优抚等民众事务的行政工作。", "primary_collocate": null, "pronunciation": "mín zhèng", "ipa": "min˧˥ ʈʂɤŋ˥˩", "syllable_count": 2, "sentences": [{"text": "他在市政府负责民政。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民政包括社会救济和婚姻登记。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民政工作和老百姓的生活关系很大。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她大学毕业后，做了民政方面的工作。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这件事归民政管，不归教育管。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "民政为生活困难的家庭提供帮助。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "县里的民政工作人员每天都很忙。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他对民政很熟悉，什么手续都知道。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "办理婚姻登记是民政的工作。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "新的民政政策让老人得到了更多照顾。", "target_word": "民政", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "正式", "sense_fingerprint": "政府里管社会救济、婚姻登记等民众事务的行政工作", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '80a96547-d1a2-4444-8d6e-1252fc20d0d4') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88238, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "月亮", "is_correct": false, "explanation": "搭配：“负责”后面接的是工作或事务，“负责月亮”不成立。"}, {"text": "闲事", "is_correct": false, "explanation": "语域：“闲事”是口语，常带贬义，与“负责”这种正式职务的语气不合。"}, {"text": "民政", "is_correct": true, "explanation": "语义：民政是政府负责社会救济、婚姻登记等民众事务的行政工作，符合“市政府负责”的语境。"}, {"text": "黑板", "is_correct": false, "explanation": "搭配：“负责”后面接的是工作或事务，“负责黑板”不成立。"}], "explanations": {"月亮": "搭配：“负责”后面接的是工作或事务，“负责月亮”不成立。", "闲事": "语域：“闲事”是口语，常带贬义，与“负责”这种正式职务的语气不合。", "民政": "语义：民政是政府负责社会救济、婚姻登记等民众事务的行政工作，符合“市政府负责”的语境。", "黑板": "搭配：“负责”后面接的是工作或事务，“负责黑板”不成立。"}, "sentence_index": 0, "correct_answer": "民政"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这起纠纷属于民政，需要法院来判决。", "explanation": "这里应该用〈民事〉。民事指公民、法人之间的财产和人身关系纠纷，由法院判决；民政是政府处理社会救济、婚姻登记等事务的工作，不能用来指纠纷的类别。"}, {"text": "公司为员工提供的民政待遇很好，大家都很满意。", "explanation": "这里应该用〈福利〉。企业给员工提供的待遇叫“福利”，民政是政府管理社会事务的工作，不能用来指企业的待遇。"}, {"text": "我们社区新设了一座民政。", "explanation": "量词用错。〈座〉用于山、桥、楼等大型固定建筑，不能修饰民政这样的工作领域；应说“一项民政工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88238, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "中央", "is_correct": false, "explanation": "语义：“中央”指国家最高层级，与“县里”的范围矛盾，句子不通。"}, {"text": "游戏", "is_correct": false, "explanation": "语义：“游戏”工作人员属于游戏行业，县政府里不会有这样的人员。"}, {"text": "民政", "is_correct": true, "explanation": "语义：民政工作人员在县级政府办理社会救济、婚姻登记等事务，符合“县里”的语境。"}, {"text": "外星", "is_correct": false, "explanation": "搭配：“外星”不能修饰本地机构的工作人员，这种组合不成立。"}], "explanations": {"中央": "语义：“中央”指国家最高层级，与“县里”的范围矛盾，句子不通。", "游戏": "语义：“游戏”工作人员属于游戏行业，县政府里不会有这样的人员。", "民政": "语义：民政工作人员在县级政府办理社会救济、婚姻登记等事务，符合“县里”的语境。", "外星": "搭配：“外星”不能修饰本地机构的工作人员，这种组合不成立。"}, "sentence_index": 6, "correct_answer": "民政"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "新的政策让民政得到了更多照顾。", "explanation": "这里应该用〈民众〉。得到照顾的是老百姓这类人，民政是政府工作，不能作为被照顾的对象。"}, {"text": "这个国家实行民政选举制度。", "explanation": "这里应该用〈民主〉。选举制度属于政治制度，要说“民主选举”；民政指政府处理社会事务的工作。"}, {"text": "他买了一台民政，放在办公室里。", "explanation": "量词用错。〈台〉用于机器、电器，不能修饰民政这类工作；应说“一项民政工作”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88238, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这本民政工作很重要。", "corrected_sentence": "这项民政工作很重要。", "error_description": "错误形式“这本民政工作”，正确形式“这项民政工作”。“工作”前的量词应用“项”，“本”多用于书籍，不能修饰工作。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88238, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "她把一条民政工作做得很好。", "corrected_sentence": "她把一项民政工作做得很好。", "error_description": "量词“条”用于细长的东西，不能修饰工作；应说“一项民政工作”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '8a4b5f20-214f-43cf-91f7-e2cb940ef8fb') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
