INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88239, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "将才是很会带兵打仗的人。", "primary_collocate": null, "pronunciation": "jiàng cái", "ipa": "tɕjɑŋ˥˩ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他很会打仗，是一位难得的将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这位将军年轻时就是有名的将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "皇帝想找一个能带兵的将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这场仗赢了，因为我们有将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他从小爱看兵书，长大后成了将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国家需要将才来保护边境。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都说他是个会带兵的将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这支队伍里有不少将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老皇帝一直在找将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她打仗很厉害，真是个将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位将才", "label": "量词"}, {"form": "一个将才", "label": "量词"}], "register": "书面语", "sense_fingerprint": "很会带兵打仗的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be7a67a-0052-4629-80f6-eca6c3881ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88239, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将才", "is_correct": true, "explanation": "正确：将才指很会带兵打仗的人，与“很会打仗”的语境相合。"}, {"text": "厨师", "is_correct": false, "explanation": "语义：“厨师”指做饭的人，与“很会打仗”的语境不合。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：“园丁”指照料花木的人，与“很会打仗”不相合。"}, {"text": "歌手", "is_correct": false, "explanation": "语义：“歌手”指唱歌的人，不能与“很会打仗”相配。"}], "explanations": {"将才": "正确：将才指很会带兵打仗的人，与“很会打仗”的语境相合。", "厨师": "语义：“厨师”指做饭的人，与“很会打仗”的语境不合。", "园丁": "语义：“园丁”指照料花木的人，与“很会打仗”不相合。", "歌手": "语义：“歌手”指唱歌的人，不能与“很会打仗”相配。"}, "sentence_index": 0, "correct_answer": "将才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "公司正在招聘，需要更多将才来负责市场推广。", "explanation": "这里应该用〈人才〉。将才专指能带兵作战的人，不能用来指一般的人才。"}, {"text": "这个孩子是数学将才，每道题都做得很快。", "explanation": "这里应该用〈天才〉。将才只用于带兵打仗的人才，形容数学能力要用〈天才〉。"}, {"text": "这个年轻人写文章很厉害，是一位难得的将才。", "explanation": "这里应该用〈才子〉。将才专指能带兵作战的人，不能用来形容擅长写文章的人。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88239, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将才", "is_correct": true, "explanation": "正确：将才指能带兵的人，与“会带兵的”相合。"}, {"text": "商人", "is_correct": false, "explanation": "语义：“商人”指做生意的人，与“会带兵的”不相合。"}, {"text": "作家", "is_correct": false, "explanation": "语义：“作家”指写作的人，不能与“会带兵的”搭配。"}, {"text": "裁缝", "is_correct": false, "explanation": "语义：“裁缝”指做衣服的人，与“会带兵的”不相合。"}], "explanations": {"将才": "正确：将才指能带兵的人，与“会带兵的”相合。", "商人": "语义：“商人”指做生意的人，与“会带兵的”不相合。", "作家": "语义：“作家”指写作的人，不能与“会带兵的”搭配。", "裁缝": "语义：“裁缝”指做衣服的人，与“会带兵的”不相合。"}, "sentence_index": 6, "correct_answer": "将才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这台电脑是个将才，很会处理数据。", "explanation": "这里是把将才用成了“办事能力强的高手”的意思，但将才只指很会带兵打仗的人，不能用来指机器。"}, {"text": "我家的小狗是个将才，每天都会看门。", "explanation": "这里是把将才用成了“尽职能干”的意思，但将才只指很会带兵打仗的人，不能用来指动物。"}, {"text": "这座城市是个将才，发展得很快。", "explanation": "这里是把将才用成了“有能力、能干”的意思，但将才只指很会带兵打仗的人，不能用来指城市。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88239, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "这位少年将来会成为一只出色的将才。", "corrected_sentence": "这位少年将来会成为一位出色的将才。", "error_description": "量词错误：将才指人，应用“位”或“个”，不能用“只”（“只”多用于动物）。应改为“一位出色的将才”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88239, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他是我们部队里一张难得的将才。", "corrected_sentence": "他是我们部队里一位难得的将才。", "error_description": "量词错误：将才指人，应用“位”或“个”，不能用“张”（“张”多用于纸、桌子等平面物体）。应改为“一位难得的将才”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88240, 1, 'llm_types_A', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88240, 1, 'llm_types_B', '{}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88240, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "有指挥作战才能的人。", "primary_collocate": null, "pronunciation": "jiàng cái", "ipa": "tɕjɑŋ˥˩ tsʰaɪ˧˥", "syllable_count": 2, "sentences": [{"text": "他有指挥的本事，是个将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "大家都觉得年轻的小王是将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "战争时期，国家最缺的是将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指挥作战很聪明，是真正的将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老师说，这位古代的将才从没输过。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "将才不一定是最强壮的人。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "这本书写了很多古代将才的故事。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "国王给将才送去了一匹好马。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "要成为将才，要先学会看地图。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他指挥得很好，大家夸他是将才。", "target_word": "将才", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一位将才", "label": "量词"}, {"form": "一个将才", "label": "量词"}], "register": "书面语", "sense_fingerprint": "有指挥作战才能的人", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '0be7a67a-0052-4629-80f6-eca6c3881ca5') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88240, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "将才", "is_correct": true, "explanation": "正确：将才指有指挥作战才能的人，与“有指挥的本事”相合。"}, {"text": "园丁", "is_correct": false, "explanation": "语义：“园丁”指照料花木的人，与“有指挥的本事”不相合。"}, {"text": "诗人", "is_correct": false, "explanation": "语义：“诗人”指写诗的人，与“指挥的本事”不相合。"}, {"text": "路灯", "is_correct": false, "explanation": "语义：“路灯”是器物，不能说人“有指挥的本事”，句子读不通。"}], "explanations": {"将才": "正确：将才指有指挥作战才能的人，与“有指挥的本事”相合。", "园丁": "语义：“园丁”指照料花木的人，与“有指挥的本事”不相合。", "诗人": "语义：“诗人”指写诗的人，与“指挥的本事”不相合。", "路灯": "语义：“路灯”是器物，不能说人“有指挥的本事”，句子读不通。"}, "sentence_index": 0, "correct_answer": "将才"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "他是一位很会画画的将才，画的山水特别美。", "explanation": "这里应该用〈画家〉。将才指有指挥作战才能的人，不能用来指会画画的人。"}, {"text": "他是一位很会做饭的将才，菜做得又快又好。", "explanation": "这里应该用〈厨师〉。将才指有指挥作战才能的人，不能用来指做饭的人。"}, {"text": "这把伞是个将才，遇到雨天很灵。", "explanation": "这里是把将才用成了“好用、顶用”的意思，但将才只指有指挥作战才能的人，不能用来指伞。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88240, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "将才", "is_correct": true, "explanation": "正确：将才指有指挥作战才能的人，与“古代”“故事”的语境相合。"}, {"text": "电脑", "is_correct": false, "explanation": "语义：古代没有电脑，“古代电脑的故事”与语境不合。"}, {"text": "手机", "is_correct": false, "explanation": "语义：古代没有手机，“古代手机的故事”与语境不合。"}, {"text": "飞机", "is_correct": false, "explanation": "语义：古代没有飞机，“古代飞机的故事”与语境不合。"}], "explanations": {"将才": "正确：将才指有指挥作战才能的人，与“古代”“故事”的语境相合。", "电脑": "语义：古代没有电脑，“古代电脑的故事”与语境不合。", "手机": "语义：古代没有手机，“古代手机的故事”与语境不合。", "飞机": "语义：古代没有飞机，“古代飞机的故事”与语境不合。"}, "sentence_index": 6, "correct_answer": "将才"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部电影的将才很会拍戏，大家都夸他。", "explanation": "这里应该用〈导演〉。将才专指指挥作战的人，不能用来指电影的导演。"}, {"text": "这位将才很会带乐队，大家都很佩服。", "explanation": "这里应该用〈指挥家〉。将才指统兵作战的人，不能用来指乐队的指挥。"}, {"text": "这间屋子是个将才，很会保暖。", "explanation": "这里是把将才用成了“本领高强、顶用”的意思，但将才只指有指挥作战才能的人，不能用来指房屋。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88240, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "他从小就很有谋略，将来一定是只将才。", "corrected_sentence": "他从小就很有谋略，将来一定是个将才。", "error_description": "量词错误：将才指人，应用“个”或“位”，不能用“只”（“只”多用于动物）。应改为“是个将才”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88240, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他指挥作战很有一套，是一张难得的将才。", "corrected_sentence": "他指挥作战很有一套，是一位难得的将才。", "error_description": "量词错误：将才指人，应用“位”或“个”，不能用“张”。应改为“一位难得的将才”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7de6260c-2a6c-410a-9af0-ba6c08bfd103') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
