INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88241, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水面是水的最上面那一层。", "primary_collocate": null, "pronunciation": "shuǐ miàn", "ipa": "ʂweɪ˨˩˦ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "水面上有一片叶子。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "风一吹，水面就动了。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "小鸟飞过水面。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面很平，像一面镜子。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "鱼跳出了水面。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "太阳照在水面上，很亮。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面上漂着几朵花。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "孩子们看着水面，一动不动。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "下雨了，水面上泛起了一圈圈涟漪。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他把石头扔到水面上。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片水面", "label": "量词搭配"}, {"form": "水面上", "label": "方位短语"}], "register": "中性", "sense_fingerprint": "水最上面的一层，能看到叶子、花、小鸟等东西在上面", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a55c6fd-35f4-4c8a-92f0-78d112ddc57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88241, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "书面", "is_correct": false, "explanation": "shū（第一声）比 shuǐ（第三声）少了韵母 i，声调也不同，意思是用文字表达的形式。"}, {"text": "水面", "is_correct": true, "explanation": "正确选项，即目标词，意思是水的最上面一层。"}, {"text": "睡眠", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）、mián（第二声）与 miàn（第四声）声调都不同，意思是睡觉。"}, {"text": "水门", "is_correct": false, "explanation": "mén（第二声）与 miàn（第四声）韵母和声调都不同，意思是水闸的闸门。"}], "explanations": {"书面": "shū（第一声）比 shuǐ（第三声）少了韵母 i，声调也不同，意思是用文字表达的形式。", "水面": "正确选项，即目标词，意思是水的最上面一层。", "睡眠": "shuì（第四声）与 shuǐ（第三声）、mián（第二声）与 miàn（第四声）声调都不同，意思是睡觉。", "水门": "mén（第二声）与 miàn（第四声）韵母和声调都不同，意思是水闸的闸门。"}, "sentence_index": null, "correct_answer": "水面"}, "level_3": {"options": [{"text": "水面", "is_correct": true, "explanation": "正确：“水面上”指水的表层，与“有一片叶子”搭配。"}, {"text": "声音", "is_correct": false, "explanation": "语义：“声音”不是可以放叶子的处所，“声音上有一片叶子”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格上”指方面，不指位置，与“有一片叶子”不搭配。"}, {"text": "年龄", "is_correct": false, "explanation": "语义：年龄是抽象概念，不能有叶子漂浮在上面。"}], "explanations": {"水面": "正确：“水面上”指水的表层，与“有一片叶子”搭配。", "声音": "语义：“声音”不是可以放叶子的处所，“声音上有一片叶子”说不通。", "价格": "搭配：“价格上”指方面，不指位置，与“有一片叶子”不搭配。", "年龄": "语义：年龄是抽象概念，不能有叶子漂浮在上面。"}, "sentence_index": 0, "correct_answer": "水面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "桌子的水面很光滑，擦得很干净。", "explanation": "这里应该用〈表面〉。水面只指水的表层，桌子是固体，不能说“水面”。"}, {"text": "手机的水面碎了，换一块就好了。", "explanation": "这里应该用〈屏幕〉。水面只指水的表层，手机屏幕不能说“水面”。"}, {"text": "河里的水面很急，船不敢过。", "explanation": "这里应该用〈水流〉。“急”形容水的流动，水面是水的表层，不能说“水面很急”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88241, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水面", "is_correct": true, "explanation": "正确：“水面上漂着”指水的表层上浮着东西，搭配自然。"}, {"text": "桌面", "is_correct": false, "explanation": "语义：桌面是固体，花不会漂在上面，与“漂着”冲突。"}, {"text": "窗户", "is_correct": false, "explanation": "搭配：“漂”要求液体表面，窗户不能说“漂着几朵花”。"}, {"text": "脚步", "is_correct": false, "explanation": "语义：脚步不是处所，花不能漂在脚步上。"}], "explanations": {"水面": "正确：“水面上漂着”指水的表层上浮着东西，搭配自然。", "桌面": "语义：桌面是固体，花不会漂在上面，与“漂着”冲突。", "窗户": "搭配：“漂”要求液体表面，窗户不能说“漂着几朵花”。", "脚步": "语义：脚步不是处所，花不能漂在脚步上。"}, "sentence_index": 6, "correct_answer": "水面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "他把被子铺在水面上，准备睡觉。", "explanation": "这里应该用〈床〉。被子要铺在平整的固体表面，水面不能铺被子。"}, {"text": "他在水面上贴了一张海报，很醒目。", "explanation": "这里应该用〈墙〉。水面是水的表层，不能贴海报；贴东西要用墙等固体表面。"}, {"text": "他抱着水面哭了很久。", "explanation": "这里应该用〈枕头〉。“抱”用于可以抱的有形物体，水面不能被抱。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88241, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "鸭子水面上游来游去。", "corrected_sentence": "鸭子在水面上游来游去。", "error_description": "错误：缺少介词“在”。应为“在水面上”，动作“游”的处所前要用“在”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88241, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "芦苇的影子倒映在水面的上。", "corrected_sentence": "芦苇的影子倒映在水面上。", "error_description": "错误：“水面”后多加了“的”。方位词“上”前不加“的”，应为“水面上”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
