INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88242, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "concrete", "definition": "水的表层；水域的表面。", "primary_collocate": null, "pronunciation": "shuǐ miàn", "ipa": "ʂweɪ˨˩˦ mjɛn˥˩", "syllable_count": 2, "sentences": [{"text": "湖的水面很大，一眼看不到头。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "夜里，水面上没有一条船。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "河水涨了，水面比昨天高了。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "冬天，湖的水面结了一层冰。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "清早的水面上有一层雾。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "船慢慢划过平静的水面。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面下是深水，上面飘着白云。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面倒映着山，像一幅画。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "水面上的光一闪一闪的。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "渔船在宽宽的水面上慢慢走。", "target_word": "水面", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "一片水面", "label": "量词搭配"}, {"form": "水面上", "label": "方位短语"}], "register": "中性", "sense_fingerprint": "湖、河、海等水域的表面，常说它的大小、高低、平静或结冰", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '9a55c6fd-35f4-4c8a-92f0-78d112ddc57a') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88242, 1, 'prompt2_exercises_A', '{"level_1": {"options": [{"text": "书面", "is_correct": false, "explanation": "shū（第一声）比 shuǐ（第三声）少了韵母 i，声调也不同，意思是用文字表达的形式。"}, {"text": "水面", "is_correct": true, "explanation": "正确选项，即目标词，意思是水域的表面。"}, {"text": "睡眠", "is_correct": false, "explanation": "shuì（第四声）与 shuǐ（第三声）、mián（第二声）与 miàn（第四声）声调都不同，意思是睡觉。"}, {"text": "水门", "is_correct": false, "explanation": "mén（第二声）与 miàn（第四声）韵母和声调都不同，意思是水闸的闸门。"}], "explanations": {"书面": "shū（第一声）比 shuǐ（第三声）少了韵母 i，声调也不同，意思是用文字表达的形式。", "水面": "正确选项，即目标词，意思是水域的表面。", "睡眠": "shuì（第四声）与 shuǐ（第三声）、mián（第二声）与 miàn（第四声）声调都不同，意思是睡觉。", "水门": "mén（第二声）与 miàn（第四声）韵母和声调都不同，意思是水闸的闸门。"}, "sentence_index": null, "correct_answer": "水面"}, "level_3": {"options": [{"text": "水面", "is_correct": true, "explanation": "正确：“湖的水面”指湖的表面，可以说它很大。"}, {"text": "体重", "is_correct": false, "explanation": "语义：湖没有体重，“湖的体重很大”说不通。"}, {"text": "学费", "is_correct": false, "explanation": "语义：学费是上学的花费，与湖无关，“湖的学费很大”说不通。"}, {"text": "价格", "is_correct": false, "explanation": "搭配：“价格”可以说高或低，但不能说“湖的价格很大”。"}], "explanations": {"水面": "正确：“湖的水面”指湖的表面，可以说它很大。", "体重": "语义：湖没有体重，“湖的体重很大”说不通。", "学费": "语义：学费是上学的花费，与湖无关，“湖的学费很大”说不通。", "价格": "搭配：“价格”可以说高或低，但不能说“湖的价格很大”。"}, "sentence_index": 0, "correct_answer": "水面"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "冬天，操场的水面结了一层冰。", "explanation": "这里应该用〈地面〉。操场是地面，不是水域，不能说“水面”。"}, {"text": "这块石头的水面很粗糙，摸起来扎手。", "explanation": "这里应该用〈表面〉。水面指水的表层或水域的表面，石头是固体，不能说“水面”。"}, {"text": "他用抹布把水面擦干净，然后放上了碗筷。", "explanation": "这里应该用〈桌面〉。水面是水域的表面，不能用抹布擦，也不能放碗筷。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88242, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "水面", "is_correct": true, "explanation": "正确：“水面下”与“上面”对应，指水域表面的下方是深水，与语境搭配。"}, {"text": "黑板", "is_correct": false, "explanation": "语义：黑板下不可能是深水，与整句的水域语境冲突。"}, {"text": "作业", "is_correct": false, "explanation": "语义：作业不是水域，“作业下是深水”说不通。"}, {"text": "书包", "is_correct": false, "explanation": "语义：书包不是水域，“书包下是深水”说不通。"}], "explanations": {"水面": "正确：“水面下”与“上面”对应，指水域表面的下方是深水，与语境搭配。", "黑板": "语义：黑板下不可能是深水，与整句的水域语境冲突。", "作业": "语义：作业不是水域，“作业下是深水”说不通。", "书包": "语义：书包不是水域，“书包下是深水”说不通。"}, "sentence_index": 6, "correct_answer": "水面"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "老师在水面上写字，写得很认真。", "explanation": "这里应该用〈黑板〉。水面是水的表层，不能写字；写字要用黑板等平面。"}, {"text": "汽车在宽宽的水面上慢慢走。", "explanation": "这里应该用〈马路〉。汽车要在路上行驶，水面上不能行驶汽车。"}, {"text": "孩子们在宽宽的水面上种了一排树。", "explanation": "这里应该用〈土地〉。树要种在土里，水面不能种树。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88242, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "夏天，湖的水面的上飘着荷花。", "corrected_sentence": "夏天，湖的水面上飘着荷花。", "error_description": "错误：“水面”与方位词“上”之间多了“的”。应为“水面上”，方位词“上”直接接在名词后。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88242, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "傍晚，白鹭落湖的水面上。", "corrected_sentence": "傍晚，白鹭落在湖的水面上。", "error_description": "错误：缺少介词“在”。应为“落在湖的水面上”，表示处所的“在”不能省略。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '761507c9-3cd9-465f-9c56-7b5e2d036aa9') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
