INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88243, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "别人请你帮忙,你很愿意答应的时候,就说好说。", "primary_collocate": null, "pronunciation": "hǎo shuō", "ipa": "xau̯˨˩˦ ʂu̯o˥", "syllable_count": 2, "sentences": [{"text": "“帮我拿一下书，行吗？”“好说。”", "target_word": "好说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“借我一支笔。”“好说，给你。”", "target_word": "好说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "朋友请他帮忙搬家，他说：“好说！”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“周末能陪我去买东西吗？”“好说，没问题。”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“麻烦你送我一下。”“好说，上车吧。”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他拍拍我的肩说：“有事找我，好说。”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“能教我做这道菜吗？”“好说，现在就教。”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我请老张帮个忙，他笑着说：“好说，包在我身上。”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“能借我一点钱吗？”“好说，你要多少？”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“你能不能帮我写封信？”“好说，我来写。”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "别人请帮忙，愿意答应时说", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2634a1f-e0ef-4c1b-853c-f701f33e6317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88243, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "哼", "is_correct": false, "explanation": "语义：“哼”表示不满或不屑，不是答应，不能用来回应请求。"}, {"text": "哎哟", "is_correct": false, "explanation": "语义：“哎哟”表示疼痛或惊呼，与答应对方的请求无关。"}, {"text": "好说", "is_correct": true, "explanation": "“好说”表示乐意答应对方的请求，接在“行吗？”之后语境通顺。"}, {"text": "不敢当", "is_correct": false, "explanation": "语域：“不敢当”是对夸奖的谦辞，用在请求之后语境不合。"}], "explanations": {"哼": "语义：“哼”表示不满或不屑，不是答应，不能用来回应请求。", "哎哟": "语义：“哎哟”表示疼痛或惊呼，与答应对方的请求无关。", "好说": "“好说”表示乐意答应对方的请求，接在“行吗？”之后语境通顺。", "不敢当": "语域：“不敢当”是对夸奖的谦辞，用在请求之后语境不合。"}, "sentence_index": 0, "correct_answer": "好说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这幅画很好说，颜色特别鲜艳。", "explanation": "这里应该用〈好看〉。“好说”不用来评价画作的美观，夸画好看要用“好看”。"}, {"text": "“现在几点了？”“好说，十点了。”", "explanation": "“好说”只用于回应请求或提议，表示答应。询问时间这类事实问题应直接回答时间。"}, {"text": "“能帮我修一下电脑吗？”“好说，我肯定修不好。”", "explanation": "“好说”表示乐意答应，后面却说修不好，前后矛盾。这个词不能与否定自己承诺的话连用。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88243, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "对不起", "is_correct": false, "explanation": "语义：“对不起”是道歉语，与“现在就教”的爽快答应相矛盾。"}, {"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”表示让人安静，无法回应对方的请求。"}, {"text": "好说", "is_correct": true, "explanation": "“好说”表示答应对方的请求，与“现在就教”语义一致，填入此处正确。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”是粗俗的唾弃声，用在这里既不礼貌，也不符合答应请求的语境。"}], "explanations": {"对不起": "语义：“对不起”是道歉语，与“现在就教”的爽快答应相矛盾。", "嘘": "语义：“嘘”表示让人安静，无法回应对方的请求。", "好说": "“好说”表示答应对方的请求，与“现在就教”语义一致，填入此处正确。", "呸": "语域：“呸”是粗俗的唾弃声，用在这里既不礼貌，也不符合答应请求的语境。"}, "sentence_index": 6, "correct_answer": "好说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这些作业很好说，半小时就做完了。", "explanation": "这里应该用〈好做〉。“好说”不用来形容作业的难易；说作业容易要用“好做”。"}, {"text": "（正式公函）关于贵方的请求，我方好说。", "explanation": "“好说”是口语客套话，用在正式公函中语域不合，应改用“同意”。"}, {"text": "这块布料很好说，洗起来不费劲。", "explanation": "“好说”没有形容事物“容易处理”的用法，这里误用了词义。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88243, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“帮我订一下餐厅，行吗？”“好说着，我现在就订。”", "corrected_sentence": "“帮我订一下餐厅，行吗？”“好说，我现在就订。”", "error_description": "错误在“好说”后面加了动态助词“着”。“好说”是叹词，不能带“着”，应说“好说，我现在就订。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88243, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“明天能早点叫我起床吗？”“好说过，我定个闹钟。”", "corrected_sentence": "“明天能早点叫我起床吗？”“好说，我定个闹钟。”", "error_description": "错误在“好说”后面加了动态助词“过”。“好说”是叹词，不能带“过”，应说“好说，我定个闹钟。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
