INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88244, 1, 'prompt1_core', '{"pos": "叹词", "semantic_class": "function", "definition": "客套话,表示对方的请求或提议容易商量,可以答应。", "primary_collocate": null, "pronunciation": "hǎo shuō", "ipa": "xau̯˨˩˦ ʂu̯o˥", "syllable_count": 2, "sentences": [{"text": "“能帮我一下吗？”“好说，没问题。”", "target_word": "好说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "“价钱能便宜点儿吗？”“好说，好说。”", "target_word": "好说", "complexity_tier": "T2", "sentence_source": "generated"}, {"text": "你想借我的车用一下？好说，拿去吧。", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“明天能早点来吗？”“好说，我七点到。”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他笑着说：“这事好说，你放心。”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“以后能常来坐坐吗？”“好说，随时都行。”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "想让我多给你一天时间？好说。", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这个价格能再少点吗？”“好说，给你打八折。”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“我想换个座位。”“好说，请坐这边。”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "“这事能商量吗？”“好说，坐下谈。”", "target_word": "好说", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [], "register": "口语", "sense_fingerprint": "客套话，请求容易商量可答应", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'a2634a1f-e0ef-4c1b-853c-f701f33e6317') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88244, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”表示让人安静，接在请求之后与“没问题”语义不合。"}, {"text": "对不起", "is_correct": false, "explanation": "语义：“对不起”是道歉语，与后面的“没问题”相矛盾，不能用来痛快答应。"}, {"text": "好说", "is_correct": true, "explanation": "“好说”表示对方的请求容易答应，与后面的“没问题”语义一致，填入此处正确。"}, {"text": "不敢当", "is_correct": false, "explanation": "语域：“不敢当”是对夸奖的谦辞，不用来回应请求，放在这里语域不合。"}], "explanations": {"嘘": "语义：“嘘”表示让人安静，接在请求之后与“没问题”语义不合。", "对不起": "语义：“对不起”是道歉语，与后面的“没问题”相矛盾，不能用来痛快答应。", "好说": "“好说”表示对方的请求容易答应，与后面的“没问题”语义一致，填入此处正确。", "不敢当": "语域：“不敢当”是对夸奖的谦辞，不用来回应请求，放在这里语域不合。"}, "sentence_index": 0, "correct_answer": "好说"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "这首歌很好说，我每天都听。", "explanation": "这里应该用〈好听〉。“好说”是客套话，只用来答应请求或提议，不用来评价歌曲；说歌好听要用“好听”。"}, {"text": "“你叫什么名字？”“好说，我叫小王。”", "explanation": "“好说”只用来回应请求或提议，表示可以答应。回答“叫什么名字”这类事实问题时，应直接说出名字。"}, {"text": "“能借我一下你的笔吗？”“好说，我不借。”", "explanation": "“好说”表示可以答应，后面却说“我不借”，前后矛盾。这个词不能用来拒绝。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88244, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "嘘", "is_correct": false, "explanation": "语义：“嘘”表示让人安静或制止，与对方的请求无关，不能用来回应。"}, {"text": "好说", "is_correct": true, "explanation": "“好说”表示答应，接在问句之后回应对方的请求，语境通顺。"}, {"text": "呸", "is_correct": false, "explanation": "语域：“呸”是强烈唾弃的粗俗语，用在请求之后极不礼貌，语域不合。"}, {"text": "哎哟", "is_correct": false, "explanation": "语义：“哎哟”表示疼痛或惊呼，并不是答应，放在这里无法回应对方的请求。"}], "explanations": {"嘘": "语义：“嘘”表示让人安静或制止，与对方的请求无关，不能用来回应。", "好说": "“好说”表示答应，接在问句之后回应对方的请求，语境通顺。", "呸": "语域：“呸”是强烈唾弃的粗俗语，用在请求之后极不礼貌，语域不合。", "哎哟": "语义：“哎哟”表示疼痛或惊呼，并不是答应，放在这里无法回应对方的请求。"}, "sentence_index": 6, "correct_answer": "好说"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这份工作很好说，干久了就熟练了。", "explanation": "这里应该用〈好干〉。“好说”是客套话，不用来描述工作的难易；说工作容易要用“好干”。"}, {"text": "（正式公函）关于贵方的提议，我方好说。", "explanation": "“好说”是口语客套话，正式公函中应改用“同意”或“可以”，这里语域不合。"}, {"text": "这块蛋糕很好说，三口就吃完了。", "explanation": "这里应该用〈好吃〉。“好说”不用来形容食物的味道，说好吃要用“好吃”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88244, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "“能帮我看看这份资料吗？”“好说过，我现在就看。”", "corrected_sentence": "“能帮我看看这份资料吗？”“好说，我现在就看。”", "error_description": "错误在“好说”后面加了动态助词“过”。“好说”是叹词，不能带“过”，应说“好说，我现在就看。”", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88244, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "“这个价钱能再优惠些吗？”“好说地，给你打九折。”", "corrected_sentence": "“这个价钱能再优惠些吗？”“好说，给你打九折。”", "error_description": "错误在“好说”后面加了结构助词“地”。“好说”是叹词，不能用“地”来修饰后面的动作，应说“好说，给你打九折。”", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '7583ec12-e2fe-4986-a7f0-f7d7e08f100b') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
