INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88246, 1, 'prompt1_core', '{"pos": "名词", "semantic_class": "abstract", "definition": "年纪；多指老年人的年龄。", "primary_collocate": null, "pronunciation": "nián shì", "ipa": "njɛn˧˥ ʂɻ̩˥˩", "syllable_count": 2, "sentences": [{"text": "外公年事已高，常常忘记事情。", "target_word": "年事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "村里年事最高的老人今年九十岁了。", "target_word": "年事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "老教授年事虽高，说话还很有力气。", "target_word": "年事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "年事高的人最好别爬山。", "target_word": "年事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "他年事太高，儿子不放心他一个人住。", "target_word": "年事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "对年事高的客人，我们要多照顾。", "target_word": "年事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "她年事已高，可是看起来很年轻。", "target_word": "年事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "校长年事渐高，决定明年回家休息。", "target_word": "年事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "我们应该尊敬年事高的人。", "target_word": "年事", "complexity_tier": "T3", "sentence_source": "generated"}, {"text": "随着年事渐高，他走路越来越慢。", "target_word": "年事", "complexity_tier": "T3", "sentence_source": "generated"}], "morphological_forms": [{"form": "年事已高", "label": "复合"}, {"form": "年事渐高", "label": "复合"}], "register": "书面", "sense_fingerprint": "年纪，多指老年人的年龄", "collocate_grounding": {"status": "no_source", "reason": "no collocate asserted for this sense"}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, 'c528a757-cc74-4946-831f-bf1e90a388f2') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88246, 1, 'prompt2_exercises_A', '{"level_3": {"options": [{"text": "房价", "is_correct": false, "explanation": "语义：“房价”指房屋的价格，句子的主语是“外公”，“外公房价已高”说不通。"}, {"text": "年事", "is_correct": true, "explanation": "正确：“年事已高”指年纪大，与“外公”搭配，符合句意，后半句“常常忘记事情”也合理。"}, {"text": "车速", "is_correct": false, "explanation": "语义：“车速”指车辆行驶的快慢，不能用来说人的年纪。"}, {"text": "岁月", "is_correct": false, "explanation": "搭配：“岁月”常与“悠长”“已久”搭配，不说“岁月已高”。"}], "explanations": {"房价": "语义：“房价”指房屋的价格，句子的主语是“外公”，“外公房价已高”说不通。", "年事": "正确：“年事已高”指年纪大，与“外公”搭配，符合句意，后半句“常常忘记事情”也合理。", "车速": "语义：“车速”指车辆行驶的快慢，不能用来说人的年纪。", "岁月": "搭配：“岁月”常与“悠长”“已久”搭配，不说“岁月已高”。"}, "sentence_index": 0, "correct_answer": "年事"}, "level_6": {"correct_sentence_index": 3, "wrong_sentences": [{"text": "我今年的年事是二十岁。", "explanation": "这里应该用〈年龄〉。年事多指老年人的年纪，常与“高”连用；说自己的年龄要用“年龄”。"}, {"text": "他年事轻轻就当了老师。", "explanation": "这里应该用〈年纪〉。年事只指老年人的年纪，不能用来形容年轻人；“年纪轻轻”要用“年纪”。"}, {"text": "这个小孩的年事才五岁。", "explanation": "这里应该用〈岁数〉。年事指老年人的年纪，说小孩的年纪口语里用“岁数”。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88246, 1, 'prompt2_exercises_B', '{"level_3": {"options": [{"text": "物价", "is_correct": false, "explanation": "语义：“物价”指商品价格的总体水平，不能指人，“她物价已高”说不通。"}, {"text": "年事", "is_correct": true, "explanation": "正确：“年事已高”指她年纪大，与后半句“看起来很年轻”形成对比，语义连贯。"}, {"text": "油价", "is_correct": false, "explanation": "语义：“油价”是石油的价格，不能用来描述“她”，“她油价已高”不成立。"}, {"text": "年限", "is_correct": false, "explanation": "搭配：“年限”多与“使用”“服役”搭配，不能用来说一个人的年纪。"}], "explanations": {"物价": "语义：“物价”指商品价格的总体水平，不能指人，“她物价已高”说不通。", "年事": "正确：“年事已高”指她年纪大，与后半句“看起来很年轻”形成对比，语义连贯。", "油价": "语义：“油价”是石油的价格，不能用来描述“她”，“她油价已高”不成立。", "年限": "搭配：“年限”多与“使用”“服役”搭配，不能用来说一个人的年纪。"}, "sentence_index": 6, "correct_answer": "年事"}, "level_6": {"correct_sentence_index": 9, "wrong_sentences": [{"text": "这部旧电视年事已高，屏幕发暗。", "explanation": "这里不这么用。年事只指人的年纪，多用于老人，不能用来说电视的使用年限。"}, {"text": "这台老电脑年事渐高，开机越来越慢。", "explanation": "这里不这么用。年事指人的年纪，不能用来描述电脑已经用了多少年。"}, {"text": "这台旧冰箱年事已高，制冷越来越差。", "explanation": "这里不这么用。年事是人的年纪，不用于冰箱这类物品。"}]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88246, 1, 'prompt3_transforms_A', '{"level_7": {"incorrect_sentence": "舅舅年事了高，还是很爱笑。", "corrected_sentence": "舅舅年事渐高，还是很爱笑。", "error_description": "“年事渐高”中“渐”表示逐渐变化，不能换成“了”。“年事了高”不成句，应改为“年事渐高”。", "correct_sentence_indices": [0, 1, 2]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
INSERT INTO word_assets (sense_id, language_id, asset_type, content, model_used, prompt_version, is_valid, validation_errors, validation_warnings, generation_batch_id) VALUES (88246, 1, 'prompt3_transforms_B', '{"level_7": {"incorrect_sentence": "他年事的渐高，记性也变差了。", "corrected_sentence": "他年事渐高，记性也变差了。", "error_description": "“年事渐高”中间不能加“的”。“年事的渐高”错误，应去掉“的”，写成“年事渐高”。", "correct_sentence_indices": [6, 7, 9]}}'::jsonb, 'claude-code:fat-seed', 'v1', true, NULL, NULL, '6f0544b3-b24e-431a-b9a6-1209bee21dec') ON CONFLICT (sense_id, asset_type) DO UPDATE SET content = EXCLUDED.content, model_used = EXCLUDED.model_used, prompt_version = EXCLUDED.prompt_version, is_valid = EXCLUDED.is_valid, validation_errors = EXCLUDED.validation_errors, validation_warnings = EXCLUDED.validation_warnings, generation_batch_id = EXCLUDED.generation_batch_id;
